bool isRedR8TextureShadowDropShape(const GLTextureImageLevel& image) {
    return image.defined &&
        image.desc.internalFormat == GL_R8 &&
        image.desc.sourceFormat == GL_RED &&
        image.desc.sourceType == GL_UNSIGNED_BYTE &&
        image.nativeBpp == 1 &&
        !image.nativeData.empty();
}

bool isDepth32FTextureShadowDropShape(const GLTextureImageLevel& image) {
    const std::size_t texelCount =
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.width, 1)) *
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.height, 1)) *
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.depth, 1));
    return image.defined &&
        image.desc.internalFormat == GL_DEPTH_COMPONENT32F &&
        image.nativeBpp == sizeof(float) &&
        image.nativeData.size() >= texelCount * sizeof(float);
}

bool isDefaultTextureSwizzle(const std::array<GLint, 4>& swizzle) {
    return swizzle[0] == GL_RED &&
        swizzle[1] == GL_GREEN &&
        swizzle[2] == GL_BLUE &&
        swizzle[3] == GL_ALPHA;
}

bool depth32FTextureShadowDropUsesSamplingProxy(const GLTextureObject& object) {
    return object.params.depthStencilTextureMode == GL_STENCIL_INDEX ||
        !isDefaultTextureSwizzle(object.params.swizzle);
}

bool materializeRedR8TextureShadowFromNativeData(GLTextureImageLevel& image) {
    if (!isRedR8TextureShadowDropShape(image)) {
        return false;
    }
    const std::size_t texelCount =
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.width, 1)) *
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.height, 1)) *
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.depth, 1));
    if (image.nativeData.size() < texelCount) {
        return false;
    }
    const std::size_t rgba8Bytes = texelCount * 4u;
    if (image.rgba8.size() != rgba8Bytes) {
        image.rgba8.assign(rgba8Bytes, 0);
    }
    for (std::size_t texel = 0; texel < texelCount; ++texel) {
        const std::uint8_t r = image.nativeData[texel];
        const std::size_t rgbaOffset = texel * 4u;
        image.rgba8[rgbaOffset + 0u] = r;
        image.rgba8[rgbaOffset + 1u] = 0u;
        image.rgba8[rgbaOffset + 2u] = 0u;
        image.rgba8[rgbaOffset + 3u] = 255u;
    }
    return true;
}

bool materializeDepth32FTextureShadowFromNativeData(GLTextureImageLevel& image) {
    if (!isDepth32FTextureShadowDropShape(image)) {
        return false;
    }
    const std::size_t texelCount =
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.width, 1)) *
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.height, 1)) *
        static_cast<std::size_t>(std::max<GLsizei>(image.desc.depth, 1));
    if (image.nativeData.size() < texelCount * sizeof(float)) {
        return false;
    }
    const std::size_t rgba8Bytes = texelCount * 4u;
    if (image.rgba8.size() != rgba8Bytes) {
        image.rgba8.assign(rgba8Bytes, 0);
    }
    for (std::size_t texel = 0; texel < texelCount; ++texel) {
        float depthValue = 0.0f;
        std::memcpy(&depthValue,
                    image.nativeData.data() + texel * sizeof(float),
                    sizeof(depthValue));
        const GLfloat clamped = std::clamp(depthValue, 0.0f, 1.0f);
        const std::size_t rgbaOffset = texel * 4u;
        image.rgba8[rgbaOffset + 0u] = static_cast<std::uint8_t>(
            clamped * 255.0f + 0.5f);
        image.rgba8[rgbaOffset + 1u] = 0u;
        image.rgba8[rgbaOffset + 2u] = 0u;
        image.rgba8[rgbaOffset + 3u] = 255u;
    }
    return true;
}

bool traceSamplerBindingsProgramMatches(const char* raw, GLuint program) {
    if (raw == nullptr || raw[0] == '\0') {
        return false;
    }
    if (std::strcmp(raw, "1") == 0 ||
        std::strcmp(raw, "all") == 0 ||
        std::strcmp(raw, "*") == 0) {
        return true;
    }
    const char* cursor = raw;
    while (*cursor != '\0') {
        while (*cursor == ',' ||
               std::isspace(static_cast<unsigned char>(*cursor))) {
            ++cursor;
        }
        if (*cursor == '\0') {
            break;
        }
        char* end = nullptr;
        const unsigned long value = std::strtoul(cursor, &end, 10);
        if (end != cursor && value == static_cast<unsigned long>(program)) {
            return true;
        }
        cursor = (end != cursor) ? end : cursor + 1;
        while (*cursor != '\0' && *cursor != ',') {
            ++cursor;
        }
    }
    return false;
}

std::uint32_t traceSamplerBindingsLimit() {
    const char* raw = std::getenv("APPGL_TRACE_SAMPLER_BINDINGS_LIMIT");
    if (raw == nullptr || raw[0] == '\0') {
        return 512u;
    }
    char* end = nullptr;
    const unsigned long parsed = std::strtoul(raw, &end, 10);
    if (end == raw || parsed == 0ul) {
        return 512u;
    }
    return static_cast<std::uint32_t>(parsed);
}

bool shouldTraceSamplerBinding(GLuint program) {
    const char* raw = std::getenv("APPGL_TRACE_SAMPLER_BINDINGS");
    if (!traceSamplerBindingsProgramMatches(raw, program)) {
        return false;
    }
    static std::atomic<std::uint32_t> emitted{0u};
    return emitted.fetch_add(1u, std::memory_order_relaxed) <
        traceSamplerBindingsLimit();
}

const char* traceTextureTargetName(GLenum target) {
    switch (target) {
        case GL_TEXTURE_1D: return "GL_TEXTURE_1D";
        case GL_TEXTURE_2D: return "GL_TEXTURE_2D";
        case GL_TEXTURE_3D: return "GL_TEXTURE_3D";
        case GL_TEXTURE_CUBE_MAP: return "GL_TEXTURE_CUBE_MAP";
        case GL_TEXTURE_1D_ARRAY: return "GL_TEXTURE_1D_ARRAY";
        case GL_TEXTURE_2D_ARRAY: return "GL_TEXTURE_2D_ARRAY";
        case GL_TEXTURE_CUBE_MAP_ARRAY: return "GL_TEXTURE_CUBE_MAP_ARRAY";
        case GL_TEXTURE_RECTANGLE: return "GL_TEXTURE_RECTANGLE";
        case GL_TEXTURE_BUFFER: return "GL_TEXTURE_BUFFER";
        case GL_TEXTURE_2D_MULTISAMPLE: return "GL_TEXTURE_2D_MULTISAMPLE";
        case GL_TEXTURE_2D_MULTISAMPLE_ARRAY: return "GL_TEXTURE_2D_MULTISAMPLE_ARRAY";
        default: return "unknown";
    }
}

enum class R5EvictionReason : std::uint8_t {
    Test,
    Pressure,
};

using R5EvictionBucketMask = std::uint32_t;

constexpr R5EvictionBucketMask kR5EvictionBucketTextureView = 1u << 0;
constexpr R5EvictionBucketMask kR5EvictionBucketSwizzledTextureView = 1u << 1;
constexpr R5EvictionBucketMask kR5EvictionBucketExpandedIndexCache = 1u << 2;
constexpr R5EvictionBucketMask kR5EvictionBucketPrimaryTexture = 1u << 3;
constexpr R5EvictionBucketMask kR5EvictionBucketDerivedCaches =
    kR5EvictionBucketTextureView |
    kR5EvictionBucketSwizzledTextureView |
    kR5EvictionBucketExpandedIndexCache;
constexpr R5EvictionBucketMask kR5EvictionBucketAll =
    kR5EvictionBucketDerivedCaches |
    kR5EvictionBucketPrimaryTexture;

struct R5EvictionRequest {
    R5EvictionReason reason = R5EvictionReason::Test;
    MetalMemoryPressureState pressureLevel = MetalMemoryPressureState::Idle;
    std::uint64_t budgetRecords = 0;
    R5EvictionBucketMask bucketAllowlist = kR5EvictionBucketAll;
    MetalMemoryPressureClass memoryClass = MetalMemoryPressureClass::Unknown;
    std::uint64_t minIdleBoundaryAge = 0;
    std::uint64_t policySoftBudgetRecords = 0;
    std::uint64_t policyHardBudgetRecords = 0;
    std::uint64_t policyCriticalBudgetRecords = 0;
};

struct R5EvictionCandidate {
    ResourceResidencyRecord record;
    R5EvictionBucketMask bucket = 0;
};

struct R5PressureEvictionPolicy {
    MetalMemoryPressureClass memoryClass = MetalMemoryPressureClass::Unknown;
    std::uint64_t softBudgetRecords = 8;
    std::uint64_t hardBudgetRecords = 16;
    std::uint64_t criticalBudgetRecords = kMetalR5ResidencyCandidateLimit;
    std::uint64_t softMinIdleBoundaryAge = 0;
    std::uint64_t hardMinIdleBoundaryAge = 0;
    std::uint64_t criticalMinIdleBoundaryAge = 0;
    R5EvictionBucketMask bucketAllowlist = kR5EvictionBucketAll;
};

R5EvictionBucketMask r5EvictionBucketForRecord(
    const ResourceResidencyRecord& record) {
    switch (record.diagnosticBucketId) {
    case kMetalR5DiagnosticBucketTextureView:
        return kR5EvictionBucketTextureView;
    case kMetalR5DiagnosticBucketSwizzledTextureView:
        return kR5EvictionBucketSwizzledTextureView;
    case kMetalR5DiagnosticBucketExpandedIndexCache:
        return kR5EvictionBucketExpandedIndexCache;
    case kMetalR5DiagnosticBucketPrimaryTexture:
        return kR5EvictionBucketPrimaryTexture;
    default:
        return 0;
    }
}

bool r5EvictionBucketAllowed(const ResourceResidencyRecord& record,
                             R5EvictionBucketMask allowlist) {
    const R5EvictionBucketMask bucket = r5EvictionBucketForRecord(record);
    return bucket != 0 && (bucket & allowlist) != 0;
}

MetalMemoryPressureState metalMemoryPressureStateFromValue(
    std::uint64_t value) {
    if (value >= metalMemoryPressureStateValue(
            MetalMemoryPressureState::Critical)) {
        return MetalMemoryPressureState::Critical;
    }
    if (value >= metalMemoryPressureStateValue(MetalMemoryPressureState::Hard)) {
        return MetalMemoryPressureState::Hard;
    }
    if (value >= metalMemoryPressureStateValue(MetalMemoryPressureState::Soft)) {
        return MetalMemoryPressureState::Soft;
    }
    return MetalMemoryPressureState::Idle;
}

MetalMemoryPressureState r5MaxPressureLevel(MetalMemoryPressureState lhs,
                                            MetalMemoryPressureState rhs) {
    return metalMemoryPressureStateValue(lhs) >=
            metalMemoryPressureStateValue(rhs)
        ? lhs
        : rhs;
}

R5PressureEvictionPolicy r5PressureEvictionPolicyForSnapshot(
    const MetalMemoryPressureSnapshot& snapshot) {
    R5PressureEvictionPolicy policy;
    policy.memoryClass =
        metalMemoryPressureClassFromValue(snapshot.inputs.memoryClass);
    switch (policy.memoryClass) {
    case MetalMemoryPressureClass::Low:
        policy.softBudgetRecords = 4;
        policy.hardBudgetRecords = 8;
        policy.criticalBudgetRecords = 32;
        break;
    case MetalMemoryPressureClass::High:
        policy.softBudgetRecords = 12;
        policy.hardBudgetRecords = 32;
        policy.criticalBudgetRecords = kMetalR5ResidencyCandidateLimit;
        policy.softMinIdleBoundaryAge = 4;
        policy.hardMinIdleBoundaryAge = 2;
        policy.criticalMinIdleBoundaryAge = 0;
        break;
    case MetalMemoryPressureClass::Mid:
    case MetalMemoryPressureClass::Unknown:
        break;
    }
    return policy;
}

std::uint64_t r5PressureBudgetForLevel(
    MetalMemoryPressureState level,
    const R5PressureEvictionPolicy& policy) {
    switch (level) {
    case MetalMemoryPressureState::Soft:
        return policy.softBudgetRecords;
    case MetalMemoryPressureState::Hard:
        return policy.hardBudgetRecords;
    case MetalMemoryPressureState::Critical:
        return policy.criticalBudgetRecords;
    case MetalMemoryPressureState::Idle:
        return 0;
    }
    return 0;
}

std::uint64_t r5PressureRetentionAgeForLevel(
    MetalMemoryPressureState level,
    const R5PressureEvictionPolicy& policy) {
    switch (level) {
    case MetalMemoryPressureState::Soft:
        return policy.softMinIdleBoundaryAge;
    case MetalMemoryPressureState::Hard:
        return policy.hardMinIdleBoundaryAge;
    case MetalMemoryPressureState::Critical:
        return policy.criticalMinIdleBoundaryAge;
    case MetalMemoryPressureState::Idle:
        return 0;
    }
    return 0;
}

using GLDrawProfileClock = std::chrono::steady_clock;
using GLDrawProfileTimePoint = GLDrawProfileClock::time_point;

static GLDrawProfileTimePoint glDrawProfileNow() {
    return GLDrawProfileClock::now();
}

static double glDrawProfileElapsedUs(GLDrawProfileTimePoint start,
                                     GLDrawProfileTimePoint end) {
    return std::chrono::duration<double, std::micro>(end - start).count();
}

static bool bindingConstructionSizingEnabled() {
    return appglEnvEnabledDefaultOff("APPGL_BINDING_CONSTRUCTION_SIZING");
}

static bool defaultUniformGenerationBindCacheValidateEnabled() {
    return appglEnvEnabledDefaultOff(
        "APPGL_DEFAULT_UNIFORM_GENERATION_BIND_CACHE_VALIDATE");
}

