struct BindingConstructionSizingProfile {
    bool enabled = bindingConstructionSizingEnabled();
    std::uint64_t draws = 0;
    std::uint64_t coarseCandidates = 0;
    std::uint64_t coarseHits = 0;
    std::uint64_t coarseMisses = 0;
    std::uint64_t validateWalks = 0;
    std::uint64_t replayCopies = 0;
    std::uint64_t referencedTextures = 0;
    std::uint64_t referencedUboBindings = 0;
    std::uint64_t referencedSsboBindings = 0;
    std::uint64_t referencedAtomicBindings = 0;
    std::uint64_t replayCopyBytes = 0;
    std::uint64_t validateHash = 0;
    std::uint64_t planKeyCalls = 0;
    double keyReadCompareUs = 0.0;
    double uniformPackUs = 0.0;
    double samplerResolveUs = 0.0;
    double uboResolveUs = 0.0;
    double ssboAtomicResolveUs = 0.0;
    double imageResolveUs = 0.0;
    double validateWalkUs = 0.0;
    double replayCopyUs = 0.0;
    double planKeyUs = 0.0;
    bool hasLastKey = false;
    BindingConstructionSizingKey lastKey{};

    bool observeCoarseKey(const BindingConstructionSizingKey& key) {
        if (!enabled) {
            return false;
        }
        ++coarseCandidates;
        const bool hit = hasLastKey && key == lastKey;
        if (hit) {
            ++coarseHits;
        } else {
            ++coarseMisses;
        }
        lastKey = key;
        hasLastKey = true;
        return hit;
    }

    void record(const BindingConstructionSizingSample& sample) {
        if (!enabled) {
            return;
        }
        ++draws;
        keyReadCompareUs += sample.keyReadCompareUs;
        uniformPackUs += sample.uniformPackUs;
        samplerResolveUs += sample.samplerResolveUs;
        uboResolveUs += sample.uboResolveUs;
        ssboAtomicResolveUs += sample.ssboAtomicResolveUs;
        imageResolveUs += sample.imageResolveUs;
        validateWalkUs += sample.validateWalkUs;
        replayCopyUs += sample.replayCopyUs;
        referencedTextures += sample.referencedTextures;
        referencedUboBindings += sample.referencedUboBindings;
        referencedSsboBindings += sample.referencedSsboBindings;
        referencedAtomicBindings += sample.referencedAtomicBindings;
        replayCopyBytes += sample.replayCopyBytes;
        validateHash ^= sample.validateHash;
        if (sample.validateWalkUs > 0.0) {
            ++validateWalks;
        }
        if (sample.replayCopyUs > 0.0) {
            ++replayCopies;
        }
    }

    void recordPlanKey(double us) {
        if (!enabled) {
            return;
        }
        ++planKeyCalls;
        planKeyUs += us;
    }

    void dump() const {
        if (!enabled || draws == 0) {
            return;
        }
        const double denom = static_cast<double>(draws);
        const double hitRate = coarseCandidates > 0
            ? static_cast<double>(coarseHits) /
                  static_cast<double>(coarseCandidates)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_BINDING_CONSTRUCTION_SIZING] summary draws=%llu "
            "coarse_candidates=%llu coarse_hits=%llu coarse_misses=%llu "
            "coarse_hit_rate=%.6f key_read_compare_us=%.3f "
            "avg_key_read_compare_us=%.3f uniform_pack_us=%.3f "
            "avg_uniform_pack_us=%.3f sampler_resolve_us=%.3f "
            "avg_sampler_resolve_us=%.3f ubo_resolve_us=%.3f "
            "avg_ubo_resolve_us=%.3f ssbo_atomic_resolve_us=%.3f "
            "avg_ssbo_atomic_resolve_us=%.3f image_resolve_us=%.3f "
            "avg_image_resolve_us=%.3f validate_walks=%llu "
            "validate_walk_us=%.3f avg_validate_walk_us=%.3f "
            "replay_copies=%llu replay_copy_us=%.3f "
            "avg_replay_copy_us=%.3f replay_copy_bytes=%llu "
            "plan_key_calls=%llu plan_key_us=%.3f avg_plan_key_us=%.3f "
            "referenced_textures=%llu referenced_ubos=%llu "
            "referenced_ssbos=%llu referenced_atomics=%llu "
            "validate_hash=0x%016llx\n",
            static_cast<unsigned long long>(draws),
            static_cast<unsigned long long>(coarseCandidates),
            static_cast<unsigned long long>(coarseHits),
            static_cast<unsigned long long>(coarseMisses),
            hitRate,
            keyReadCompareUs,
            keyReadCompareUs / denom,
            uniformPackUs,
            uniformPackUs / denom,
            samplerResolveUs,
            samplerResolveUs / denom,
            uboResolveUs,
            uboResolveUs / denom,
            ssboAtomicResolveUs,
            ssboAtomicResolveUs / denom,
            imageResolveUs,
            imageResolveUs / denom,
            static_cast<unsigned long long>(validateWalks),
            validateWalkUs,
            validateWalkUs / denom,
            static_cast<unsigned long long>(replayCopies),
            replayCopyUs,
            replayCopyUs / denom,
            static_cast<unsigned long long>(replayCopyBytes),
            static_cast<unsigned long long>(planKeyCalls),
            planKeyUs,
            planKeyCalls > 0
                ? planKeyUs / static_cast<double>(planKeyCalls)
                : 0.0,
            static_cast<unsigned long long>(referencedTextures),
            static_cast<unsigned long long>(referencedUboBindings),
            static_cast<unsigned long long>(referencedSsboBindings),
            static_cast<unsigned long long>(referencedAtomicBindings),
            static_cast<unsigned long long>(validateHash));
        std::fflush(stderr);
    }

    std::string diagnosticsJson() const {
        if (!enabled || draws == 0) {
            return std::string();
        }
        const double hitRate = coarseCandidates > 0
            ? static_cast<double>(coarseHits) /
                  static_cast<double>(coarseCandidates)
            : 0.0;
        std::ostringstream out;
        out << "{\"draws\":" << draws
            << ",\"coarseCandidates\":" << coarseCandidates
            << ",\"coarseHits\":" << coarseHits
            << ",\"coarseMisses\":" << coarseMisses
            << ",\"coarseHitRate\":" << hitRate
            << ",\"keyReadCompareUs\":" << keyReadCompareUs
            << ",\"uniformPackUs\":" << uniformPackUs
            << ",\"samplerResolveUs\":" << samplerResolveUs
            << ",\"uboResolveUs\":" << uboResolveUs
            << ",\"ssboAtomicResolveUs\":" << ssboAtomicResolveUs
            << ",\"imageResolveUs\":" << imageResolveUs
            << ",\"validateWalks\":" << validateWalks
            << ",\"validateWalkUs\":" << validateWalkUs
            << ",\"replayCopies\":" << replayCopies
            << ",\"replayCopyUs\":" << replayCopyUs
            << ",\"replayCopyBytes\":" << replayCopyBytes
            << ",\"planKeyCalls\":" << planKeyCalls
            << ",\"planKeyUs\":" << planKeyUs
            << ",\"referencedTextures\":" << referencedTextures
            << ",\"referencedUboBindings\":" << referencedUboBindings
            << ",\"referencedSsboBindings\":" << referencedSsboBindings
            << ",\"referencedAtomicBindings\":" << referencedAtomicBindings
            << ",\"validateHash\":" << validateHash
            << "}";
        return out.str();
    }
};

struct ClearColorAttachmentSizingProfile {
    enum class EncoderClass : std::uint8_t {
        NoFrameGraph,
        NoMetalTexture,
        NoOpenEncoder,
        SameTargetEncoder,
        OtherTargetEncoder,
    };

    enum class F1FallbackReason : std::uint8_t {
        None,
        Scissor,
        ColorMask,
        PartialCoverage,
        NoFrameGraph,
        NoMetalTexture,
        Multisample,
        TextureTarget,
        Format,
        RenderbufferNativeBpp,
        ZeroArea,
    };

    bool enabled = bindingConstructionSizingEnabled();
    std::uint64_t clearCalls = 0;
    std::uint64_t clearBytesCleared = 0;
    // Mutually-exclusive outcome partition. Exactly one of these increments
    // per recorded clear.
    std::uint64_t clearsViaLoadAction = 0;
    std::uint64_t clearsCpuSide = 0;
    std::uint64_t clearsMidPass = 0;
    // Independent facts for clears that legitimately do more than one thing
    // today, such as CPU shadow fill plus deferred GPU loadAction clear.
    std::uint64_t clearsLoadActionRouted = 0;
    std::uint64_t clearsCpuSideObserved = 0;
    std::uint64_t clearsMidPassObserved = 0;
    std::uint64_t clearsLoadActionEligibleAtPassStart = 0;
    std::uint64_t clearMemsetBytes = 0;
    std::uint64_t clearDescriptorRebuildCalls = 0;
    std::uint64_t clearViaDrawCalls = 0;
    std::uint64_t f1ClassifierCalls = 0;
    std::uint64_t f1TextureAttachments = 0;
    std::uint64_t f1RenderbufferAttachments = 0;
    std::uint64_t f1FullUnmasked = 0;
    std::uint64_t f1Scissor = 0;
    std::uint64_t f1ColorMask = 0;
    std::uint64_t f1PartialCoverage = 0;
    std::uint64_t f1FramebufferColorClearCalls = 0;
    std::uint64_t f1FramebufferColorClearSlots = 0;
    std::uint64_t f1FramebufferMrtClearCalls = 0;
    std::uint64_t f1EncoderNoFrameGraph = 0;
    std::uint64_t f1EncoderNoMetalTexture = 0;
    std::uint64_t f1EncoderNoOpen = 0;
    std::uint64_t f1EncoderSameTarget = 0;
    std::uint64_t f1EncoderOtherTarget = 0;
    std::uint64_t f1Eligible = 0;
    std::uint64_t f1FallbackScissor = 0;
    std::uint64_t f1FallbackColorMask = 0;
    std::uint64_t f1FallbackPartialCoverage = 0;
    std::uint64_t f1FallbackNoFrameGraph = 0;
    std::uint64_t f1FallbackNoMetalTexture = 0;
    std::uint64_t f1FallbackMultisample = 0;
    std::uint64_t f1FallbackTextureTarget = 0;
    std::uint64_t f1FallbackFormat = 0;
    std::uint64_t f1FallbackRenderbufferNativeBpp = 0;
    std::uint64_t f1FallbackZeroArea = 0;
    double clearMemsetUs = 0.0;
    double clearDescriptorRebuildUs = 0.0;
    double clearViaDrawUs = 0.0;

    void recordCall(std::uint64_t bytes, bool midPass) {
        if (!enabled) {
            return;
        }
        ++clearCalls;
        clearBytesCleared += bytes;
        if (midPass) {
            ++clearsMidPassObserved;
        }
    }

    void recordCpuSide(double us, std::uint64_t bytes) {
        if (!enabled) {
            return;
        }
        ++clearsCpuSideObserved;
        clearMemsetUs += us;
        clearMemsetBytes += bytes;
    }

    void recordLoadAction(double us) {
        if (!enabled) {
            return;
        }
        ++clearsLoadActionRouted;
        ++clearDescriptorRebuildCalls;
        clearDescriptorRebuildUs += us;
    }

    void recordPartition(bool midPassAtClearStart,
                         bool cpuSideObserved,
                         bool loadActionRouted) {
        if (!enabled) {
            return;
        }
        if (loadActionRouted && !midPassAtClearStart) {
            ++clearsLoadActionEligibleAtPassStart;
        }
        if (midPassAtClearStart) {
            ++clearsMidPass;
        } else if (loadActionRouted) {
            ++clearsViaLoadAction;
        } else if (cpuSideObserved) {
            ++clearsCpuSide;
        } else {
            ++clearsCpuSide;
        }
    }

    void recordFramebufferColorClear(std::uint64_t activeSlots) {
        if (!enabled) {
            return;
        }
        ++f1FramebufferColorClearCalls;
        f1FramebufferColorClearSlots += activeSlots;
        if (activeSlots > 1) {
            ++f1FramebufferMrtClearCalls;
        }
    }

    void recordF1Classifier(bool textureAttachment,
                            bool renderbufferAttachment,
                            bool scissorActive,
                            bool fullColorMask,
                            bool fullCoverage,
                            EncoderClass encoderClass,
                            bool eligible,
                            F1FallbackReason fallbackReason) {
        if (!enabled) {
            return;
        }
        ++f1ClassifierCalls;
        if (textureAttachment) {
            ++f1TextureAttachments;
        }
        if (renderbufferAttachment) {
            ++f1RenderbufferAttachments;
        }
        if (!scissorActive && fullColorMask && fullCoverage) {
            ++f1FullUnmasked;
        }
        if (scissorActive) {
            ++f1Scissor;
        }
        if (!fullColorMask) {
            ++f1ColorMask;
        }
        if (!fullCoverage) {
            ++f1PartialCoverage;
        }
        switch (encoderClass) {
            case EncoderClass::NoFrameGraph:
                ++f1EncoderNoFrameGraph;
                break;
            case EncoderClass::NoMetalTexture:
                ++f1EncoderNoMetalTexture;
                break;
            case EncoderClass::NoOpenEncoder:
                ++f1EncoderNoOpen;
                break;
            case EncoderClass::SameTargetEncoder:
                ++f1EncoderSameTarget;
                break;
            case EncoderClass::OtherTargetEncoder:
                ++f1EncoderOtherTarget;
                break;
        }
        if (eligible) {
            ++f1Eligible;
            return;
        }
        switch (fallbackReason) {
            case F1FallbackReason::None:
                break;
            case F1FallbackReason::Scissor:
                ++f1FallbackScissor;
                break;
            case F1FallbackReason::ColorMask:
                ++f1FallbackColorMask;
                break;
            case F1FallbackReason::PartialCoverage:
                ++f1FallbackPartialCoverage;
                break;
            case F1FallbackReason::NoFrameGraph:
                ++f1FallbackNoFrameGraph;
                break;
            case F1FallbackReason::NoMetalTexture:
                ++f1FallbackNoMetalTexture;
                break;
            case F1FallbackReason::Multisample:
                ++f1FallbackMultisample;
                break;
            case F1FallbackReason::TextureTarget:
                ++f1FallbackTextureTarget;
                break;
            case F1FallbackReason::Format:
                ++f1FallbackFormat;
                break;
            case F1FallbackReason::RenderbufferNativeBpp:
                ++f1FallbackRenderbufferNativeBpp;
                break;
            case F1FallbackReason::ZeroArea:
                ++f1FallbackZeroArea;
                break;
        }
    }

    void dump() const {
        if (!enabled || clearCalls == 0) {
            return;
        }
        const double denom = static_cast<double>(clearCalls);
        std::fprintf(stderr,
            "[APPGL_CLEAR_COLOR_ATTACHMENT_SIZING] summary clear_calls=%llu "
            "clear_bytes=%llu clears_via_load_action=%llu clears_cpu_side=%llu "
            "clears_mid_pass=%llu clears_load_action_routed=%llu "
            "clears_cpu_side_observed=%llu clears_mid_pass_observed=%llu "
            "clears_load_action_eligible_at_pass_start=%llu clear_memset_us=%.3f "
            "avg_clear_memset_us=%.3f clear_memset_bytes=%llu "
            "clear_descriptor_rebuild_us=%.3f clear_descriptor_rebuild_calls=%llu "
            "avg_clear_descriptor_rebuild_us=%.3f clear_via_draw_us=%.3f "
            "clear_via_draw_calls=%llu avg_clear_via_draw_us=%.3f\n",
            static_cast<unsigned long long>(clearCalls),
            static_cast<unsigned long long>(clearBytesCleared),
            static_cast<unsigned long long>(clearsViaLoadAction),
            static_cast<unsigned long long>(clearsCpuSide),
            static_cast<unsigned long long>(clearsMidPass),
            static_cast<unsigned long long>(clearsLoadActionRouted),
            static_cast<unsigned long long>(clearsCpuSideObserved),
            static_cast<unsigned long long>(clearsMidPassObserved),
            static_cast<unsigned long long>(
                clearsLoadActionEligibleAtPassStart),
            clearMemsetUs,
            clearMemsetUs / denom,
            static_cast<unsigned long long>(clearMemsetBytes),
            clearDescriptorRebuildUs,
            static_cast<unsigned long long>(clearDescriptorRebuildCalls),
            clearDescriptorRebuildCalls > 0
                ? clearDescriptorRebuildUs /
                    static_cast<double>(clearDescriptorRebuildCalls)
                : 0.0,
            clearViaDrawUs,
            static_cast<unsigned long long>(clearViaDrawCalls),
            clearViaDrawCalls > 0
                ? clearViaDrawUs / static_cast<double>(clearViaDrawCalls)
                : 0.0);
        std::fprintf(stderr,
            "[APPGL_CLEAR_F1_CLASSIFIER] summary calls=%llu texture=%llu "
            "renderbuffer=%llu full_unmasked=%llu scissor=%llu color_mask=%llu "
            "partial_coverage=%llu fbo_color_clears=%llu fbo_color_slots=%llu "
            "mrt_clears=%llu encoder_no_frame_graph=%llu "
            "encoder_no_metal_texture=%llu encoder_no_open=%llu "
            "encoder_same_target=%llu encoder_other_target=%llu "
            "eligible=%llu fallback_scissor=%llu fallback_color_mask=%llu "
            "fallback_partial_coverage=%llu fallback_no_frame_graph=%llu "
            "fallback_no_metal_texture=%llu fallback_multisample=%llu "
            "fallback_texture_target=%llu fallback_format=%llu "
            "fallback_renderbuffer_native_bpp=%llu fallback_zero_area=%llu\n",
            static_cast<unsigned long long>(f1ClassifierCalls),
            static_cast<unsigned long long>(f1TextureAttachments),
            static_cast<unsigned long long>(f1RenderbufferAttachments),
            static_cast<unsigned long long>(f1FullUnmasked),
            static_cast<unsigned long long>(f1Scissor),
            static_cast<unsigned long long>(f1ColorMask),
            static_cast<unsigned long long>(f1PartialCoverage),
            static_cast<unsigned long long>(f1FramebufferColorClearCalls),
            static_cast<unsigned long long>(f1FramebufferColorClearSlots),
            static_cast<unsigned long long>(f1FramebufferMrtClearCalls),
            static_cast<unsigned long long>(f1EncoderNoFrameGraph),
            static_cast<unsigned long long>(f1EncoderNoMetalTexture),
            static_cast<unsigned long long>(f1EncoderNoOpen),
            static_cast<unsigned long long>(f1EncoderSameTarget),
            static_cast<unsigned long long>(f1EncoderOtherTarget),
            static_cast<unsigned long long>(f1Eligible),
            static_cast<unsigned long long>(f1FallbackScissor),
            static_cast<unsigned long long>(f1FallbackColorMask),
            static_cast<unsigned long long>(f1FallbackPartialCoverage),
            static_cast<unsigned long long>(f1FallbackNoFrameGraph),
            static_cast<unsigned long long>(f1FallbackNoMetalTexture),
            static_cast<unsigned long long>(f1FallbackMultisample),
            static_cast<unsigned long long>(f1FallbackTextureTarget),
            static_cast<unsigned long long>(f1FallbackFormat),
            static_cast<unsigned long long>(f1FallbackRenderbufferNativeBpp),
            static_cast<unsigned long long>(f1FallbackZeroArea));
        std::fflush(stderr);
    }

    std::string diagnosticsJson() const {
        if (!enabled || clearCalls == 0) {
            return std::string();
        }
        std::ostringstream out;
        out << "{\"clearCalls\":" << clearCalls
            << ",\"clearBytesCleared\":" << clearBytesCleared
            << ",\"clearsViaLoadAction\":" << clearsViaLoadAction
            << ",\"clearsCpuSide\":" << clearsCpuSide
            << ",\"clearsMidPass\":" << clearsMidPass
            << ",\"clearsLoadActionRouted\":"
            << clearsLoadActionRouted
            << ",\"clearsCpuSideObserved\":"
            << clearsCpuSideObserved
            << ",\"clearsMidPassObserved\":"
            << clearsMidPassObserved
            << ",\"clearsLoadActionEligibleAtPassStart\":"
            << clearsLoadActionEligibleAtPassStart
            << ",\"clearMemsetUs\":" << clearMemsetUs
            << ",\"clearMemsetBytes\":" << clearMemsetBytes
            << ",\"clearDescriptorRebuildUs\":"
            << clearDescriptorRebuildUs
            << ",\"clearDescriptorRebuildCalls\":"
            << clearDescriptorRebuildCalls
            << ",\"clearViaDrawUs\":" << clearViaDrawUs
            << ",\"clearViaDrawCalls\":" << clearViaDrawCalls
            << ",\"f1ClassifierCalls\":" << f1ClassifierCalls
            << ",\"f1TextureAttachments\":" << f1TextureAttachments
            << ",\"f1RenderbufferAttachments\":"
            << f1RenderbufferAttachments
            << ",\"f1FullUnmasked\":" << f1FullUnmasked
            << ",\"f1Scissor\":" << f1Scissor
            << ",\"f1ColorMask\":" << f1ColorMask
            << ",\"f1PartialCoverage\":" << f1PartialCoverage
            << ",\"f1FramebufferColorClearCalls\":"
            << f1FramebufferColorClearCalls
            << ",\"f1FramebufferColorClearSlots\":"
            << f1FramebufferColorClearSlots
            << ",\"f1FramebufferMrtClearCalls\":"
            << f1FramebufferMrtClearCalls
            << ",\"f1EncoderNoFrameGraph\":"
            << f1EncoderNoFrameGraph
            << ",\"f1EncoderNoMetalTexture\":"
            << f1EncoderNoMetalTexture
            << ",\"f1EncoderNoOpen\":" << f1EncoderNoOpen
            << ",\"f1EncoderSameTarget\":"
            << f1EncoderSameTarget
            << ",\"f1EncoderOtherTarget\":"
            << f1EncoderOtherTarget
            << ",\"f1Eligible\":" << f1Eligible
            << ",\"f1FallbackScissor\":"
            << f1FallbackScissor
            << ",\"f1FallbackColorMask\":"
            << f1FallbackColorMask
            << ",\"f1FallbackPartialCoverage\":"
            << f1FallbackPartialCoverage
            << ",\"f1FallbackNoFrameGraph\":"
            << f1FallbackNoFrameGraph
            << ",\"f1FallbackNoMetalTexture\":"
            << f1FallbackNoMetalTexture
            << ",\"f1FallbackMultisample\":"
            << f1FallbackMultisample
            << ",\"f1FallbackTextureTarget\":"
            << f1FallbackTextureTarget
            << ",\"f1FallbackFormat\":" << f1FallbackFormat
            << ",\"f1FallbackRenderbufferNativeBpp\":"
            << f1FallbackRenderbufferNativeBpp
            << ",\"f1FallbackZeroArea\":"
            << f1FallbackZeroArea
            << "}";
        return out.str();
    }
};

static void bindingConstructionHashMix(std::uint64_t& hash,
                                       std::uint64_t value) {
    hash ^= value + 0x9e3779b97f4a7c15ull + (hash << 6u) + (hash >> 2u);
}

static BindingConstructionSizingKey bindingConstructionSizingKeyFor(
    const GLStateTracker& state,
    const GLProgramObject& program,
    const TranslatedDrawInfo& info)
{
    BindingConstructionSizingKey key;
    key.program = info.program;
    key.programPipeline = state.currentProgramPipeline();
    key.programObjectSerial = program.objectSerial;
    key.executableGeneration = program.executableGeneration;
    key.samplerUniformGeneration = program.samplerUniformValueGen;
    key.samplerRecipeGeneration = program.samplerBindingRecipeGeneration;
    key.globalStateGeneration = state.stateGeneration();
    key.textureDomainGeneration =
        state.domainGeneration(GLStateTracker::kDomainTexture);
    key.bufferDomainGeneration =
        state.domainGeneration(GLStateTracker::kDomainBuffer);
    key.programDomainGeneration =
        state.domainGeneration(GLStateTracker::kDomainProgram);
    key.vertexReflection =
        reinterpret_cast<std::uintptr_t>(info.vertexReflection);
    key.fragmentReflection =
        reinterpret_cast<std::uintptr_t>(info.fragmentReflection);
    key.vertexMsl = reinterpret_cast<std::uintptr_t>(info.vertexMSL);
    key.fragmentMsl = reinterpret_cast<std::uintptr_t>(info.fragmentMSL);
    key.resourceUniformBlockCount =
        static_cast<std::uint32_t>(program.resourceUniformBlocks.size());
    key.resourceStorageBlockCount =
        static_cast<std::uint32_t>(program.resourceStorageBlocks.size());
    key.resourceAtomicBlockCount =
        static_cast<std::uint32_t>(program.resourceAtomicCounterBuffers.size());
    key.vertexUsesArgumentBuffer = info.vertexMslUsesArgumentBuffer;
    key.fragmentUsesArgumentBuffer = info.fragmentMslUsesArgumentBuffer;
    return key;
}

static void bindingConstructionSizingValidateWalk(
    const TranslatedDrawInfo& info,
    BindingConstructionSizingSample& sample)
{
    std::uint64_t hash = 1469598103934665603ull;
    auto walkTextures =
        [&](const std::vector<TranslatedDrawInfo::TextureBinding>& textures) {
            sample.referencedTextures +=
                static_cast<std::uint64_t>(textures.size());
            for (const auto& binding : textures) {
                bindingConstructionHashMix(hash, binding.textureName);
                bindingConstructionHashMix(
                    hash,
                    reinterpret_cast<std::uintptr_t>(binding.metalTexture));
                bindingConstructionHashMix(
                    hash,
                    reinterpret_cast<std::uintptr_t>(
                        binding.metalSamplerState));
                bindingConstructionHashMix(
                    hash,
                    reinterpret_cast<std::uintptr_t>(
                        binding.textureBufferBackingMetalBuffer));
                bindingConstructionHashMix(
                    hash,
                    reinterpret_cast<std::uintptr_t>(
                        binding.imageAtomicMetalBuffer));
                bindingConstructionHashMix(hash, binding.metalSlot);
            }
        };
    walkTextures(info.fragmentTextures);
    walkTextures(info.vertexTextures);
    sample.referencedUboBindings =
        static_cast<std::uint64_t>(info.uboBindings.size());
    for (const auto& ubo : info.uboBindings) {
        bindingConstructionHashMix(hash, ubo.glBufferName);
        bindingConstructionHashMix(
            hash, reinterpret_cast<std::uintptr_t>(ubo.metalBuffer));
        bindingConstructionHashMix(hash, ubo.metalBufferOffset);
        bindingConstructionHashMix(hash, ubo.size);
        bindingConstructionHashMix(hash, ubo.metalSlot);
    }
    sample.referencedSsboBindings =
        static_cast<std::uint64_t>(info.ssboBindings.size());
    for (const auto& ssbo : info.ssboBindings) {
        bindingConstructionHashMix(hash, ssbo.glBufferName);
        bindingConstructionHashMix(
            hash, reinterpret_cast<std::uintptr_t>(ssbo.metalBuffer));
        bindingConstructionHashMix(hash, ssbo.offset);
        bindingConstructionHashMix(hash, ssbo.size);
        bindingConstructionHashMix(hash, ssbo.metalSlot);
    }
    sample.referencedAtomicBindings =
        static_cast<std::uint64_t>(info.atomicCounterBindings.size());
    for (const auto& atomic : info.atomicCounterBindings) {
        bindingConstructionHashMix(hash, atomic.glBufferName);
        bindingConstructionHashMix(
            hash, reinterpret_cast<std::uintptr_t>(atomic.metalBuffer));
        bindingConstructionHashMix(hash, atomic.offset);
        bindingConstructionHashMix(hash, atomic.metalSlot);
    }
    sample.validateHash = hash;
}

static std::uint64_t bindingConstructionSizingReplayCopyBytes(
    const TranslatedDrawInfo& info)
{
    std::uint64_t bytes = 0;
    bytes += static_cast<std::uint64_t>(
        info.fragmentTextures.size() *
        sizeof(TranslatedDrawInfo::TextureBinding));
    bytes += static_cast<std::uint64_t>(
        info.vertexTextures.size() *
        sizeof(TranslatedDrawInfo::TextureBinding));
    bytes += static_cast<std::uint64_t>(
        info.uboBindings.size() * sizeof(TranslatedDrawInfo::UBOBinding));
    bytes += static_cast<std::uint64_t>(
        info.ssboBindings.size() * sizeof(TranslatedDrawInfo::SSBOBinding));
    bytes += static_cast<std::uint64_t>(
        info.atomicCounterBindings.size() *
        sizeof(TranslatedDrawInfo::AtomicCounterBinding));
    bytes += static_cast<std::uint64_t>(
        info.sampledTextureNames.size() * sizeof(GLuint));
    bytes += static_cast<std::uint64_t>(
        info.readImageTextureNames.size() * sizeof(GLuint));
    bytes += static_cast<std::uint64_t>(
        info.writtenImageTextureNames.size() * sizeof(GLuint));
    return bytes;
}

static void bindingConstructionSizingReplayCopyWalk(
    const TranslatedDrawInfo& info,
    BindingConstructionSizingSample& sample)
{
    thread_local std::vector<TranslatedDrawInfo::TextureBinding> fragTextures;
    thread_local std::vector<TranslatedDrawInfo::TextureBinding> vertTextures;
    thread_local std::vector<TranslatedDrawInfo::UBOBinding> ubos;
    thread_local std::vector<TranslatedDrawInfo::SSBOBinding> ssbos;
    thread_local std::vector<TranslatedDrawInfo::AtomicCounterBinding> atomics;
    thread_local std::vector<GLuint> sampledNames;
    thread_local std::vector<GLuint> readImageNames;
    thread_local std::vector<GLuint> writtenImageNames;
    fragTextures = info.fragmentTextures;
    vertTextures = info.vertexTextures;
    ubos = info.uboBindings;
    ssbos = info.ssboBindings;
    atomics = info.atomicCounterBindings;
    sampledNames = info.sampledTextureNames;
    readImageNames = info.readImageTextureNames;
    writtenImageNames = info.writtenImageTextureNames;
    sample.replayCopyBytes = bindingConstructionSizingReplayCopyBytes(info);
}

static std::size_t glProducerTokenKindIndex(
    GLProducerTokenResourceKind kind) {
    switch (kind) {
        case GLProducerTokenResourceKind::Texture: return 0;
        case GLProducerTokenResourceKind::Renderbuffer: return 1;
        case GLProducerTokenResourceKind::Buffer: return 2;
    }
    return 0;
}

static const char* glProducerTokenKindName(
    GLProducerTokenResourceKind kind) {
    switch (kind) {
        case GLProducerTokenResourceKind::Texture: return "texture";
        case GLProducerTokenResourceKind::Renderbuffer: return "renderbuffer";
        case GLProducerTokenResourceKind::Buffer: return "buffer";
    }
    return "unknown";
}

enum class SamplerGpuOrderSkipBlockReason {
    None,
    LegacyMsaa,
    NonTexture,
    NoToken,
    TokenKind,
    TokenName,
    Ordering,
    ProducerBits,
};

struct GLProducerTokenProfile {
    bool enabled =
        std::getenv("APPGL_GL_DRAW_PROFILE") != nullptr ||
        std::getenv("APPGL_GL_PRODUCER_TOKEN_PROFILE") != nullptr;

    std::uint64_t markEntries = 0;
    std::uint64_t markSkippedZero = 0;
    std::uint64_t tokensMarked = 0;
    std::uint64_t tokenMergedMarks = 0;
    std::uint64_t textureAliasMarks = 0;
    std::uint64_t textureAliasFanout = 0;
    std::uint64_t bufferGpuAuthoredMarks = 0;

    std::uint64_t drainCalls = 0;
    std::uint64_t drainNoops = 0;
    std::uint64_t drainFlushes = 0;
    std::uint64_t drainNoFrameGraph = 0;
    std::uint64_t drainResourcesScanned = 0;
    std::uint64_t drainPendingHits = 0;
    std::uint64_t drainLegacyMsaaHits = 0;
    std::uint64_t drainCompletedSkipCandidates = 0;
    std::uint64_t drainGpuOrderedCandidates = 0;
    std::uint64_t drainUnmodeledTokenHits = 0;
    std::uint64_t drainResourcesCleared = 0;

    std::uint64_t directDrainCalls = 0;
    std::uint64_t directDrainNoops = 0;
    std::uint64_t directDrainFlushes = 0;
    std::uint64_t directDrainLegacyMsaaHits = 0;

    std::uint64_t samplerReadSets = 0;
    std::uint64_t samplerPendingReadSets = 0;
    std::uint64_t samplerFlushCandidates = 0;
    std::uint64_t samplerResourcesScanned = 0;
    std::uint64_t samplerPendingHits = 0;
    std::uint64_t samplerLegacyMsaaHits = 0;
    std::uint64_t samplerCompletedSkipCandidates = 0;
    std::uint64_t samplerGpuOrderedCandidates = 0;
    std::uint64_t samplerUnmodeledTokenHits = 0;
    std::uint64_t samplerGpuOrderSkips = 0;
    std::uint64_t samplerGpuOrderSkipResources = 0;
    std::uint64_t samplerGpuOrderSkipBlocked = 0;
    std::uint64_t samplerGpuOrderSkipBlockedLegacyMsaa = 0;
    std::uint64_t samplerGpuOrderSkipBlockedNonTexture = 0;
    std::uint64_t samplerGpuOrderSkipBlockedNoToken = 0;
    std::uint64_t samplerGpuOrderSkipBlockedTokenKind = 0;
    std::uint64_t samplerGpuOrderSkipBlockedTokenName = 0;
    std::uint64_t samplerGpuOrderSkipBlockedOrdering = 0;
    std::uint64_t samplerGpuOrderSkipBlockedProducerBits = 0;
    std::uint64_t samplerGpuOrderSkipPressureFlushes = 0;
    std::uint64_t samplerGpuOrderSkipGuardedInflight = 0;
    std::uint64_t samplerGpuOrderSkipGuardedPeriodic = 0;
    std::uint64_t samplerGpuOrderSkipGuardedMemory = 0;

    std::uint64_t translatedDrawFboWrites = 0;
    std::uint64_t translatedDrawStorageImageWrites = 0;
    std::uint64_t translatedDrawSsboWrites = 0;
    std::uint64_t translatedDrawAtomicCounterWrites = 0;

    std::array<std::uint64_t, 3> marksByKind{};
    std::array<std::uint64_t, 3> drainPendingHitsByKind{};
    std::array<std::uint64_t, 3> drainCompletedSkipCandidatesByKind{};
    std::array<std::uint64_t, 3> drainGpuOrderedCandidatesByKind{};
    std::array<std::uint64_t, 3> drainClearsByKind{};
    std::array<std::uint64_t, 3> samplerPendingHitsByKind{};
    std::array<std::uint64_t, 3> samplerCompletedSkipCandidatesByKind{};
    std::array<std::uint64_t, 3> samplerGpuOrderedCandidatesByKind{};

    void recordMark(GLProducerTokenResourceKind kind) {
        if (!enabled) return;
        ++tokensMarked;
        ++marksByKind[glProducerTokenKindIndex(kind)];
    }

    void recordDrainPendingHit(GLProducerTokenResourceKind kind,
                               bool knownCompleted,
                               bool sameQueueOrdered,
                               bool hasToken) {
        if (!enabled) return;
        const std::size_t idx = glProducerTokenKindIndex(kind);
        ++drainPendingHits;
        ++drainPendingHitsByKind[idx];
        if (!hasToken) {
            ++drainUnmodeledTokenHits;
        }
        if (knownCompleted) {
            ++drainCompletedSkipCandidates;
            ++drainCompletedSkipCandidatesByKind[idx];
        }
        if (sameQueueOrdered) {
            ++drainGpuOrderedCandidates;
            ++drainGpuOrderedCandidatesByKind[idx];
        }
    }

    void recordSamplerPendingHit(GLProducerTokenResourceKind kind,
                                 bool knownCompleted,
                                 bool sameQueueOrdered,
                                 bool hasToken) {
        if (!enabled) return;
        const std::size_t idx = glProducerTokenKindIndex(kind);
        ++samplerPendingHits;
        ++samplerPendingHitsByKind[idx];
        if (!hasToken) {
            ++samplerUnmodeledTokenHits;
        }
        if (knownCompleted) {
            ++samplerCompletedSkipCandidates;
            ++samplerCompletedSkipCandidatesByKind[idx];
        }
        if (sameQueueOrdered) {
            ++samplerGpuOrderedCandidates;
            ++samplerGpuOrderedCandidatesByKind[idx];
        }
    }

    void recordClear(GLProducerTokenResourceKind kind) {
        if (!enabled) return;
        ++drainResourcesCleared;
        ++drainClearsByKind[glProducerTokenKindIndex(kind)];
    }

    void recordSamplerGpuOrderSkipBlock(
        SamplerGpuOrderSkipBlockReason reason) {
        if (!enabled) return;
        switch (reason) {
            case SamplerGpuOrderSkipBlockReason::LegacyMsaa:
                ++samplerGpuOrderSkipBlockedLegacyMsaa;
                break;
            case SamplerGpuOrderSkipBlockReason::NonTexture:
                ++samplerGpuOrderSkipBlockedNonTexture;
                break;
            case SamplerGpuOrderSkipBlockReason::NoToken:
                ++samplerGpuOrderSkipBlockedNoToken;
                break;
            case SamplerGpuOrderSkipBlockReason::TokenKind:
                ++samplerGpuOrderSkipBlockedTokenKind;
                break;
            case SamplerGpuOrderSkipBlockReason::TokenName:
                ++samplerGpuOrderSkipBlockedTokenName;
                break;
            case SamplerGpuOrderSkipBlockReason::Ordering:
                ++samplerGpuOrderSkipBlockedOrdering;
                break;
            case SamplerGpuOrderSkipBlockReason::ProducerBits:
                ++samplerGpuOrderSkipBlockedProducerBits;
                break;
            case SamplerGpuOrderSkipBlockReason::None:
                break;
        }
    }

    void dump(std::uint64_t tokenEpoch,
              std::uint64_t knownCompletedEpoch) const {
        if (!enabled) {
            return;
        }
        const bool hasSamples =
            markEntries != 0 ||
            tokensMarked != 0 ||
            drainCalls != 0 ||
            directDrainCalls != 0 ||
            samplerReadSets != 0;
        if (!hasSamples && tokenEpoch == 0) {
            return;
        }
        std::fprintf(stderr,
            "[APPGL_GL_PRODUCER_TOKEN_PROFILE] summary "
            "token_epoch=%llu known_completed_epoch=%llu "
            "mark_entries=%llu mark_skipped_zero=%llu tokens_marked=%llu "
            "token_merged_marks=%llu texture_alias_marks=%llu "
            "texture_alias_fanout=%llu "
            "buffer_gpu_authored_marks=%llu drain_calls=%llu "
            "drain_noops=%llu drain_flushes=%llu drain_no_framegraph=%llu "
            "drain_scanned=%llu drain_pending_hits=%llu "
            "drain_legacy_msaa_hits=%llu completed_skip_candidates=%llu "
            "gpu_ordered_candidates=%llu unmodeled_token_hits=%llu "
            "drain_cleared=%llu direct_drain_calls=%llu "
            "direct_drain_noops=%llu direct_drain_flushes=%llu "
            "direct_drain_legacy_msaa_hits=%llu\n",
            static_cast<unsigned long long>(tokenEpoch),
            static_cast<unsigned long long>(knownCompletedEpoch),
            static_cast<unsigned long long>(markEntries),
            static_cast<unsigned long long>(markSkippedZero),
            static_cast<unsigned long long>(tokensMarked),
            static_cast<unsigned long long>(tokenMergedMarks),
            static_cast<unsigned long long>(textureAliasMarks),
            static_cast<unsigned long long>(textureAliasFanout),
            static_cast<unsigned long long>(bufferGpuAuthoredMarks),
            static_cast<unsigned long long>(drainCalls),
            static_cast<unsigned long long>(drainNoops),
            static_cast<unsigned long long>(drainFlushes),
            static_cast<unsigned long long>(drainNoFrameGraph),
            static_cast<unsigned long long>(drainResourcesScanned),
            static_cast<unsigned long long>(drainPendingHits),
            static_cast<unsigned long long>(drainLegacyMsaaHits),
            static_cast<unsigned long long>(drainCompletedSkipCandidates),
            static_cast<unsigned long long>(drainGpuOrderedCandidates),
            static_cast<unsigned long long>(drainUnmodeledTokenHits),
            static_cast<unsigned long long>(drainResourcesCleared),
            static_cast<unsigned long long>(directDrainCalls),
            static_cast<unsigned long long>(directDrainNoops),
            static_cast<unsigned long long>(directDrainFlushes),
            static_cast<unsigned long long>(directDrainLegacyMsaaHits));
        std::fprintf(stderr,
            "[APPGL_GL_PRODUCER_TOKEN_PROFILE] sampler read_sets=%llu "
            "pending_read_sets=%llu flush_candidates=%llu scanned=%llu "
            "pending_hits=%llu legacy_msaa_hits=%llu "
            "completed_skip_candidates=%llu gpu_ordered_candidates=%llu "
            "unmodeled_token_hits=%llu gpu_order_skips=%llu "
            "gpu_order_skip_resources=%llu gpu_order_skip_blocked=%llu "
            "gpu_order_skip_blocked_legacy_msaa=%llu "
            "gpu_order_skip_blocked_non_texture=%llu "
            "gpu_order_skip_blocked_no_token=%llu "
            "gpu_order_skip_blocked_token_kind=%llu "
            "gpu_order_skip_blocked_token_name=%llu "
            "gpu_order_skip_blocked_ordering=%llu "
            "gpu_order_skip_blocked_producer_bits=%llu "
            "gpu_order_skip_pressure_flushes=%llu "
            "gpu_order_skip_guarded_inflight=%llu "
            "gpu_order_skip_guarded_periodic=%llu "
            "gpu_order_skip_guarded_memory=%llu\n",
            static_cast<unsigned long long>(samplerReadSets),
            static_cast<unsigned long long>(samplerPendingReadSets),
            static_cast<unsigned long long>(samplerFlushCandidates),
            static_cast<unsigned long long>(samplerResourcesScanned),
            static_cast<unsigned long long>(samplerPendingHits),
            static_cast<unsigned long long>(samplerLegacyMsaaHits),
            static_cast<unsigned long long>(samplerCompletedSkipCandidates),
            static_cast<unsigned long long>(samplerGpuOrderedCandidates),
            static_cast<unsigned long long>(samplerUnmodeledTokenHits),
            static_cast<unsigned long long>(samplerGpuOrderSkips),
            static_cast<unsigned long long>(samplerGpuOrderSkipResources),
            static_cast<unsigned long long>(samplerGpuOrderSkipBlocked),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipBlockedLegacyMsaa),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipBlockedNonTexture),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipBlockedNoToken),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipBlockedTokenKind),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipBlockedTokenName),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipBlockedOrdering),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipBlockedProducerBits),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipPressureFlushes),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipGuardedInflight),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipGuardedPeriodic),
            static_cast<unsigned long long>(
                samplerGpuOrderSkipGuardedMemory));
        std::fprintf(stderr,
            "[APPGL_GL_PRODUCER_TOKEN_PROFILE] translated_draw_writes "
            "fbo=%llu storage_image=%llu ssbo=%llu atomic_counter=%llu\n",
            static_cast<unsigned long long>(translatedDrawFboWrites),
            static_cast<unsigned long long>(translatedDrawStorageImageWrites),
            static_cast<unsigned long long>(translatedDrawSsboWrites),
            static_cast<unsigned long long>(translatedDrawAtomicCounterWrites));
        for (GLProducerTokenResourceKind kind : {
                 GLProducerTokenResourceKind::Texture,
                 GLProducerTokenResourceKind::Renderbuffer,
                 GLProducerTokenResourceKind::Buffer}) {
            const std::size_t idx = glProducerTokenKindIndex(kind);
            std::fprintf(stderr,
                "[APPGL_GL_PRODUCER_TOKEN_PROFILE] resource_kind=%s "
                "marks=%llu drain_pending_hits=%llu "
                "drain_completed_skip_candidates=%llu "
                "drain_gpu_ordered_candidates=%llu drain_cleared=%llu "
                "sampler_pending_hits=%llu "
                "sampler_completed_skip_candidates=%llu "
                "sampler_gpu_ordered_candidates=%llu\n",
                glProducerTokenKindName(kind),
                static_cast<unsigned long long>(marksByKind[idx]),
                static_cast<unsigned long long>(drainPendingHitsByKind[idx]),
                static_cast<unsigned long long>(
                    drainCompletedSkipCandidatesByKind[idx]),
                static_cast<unsigned long long>(
                    drainGpuOrderedCandidatesByKind[idx]),
                static_cast<unsigned long long>(drainClearsByKind[idx]),
                static_cast<unsigned long long>(samplerPendingHitsByKind[idx]),
                static_cast<unsigned long long>(
                    samplerCompletedSkipCandidatesByKind[idx]),
                static_cast<unsigned long long>(
                    samplerGpuOrderedCandidatesByKind[idx]));
        }
        std::fflush(stderr);
    }
};

enum class ColdPathDiagnosticBucket : std::size_t {
    BoundaryBookkeeping,
    BoundaryHazardDecision,
    CacheKeyProgram,
    CacheKeyVaoLayout,
    CacheKeyFbo,
    CacheKeyBindings,
    CacheKeyFixedState,
    CacheKeyOther,
    ProgramVaoFboFp64Sidecars,
    ProgramVaoFboPrimitiveCounters,
    ProgramVaoFboFrontendVaoSource,
    ProgramVaoFboVaoSource,
    ProgramVaoFboGenericAttributes,
    ProgramVaoFboBoundFbo,
    ProgramVaoFboLayoutCache,
    ProgramVaoFboLayoutApply,
    SnapshotEstimate,
    Count,
};

struct ColdPathDiagnosticBucketStats {
    std::uint64_t count = 0;
    double totalUs = 0.0;
};

static const char* coldPathDiagnosticBucketName(
    ColdPathDiagnosticBucket bucket) {
    switch (bucket) {
        case ColdPathDiagnosticBucket::BoundaryBookkeeping:
            return "boundary_bookkeeping";
        case ColdPathDiagnosticBucket::BoundaryHazardDecision:
            return "boundary_hazard_decision";
        case ColdPathDiagnosticBucket::CacheKeyProgram:
            return "cache_key_program";
        case ColdPathDiagnosticBucket::CacheKeyVaoLayout:
            return "cache_key_vao_layout";
        case ColdPathDiagnosticBucket::CacheKeyFbo:
            return "cache_key_fbo";
        case ColdPathDiagnosticBucket::CacheKeyBindings:
            return "cache_key_bindings";
        case ColdPathDiagnosticBucket::CacheKeyFixedState:
            return "cache_key_fixed_state";
        case ColdPathDiagnosticBucket::CacheKeyOther:
            return "cache_key_other";
        case ColdPathDiagnosticBucket::ProgramVaoFboFp64Sidecars:
            return "program_vao_fbo_fp64_sidecars";
        case ColdPathDiagnosticBucket::ProgramVaoFboPrimitiveCounters:
            return "program_vao_fbo_primitive_counters";
        case ColdPathDiagnosticBucket::ProgramVaoFboFrontendVaoSource:
            return "program_vao_fbo_frontend_vao_source";
        case ColdPathDiagnosticBucket::ProgramVaoFboVaoSource:
            return "program_vao_fbo_vao_source";
        case ColdPathDiagnosticBucket::ProgramVaoFboGenericAttributes:
            return "program_vao_fbo_generic_attributes";
        case ColdPathDiagnosticBucket::ProgramVaoFboBoundFbo:
            return "program_vao_fbo_bound_fbo";
        case ColdPathDiagnosticBucket::ProgramVaoFboLayoutCache:
            return "program_vao_fbo_layout_cache";
        case ColdPathDiagnosticBucket::ProgramVaoFboLayoutApply:
            return "program_vao_fbo_layout_apply";
        case ColdPathDiagnosticBucket::SnapshotEstimate:
            return "snapshot_estimate";
        case ColdPathDiagnosticBucket::Count:
            break;
    }
    return "unknown";
}

static void coldPathHashU64(std::uint64_t& hash, std::uint64_t value) {
    hash ^= value;
    hash *= 1099511628211ull;
}

static void coldPathHashPointer(std::uint64_t& hash, const void* ptr) {
    coldPathHashU64(
        hash,
        static_cast<std::uint64_t>(
            reinterpret_cast<std::uintptr_t>(ptr)));
}

static bool mslUsesArgumentBuffer(const std::string& msl) {
    return msl.find("spvDescriptorSetBuffer") != std::string::npos;
}

static bool mslUsesArgumentBuffer(const std::string* msl) {
    return msl != nullptr && mslUsesArgumentBuffer(*msl);
}

static bool mslContains(const std::string& msl, const char* needle) {
    return msl.find(needle) != std::string::npos;
}

static void refreshProgramMslArgumentBufferMetadata(GLProgramObject& program) {
    program.vertexMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.vertexMSL);
    program.fragmentMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.fragmentMSL);
    program.vertexMslWritesRenderTargetArrayIndex =
        mslContains(program.vertexMSL, "[[render_target_array_index]]");
    program.vertexMslWritesViewportArrayIndex =
        mslContains(program.vertexMSL, "[[viewport_array_index]]");
    program.vertexMslHasClipControlYSignParameter =
        mslContains(program.vertexMSL, "_appgl_ClipControlYSign [[buffer(");
    program.fragmentMslUsesFragCoordParams =
        mslContains(program.fragmentMSL, "_appgl_FragCoordParams");
    program.gsPassThroughVertexMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.gsPassThroughVertexMSL);
    program.gsPassThroughFragmentMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.gsPassThroughFragmentMSL);
}

static void assignTranslatedDrawProgramMsl(TranslatedDrawInfo& tdi,
                                           const GLProgramObject& program) {
    tdi.vertexMSL = &program.vertexMSL;
    tdi.fragmentMSL = &program.fragmentMSL;
    // S25 state_resolve memo: the program's monotonic serial (absolute realloc
    // guard for the MSL-FNV memo identity); 0 → memo fail-safe.
    tdi.programObjectSerial = program.objectSerial;
    // ABA residual fix: the program's executableGeneration (relink-in-place guard).
    tdi.programObjectExecutableGeneration = program.executableGeneration;
    // ABA fix (c): splice-container volatile MSL → memo skip.
    tdi.programMslVolatile = program.mslVolatile;
    tdi.vertexMslUsesArgumentBuffer =
        program.vertexMslUsesArgumentBuffer;
    tdi.fragmentMslUsesArgumentBuffer =
        program.fragmentMslUsesArgumentBuffer;
    tdi.mslPredicateCacheValid = !program.mslVolatile;
    tdi.vertexMslWritesRenderTargetArrayIndex =
        program.vertexMslWritesRenderTargetArrayIndex;
    tdi.vertexMslWritesViewportArrayIndex =
        program.vertexMslWritesViewportArrayIndex;
    tdi.vertexMslHasClipControlYSignParameter =
        program.vertexMslHasClipControlYSignParameter;
    tdi.fragmentMslUsesFragCoordParams =
        program.fragmentMslUsesFragCoordParams;
}

struct ColdPathDiagnosticProfile {
    bool enabled = std::getenv("APPGL_7G_COLD_PATH_PROFILE") != nullptr;
    std::array<ColdPathDiagnosticBucketStats,
               static_cast<std::size_t>(ColdPathDiagnosticBucket::Count)>
        buckets{};

    std::uint64_t draws = 0;
    std::uint64_t phase2Candidates = 0;
    std::uint64_t phase2PlanHits = 0;
    std::uint64_t phase2PlanMisses = 0;
    std::uint64_t phase2PlanRejects = 0;
    std::uint64_t phase2PlanForceMisses = 0;
    std::uint64_t phase2MemoLookups = 0;
    std::uint64_t phase2MemoSupported = 0;
    std::uint64_t phase2MemoHits = 0;
    std::uint64_t phase2MemoMisses = 0;
    std::uint64_t programFingerprintLookups = 0;
    std::uint64_t programFingerprintHits = 0;
    std::uint64_t programFingerprintMisses = 0;
    std::uint64_t programFingerprintFallbacks = 0;
    std::uint64_t preflightSnapshots = 0;
    std::uint64_t preflightGenericPrepared = 0;
    std::uint64_t preflightGenericUnprepared = 0;
    std::uint64_t snapshotSamples = 0;
    std::uint64_t snapshotBytes = 0;
    std::uint64_t maxSnapshotBytes = 0;
    std::uint64_t mergeBytes = 0;
    std::uint64_t maxMergeBytes = 0;
    std::uint64_t phase2KeyRepeats = 0;
    std::uint64_t programRepeats = 0;
    std::uint64_t vaoFboRepeats = 0;
    std::uint64_t programVaoFboRepeats = 0;
    std::uint64_t boundaryRepeats = 0;
    std::uint64_t saturatedSurfaces = 0;

    std::unordered_set<std::uint64_t> phase2Keys;
    std::unordered_set<std::uint64_t> programKeys;
    std::unordered_set<std::uint64_t> vaoFboKeys;
    std::unordered_set<std::uint64_t> programVaoFboKeys;
    std::unordered_set<std::uint64_t> boundaryKeys;

    static constexpr std::size_t kMaxTrackedKeys = 1u << 20;

    void record(ColdPathDiagnosticBucket bucket, double us) {
        if (!enabled) {
            return;
        }
        auto& stats = buckets[static_cast<std::size_t>(bucket)];
        ++stats.count;
        stats.totalUs += us;
    }

    void record(ColdPathDiagnosticBucket bucket,
                GLDrawProfileTimePoint start,
                GLDrawProfileTimePoint end) {
        record(bucket, glDrawProfileElapsedUs(start, end));
    }

    void recordRepeat(std::unordered_set<std::uint64_t>& surface,
                      std::uint64_t key,
                      std::uint64_t& repeats) {
        if (!enabled) {
            return;
        }
        auto found = surface.find(key);
        if (found != surface.end()) {
            ++repeats;
            return;
        }
        if (surface.size() >= kMaxTrackedKeys) {
            ++saturatedSurfaces;
            return;
        }
        surface.insert(key);
    }

    void recordPreflight(bool hasPreflight, bool genericPrepared) {
        if (!enabled || !hasPreflight) {
            return;
        }
        ++preflightSnapshots;
        if (genericPrepared) {
            ++preflightGenericPrepared;
        } else {
            ++preflightGenericUnprepared;
        }
    }

    void recordDrawKeys(const TranslatedDrawInfo& tdi,
                        GLuint vaoName,
                        std::uint32_t vaoGeneration,
                        GLuint drawFboName) {
        if (!enabled) {
            return;
        }
        ++draws;

        std::uint64_t programKey = 1469598103934665603ull;
        coldPathHashU64(programKey, tdi.program);
        coldPathHashU64(programKey, tdi.pipelineEmulationFragmentProgram);
        coldPathHashPointer(programKey, tdi.vertexMSL);
        coldPathHashPointer(programKey, tdi.fragmentMSL);
        recordRepeat(programKeys, programKey, programRepeats);

        std::uint64_t vaoFboKey = 1469598103934665603ull;
        coldPathHashU64(vaoFboKey, vaoName);
        coldPathHashU64(vaoFboKey, vaoGeneration);
        coldPathHashU64(vaoFboKey, drawFboName);
        recordRepeat(vaoFboKeys, vaoFboKey, vaoFboRepeats);

        std::uint64_t programVaoFboKey = programKey;
        coldPathHashU64(programVaoFboKey, vaoName);
        coldPathHashU64(programVaoFboKey, vaoGeneration);
        coldPathHashU64(programVaoFboKey, drawFboName);
        recordRepeat(programVaoFboKeys,
                     programVaoFboKey,
                     programVaoFboRepeats);
    }

    void recordBoundaryKey(const AppGLSubmissionGroup& group,
                           GLuint drawFboName) {
        if (!enabled) {
            return;
        }
        std::uint64_t key = 1469598103934665603ull;
        coldPathHashU64(key, drawFboName);
        coldPathHashU64(key, static_cast<std::uint64_t>(group.kind));
        coldPathHashU64(key, static_cast<std::uint64_t>(group.primaryReason));
        coldPathHashU64(key, group.declared ? 1u : 0u);
        coldPathHashU64(key, group.argumentBuffersEnabled ? 1u : 0u);
        coldPathHashU64(key, group.approximateFallbackDisallowed ? 1u : 0u);
        coldPathHashU64(key, group.subgroupCount);
        coldPathHashU64(key, group.readCount);
        coldPathHashU64(key, group.writeCount);
        coldPathHashU64(key, group.transientCount);
        for (std::uint8_t i = 0; i < group.subgroupCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.subgroups[i].kind));
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.subgroups[i].reason));
        }
        for (std::uint8_t i = 0; i < group.readCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.reads[i].kind));
            coldPathHashU64(key, group.reads[i].name);
            coldPathHashU64(key, group.reads[i].producerBits);
        }
        for (std::uint8_t i = 0; i < group.writeCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.writes[i].kind));
            coldPathHashU64(key, group.writes[i].name);
            coldPathHashU64(key, group.writes[i].producerBits);
        }
        for (std::uint8_t i = 0; i < group.transientCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.transients[i].kind));
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.transients[i].ordering));
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.transients[i].reason));
            coldPathHashU64(key, group.transients[i].slot);
            coldPathHashU64(key, group.transients[i].bytes);
        }
        recordRepeat(boundaryKeys, key, boundaryRepeats);
    }

    void recordPhase2Key(std::uint64_t key) {
        if (!enabled) {
            return;
        }
        ++phase2Candidates;
        recordRepeat(phase2Keys, key, phase2KeyRepeats);
    }

    void recordPhase2Decision(const char* decision) {
        if (!enabled || decision == nullptr) {
            return;
        }
        if (std::strcmp(decision, "hit") == 0) {
            ++phase2PlanHits;
        } else if (std::strcmp(decision, "miss") == 0) {
            ++phase2PlanMisses;
        } else if (std::strcmp(decision, "reject") == 0) {
            ++phase2PlanRejects;
        }
    }

    void recordPhase2ForceMiss() {
        if (enabled) {
            ++phase2PlanForceMisses;
        }
    }

    void recordMemo(bool supported, bool hit) {
        if (!enabled) {
            return;
        }
        ++phase2MemoLookups;
        if (supported) {
            ++phase2MemoSupported;
        }
        if (hit) {
            ++phase2MemoHits;
        } else {
            ++phase2MemoMisses;
        }
    }

    void recordProgramFingerprint(bool eligible, bool hit) {
        if (!enabled) {
            return;
        }
        if (!eligible) {
            ++programFingerprintFallbacks;
            return;
        }
        ++programFingerprintLookups;
        if (hit) {
            ++programFingerprintHits;
        } else {
            ++programFingerprintMisses;
        }
    }

    void recordSnapshotEstimate(const TranslatedDrawInfo& tdi) {
        if (!enabled) {
            return;
        }
        const auto estimateStart = glDrawProfileNow();
        std::size_t bytes = sizeof(TranslatedDrawInfo);
        bytes +=
            tdi.vertexAttributeLayouts.size() *
            sizeof(TranslatedDrawInfo::VertexAttributeLayout);
        for (const auto& extra : tdi.extraVertexBuffers) {
            bytes += sizeof(TranslatedDrawInfo::ExtraVertexBuffer);
            bytes +=
                extra.attributes.size() *
                sizeof(TranslatedDrawInfo::VertexAttributeLayout);
            bytes += extra.ownedData.size();
        }
        bytes += tdi.fragmentTextures.size() *
                 sizeof(TranslatedDrawInfo::TextureBinding);
        bytes += tdi.vertexTextures.size() *
                 sizeof(TranslatedDrawInfo::TextureBinding);
        bytes += tdi.uboBindings.size() *
                 sizeof(TranslatedDrawInfo::UBOBinding);
        bytes += tdi.ssboBindings.size() *
                 sizeof(TranslatedDrawInfo::SSBOBinding);
        bytes += tdi.atomicCounterBindings.size() *
                 sizeof(TranslatedDrawInfo::AtomicCounterBinding);
        bytes += tdi.sampledTextureNames.size() * sizeof(GLuint);
        bytes += tdi.readImageTextureNames.size() * sizeof(GLuint);
        bytes += tdi.writtenImageTextureNames.size() * sizeof(GLuint);
        bytes += tdi.vertexUniformSize + tdi.fragmentUniformSize;

        const AppGLSubmissionGroup& group = tdi.submissionGroup;
        std::size_t estimatedMergeBytes = sizeof(AppGLSubmissionGroup);
        estimatedMergeBytes +=
            static_cast<std::size_t>(group.readCount + group.writeCount) *
            sizeof(AppGLSubmissionResourceAccess);
        estimatedMergeBytes +=
            static_cast<std::size_t>(group.transientCount) *
            sizeof(AppGLSubmissionTransient);

        ++snapshotSamples;
        snapshotBytes += static_cast<std::uint64_t>(bytes);
        maxSnapshotBytes =
            std::max<std::uint64_t>(maxSnapshotBytes, bytes);
        mergeBytes += static_cast<std::uint64_t>(estimatedMergeBytes);
        maxMergeBytes =
            std::max<std::uint64_t>(maxMergeBytes, estimatedMergeBytes);
        record(ColdPathDiagnosticBucket::SnapshotEstimate,
               estimateStart,
               glDrawProfileNow());
    }

    void dumpRepeat(const char* surface,
                    std::uint64_t samples,
                    std::size_t unique,
                    std::uint64_t repeats) const {
        if (samples == 0 && unique == 0) {
            return;
        }
        const double repeatRate = samples > 0
            ? (static_cast<double>(repeats) * 100.0) /
                  static_cast<double>(samples)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] repeat surface=%s "
            "samples=%llu unique=%llu repeats=%llu repeat_rate_pct=%.2f\n",
            surface,
            static_cast<unsigned long long>(samples),
            static_cast<unsigned long long>(unique),
            static_cast<unsigned long long>(repeats),
            repeatRate);
    }

    void dump() const {
        if (!enabled) {
            return;
        }
        double totalUs = 0.0;
        std::uint64_t samples = 0;
        for (const auto& bucket : buckets) {
            totalUs += bucket.totalUs;
            samples += bucket.count;
        }
        const double avgSnapshotBytes = snapshotSamples > 0
            ? static_cast<double>(snapshotBytes) /
                  static_cast<double>(snapshotSamples)
            : 0.0;
        const double avgMergeBytes = snapshotSamples > 0
            ? static_cast<double>(mergeBytes) /
                  static_cast<double>(snapshotSamples)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] summary draws=%llu "
            "timed_samples=%llu total_us=%.3f phase2_candidates=%llu "
            "phase2_cache_hits=%llu phase2_cache_misses=%llu "
            "phase2_cache_rejects=%llu phase2_force_misses=%llu "
            "snapshot_samples=%llu avg_snapshot_bytes=%.1f "
            "max_snapshot_bytes=%llu avg_merge_bytes=%.1f "
            "max_merge_bytes=%llu saturated_surfaces=%llu\n",
            static_cast<unsigned long long>(draws),
            static_cast<unsigned long long>(samples),
            totalUs,
            static_cast<unsigned long long>(phase2Candidates),
            static_cast<unsigned long long>(phase2PlanHits),
            static_cast<unsigned long long>(phase2PlanMisses),
            static_cast<unsigned long long>(phase2PlanRejects),
            static_cast<unsigned long long>(phase2PlanForceMisses),
            static_cast<unsigned long long>(snapshotSamples),
            avgSnapshotBytes,
            static_cast<unsigned long long>(maxSnapshotBytes),
            avgMergeBytes,
            static_cast<unsigned long long>(maxMergeBytes),
            static_cast<unsigned long long>(saturatedSurfaces));
        const double denom = draws > 0 ? static_cast<double>(draws) : 1.0;
        for (std::size_t i = 0;
             i < static_cast<std::size_t>(ColdPathDiagnosticBucket::Count);
             ++i) {
            const auto& bucket = buckets[i];
            if (bucket.count == 0) {
                continue;
            }
            const auto bucketId = static_cast<ColdPathDiagnosticBucket>(i);
            std::fprintf(stderr,
                "[APPGL_7G_COLD_PATH_PROFILE] component=%s count=%llu "
                "total_us=%.3f avg_us=%.3f avg_per_draw_us=%.3f\n",
                coldPathDiagnosticBucketName(bucketId),
                static_cast<unsigned long long>(bucket.count),
                bucket.totalUs,
                bucket.totalUs / static_cast<double>(bucket.count),
                bucket.totalUs / denom);
        }
        dumpRepeat("phase2_key",
                   phase2Candidates,
                   phase2Keys.size(),
                   phase2KeyRepeats);
        dumpRepeat("program",
                   draws,
                   programKeys.size(),
                   programRepeats);
        dumpRepeat("vao_fbo",
                   draws,
                   vaoFboKeys.size(),
                   vaoFboRepeats);
        dumpRepeat("program_vao_fbo",
                   draws,
                   programVaoFboKeys.size(),
                   programVaoFboRepeats);
        dumpRepeat("boundary",
                   draws,
                   boundaryKeys.size(),
                   boundaryRepeats);
        const double memoHitRate = phase2MemoLookups > 0
            ? (static_cast<double>(phase2MemoHits) * 100.0) /
                  static_cast<double>(phase2MemoLookups)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] memo lookups=%llu "
            "supported=%llu hits=%llu misses=%llu hit_rate_pct=%.2f\n",
            static_cast<unsigned long long>(phase2MemoLookups),
            static_cast<unsigned long long>(phase2MemoSupported),
            static_cast<unsigned long long>(phase2MemoHits),
            static_cast<unsigned long long>(phase2MemoMisses),
            memoHitRate);
        const double fingerprintHitRate = programFingerprintLookups > 0
            ? (static_cast<double>(programFingerprintHits) * 100.0) /
                  static_cast<double>(programFingerprintLookups)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] fingerprint surface=program "
            "lookups=%llu hits=%llu misses=%llu fallbacks=%llu "
            "hit_rate_pct=%.2f\n",
            static_cast<unsigned long long>(programFingerprintLookups),
            static_cast<unsigned long long>(programFingerprintHits),
            static_cast<unsigned long long>(programFingerprintMisses),
            static_cast<unsigned long long>(programFingerprintFallbacks),
            fingerprintHitRate);
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] preflight snapshots=%llu "
            "generic_prepared=%llu generic_unprepared=%llu\n",
            static_cast<unsigned long long>(preflightSnapshots),
            static_cast<unsigned long long>(preflightGenericPrepared),
            static_cast<unsigned long long>(preflightGenericUnprepared));
        std::fflush(stderr);
    }
};

class ColdPathDiagnosticScope {
public:
    ColdPathDiagnosticScope(ColdPathDiagnosticProfile* profile,
                            ColdPathDiagnosticBucket bucket)
        : profile_(profile != nullptr && profile->enabled ? profile : nullptr),
          bucket_(bucket) {
        if (profile_ != nullptr) {
            start_ = glDrawProfileNow();
        }
    }

    ColdPathDiagnosticScope(const ColdPathDiagnosticScope&) = delete;
    ColdPathDiagnosticScope& operator=(const ColdPathDiagnosticScope&) =
        delete;

    ~ColdPathDiagnosticScope() {
        if (profile_ != nullptr) {
            profile_->record(bucket_, start_, glDrawProfileNow());
        }
    }

private:
    ColdPathDiagnosticProfile* profile_ = nullptr;
    ColdPathDiagnosticBucket bucket_ = ColdPathDiagnosticBucket::Count;
    GLDrawProfileTimePoint start_{};
};

enum class Phase2PlanRejectReason : std::size_t {
    MissingProgram,
    MissingShader,
    MissingReflection,
    ProgramPipelineOrSubroutineState,
    SideEffect,
    KeyCapacity,
    Count,
};

static const char* phase2PlanRejectReasonName(Phase2PlanRejectReason reason) {
    switch (reason) {
        case Phase2PlanRejectReason::MissingProgram: return "missing_program";
        case Phase2PlanRejectReason::MissingShader: return "missing_shader";
        case Phase2PlanRejectReason::MissingReflection: return "missing_reflection";
        case Phase2PlanRejectReason::ProgramPipelineOrSubroutineState: return "program_pipeline_or_subroutine_state";
        case Phase2PlanRejectReason::SideEffect: return "side_effect";
        case Phase2PlanRejectReason::KeyCapacity: return "key_capacity";
        case Phase2PlanRejectReason::Count: break;
    }
    return "unknown";
}

static bool phase2PlanProfileEnabled() {
    return std::getenv("APPGL_PHASE2_PLAN_PROFILE") != nullptr ||
           std::getenv("APPGL_PHASE2_PLAN_KEY_PROFILE") != nullptr;
}

// S24 rider-2: latched once per process (d3e62ea pattern) — all three are
// read per draw on the encodeTranslatedDrawAndMarkFbo path and nothing
// toggles them at runtime.
static bool phase2TranslatedDrawPlanCacheEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_PLAN_DISABLE") == nullptr;
    return enabled;
}

static bool phase2TranslatedDrawPlanForceMiss() {
    static const bool forceMiss =
        std::getenv("APPGL_PHASE2_PLAN_FORCE_MISS") != nullptr;
    return forceMiss;
}

// S25 W2 probe knob (P3 capacity-freeze red→green): clamp the Phase-2 plan
// cache capacity so the gauntlet can reproduce the measured live-WZ failure
// mode (cache at capacity → KeyCapacity reject → no plan ever reaches the
// record path) without 1M draws. Probe-only; absent env = production limit.
static std::size_t phase2TranslatedDrawPlanCapacity(std::size_t productionLimit) {
    static const std::size_t capacity = [] {
        const char* value = std::getenv("APPGL_PHASE2_PLAN_CAPACITY");
        if (value == nullptr || *value == '\0') {
            return std::numeric_limits<std::size_t>::max();
        }
        return static_cast<std::size_t>(std::strtoull(value, nullptr, 10));
    }();
    return capacity == std::numeric_limits<std::size_t>::max()
        ? productionLimit
        : capacity;
}

static bool phase2TranslatedDrawPlanTraceEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_PLAN_TRACE") != nullptr;
    return enabled;
}

static bool phase2FixedStateSegmentShadowEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_FIXED_STATE_SEGMENT_SHADOW") != nullptr;
    return enabled;
}

static bool phase2BindingShapeSegmentShadowEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_BINDING_SEGMENT_SHADOW") != nullptr;
    return enabled;
}

static bool phase2VaoLayoutSegmentShadowEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW") != nullptr;
    return enabled;
}

static constexpr std::uint64_t kPhase2PlanHashOffset = 1469598103934665603ull;
static constexpr std::uint64_t kPhase2PlanHashPrime = 1099511628211ull;
static constexpr std::uint64_t kPhase2PlanVaoLayoutRuntimeCacheIndex =
    std::numeric_limits<std::uint64_t>::max();

static void phase2PlanHashByte(std::uint64_t& hash, std::uint8_t byte) {
    hash ^= byte;
    hash *= kPhase2PlanHashPrime;
}

static void phase2PlanHashU64(std::uint64_t& hash, std::uint64_t value) {
    for (int i = 0; i < 8; ++i) {
        phase2PlanHashByte(
            hash, static_cast<std::uint8_t>((value >> (i * 8)) & 0xFFu));
    }
}

static void phase2PlanHashBool(std::uint64_t& hash, bool value) {
    phase2PlanHashU64(hash, value ? 1ull : 0ull);
}

static std::uint32_t phase2PlanFloatBits(float value) {
    std::uint32_t bits = 0;
    std::memcpy(&bits, &value, sizeof(bits));
    return bits;
}

static void phase2PlanHashFloat(std::uint64_t& hash, float value) {
    phase2PlanHashU64(hash, phase2PlanFloatBits(value));
}

static void phase2PlanHashPointer(std::uint64_t& hash, const void* pointer) {
    phase2PlanHashU64(hash,
        static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pointer)));
}

static void phase2PlanHashShaderIdentity(
    std::uint64_t& hash,
    const std::string* source)
{
    phase2PlanHashPointer(hash, source);
    phase2PlanHashU64(hash, source != nullptr ? source->size() : 0u);
    phase2PlanHashPointer(
        hash, source != nullptr && !source->empty() ? source->data() : nullptr);
}

static void phase2PlanHashResourceBindingShape(
    std::uint64_t& hash,
    const ShaderReflection::ResourceBinding& binding)
{
    phase2PlanHashU64(hash, binding.glBinding);
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(binding.uniformLocation));
    phase2PlanHashU64(hash, binding.glType);
    phase2PlanHashU64(hash, binding.arraySize);
    phase2PlanHashU64(hash, binding.metalBinding);
    phase2PlanHashU64(hash, binding.byteSize);
    phase2PlanHashBool(hash, binding.hasInstanceName);
    phase2PlanHashU64(hash, binding.blockArraySize);
    phase2PlanHashBool(hash, binding.hasExplicitBinding);
    phase2PlanHashBool(hash, binding.active);
    phase2PlanHashBool(hash, binding.multisampleStorageImage);
    phase2PlanHashBool(hash, binding.multisampleStorageImageArray);
    phase2PlanHashU64(hash, binding.storageImageTarget);
    phase2PlanHashU64(hash, binding.metalAtomicBufferBinding);
    phase2PlanHashBool(hash, binding.sparseStorageImageRead);
    phase2PlanHashBool(hash, binding.sparseStorageImageWrite);
    phase2PlanHashBool(hash, binding.containsFp64);
    phase2PlanHashU64(hash, binding.members.size());
    for (const auto& member : binding.members) {
        phase2PlanHashU64(hash, member.offset);
        phase2PlanHashU64(hash, member.size);
        phase2PlanHashU64(hash, member.type);
        phase2PlanHashBool(hash, member.isRowMajor);
        phase2PlanHashU64(hash, member.arraySize);
        phase2PlanHashBool(hash, member.isArray);
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.arrayStride));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.matrixStride));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.topLevelArraySize));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.topLevelArrayStride));
        phase2PlanHashBool(hash, member.containsFp64);
    }
}

static void phase2PlanHashReflectionShape(
    std::uint64_t& hash,
    const ShaderReflection* reflection)
{
    phase2PlanHashPointer(hash, reflection);
    if (reflection == nullptr) {
        return;
    }

    phase2PlanHashU64(hash, reflection->vertexInputs.size());
    for (const auto& input : reflection->vertexInputs) {
        phase2PlanHashU64(hash, input.location);
        phase2PlanHashU64(hash, input.sourceLocation);
        phase2PlanHashU64(hash, input.type);
        phase2PlanHashBool(hash, input.containsFp64);
    }

    auto hashBindings = [&](const auto& bindings) {
        phase2PlanHashU64(hash, bindings.size());
        for (const auto& binding : bindings) {
            phase2PlanHashResourceBindingShape(hash, binding);
        }
    };
    hashBindings(reflection->uniformBlocks);
    hashBindings(reflection->sampledTextures);
    hashBindings(reflection->storageBuffers);
    hashBindings(reflection->storageImages);
    phase2PlanHashBool(hash, reflection->usesPointSize);
    phase2PlanHashBool(hash, reflection->usesFragmentShadingRateBuiltins);
    phase2PlanHashBool(hash, reflection->usesFp64);
    phase2PlanHashBool(hash, reflection->fp64TranslationActive);
}

struct Phase2ProgramStructuralFingerprint {
    bool valid = false;
    std::uint64_t programSegmentHash = 0;
};

static void phase2PlanInvalidateProgramStructuralFingerprint(
    GLProgramObject& program)
{
    program.phase2ProgramStructuralFingerprintValid = false;
    program.phase2ProgramStructuralFingerprintProgram = 0;
    program.phase2ProgramStructuralFingerprintGeneration = 0;
    program.phase2ProgramStructuralFingerprint = 0;
}

static std::uint64_t phase2PlanBuildProgramStructuralFingerprint(
    GLuint programName,
    const GLProgramObject& program)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C50324B31ull); // "APGLP2K1"
    phase2PlanHashU64(hash, programName);
    phase2PlanHashU64(hash, 0u);
    phase2PlanHashShaderIdentity(hash, &program.vertexMSL);
    phase2PlanHashShaderIdentity(hash, &program.fragmentMSL);
    phase2PlanHashReflectionShape(hash, &program.vertexReflection);
    phase2PlanHashReflectionShape(hash, &program.fragmentReflection);
    return hash;
}

static Phase2ProgramStructuralFingerprint
phase2PlanProgramStructuralFingerprintForDraw(
    const TranslatedDrawInfo& tdi,
    GLObjectStore* objects,
    ColdPathDiagnosticProfile* coldProfile)
{
    auto fallback = [&]() {
        if (coldProfile != nullptr) {
            coldProfile->recordProgramFingerprint(/*eligible=*/false,
                                                  /*hit=*/false);
        }
        return Phase2ProgramStructuralFingerprint{};
    };

    if (objects == nullptr || tdi.rasterizerDiscard ||
        tdi.pipelineEmulationFragmentProgram != 0) {
        return fallback();
    }

    GLProgramObject* program = objects->programs().get(tdi.program);
    if (program == nullptr || !program->linked || program->separableLinked) {
        return fallback();
    }
    if (tdi.vertexMSL != &program->vertexMSL ||
        tdi.fragmentMSL != &program->fragmentMSL ||
        tdi.vertexReflection != &program->vertexReflection ||
        tdi.fragmentReflection != &program->fragmentReflection) {
        return fallback();
    }

    const bool hit =
        program->phase2ProgramStructuralFingerprintValid &&
        program->phase2ProgramStructuralFingerprintProgram == tdi.program &&
        program->phase2ProgramStructuralFingerprintGeneration ==
            program->executableGeneration;
    if (!hit) {
        program->phase2ProgramStructuralFingerprint =
            phase2PlanBuildProgramStructuralFingerprint(tdi.program, *program);
        program->phase2ProgramStructuralFingerprintProgram = tdi.program;
        program->phase2ProgramStructuralFingerprintGeneration =
            program->executableGeneration;
        program->phase2ProgramStructuralFingerprintValid = true;
    }
    if (coldProfile != nullptr) {
        coldProfile->recordProgramFingerprint(/*eligible=*/true, hit);
    }

    Phase2ProgramStructuralFingerprint fingerprint;
    fingerprint.valid = true;
    fingerprint.programSegmentHash =
        program->phase2ProgramStructuralFingerprint;
    return fingerprint;
}

static void phase2PlanHashVertexLayout(
    std::uint64_t& hash,
    const TranslatedDrawInfo::VertexAttributeLayout& layout)
{
    phase2PlanHashU64(hash, layout.location);
    phase2PlanHashU64(hash, layout.offset);
    phase2PlanHashU64(hash, layout.glType);
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(layout.glComponentCount));
    phase2PlanHashBool(hash, layout.glNormalized != GL_FALSE);
    phase2PlanHashBool(hash, layout.glIsInteger);
}

static void phase2PlanHashCachedVertexLayoutAsTranslated(
    std::uint64_t& hash,
    const GLVertexArrayCachedAttributeLayout& layout,
    std::size_t baseOffset = 0)
{
    phase2PlanHashU64(hash, layout.location);
    phase2PlanHashU64(hash, layout.offset - baseOffset);
    phase2PlanHashU64(hash, layout.glType);
    phase2PlanHashU64(
        hash, static_cast<std::uint64_t>(layout.glComponentCount));
    phase2PlanHashBool(hash, layout.glNormalized != GL_FALSE);
    phase2PlanHashBool(hash, layout.glIsInteger);
}

static void phase2PlanHashVaoLayoutSegmentFields(
    std::uint64_t& hash,
    const TranslatedDrawInfo& tdi,
    std::uint64_t cacheIndex)
{
    phase2PlanHashU64(hash, 0x4150474C5032564Cull); // "APGLP2VL"
    phase2PlanHashU64(hash, cacheIndex);
    phase2PlanHashU64(hash, tdi.vertexStride);
    phase2PlanHashU64(hash, tdi.vertexAttributeLayouts.size());
    for (const auto& layout : tdi.vertexAttributeLayouts) {
        phase2PlanHashVertexLayout(hash, layout);
    }
    phase2PlanHashU64(hash, tdi.extraVertexBuffers.size());
    for (const auto& extra : tdi.extraVertexBuffers) {
        phase2PlanHashU64(hash, extra.stride);
        phase2PlanHashU64(hash, extra.divisor);
        phase2PlanHashBool(hash, extra.constantStep);
        phase2PlanHashU64(hash, extra.attributes.size());
        for (const auto& layout : extra.attributes) {
            phase2PlanHashVertexLayout(hash, layout);
        }
    }
}

static std::uint64_t phase2PlanBuildVaoLayoutSegmentHash(
    const TranslatedDrawInfo& tdi,
    std::uint64_t cacheIndex)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashVaoLayoutSegmentFields(hash, tdi, cacheIndex);
    return hash;
}

static std::uint64_t phase2PlanBuildCachedVaoLayoutFingerprint(
    const GLVertexArrayCachedLayout& cache,
    std::uint64_t cacheIndex)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C5032564Cull); // "APGLP2VL"
    phase2PlanHashU64(hash, cacheIndex);
    phase2PlanHashU64(hash, cache.primaryStride);
    phase2PlanHashU64(hash, cache.primaryAttributes.size());
    for (const auto& layout : cache.primaryAttributes) {
        phase2PlanHashCachedVertexLayoutAsTranslated(
            hash, layout, cache.primaryBaseOffset);
    }
    phase2PlanHashU64(hash, cache.extraGroups.size());
    for (const auto& group : cache.extraGroups) {
        phase2PlanHashU64(hash, group.stride);
        phase2PlanHashU64(hash, group.divisor);
        phase2PlanHashBool(hash, false);
        phase2PlanHashU64(hash, group.attributes.size());
        for (const auto& layout : group.attributes) {
            phase2PlanHashCachedVertexLayoutAsTranslated(hash, layout);
        }
    }
    return hash;
}

static void phase2PlanLogVaoLayoutSegmentNamespaceOnce()
{
    if (!phase2VaoLayoutSegmentShadowEnabled()) {
        return;
    }
    static bool logged = false;
    if (logged) {
        return;
    }
    logged = true;
    std::fprintf(
        stderr,
        "[APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW] "
        "final key namespace changed intentionally; "
        "checking vao-layout segment coverage\n");
}

static void phase2PlanAssertVaoLayoutSegmentCoverage(
    const TranslatedDrawInfo& tdi,
    const char* site,
    std::uint64_t segmentHash)
{
    if (!phase2VaoLayoutSegmentShadowEnabled()) {
        return;
    }
    phase2PlanLogVaoLayoutSegmentNamespaceOnce();
    const std::uint64_t reference =
        phase2PlanBuildVaoLayoutSegmentHash(
            tdi, tdi.phase2VaoLayoutSegmentCacheIndex);
    if (segmentHash == reference) {
        return;
    }
    std::fprintf(
        stderr,
        "[APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW] "
        "vao-layout segment coverage mismatch site=%s stored=0x%016llx "
        "reference=0x%016llx cache_index=%llu "
        "final_key_namespace=changed_intentionally\n",
        site != nullptr ? site : "unknown",
        static_cast<unsigned long long>(segmentHash),
        static_cast<unsigned long long>(reference),
        static_cast<unsigned long long>(
            tdi.phase2VaoLayoutSegmentCacheIndex));
    std::abort();
}

static void phase2PlanInvalidateVaoLayoutSegmentHash(TranslatedDrawInfo& tdi)
{
    tdi.phase2VaoLayoutSegmentHashValid = false;
    tdi.phase2VaoLayoutSegmentHash = 0;
    tdi.phase2VaoLayoutSegmentCacheIndex =
        kPhase2PlanVaoLayoutRuntimeCacheIndex;
}

static void phase2PlanRefreshVaoLayoutSegmentHash(
    TranslatedDrawInfo& tdi,
    const char* site,
    std::uint64_t cacheIndex = kPhase2PlanVaoLayoutRuntimeCacheIndex)
{
    tdi.phase2VaoLayoutSegmentCacheIndex = cacheIndex;
    tdi.phase2VaoLayoutSegmentHash =
        phase2PlanBuildVaoLayoutSegmentHash(tdi, cacheIndex);
    tdi.phase2VaoLayoutSegmentHashValid = true;
    phase2PlanAssertVaoLayoutSegmentCoverage(
        tdi, site, tdi.phase2VaoLayoutSegmentHash);
}

static void phase2PlanSetVaoLayoutSegmentHashFromCache(
    TranslatedDrawInfo& tdi,
    const GLVertexArrayCachedLayout& cache,
    const char* site)
{
    if (!cache.phase2LayoutFingerprintValid) {
        phase2PlanInvalidateVaoLayoutSegmentHash(tdi);
        return;
    }
    tdi.phase2VaoLayoutSegmentCacheIndex =
        cache.phase2LayoutFingerprintCacheIndex;
    tdi.phase2VaoLayoutSegmentHash = cache.phase2LayoutFingerprint;
    tdi.phase2VaoLayoutSegmentHashValid = true;
    phase2PlanAssertVaoLayoutSegmentCoverage(
        tdi, site, tdi.phase2VaoLayoutSegmentHash);
}

static void phase2PlanEnsureVaoLayoutSegmentHash(TranslatedDrawInfo& tdi,
                                                 const char* site)
{
    if (!tdi.phase2VaoLayoutSegmentHashValid) {
        phase2PlanRefreshVaoLayoutSegmentHash(tdi, site);
        return;
    }
    phase2PlanAssertVaoLayoutSegmentCoverage(
        tdi, site, tdi.phase2VaoLayoutSegmentHash);
}

static std::uint64_t phase2PlanVaoLayoutSegmentHashForKey(
    const TranslatedDrawInfo& tdi)
{
    if (tdi.phase2VaoLayoutSegmentHashValid) {
        phase2PlanAssertVaoLayoutSegmentCoverage(
            tdi, "key", tdi.phase2VaoLayoutSegmentHash);
        return tdi.phase2VaoLayoutSegmentHash;
    }
    const std::uint64_t fallback =
        phase2PlanBuildVaoLayoutSegmentHash(
            tdi, kPhase2PlanVaoLayoutRuntimeCacheIndex);
    if (phase2VaoLayoutSegmentShadowEnabled()) {
        phase2PlanLogVaoLayoutSegmentNamespaceOnce();
        std::fprintf(
            stderr,
            "[APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW] "
            "vao-layout segment missing before key site=key "
            "fallback=0x%016llx final_key_namespace=changed_intentionally\n",
            static_cast<unsigned long long>(fallback));
        std::abort();
    }
    return fallback;
}

static void phase2PlanHashTextureBindings(
    std::uint64_t& hash,
    const std::vector<TranslatedDrawInfo::TextureBinding>& bindings)
{
    phase2PlanHashU64(hash, bindings.size());
    for (const auto& binding : bindings) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(hash, binding.textureBufferBackingMetalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.imageAtomicMetalBuffer != nullptr);
        phase2PlanHashU64(hash, binding.imageAtomicBufferSlot);
        phase2PlanHashU64(hash, binding.reductionMode);
        phase2PlanHashU64(hash, binding.borderClampMask);
    }
}

template <typename Binding>
static void phase2PlanHashBufferBindings(
    std::uint64_t& hash,
    const std::vector<Binding>& bindings)
{
    phase2PlanHashU64(hash, bindings.size());
    for (const auto& binding : bindings) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(hash, binding.metalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.isVertex);
        phase2PlanHashBool(hash, binding.isFragment);
    }
}

static std::uint64_t phase2PlanBuildBindingShapeSegmentHash(
    const TranslatedDrawInfo& tdi)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C50324253ull); // "APGLP2BS"
    phase2PlanHashU64(hash, tdi.vertexUniformSize);
    phase2PlanHashU64(hash, tdi.fragmentUniformSize);
    phase2PlanHashTextureBindings(hash, tdi.fragmentTextures);
    phase2PlanHashTextureBindings(hash, tdi.vertexTextures);
    phase2PlanHashBufferBindings(hash, tdi.uboBindings);
    phase2PlanHashBufferBindings(hash, tdi.ssboBindings);
    phase2PlanHashBufferBindings(hash, tdi.atomicCounterBindings);
    phase2PlanHashU64(hash, tdi.sampledTextureNames.size());
    phase2PlanHashU64(hash, tdi.readImageTextureNames.size());
    phase2PlanHashU64(hash, tdi.writtenImageTextureNames.size());
    return hash;
}

static std::uint64_t phase2PlanBuildBindingShapeReferenceSegmentHash(
    const TranslatedDrawInfo& tdi)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C50324253ull); // "APGLP2BS"
    phase2PlanHashU64(hash, tdi.vertexUniformSize);
    phase2PlanHashU64(hash, tdi.fragmentUniformSize);

    phase2PlanHashU64(hash, tdi.fragmentTextures.size());
    for (const auto& binding : tdi.fragmentTextures) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(
            hash, binding.textureBufferBackingMetalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.imageAtomicMetalBuffer != nullptr);
        phase2PlanHashU64(hash, binding.imageAtomicBufferSlot);
        phase2PlanHashU64(hash, binding.reductionMode);
        phase2PlanHashU64(hash, binding.borderClampMask);
    }
    phase2PlanHashU64(hash, tdi.vertexTextures.size());
    for (const auto& binding : tdi.vertexTextures) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(
            hash, binding.textureBufferBackingMetalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.imageAtomicMetalBuffer != nullptr);
        phase2PlanHashU64(hash, binding.imageAtomicBufferSlot);
        phase2PlanHashU64(hash, binding.reductionMode);
        phase2PlanHashU64(hash, binding.borderClampMask);
    }

    phase2PlanHashU64(hash, tdi.uboBindings.size());
    for (const auto& ubo : tdi.uboBindings) {
        phase2PlanHashU64(hash, ubo.metalSlot);
        phase2PlanHashBool(hash, ubo.metalBuffer != nullptr);
        phase2PlanHashBool(hash, ubo.isVertex);
        phase2PlanHashBool(hash, ubo.isFragment);
    }
    phase2PlanHashU64(hash, tdi.ssboBindings.size());
    for (const auto& ssbo : tdi.ssboBindings) {
        phase2PlanHashU64(hash, ssbo.metalSlot);
        phase2PlanHashBool(hash, ssbo.metalBuffer != nullptr);
        phase2PlanHashBool(hash, ssbo.isVertex);
        phase2PlanHashBool(hash, ssbo.isFragment);
    }
    phase2PlanHashU64(hash, tdi.atomicCounterBindings.size());
    for (const auto& atomic : tdi.atomicCounterBindings) {
        phase2PlanHashU64(hash, atomic.metalSlot);
        phase2PlanHashBool(hash, atomic.metalBuffer != nullptr);
        phase2PlanHashBool(hash, atomic.isVertex);
        phase2PlanHashBool(hash, atomic.isFragment);
    }
    phase2PlanHashU64(hash, tdi.sampledTextureNames.size());
    phase2PlanHashU64(hash, tdi.readImageTextureNames.size());
    phase2PlanHashU64(hash, tdi.writtenImageTextureNames.size());
    return hash;
}

