    return fallback;
}

static void phase2PlanHashSubmissionGroup(
    std::uint64_t& hash,
    const AppGLSubmissionGroup& group)
{
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.kind));
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.primaryReason));
    phase2PlanHashBool(hash, group.declared);
    phase2PlanHashBool(hash, group.argumentBuffersEnabled);
    phase2PlanHashBool(hash, group.approximateFallbackDisallowed);
    phase2PlanHashU64(hash, group.subgroupCount);
    for (std::uint8_t i = 0; i < group.subgroupCount; ++i) {
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.subgroups[i].kind));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.subgroups[i].reason));
    }
    phase2PlanHashU64(hash, group.readCount);
    for (std::uint8_t i = 0; i < group.readCount; ++i) {
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.reads[i].kind));
        phase2PlanHashU64(hash, group.reads[i].producerBits);
    }
    phase2PlanHashU64(hash, group.writeCount);
    for (std::uint8_t i = 0; i < group.writeCount; ++i) {
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.writes[i].kind));
        phase2PlanHashU64(hash, group.writes[i].producerBits);
    }
    phase2PlanHashU64(hash, group.transientCount);
    for (std::uint8_t i = 0; i < group.transientCount; ++i) {
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.transients[i].kind));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.transients[i].ordering));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(group.transients[i].reason));
        phase2PlanHashU64(hash, group.transients[i].slot);
        phase2PlanHashU64(hash, group.transients[i].bytes);
    }
}

// Phase-2 plan-cacheability gate — NOT a parallel-eligibility gate. This is
// intentionally WRITE-only on images (readImageTextureNames is absent): a
// read-image draw CAN safely cache its translated plan (its PSO is valid;
// the serial heavy path binds the read-images correctly), so denying it a
// cached plan would only pessimize without benefit. The W2.2 read-image
// PARALLEL rejection lives in translatedDrawParallelStructuralReject
// (MetalFrameGraph.mm) — the authoritative parallel backstop — so a
// read-image draw stays off the parallel path regardless of this gate's
// caching decision. Keep this concern (cacheability) separate from that one
// (parallel-eligibility); do NOT "align" the two by adding read-images here.
static bool phase2PlanHasSideEffect(const TranslatedDrawInfo& tdi) {
    return tdi.rasterizerDiscard ||
           !tdi.writtenImageTextureNames.empty() ||
           !tdi.ssboBindings.empty() ||
           !tdi.atomicCounterBindings.empty() ||
           tdi.submissionGroup.hasSubgroup(
               AppGLSubmissionGroupKind::TransformFeedbackCapture);
}

static std::uint64_t phase2PlanKeyForDraw(const TranslatedDrawInfo& tdi,
                                          GLuint vaoName,
                                          std::uint32_t vaoGeneration,
                                          GLuint drawFboName,
                                          ColdPathDiagnosticProfile* coldProfile = nullptr,
                                          const Phase2ProgramStructuralFingerprint* programFingerprint = nullptr,
                                          double coldProgramPrefixUs = 0.0)
{
    const bool coldEnabled = coldProfile != nullptr && coldProfile->enabled;
    GLDrawProfileTimePoint coldCursor =
        coldEnabled ? glDrawProfileNow() : GLDrawProfileTimePoint{};
    double coldProgramUs = coldProgramPrefixUs;
    double coldVaoLayoutUs = 0.0;
    double coldFboUs = 0.0;
    double coldBindingsUs = 0.0;
    double coldFixedStateUs = 0.0;
    double coldOtherUs = 0.0;
    auto coldMark = [&](double& accumulator) {
        if (!coldEnabled) {
            return;
        }
        const auto now = glDrawProfileNow();
        accumulator += glDrawProfileElapsedUs(coldCursor, now);
        coldCursor = now;
    };

    std::uint64_t hash = kPhase2PlanHashOffset;
    if (programFingerprint != nullptr && programFingerprint->valid) {
        hash = programFingerprint->programSegmentHash;
    } else {
        phase2PlanHashU64(hash, 0x4150474C50324B31ull); // "APGLP2K1"
        phase2PlanHashU64(hash, tdi.program);
        phase2PlanHashU64(hash, tdi.pipelineEmulationFragmentProgram);
        phase2PlanHashShaderIdentity(hash, tdi.vertexMSL);
        phase2PlanHashShaderIdentity(hash, tdi.fragmentMSL);
        phase2PlanHashReflectionShape(hash, tdi.vertexReflection);
        phase2PlanHashReflectionShape(hash, tdi.fragmentReflection);
    }
    coldMark(coldProgramUs);

    phase2PlanHashU64(hash, vaoName);
    phase2PlanHashU64(hash, vaoGeneration);
    coldMark(coldVaoLayoutUs);
    phase2PlanHashU64(hash, drawFboName);
    coldMark(coldFboUs);
    phase2PlanHashU64(hash, tdi.mode);
    phase2PlanHashBool(hash, tdi.indices != nullptr || tdi.metalIndexBuffer != nullptr);
    phase2PlanHashU64(hash, tdi.indexType);
    phase2PlanHashBool(hash, tdi.instanceCount != 1);
    phase2PlanHashBool(hash, tdi.baseInstance != 0);
    phase2PlanHashBool(hash, tdi.baseVertex != 0);

    phase2PlanHashBool(hash, tdi.vertexData != nullptr);
    phase2PlanHashBool(hash, tdi.metalVertexBuffer != nullptr);
    phase2PlanHashU64(hash, phase2PlanVaoLayoutSegmentHashForKey(tdi));
    phase2PlanHashU64(hash, tdi.extraVertexBuffers.size());
    for (const auto& extra : tdi.extraVertexBuffers) {
        phase2PlanHashBool(hash, extra.data != nullptr);
        phase2PlanHashBool(hash, extra.metalBuffer != nullptr);
    }
    phase2PlanHashBool(hash, tdi.metalIndexBuffer != nullptr);
    coldMark(coldVaoLayoutUs);

    phase2PlanHashU64(hash, phase2PlanBindingShapeSegmentHashForKey(tdi));
    coldMark(coldBindingsUs);

    phase2PlanHashU64(hash, phase2PlanFixedStateSegmentHashForKey(tdi));
    coldMark(coldFixedStateUs);

    phase2PlanHashBool(hash, tdi.pipelineStateOut != nullptr);
    phase2PlanHashBool(hash, tdi.pipelineColorFormatOut != nullptr);
    phase2PlanHashBool(hash, tdi.pipelineStateCacheOut != nullptr);
    phase2PlanHashBool(hash, tdi.metalVertexFunction != nullptr);
    phase2PlanHashBool(hash, tdi.metalFragmentFunction != nullptr);
    phase2PlanHashBool(hash, tdi.metalVertexFunctionOut != nullptr);
    phase2PlanHashBool(hash, tdi.metalFragmentFunctionOut != nullptr);
    coldMark(coldOtherUs);

    phase2PlanHashPointer(hash, tdi.fboColorTexture);
    for (void* texture : tdi.fboAdditionalColorTextures) {
        phase2PlanHashPointer(hash, texture);
    }
    phase2PlanHashPointer(hash, tdi.fboDepthStencilTexture);
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(tdi.fboWidth));
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(tdi.fboHeight));
    phase2PlanHashBool(hash, tdi.fboAttachmentless);
    phase2PlanHashU64(hash, tdi.fboDefaultLayers);
    phase2PlanHashU64(hash, tdi.fboColorArrayLength);
    phase2PlanHashU64(hash, tdi.maxEmittedLayer);
    for (auto value : tdi.fboColorSlices) {
        phase2PlanHashU64(hash, value);
    }
    for (auto value : tdi.fboColorLevels) {
        phase2PlanHashU64(hash, value);
    }
    phase2PlanHashU64(hash, tdi.fboDepthStencilSlice);
    phase2PlanHashU64(hash, tdi.fboDepthStencilLevel);
    coldMark(coldFboUs);

    phase2PlanHashU64(hash, static_cast<std::uint64_t>(tdi.fallbackSubgroupKind));
    phase2PlanHashSubmissionGroup(hash, tdi.submissionGroup);
    coldMark(coldOtherUs);
    if (coldEnabled) {
        coldProfile->record(ColdPathDiagnosticBucket::CacheKeyProgram,
                            coldProgramUs);
        coldProfile->record(ColdPathDiagnosticBucket::CacheKeyVaoLayout,
                            coldVaoLayoutUs);
        coldProfile->record(ColdPathDiagnosticBucket::CacheKeyFbo,
                            coldFboUs);
        coldProfile->record(ColdPathDiagnosticBucket::CacheKeyBindings,
                            coldBindingsUs);
        coldProfile->record(ColdPathDiagnosticBucket::CacheKeyFixedState,
                            coldFixedStateUs);
        coldProfile->record(ColdPathDiagnosticBucket::CacheKeyOther,
                            coldOtherUs);
    }
    return hash;
}

struct Phase2PlanMemoVertexAttributeLayout {
    GLuint location = 0;
    std::size_t offset = 0;
    GLenum glType = GL_FLOAT;
    GLint glComponentCount = 4;
    bool glNormalized = false;
    bool glIsInteger = false;

    bool operator==(const Phase2PlanMemoVertexAttributeLayout& other) const {
        return location == other.location &&
               offset == other.offset &&
               glType == other.glType &&
               glComponentCount == other.glComponentCount &&
               glNormalized == other.glNormalized &&
               glIsInteger == other.glIsInteger;
    }
};

struct Phase2PlanMemoExtraVertexBuffer {
    bool dataPresent = false;
    bool metalBufferPresent = false;
    std::size_t stride = 0;
    GLuint divisor = 0;
    bool constantStep = false;
    std::vector<Phase2PlanMemoVertexAttributeLayout> attributes;

    bool operator==(const Phase2PlanMemoExtraVertexBuffer& other) const {
        return dataPresent == other.dataPresent &&
               metalBufferPresent == other.metalBufferPresent &&
               stride == other.stride &&
               divisor == other.divisor &&
               constantStep == other.constantStep &&
               attributes == other.attributes;
    }
};

struct Phase2PlanMemoTextureBinding {
    std::uint32_t metalSlot = 0;
    bool textureBufferBackingMetalBufferPresent = false;
    bool imageAtomicMetalBufferPresent = false;
    std::uint32_t imageAtomicBufferSlot = 0xFFFFFFFFu;
    std::uint32_t reductionMode = GL_WEIGHTED_AVERAGE_ARB;
    std::uint32_t borderClampMask = 0;

    bool operator==(const Phase2PlanMemoTextureBinding& other) const {
        return metalSlot == other.metalSlot &&
               textureBufferBackingMetalBufferPresent ==
                   other.textureBufferBackingMetalBufferPresent &&
               imageAtomicMetalBufferPresent ==
                   other.imageAtomicMetalBufferPresent &&
               imageAtomicBufferSlot == other.imageAtomicBufferSlot &&
               reductionMode == other.reductionMode &&
               borderClampMask == other.borderClampMask;
    }
};

struct Phase2PlanMemoBufferBinding {
    std::uint32_t metalSlot = 0;
    bool metalBufferPresent = false;
    bool isVertex = false;
    bool isFragment = false;

    bool operator==(const Phase2PlanMemoBufferBinding& other) const {
        return metalSlot == other.metalSlot &&
               metalBufferPresent == other.metalBufferPresent &&
               isVertex == other.isVertex &&
               isFragment == other.isFragment;
    }
};

struct Phase2PlanMemoSubmissionSubgroup {
    AppGLSubmissionGroupKind kind = AppGLSubmissionGroupKind::None;
    AppGLCommandReason reason = AppGLCommandReason::Legacy;

    bool operator==(const Phase2PlanMemoSubmissionSubgroup& other) const {
        return kind == other.kind && reason == other.reason;
    }
};

struct Phase2PlanMemoSubmissionAccess {
    AppGLSubmissionResourceKind kind = AppGLSubmissionResourceKind::Texture;
    std::uint32_t producerBits = 0;

    bool operator==(const Phase2PlanMemoSubmissionAccess& other) const {
        return kind == other.kind && producerBits == other.producerBits;
    }
};

struct Phase2PlanMemoSubmissionTransient {
    AppGLSubmissionTransientKind kind =
        AppGLSubmissionTransientKind::ArgumentBufferPayload;
    AppGLSubmissionOrderingMechanism ordering =
        AppGLSubmissionOrderingMechanism::None;
    AppGLCommandReason reason = AppGLCommandReason::Legacy;
    std::uint32_t slot = 0;
    std::size_t bytes = 0;

    bool operator==(const Phase2PlanMemoSubmissionTransient& other) const {
        return kind == other.kind &&
               ordering == other.ordering &&
               reason == other.reason &&
               slot == other.slot &&
               bytes == other.bytes;
    }
};

struct Phase2PlanMemoSubmissionGroup {
    AppGLSubmissionGroupKind kind = AppGLSubmissionGroupKind::None;
    AppGLCommandReason primaryReason = AppGLCommandReason::Legacy;
    bool declared = false;
    bool argumentBuffersEnabled = false;
    bool approximateFallbackDisallowed = false;
    std::uint8_t subgroupCount = 0;
    std::uint8_t readCount = 0;
    std::uint8_t writeCount = 0;
    std::uint8_t transientCount = 0;
    std::array<Phase2PlanMemoSubmissionSubgroup,
               AppGLSubmissionGroup::kMaxSubgroups> subgroups{};
    std::array<Phase2PlanMemoSubmissionAccess,
               AppGLSubmissionGroup::kMaxResourceAccesses> reads{};
    std::array<Phase2PlanMemoSubmissionAccess,
               AppGLSubmissionGroup::kMaxResourceAccesses> writes{};
    std::array<Phase2PlanMemoSubmissionTransient,
               AppGLSubmissionGroup::kMaxTransients> transients{};

    bool operator==(const Phase2PlanMemoSubmissionGroup& other) const {
        if (kind != other.kind ||
            primaryReason != other.primaryReason ||
            declared != other.declared ||
            argumentBuffersEnabled != other.argumentBuffersEnabled ||
            approximateFallbackDisallowed !=
                other.approximateFallbackDisallowed ||
            subgroupCount != other.subgroupCount ||
            readCount != other.readCount ||
            writeCount != other.writeCount ||
            transientCount != other.transientCount) {
            return false;
        }
        for (std::uint8_t i = 0; i < subgroupCount; ++i) {
            if (!(subgroups[i] == other.subgroups[i])) {
                return false;
            }
        }
        for (std::uint8_t i = 0; i < readCount; ++i) {
            if (!(reads[i] == other.reads[i])) {
                return false;
            }
        }
        for (std::uint8_t i = 0; i < writeCount; ++i) {
            if (!(writes[i] == other.writes[i])) {
                return false;
            }
        }
        for (std::uint8_t i = 0; i < transientCount; ++i) {
            if (!(transients[i] == other.transients[i])) {
                return false;
            }
        }
        return true;
    }
};

