    const std::string* fragmentMSL = nullptr;
    std::size_t fragmentMSLSize = 0;
    const char* fragmentMSLData = nullptr;
    const ShaderReflection* vertexReflection = nullptr;
    const ShaderReflection* fragmentReflection = nullptr;
    GLuint vaoName = 0;
