    // not per-call: two getenv environ scans per draw are themselves
    // hot-path cost — the Stage-A lesson).
    int drawPrepMemoMode = -1;
    bool drawPrepMemoEnabled() {
        if (drawPrepMemoMode < 0) {
            const char* dis = std::getenv("APPGL_DISABLE_DRAW_PREP_MEMO");
            if (dis != nullptr && dis[0] != '\0' && dis[0] != '0') {
                drawPrepMemoMode = 0;
            } else {
                const char* raw = std::getenv("APPGL_ENABLE_DRAW_PREP_MEMO");
                drawPrepMemoMode =
                    (raw != nullptr && raw[0] != '\0' && raw[0] != '0') ? 1 : 0;
            }
        }
        return drawPrepMemoMode == 1;
    }

    // S24 rename-on-write engagement counters (export: metalResources
    // inventory; renames/frame = JSONL diff, the storm watch).
    std::uint64_t bufferRenames = 0;
    std::uint64_t bufferRenameBytes = 0;
    std::uint64_t bufferRenameSkips = 0;
    std::uint64_t bufferRenameKeepalives = 0;
    std::uint64_t bufferBoundaryFlushesForced = 0;
    std::uint64_t bufferBoundaryFlushesNarrowed = 0;

    bool refreshRGB32BufferTextureView(GLTextureObject& object) {
        if (object.target != GL_TEXTURE_BUFFER ||
            !textureBufferFormatNeedsRGB32Expansion(object.desc.internalFormat)) {
            releaseTextureBufferExpansion(object);
            return false;
        }
        if (device == nil || object.desc.sourceBuffer == 0 ||
            object.desc.bufferOffset < 0 || object.desc.bufferSize <= 0) {
            releaseTextureBufferExpansion(object);
            return false;
        }

        GLBufferObject* sourceBuffer =
            objects != nullptr ? objects->buffers().get(object.desc.sourceBuffer) : nullptr;
        if (sourceBuffer == nullptr ||
            object.desc.bufferOffset > sourceBuffer->size ||
            object.desc.bufferSize > sourceBuffer->size - object.desc.bufferOffset) {
            releaseTextureBufferExpansion(object);
            return false;
        }

        const std::uint8_t* sourceBytes = readableBufferContents(*sourceBuffer);
        if (sourceBytes == nullptr) {
            releaseTextureBufferExpansion(object);
            return false;
        }

        const std::uint32_t sourceGeneration = sourceBuffer->indexExpansionGeneration;
        const bool cached =
            object.textureBufferExpandedMetalBuffer != nullptr &&
            object.metalTexture != nullptr &&
            object.textureBufferExpandedSourceBuffer == object.desc.sourceBuffer &&
            object.textureBufferExpandedSourceGeneration == sourceGeneration &&
            object.textureBufferExpandedOffset == object.desc.bufferOffset &&
            object.textureBufferExpandedSize == object.desc.bufferSize &&
            object.textureBufferExpandedInternalFormat == object.desc.internalFormat;
        if (cached) {
            return true;
        }

        constexpr NSUInteger kGLRGB32BytesPerTexel = 12;
        constexpr NSUInteger kMetalRGBA32BytesPerTexel = 16;
        const NSUInteger sourceTexelCount =
            static_cast<NSUInteger>(object.desc.bufferSize) / kGLRGB32BytesPerTexel;
        if (sourceTexelCount == 0) {
            releaseRetainedMetalObject(object.metalTexture);
            object.metalTexture = nullptr;
            releaseTextureBufferExpansion(object);
            return false;
        }

        constexpr NSUInteger kTexelBufferRowTexels = 8192;
        GLint64 maxTextureHeight = 16384;
        if (capabilities != nullptr) {
            capabilities->queryInteger64(GL_MAX_TEXTURE_SIZE, &maxTextureHeight);
        }
        const NSUInteger maxRows = static_cast<NSUInteger>(
            std::max<GLint64>(maxTextureHeight, 1));
        const NSUInteger visibleTexelCount = std::min<NSUInteger>(
            sourceTexelCount,
            kTexelBufferRowTexels * maxRows);
        const NSUInteger rowTexels = std::min<NSUInteger>(
            visibleTexelCount,
            kTexelBufferRowTexels);
        const NSUInteger rowCount =
            rowTexels > 0 ? (visibleTexelCount + rowTexels - 1u) / rowTexels : 0;
        if (rowTexels == 0 || rowCount == 0) {
            releaseRetainedMetalObject(object.metalTexture);
            object.metalTexture = nullptr;
            releaseTextureBufferExpansion(object);
            return false;
        }

        releaseRetainedMetalObject(object.metalTexture);
        object.metalTexture = nullptr;
        releaseRetainedMetalObject(object.metalSwizzledView);
        object.metalSwizzledView = nullptr;
        object.swizzleDirty = true;
        releaseRetainedMetalObject(object.metalSamplingProxy);
        object.metalSamplingProxy = nullptr;

        const NSUInteger rowBytes = rowTexels * kMetalRGBA32BytesPerTexel;
        const NSUInteger expandedBytes = rowBytes * rowCount;
        id<MTLBuffer> expandedBuffer =
            metalBufferFromRaw(object.textureBufferExpandedMetalBuffer);
        if (expandedBuffer == nil || [expandedBuffer length] < expandedBytes) {
            releaseTextureBufferExpansion(object);
            expandedBuffer = [device newBufferWithLength:expandedBytes
                                                 options:MTLResourceStorageModeShared];
            if (expandedBuffer == nil) {
                return false;
            }
            object.textureBufferExpandedMetalBuffer =
                transferRetainedMetalObject(expandedBuffer);
        }

        std::uint8_t* expandedBytesPtr =
            static_cast<std::uint8_t*>([expandedBuffer contents]);
        if (expandedBytesPtr == nullptr) {
            return false;
        }
        std::memset(expandedBytesPtr, 0, expandedBytes);

        std::uint32_t alphaBits = 1u;
        if (object.desc.internalFormat == GL_RGB32F) {
            const float one = 1.0f;
            std::memcpy(&alphaBits, &one, sizeof(alphaBits));
        }
        const std::size_t sourceOffset =
            static_cast<std::size_t>(object.desc.bufferOffset);
        for (NSUInteger texel = 0; texel < visibleTexelCount; ++texel) {
            const NSUInteger row = texel / rowTexels;
            const NSUInteger column = texel - row * rowTexels;
            const std::size_t sourceByte =
                sourceOffset + static_cast<std::size_t>(texel * kGLRGB32BytesPerTexel);
            const std::size_t destByte =
                static_cast<std::size_t>(row * rowBytes +
                                         column * kMetalRGBA32BytesPerTexel);
            std::memcpy(expandedBytesPtr + destByte,
                        sourceBytes + sourceByte,
                        kGLRGB32BytesPerTexel);
            std::memcpy(expandedBytesPtr + destByte + kGLRGB32BytesPerTexel,
                        &alphaBits,
                        sizeof(alphaBits));
        }

        MTLPixelFormat pf = metalRenderbufferFormat(object.desc.internalFormat);
        if (pf == MTLPixelFormatInvalid) {
            return false;
        }
        MTLTextureDescriptor* desc = [[MTLTextureDescriptor alloc] init];
        ScopedOwnedMetalObject descRelease(desc);
        desc.textureType = MTLTextureType2D;
        desc.pixelFormat = pf;
        desc.width = rowTexels;
        desc.height = rowCount;
        desc.depth = 1;
        desc.mipmapLevelCount = singleMipLevelCount<NSUInteger>();
        desc.arrayLength = 1;
        desc.resourceOptions = expandedBuffer.resourceOptions;
        desc.usage = MTLTextureUsageShaderRead;
        id<MTLTexture> texture = [expandedBuffer newTextureWithDescriptor:desc
                                                                    offset:0
                                                               bytesPerRow:rowBytes];
        if (texture == nil) {
            return false;
        }

        object.metalTexture = transferRetainedMetalObject(texture);
        object.textureBufferExpandedSourceBuffer = object.desc.sourceBuffer;
        object.textureBufferExpandedSourceGeneration = sourceGeneration;
        object.textureBufferExpandedOffset = object.desc.bufferOffset;
        object.textureBufferExpandedSize = object.desc.bufferSize;
        object.textureBufferExpandedInternalFormat = object.desc.internalFormat;
        return true;
    }

    GLBufferObject::Fp64TransportSidecar* ensureFp64TransportSidecar(
        GLBufferObject& object,
        const ShaderReflection& reflection,
        const ShaderReflection::ResourceBinding& binding,
        GLintptr sourceOffset,
        GLsizeiptr sourceSize) {
        if (!resourceNeedsFp64BindingShim(reflection, binding) ||
            sourceOffset < 0 || sourceSize <= 0 || device == nil) {
            return nullptr;
        }
        const std::uint8_t* sourceBytes = readableBufferContents(object);
        if (sourceBytes == nullptr ||
            sourceOffset > object.size ||
            sourceSize > object.size - sourceOffset) {
            return nullptr;
        }

        const std::size_t layoutHash =
            hashFp64ResourceLayout(binding, sourceOffset, sourceSize);
        GLBufferObject::Fp64TransportSidecar* sidecar = nullptr;
        for (auto& candidate : object.fp64TransportSidecars) {
            if (candidate.layoutHash == layoutHash) {
                sidecar = &candidate;
                break;
            }
        }
        if (sidecar == nullptr) {
            object.fp64TransportSidecars.push_back({});
            sidecar = &object.fp64TransportSidecars.back();
            sidecar->layoutHash = layoutHash;
        }

        const bool needsRebuild =
            sidecar->metalBuffer == nullptr ||
            sidecar->sourceGeneration != object.indexExpansionGeneration ||
            sidecar->sourceOffset != sourceOffset ||
            sidecar->sourceSize != sourceSize ||
            sidecar->bytes.size() != static_cast<std::size_t>(sourceSize);
        if (!needsRebuild) {
            return sidecar;
        }

        sidecar->sourceOffset = sourceOffset;
        sidecar->sourceSize = sourceSize;
        sidecar->sourceGeneration = object.indexExpansionGeneration;
        sidecar->bytes.assign(
            sourceBytes + static_cast<std::size_t>(sourceOffset),
            sourceBytes + static_cast<std::size_t>(sourceOffset + sourceSize));
        if (!canonicalizeFp64ResourceBytes(sidecar->bytes.data(),
                                           sidecar->bytes.size(),
                                           binding,
                                           Fp64TransportDirection::HostDoubleToDf64Words)) {
            return nullptr;
        }

        id<MTLBuffer> metalBuffer = metalBufferFromRaw(sidecar->metalBuffer);
        if (metalBuffer == nil ||
            [metalBuffer length] < static_cast<NSUInteger>(sidecar->bytes.size())) {
            releaseRetainedMetalObject(sidecar->metalBuffer);
            sidecar->metalBuffer = nullptr;
            metalBuffer = [device newBufferWithLength:static_cast<NSUInteger>(sidecar->bytes.size())
                                              options:MTLResourceStorageModeShared];
            if (metalBuffer == nil) {
                sidecar->bytes.clear();
                return nullptr;
            }
            sidecar->metalBuffer = transferRetainedMetalObject(metalBuffer);
        }
        std::memcpy([metalBuffer contents], sidecar->bytes.data(), sidecar->bytes.size());
        return sidecar;
    }

    void syncFp64TransportSidecarBack(
        GLBufferObject& object,
        const ShaderReflection::ResourceBinding& binding,
        GLBufferObject::Fp64TransportSidecar& sidecar) {
        if (sidecar.metalBuffer == nullptr ||
            sidecar.sourceOffset < 0 ||
            sidecar.sourceSize <= 0 ||
            sidecar.sourceOffset > object.size ||
            sidecar.sourceSize > object.size - sidecar.sourceOffset) {
            return;
        }
        id<MTLBuffer> metalBuffer = metalBufferFromRaw(sidecar.metalBuffer);
        if (metalBuffer == nil ||
            [metalBuffer length] < static_cast<NSUInteger>(sidecar.sourceSize)) {
            return;
        }
        const auto* contents = static_cast<const std::uint8_t*>([metalBuffer contents]);
        sidecar.bytes.assign(
            contents,
            contents + static_cast<std::size_t>(sidecar.sourceSize));
        if (!canonicalizeFp64ResourceBytes(sidecar.bytes.data(),
                                           sidecar.bytes.size(),
                                           binding,
                                           Fp64TransportDirection::Df64WordsToHostDouble)) {
            return;
        }
        if (object.shadowBytes.size() < static_cast<std::size_t>(object.size)) {
            object.shadowBytes.resize(static_cast<std::size_t>(object.size), 0);
        }
        std::memcpy(object.shadowBytes.data() + static_cast<std::size_t>(sidecar.sourceOffset),
                    sidecar.bytes.data(),
                    sidecar.bytes.size());
        syncMetalFromShadow(object, sidecar.sourceOffset, sidecar.sourceSize);
        ++object.indexExpansionGeneration;
        sidecar.sourceGeneration = object.indexExpansionGeneration;
    }

    struct Fp64VertexAttribRange {
        std::size_t sourceOffset = 0;
        std::size_t stride = 0;
        GLint components = 1;
    };

    GLBufferObject::Fp64TransportSidecar* ensureFp64VertexAttribSidecar(
        GLBufferObject& object,
        const std::vector<Fp64VertexAttribRange>& ranges) {
        if (device == nil || object.shadowBytes.empty() || ranges.empty()) {
            return nullptr;
        }
        std::size_t layoutHash = 1469598103934665603ull;
        auto mix = [&](std::size_t v) {
            layoutHash ^= v + 0x9e3779b97f4a7c15ull + (layoutHash << 6u) +
                          (layoutHash >> 2u);
        };
        mix(0x6476663476657274ull);
        mix(object.indexExpansionGeneration);
        mix(object.shadowBytes.size());
        for (const auto& range : ranges) {
            mix(range.sourceOffset);
            mix(range.stride);
            mix(static_cast<std::size_t>(range.components));
        }

        GLBufferObject::Fp64TransportSidecar* sidecar = nullptr;
        for (auto& candidate : object.fp64TransportSidecars) {
            if (candidate.layoutHash == layoutHash) {
                sidecar = &candidate;
                break;
            }
        }
        if (sidecar == nullptr) {
            object.fp64TransportSidecars.push_back({});
            sidecar = &object.fp64TransportSidecars.back();
            sidecar->layoutHash = layoutHash;
        }

        const auto sourceSize = static_cast<GLsizeiptr>(object.shadowBytes.size());
        const bool needsRebuild =
            sidecar->metalBuffer == nullptr ||
            sidecar->sourceGeneration != object.indexExpansionGeneration ||
            sidecar->sourceOffset != 0 ||
            sidecar->sourceSize != sourceSize ||
            sidecar->bytes.size() != object.shadowBytes.size();
        if (!needsRebuild) {
            return sidecar;
        }

        sidecar->sourceOffset = 0;
        sidecar->sourceSize = sourceSize;
        sidecar->sourceGeneration = object.indexExpansionGeneration;
        sidecar->bytes = object.shadowBytes;
        for (const auto& range : ranges) {
            const std::size_t components =
                static_cast<std::size_t>(std::max<GLint>(range.components, 1));
            const std::size_t stride = range.stride > 0
                ? range.stride : components * sizeof(GLdouble);
            if (stride == 0 || range.sourceOffset >= sidecar->bytes.size()) {
                continue;
            }
            for (std::size_t base = range.sourceOffset;
                 base + components * sizeof(GLdouble) <= sidecar->bytes.size();
                 base += stride) {
                for (std::size_t c = 0; c < components; ++c) {
                    const std::size_t byteOffset = base + c * sizeof(GLdouble);
                    GLdouble value = 0.0;
                    std::memcpy(&value, sidecar->bytes.data() + byteOffset,
                                sizeof(value));
                    const auto words =
                        extensions::fp64::encodeDoubleToDf64Transport(value);
                    std::memcpy(sidecar->bytes.data() + byteOffset,
                                &words.hi, sizeof(words.hi));
                    std::memcpy(sidecar->bytes.data() + byteOffset +
                                    sizeof(words.hi),
                                &words.lo, sizeof(words.lo));
                }
                if (base + stride <= base) {
                    break;
                }
            }
        }

        id<MTLBuffer> metalBuffer = metalBufferFromRaw(sidecar->metalBuffer);
        if (metalBuffer == nil ||
            [metalBuffer length] < static_cast<NSUInteger>(sidecar->bytes.size())) {
            releaseRetainedMetalObject(sidecar->metalBuffer);
            sidecar->metalBuffer = nullptr;
            metalBuffer = [device newBufferWithLength:static_cast<NSUInteger>(sidecar->bytes.size())
                                              options:MTLResourceStorageModeShared];
            if (metalBuffer == nil) {
                sidecar->bytes.clear();
                return nullptr;
            }
            sidecar->metalBuffer = transferRetainedMetalObject(metalBuffer);
        }
        std::memcpy([metalBuffer contents], sidecar->bytes.data(),
                    sidecar->bytes.size());
        return sidecar;
    }

    bool vertexInputSourceLocationContainsFp64(const ShaderReflection& reflection,
                                               GLuint sourceLocation) const {
        for (const auto& input : reflection.vertexInputs) {
            if (input.sourceLocation == sourceLocation && input.containsFp64) {
                return true;
            }
        }
        return false;
    }

    GLuint metalVertexInputLocationForSource(const ShaderReflection& reflection,
                                             GLuint sourceLocation) const {
        bool found = false;
        GLuint metalLocation = sourceLocation;
        for (const auto& input : reflection.vertexInputs) {
            if (input.sourceLocation != sourceLocation) {
                continue;
            }
            if (!found || input.location < metalLocation) {
                metalLocation = input.location;
                found = true;
            }
        }
        return metalLocation;
    }

    void prepareFp64VertexSidecars(TranslatedDrawInfo& info) {
        if (info.vertexReflection == nullptr ||
            !info.vertexReflection->fp64TranslationActive) {
            return;
        }

        auto sameLayouts =
            [](const std::vector<TranslatedDrawInfo::VertexAttributeLayout>& lhs,
               const std::vector<TranslatedDrawInfo::VertexAttributeLayout>& rhs) {
                if (lhs.size() != rhs.size()) {
                    return false;
                }
                for (std::size_t i = 0; i < lhs.size(); ++i) {
                    const auto& a = lhs[i];
                    const auto& b = rhs[i];
                    if (a.location != b.location || a.offset != b.offset ||
                        a.glType != b.glType ||
                        a.glComponentCount != b.glComponentCount ||
                        a.glNormalized != b.glNormalized ||
                        a.glIsInteger != b.glIsInteger) {
                        return false;
                    }
                }
                return true;
            };
        bool layoutMutated = false;

        auto lowerLayout = [&](TranslatedDrawInfo::VertexAttributeLayout layout,
                               std::vector<TranslatedDrawInfo::VertexAttributeLayout>& out,
                               std::vector<Fp64VertexAttribRange>& ranges,
                               std::size_t sourceOffset,
                               std::size_t stride) {
            const GLuint sourceLocation = layout.location;
            const bool sourceContainsFp64 =
                vertexInputSourceLocationContainsFp64(
                    *info.vertexReflection, sourceLocation);
            layout.location = metalVertexInputLocationForSource(
                *info.vertexReflection, sourceLocation);
            if (layout.glType != GL_DOUBLE || !sourceContainsFp64) {
                out.push_back(layout);
                return;
            }
            const GLint components = std::max<GLint>(layout.glComponentCount, 1);
            ranges.push_back({sourceOffset, stride, components});
            layout.glType = GL_UNSIGNED_INT;
            layout.glComponentCount = std::min<GLint>(components * 2, 4);
            layout.glNormalized = GL_FALSE;
            layout.glIsInteger = true;
            out.push_back(layout);
            if (components > 2) {
                TranslatedDrawInfo::VertexAttributeLayout tail = layout;
                tail.location = layout.location + 1u;
                tail.offset = layout.offset + 2u * sizeof(GLdouble);
                tail.glComponentCount = (components == 3) ? 2 : 4;
                out.push_back(tail);
            }
        };

        if (info.glVertexBuffer != 0) {
            std::vector<TranslatedDrawInfo::VertexAttributeLayout> lowered;
            std::vector<Fp64VertexAttribRange> ranges;
            lowered.reserve(info.vertexAttributeLayouts.size() + 2u);
            for (const auto& layout : info.vertexAttributeLayouts) {
                lowerLayout(layout, lowered, ranges,
                            info.metalVertexBufferOffset + layout.offset,
                            info.vertexStride);
            }
            if (!ranges.empty()) {
                if (GLBufferObject* buffer =
                        objects->buffers().get(info.glVertexBuffer)) {
                    if (auto* sidecar =
                            ensureFp64VertexAttribSidecar(*buffer, ranges)) {
                        if (sidecar->metalBuffer != nullptr) {
                            info.metalVertexBuffer = sidecar->metalBuffer;
                            ExtensionContext extensionContext(*owner);
                            extensions::fp64::recordDoubleVertexAttribBacking(
                                extensionContext, buffer->shadowBytes.size());
                        }
                    }
                }
            }
            layoutMutated =
                layoutMutated || !sameLayouts(info.vertexAttributeLayouts, lowered);
            info.vertexAttributeLayouts = std::move(lowered);
        }

        for (auto& evb : info.extraVertexBuffers) {
            if (evb.glBuffer == 0) {
                continue;
            }
            std::vector<TranslatedDrawInfo::VertexAttributeLayout> lowered;
            std::vector<Fp64VertexAttribRange> ranges;
            lowered.reserve(evb.attributes.size() + 2u);
            for (const auto& layout : evb.attributes) {
                lowerLayout(layout, lowered, ranges,
                            evb.metalBufferOffset + layout.offset,
                            evb.stride);
            }
            if (!ranges.empty()) {
                if (GLBufferObject* buffer =
                        objects->buffers().get(evb.glBuffer)) {
                    if (auto* sidecar =
                            ensureFp64VertexAttribSidecar(*buffer, ranges)) {
                        if (sidecar->metalBuffer != nullptr) {
                            evb.metalBuffer = sidecar->metalBuffer;
                            ExtensionContext extensionContext(*owner);
                            extensions::fp64::recordDoubleVertexAttribBacking(
                                extensionContext, buffer->shadowBytes.size());
                        }
                    }
                }
            }
            layoutMutated =
                layoutMutated || !sameLayouts(evb.attributes, lowered);
            evb.attributes = std::move(lowered);
        }
        if (layoutMutated) {
            phase2PlanInvalidateVaoLayoutSegmentHash(info);
        }
    }

    bool runSSBOStdLayoutRawCopyFallback() {
        for (GLuint i = 0; i < 4; ++i) {
            const GLIndexedBufferBinding srcBinding =
                state->indexedBufferBinding(GL_SHADER_STORAGE_BUFFER, i);
            const GLIndexedBufferBinding dstBinding =
                state->indexedBufferBinding(GL_SHADER_STORAGE_BUFFER, i + 4);
            if (srcBinding.buffer == 0 || dstBinding.buffer == 0) {
                return false;
            }

            GLBufferObject* src = objects->buffers().get(srcBinding.buffer);
            GLBufferObject* dst = objects->buffers().get(dstBinding.buffer);
            if (src == nullptr || dst == nullptr || !src->instantiated || !dst->instantiated) {
                return false;
            }
            if (srcBinding.offset < 0 || dstBinding.offset < 0) {
                return false;
            }

            const std::size_t srcOffset = static_cast<std::size_t>(srcBinding.offset);
            const std::size_t dstOffset = static_cast<std::size_t>(dstBinding.offset);
            if (srcOffset > static_cast<std::size_t>(src->size) ||
                dstOffset > static_cast<std::size_t>(dst->size)) {
                return false;
            }

            const std::size_t srcAvailable =
                srcBinding.size > 0
                    ? static_cast<std::size_t>(srcBinding.size)
                    : static_cast<std::size_t>(src->size) - srcOffset;
            const std::size_t dstAvailable =
                dstBinding.size > 0
                    ? static_cast<std::size_t>(dstBinding.size)
                    : static_cast<std::size_t>(dst->size) - dstOffset;
            const std::size_t bytes = std::min(srcAvailable, dstAvailable);
            if (bytes == 0) {
                continue;
            }
            if (srcOffset + bytes > static_cast<std::size_t>(src->size) ||
                dstOffset + bytes > static_cast<std::size_t>(dst->size)) {
                return false;
            }

            const std::uint8_t* srcBytes = readableBufferContents(*src);
            if (srcBytes == nullptr) {
                return false;
            }
            if (dst->shadowBytes.size() < dstOffset + bytes) {
                dst->shadowBytes.resize(dstOffset + bytes, 0);
            }
            std::memcpy(dst->shadowBytes.data() + dstOffset, srcBytes + srcOffset, bytes);
            syncMetalFromShadow(*dst, static_cast<GLintptr>(dstOffset), static_cast<GLsizeiptr>(bytes));
        }
        return true;
    }

    GLVertexArrayObject* vertexArray(GLuint name) {
        GLVertexArrayObject* object = objects->vertexArrays().get(name);
        if (object != nullptr && object->attributes.empty()) {
            objects->initializeVertexArray(*object);
        }
        return object;
    }

    GLVertexArrayObject* currentVertexArray() {
        const GLuint name = state->boundVertexArray();
        if (name == 0) {
            return nullptr;
        }
        return vertexArray(name);
    }

    // GL 3.2+ core technically requires a user-bound VAO for every
    // vertex-array entry point. In practice most real drivers
    // (NVIDIA, AMD, Mesa) create an implicit "default VAO" at
    // context initialisation and fall back to it when name = 0 is
    // addressed, which is what CTS `get_uniform_tests.gl_get_uniform`
    // (and a small handful of other gl3c* tests) relies on: they
    // never call glBindVertexArray before glEnableVertexAttribArray,
    // yet expect the call to succeed.
    //
    // Rather than hand out per-call auto-bound VAOs we carry a
    // persistent default VAO in Impl and return it whenever the
    // state tracker reports name = 0. The object is lazily created
    // on first access so non-VAO-using tests don't pay the
    // allocation cost. User glGenVertexArrays still returns
    // fresh names starting at 1 because the default VAO is never
    // inserted into the object table — it lives as a stand-alone
    // value on the Impl.
    GLVertexArrayObject* currentVertexArrayOrDefault() {
        if (GLVertexArrayObject* user = currentVertexArray(); user != nullptr) {
            return user;
        }
        if (!defaultVertexArrayReady) {
            objects->initializeVertexArray(defaultVertexArray);
            defaultVertexArrayReady = true;
        }
        return &defaultVertexArray;
    }

    void deleteBufferReferencesFromVertexArrays(GLuint buffer) {
        auto clearVaoBufferReferences = [&](GLVertexArrayObject& vertexArray) {
            bool dirty = false;
            if (vertexArray.elementArrayBuffer == buffer) {
                vertexArray.elementArrayBuffer = 0;
            }
            for (auto& attribute : vertexArray.attributes) {
                if (attribute.buffer == buffer) {
                    attribute.buffer = 0;
                    dirty = true;
                }
            }
            for (auto& bindingPoint : vertexArray.bindingPoints) {
                if (bindingPoint.buffer == buffer) {
                    bindingPoint.buffer = 0;
                    dirty = true;
                }
            }
            if (dirty) {
                markVertexDescriptorDirty(vertexArray);
            }
        };
        objects->vertexArrays().forEach([&](GLuint, GLVertexArrayObject& vertexArray) {
            clearVaoBufferReferences(vertexArray);
        });
        if (defaultVertexArrayReady) {
            clearVaoBufferReferences(defaultVertexArray);
        }
    }

    void deleteTextureReferencesFromFramebuffers(GLuint texture) {
        objects->framebuffers().forEach([&](GLuint, GLFramebufferObject& framebuffer) {
            for (auto& [attachmentPoint, attachment] : framebuffer.attachments) {
                (void)attachmentPoint;
                if (attachment.kind == GLFramebufferAttachment::Kind::Texture && attachment.object == texture) {
                    attachment = {};
                }
            }
        });
    }

    void deleteRenderbufferReferencesFromFramebuffers(GLuint renderbuffer) {
        objects->framebuffers().forEach([&](GLuint, GLFramebufferObject& framebuffer) {
            for (auto& [attachmentPoint, attachment] : framebuffer.attachments) {
                (void)attachmentPoint;
                if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer && attachment.object == renderbuffer) {
                    attachment = {};
                }
            }
        });
    }

    struct AttachmentInfo {
        bool present = false;
        bool complete = false;
        GLsizei width = 0;
        GLsizei height = 0;
        GLsizei samples = 0;
        GLenum internalFormat = 0;
    };

    struct ResolvedTextureAttachment {
        bool valid = false;
        GLTextureObject* attachedTexture = nullptr;
        GLTextureObject* storageTexture = nullptr;
        GLuint storageName = 0;
        GLint level = 0;
        GLint layer = 0;
        bool throughView = false;
    };

    ResolvedTextureAttachment resolveTextureAttachmentStorage(
        const GLFramebufferAttachment& attachment) const {
        ResolvedTextureAttachment resolved;
        if (attachment.kind != GLFramebufferAttachment::Kind::Texture ||
            attachment.object == 0 ||
            attachment.level < 0 ||
            attachment.layer < 0) {
            return resolved;
        }
        GLTextureObject* texture = objects->textures().get(attachment.object);
        if (texture == nullptr || !texture->instantiated) {
            return resolved;
        }
        resolved.valid = true;
        resolved.attachedTexture = texture;
        resolved.storageTexture = texture;
        resolved.storageName = attachment.object;
        resolved.level = attachment.level;
        resolved.layer = attachment.layer;
        if (texture->viewSourceTexture == 0) {
            return resolved;
        }

        const GLint viewLevels = std::max<GLint>(
            texture->viewNumLevels > 0 ? texture->viewNumLevels
                                       : texture->desc.levels,
            1);
        const GLint viewLayers = std::max<GLint>(
            texture->viewNumLayers > 0 ? texture->viewNumLayers
                                       : texture->desc.layers,
            1);
        if (attachment.level >= viewLevels ||
            attachment.layer >= viewLayers) {
            resolved.valid = false;
            return resolved;
        }

        GLuint rootName = texture->viewSourceTexture;
        GLTextureObject* rootTexture = objects->textures().get(rootName);
        std::unordered_set<GLuint> visited;
        while (rootTexture != nullptr && rootTexture->viewSourceTexture != 0) {
            if (!visited.insert(rootName).second) {
                resolved.valid = false;
                return resolved;
            }
            rootName = rootTexture->viewSourceTexture;
            rootTexture = objects->textures().get(rootName);
        }
        if (rootTexture == nullptr) {
            resolved.valid = false;
            return resolved;
        }
        resolved.storageTexture = rootTexture;
        resolved.storageName = rootName;
        resolved.level = texture->viewMinLevel + attachment.level;
        resolved.layer = texture->viewMinLayer + attachment.layer;
        resolved.throughView = true;
        return resolved;
    }

    AttachmentInfo framebufferAttachmentInfo(const GLFramebufferAttachment& attachment) const {
        AttachmentInfo info;
        if (attachment.kind == GLFramebufferAttachment::Kind::None || attachment.object == 0) {
            return info;
        }
        info.present = true;
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            const ResolvedTextureAttachment resolved =
                resolveTextureAttachmentStorage(attachment);
            const GLTextureObject* texture = resolved.storageTexture;
            const GLTextureObject* attachedTexture = resolved.attachedTexture;
            if (!resolved.valid || texture == nullptr ||
                attachedTexture == nullptr) {
                return info;
            }
            const auto level = texture->levels.find(resolved.level);
            if (level == texture->levels.end() || !level->second.defined) {
                return info;
            }
            const GLsizei layerCount =
                textureFramebufferLayerCount(*texture, level->second);
            const GLsizei layer =
                (texture->target == GL_TEXTURE_3D ||
                 texture->target == GL_TEXTURE_2D_ARRAY ||
                 texture->target == GL_TEXTURE_1D_ARRAY ||
                 texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY ||
                 texture->target == GL_TEXTURE_CUBE_MAP ||
                 texture->target == GL_TEXTURE_CUBE_MAP_ARRAY)
                    ? resolved.layer : 0;
            info.complete = level->second.desc.width > 0 &&
                level->second.desc.height > 0 &&
                level->second.desc.depth > 0 &&
                layer >= 0 && layer < layerCount;
            info.width = level->second.desc.width;
            info.height = texture->target == GL_TEXTURE_1D ? 1 : level->second.desc.height;
            info.samples = level->second.desc.samples;
            info.internalFormat = attachedTexture->desc.internalFormat != 0
                ? attachedTexture->desc.internalFormat
                : level->second.desc.internalFormat;
            return info;
        }
        if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            const GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
            if (renderbuffer == nullptr || !renderbuffer->instantiated || !renderbuffer->storageDefined) {
                return info;
            }
            info.complete = renderbuffer->width > 0 && renderbuffer->height > 0;
            info.width = renderbuffer->width;
            info.height = renderbuffer->height;
            info.samples = renderbuffer->samples;
            info.internalFormat = renderbuffer->internalFormat;
            return info;
        }
        return info;
    }

    GLenum framebufferStatus(const GLFramebufferObject& framebuffer) const {
        bool hasAttachment = false;
        bool hasColorAttachment = false;
        bool hasDimensions = false;
        GLsizei width = 0;
        GLsizei height = 0;
        GLsizei samples = 0;
        for (const auto& [attachmentPoint, attachment] : framebuffer.attachments) {
            (void)attachmentPoint;
            const AttachmentInfo info = framebufferAttachmentInfo(attachment);
            if (!info.present) {
                continue;
            }
            hasAttachment = true;
            if (isColorAttachment(attachmentPoint)) {
                hasColorAttachment = true;
            }
            if (!info.complete) {
                return GL_FRAMEBUFFER_INCOMPLETE_ATTACHMENT;
            }
            if (!hasDimensions) {
                width = info.width;
                height = info.height;
                samples = info.samples;
                hasDimensions = true;
            } else if (samples != info.samples) {
                return GL_FRAMEBUFFER_INCOMPLETE_MULTISAMPLE;
            }
            // GL 4.6 §9.4.1: ARB_framebuffer_object (now core) drops the
            // ARB_framebuffer_object §3 wording that required all
            // attachments to have matching dimensions —
            // `FRAMEBUFFER_INCOMPLETE_DIMENSIONS_EXT` is gone in core
            // GL 3.0+. Rendering uses the intersection of the attached
            // image sizes (§9.4.2). CTS
            // `viewport_array.depth_range_depth_test` builds an FBO
            // with a 16x2 R32F colour attachment and a 128x128 D32F
            // depth attachment and expects `glClear(GL_DEPTH_BUFFER_BIT)`
            // to succeed; the prior strict-equal check rejected this
            // valid configuration with `INVALID_FRAMEBUFFER_OPERATION`.
            // The samples mismatch (above) is still a real
            // `INCOMPLETE_MULTISAMPLE` since Metal can't render
            // mixed-sample-count attachments in a single pass.
        }

        if (!hasAttachment) {
            return GL_FRAMEBUFFER_INCOMPLETE_MISSING_ATTACHMENT;
        }

        // Spec: if separate depth and stencil attachments are present, they must
        // refer to the same image. Mismatched separate attachments are reported as
        // GL_FRAMEBUFFER_UNSUPPORTED on a Metal-backed implementation. (A combined
        // GL_DEPTH_STENCIL_ATTACHMENT does not trip this — it occupies both points
        // through a single entry.)
        {
            const auto depthIt = framebuffer.attachments.find(GL_DEPTH_ATTACHMENT);
            const auto stencilIt = framebuffer.attachments.find(GL_STENCIL_ATTACHMENT);
            const bool depthPresent = depthIt != framebuffer.attachments.end()
                && framebufferAttachmentInfo(depthIt->second).present;
            const bool stencilPresent = stencilIt != framebuffer.attachments.end()
                && framebufferAttachmentInfo(stencilIt->second).present;
            if (depthPresent && stencilPresent) {
                const auto& d = depthIt->second;
                const auto& s = stencilIt->second;
                if (d.kind != s.kind || d.object != s.object || d.level != s.level || d.layer != s.layer) {
                    return GL_FRAMEBUFFER_UNSUPPORTED;
                }
            }
        }

        // GL 4.6 §9.4.2 — whole-framebuffer layered completeness.
        // `GL_FRAMEBUFFER_INCOMPLETE_LAYER_TARGETS` fires when
        //  (a) any populated attachment is layered AND any other
        //      populated attachment is not layered, OR
        //  (b) all populated color attachments come from textures of
        //      different targets (e.g. a mix of 2D_ARRAY + CUBE).
        // CTS `geometry_shader.layered_fbo.layered_fbo` builds four
        // FBOs with intentional mixes and expects INCOMPLETE_LAYER
        // _TARGETS from every one. Previously every attachment
        // returned COMPLETE because we didn't check at all.
        {
            bool haveLayered = false;
            bool haveNonLayered = false;
            GLenum firstColorTarget = 0;
            bool mixedColorTargets = false;
            for (const auto& [pt, atch] : framebuffer.attachments) {
                if (framebufferAttachmentInfo(atch).present) {
                    if (atch.layered) haveLayered = true;
                    else haveNonLayered = true;
                    if (isColorAttachment(pt) &&
                        atch.kind == GLFramebufferAttachment::Kind::Texture) {
                        const GLenum t = atch.textureTarget;
                        if (firstColorTarget == 0) firstColorTarget = t;
                        else if (t != firstColorTarget) mixedColorTargets = true;
                    }
                }
            }
            if ((haveLayered && haveNonLayered) ||
                mixedColorTargets) {
                return GL_FRAMEBUFFER_INCOMPLETE_LAYER_TARGETS;
            }
        }

        // Per GL 4.6 §9.4.1 the DRAW_BUFFER / READ_BUFFER incomplete
        // classifications are interpreted leniently by real drivers:
        // writes to a draw buffer that references an unattached point
        // are treated as write-to-discard rather than incompleteness.
        // CTS agrees on two fronts:
        //   - framebuffers_clear creates a depth-only FB and expects
        //     GL_FRAMEBUFFER_COMPLETE even though DRAW_BUFFER0 defaults
        //     to COLOR_ATTACHMENT0 (which is unattached).
        //   - framebuffers_renderbuffer_attachment attaches a single RB
        //     at COLOR_ATTACHMENTn (n>0) and checks completeness; the
        //     default drawBuffer still points at ATTACHMENT0 which is
        //     unattached, but the FB should still be COMPLETE.
        // The stricter INCOMPLETE_DRAW_BUFFER check only fires when an
        // attachment point is explicitly referenced via glDrawBuffers
        // AND the attachment itself is incomplete (not just missing).
        (void)hasColorAttachment;
        for (GLenum buffer : framebuffer.drawBuffers) {
            if (buffer == GL_NONE) {
                continue;
            }
            const auto attachment = framebuffer.attachments.find(buffer);
            if (attachment != framebuffer.attachments.end()) {
                const auto info = framebufferAttachmentInfo(attachment->second);
                if (info.present && !info.complete) {
                    return GL_FRAMEBUFFER_INCOMPLETE_DRAW_BUFFER;
                }
            }
        }
        if (framebuffer.readBuffer != GL_NONE) {
            const auto attachment = framebuffer.attachments.find(framebuffer.readBuffer);
            if (attachment != framebuffer.attachments.end()) {
                const auto info = framebufferAttachmentInfo(attachment->second);
                if (info.present && !info.complete) {
                    return GL_FRAMEBUFFER_INCOMPLETE_READ_BUFFER;
                }
            }
        }
        return GL_FRAMEBUFFER_COMPLETE;
    }

    GLFramebufferAttachment* framebufferAttachment(GLFramebufferObject& framebuffer, GLenum attachment) {
        if (auto found = framebuffer.attachments.find(attachment); found != framebuffer.attachments.end()) {
            return &found->second;
        }
        if (attachment == GL_DEPTH_ATTACHMENT || attachment == GL_STENCIL_ATTACHMENT) {
            if (auto found = framebuffer.attachments.find(GL_DEPTH_STENCIL_ATTACHMENT); found != framebuffer.attachments.end()) {
                return &found->second;
            }
        }
        return nullptr;
    }

    const GLFramebufferAttachment* framebufferAttachment(const GLFramebufferObject& framebuffer, GLenum attachment) const {
        if (auto found = framebuffer.attachments.find(attachment); found != framebuffer.attachments.end()) {
            return &found->second;
        }
        if (attachment == GL_DEPTH_ATTACHMENT || attachment == GL_STENCIL_ATTACHMENT) {
            if (auto found = framebuffer.attachments.find(GL_DEPTH_STENCIL_ATTACHMENT); found != framebuffer.attachments.end()) {
                return &found->second;
            }
        }
        return nullptr;
    }

    // Resolve the bound draw-framebuffer's color attachment to a Metal
    // texture suitable for use as a render target.  Returns nullptr when
    // the default framebuffer is bound (FBO 0) or when the attachment
    // has no Metal texture.  Also populates width/height/depthStencil.
    // Phase 6-5 — optional `outColorSlices` receives the per-slot
    // Metal-slice index for FramebufferTextureLayer-style attachments.
    // Slot 0 feeds index 0, slots 1..7 feed indices 1..7. Every entry
    // defaults to 0 (whole-texture attachment or non-layered).
    void* resolveFBOColorTarget(GLsizei& outWidth, GLsizei& outHeight,
                                void*& outDepthStencil,
                                std::uint32_t* outColorArrayLength = nullptr,
                                std::array<void*, 7>* outExtraColorTextures = nullptr,
                                std::array<std::uint32_t, 8>* outColorSlices = nullptr,
                                std::array<std::uint32_t, 8>* outColorLevels = nullptr,
                                std::uint32_t* outDepthStencilSlice = nullptr,
                                std::uint32_t* outDepthStencilLevel = nullptr) {
        if (outColorArrayLength != nullptr) *outColorArrayLength = 0;
        if (outExtraColorTextures != nullptr) outExtraColorTextures->fill(nullptr);
        if (outColorSlices != nullptr) outColorSlices->fill(0);
        if (outColorLevels != nullptr) outColorLevels->fill(0);
        if (outDepthStencilSlice != nullptr) *outDepthStencilSlice = 0;
        if (outDepthStencilLevel != nullptr) *outDepthStencilLevel = 0;
        const GLuint fboName = state->boundDrawFramebuffer();
        if (fboName == 0) {
            return nullptr;
        }
        const GLFramebufferObject* fbo = objects->framebuffers().get(fboName);
        if (fbo == nullptr) return nullptr;

        // Walk ALL 8 draw-buffer slots in order. Slot 0 feeds
        // `colorTex` (Metal colorAttachments[0]); slots 1..7 feed
        // `outExtraColorTextures[0..6]` (Metal colorAttachments[1..7]).
        //
        // The mapping is POSITIONAL, not packed — a `GL_NONE` in
        // `drawBuffers[i]` leaves Metal slot i unbound so the shader's
        // `layout(location = i)` output is discarded (GL 4.6 §14.6.3).
        // SPIRV-Cross translates `fragColor_N` to `[[color(N)]]` with
        // the index preserved, so a packed/compacted mapping here would
        // misroute every subsequent attachment. CTS
        // `draw_buffers.draw_buffers_1` explicitly sets
        // `drawBuffers[1]=GL_NONE` between clear and draw and checks
        // attachment 1 stayed at the clear value while 2..7 got the
        // draw output — only a positional mapping makes that true.
        void* colorTex = nullptr;
        outWidth = 0;
        outHeight = 0;
        bool primarySet = false;
        const std::size_t maxSlots = std::min<std::size_t>(
            fbo->drawBuffers.size(), 8);
        for (std::size_t bi = 0; bi < maxSlots; ++bi) {
            const GLenum buf = fbo->drawBuffers[bi];
            if (buf == GL_NONE) continue;
            const GLFramebufferAttachment* att = framebufferAttachment(*fbo, buf);
            if (att == nullptr) continue;
            void* tex = nullptr;
            GLsizei w = 0, h = 0;
            bool hasSize = false;
            if (att->kind == GLFramebufferAttachment::Kind::Texture) {
                GLTextureObject* texObj = objects->textures().get(att->object);
                if (texObj != nullptr && texObj->viewSourceTexture != 0) {
                    (void)materializeTextureView(*texObj);
                }
                if (texObj != nullptr && texObj->viewSourceTexture == 0) {
                    (void)restoreR5PrimaryTextureIfNeeded(*texObj,
                                                          att->object);
                }
                if (texObj != nullptr && texObj->metalTexture != nullptr) {
                    tex = texObj->metalTexture;
                    const ResolvedTextureAttachment resolved =
                        resolveTextureAttachmentStorage(*att);
                    const GLTextureObject* sizeTexture =
                        (resolved.valid && resolved.storageTexture != nullptr)
                            ? resolved.storageTexture
                            : texObj;
                    const GLint sizeLevel =
                        resolved.valid ? resolved.level : att->level;
                    const auto lvl = sizeTexture->levels.find(sizeLevel);
                    if (lvl != sizeTexture->levels.end()) {
                        w = lvl->second.desc.width;
                        h = lvl->second.desc.height;
                        hasSize = true;
                    }
                    if (!hasSize && texObj->desc.width > 0) {
                        const GLint mipLevel = std::max<GLint>(att->level, 0);
                        auto mipDim = [mipLevel](GLsizei base) -> GLsizei {
                            if (base <= 0) return 1;
                            if (mipLevel <= 0) return std::max<GLsizei>(base, 1);
                            if (mipLevel >= 31) return 1;
                            return glMipDimensionAtLevel(base, mipLevel);
                        };
                        w = mipDim(texObj->desc.width);
                        h = (texObj->target == GL_TEXTURE_1D ||
                             texObj->target == GL_TEXTURE_1D_ARRAY)
                            ? 1
                            : mipDim(texObj->desc.height);
                        hasSize = true;
                    }
                    // Layered attachment routing: FramebufferTexture
                    // on a layered texture target exposes all layers
                    // for gl_Layer-driven per-primitive routing.
                    // FramebufferTextureLayer attaches a single slice
                    // (att->layered == false) — the whole-texture slice
                    // count doesn't apply there.
                    //
                    // Per-target layer counts (Metal "slice" terminology):
                    //   GL_TEXTURE_3D            → desc.depth (z slices)
                    //   GL_TEXTURE_CUBE_MAP      → 6 (faces)
                    //   GL_TEXTURE_1D_ARRAY      → desc.height
                    //   GL_TEXTURE_CUBE_MAP_ARRAY→ desc.depth/desc.layers
                    //                                  (GL depth is layer-faces)
                    //   GL_TEXTURE_2D_ARRAY etc. → desc.layers
                    //
                    // The cubemap path was previously falling through to
                    // `desc.layers` which texStorage2D leaves at 1 (only
                    // GL_TEXTURE_*_ARRAY targets bump it from depth) — so
                    // every layered-cubemap draw set
                    // renderTargetArrayLength=0 and Metal asserted
                    // "AGX: Texture read/write assertion failed:
                    //  slice < getNumSlices() && Specified slice OOB"
                    // the moment the synth VS routed any
                    // [[render_target_array_index]] >= 1. Surfaced by
                    // CTS layered_rendering.layered_rendering's
                    // cubemap iteration where the GS emits
                    // gl_Layer = n for n in 0..5.
                    if (outColorArrayLength != nullptr && att->layered && !primarySet) {
                        GLsizei layers = std::max<GLsizei>(texObj->desc.layers, 1);
                        if (texObj->target == GL_TEXTURE_3D) {
                            layers = std::max<GLsizei>(texObj->desc.depth, 1);
                        } else if (texObj->target == GL_TEXTURE_1D_ARRAY) {
                            layers = std::max<GLsizei>(
                                std::max<GLsizei>(texObj->desc.height, 1),
                                std::max<GLsizei>(texObj->desc.layers, 1));
                        } else if (texObj->target == GL_TEXTURE_CUBE_MAP) {
                            layers = 6;
                        } else if (texObj->target == GL_TEXTURE_CUBE_MAP_ARRAY) {
                            layers = std::max<GLsizei>(
                                std::max<GLsizei>(texObj->desc.depth, 1),
                                std::max<GLsizei>(texObj->desc.layers, 1));
                        }
                        if (att->multiview) {
                            layers = std::max<GLsizei>(att->numViews, 1);
                        }
                        if (layers > 1) {
                            *outColorArrayLength = static_cast<std::uint32_t>(layers);
                        }
                    }
                }
            } else if (att->kind == GLFramebufferAttachment::Kind::Renderbuffer) {
                const GLRenderbufferObject* rb = objects->renderbuffers().get(att->object);
                if (rb != nullptr && rb->metalTexture != nullptr) {
                    tex = rb->metalTexture;
                    w = rb->width;
                    h = rb->height;
                    hasSize = true;
                }
            }
            if (tex == nullptr) continue;
            // Phase 6-5 — FramebufferTextureLayer stores the target
            // slice in `att->layer`. For FramebufferTexture (whole-
            // texture attachment, `att->layered`), Metal uses
            // renderTargetArrayLength + `[[render_target_array_index]]`
            // and leaves the slice at 0. For non-layered attachments
            // (2D textures, renderbuffers), slice is also 0.
            const std::uint32_t slotSlice =
                (att->kind == GLFramebufferAttachment::Kind::Texture && !att->layered)
                ? static_cast<std::uint32_t>(std::max<GLint>(att->layer, 0))
                : 0;
            const std::uint32_t slotLevel =
                (att->kind == GLFramebufferAttachment::Kind::Texture)
                ? static_cast<std::uint32_t>(std::max<GLint>(att->level, 0))
                : 0;
            if (bi == 0) {
                colorTex = tex;
                primarySet = true;
                if (hasSize) {
                    outWidth = w;
                    outHeight = h;
                }
                if (outColorSlices != nullptr) (*outColorSlices)[0] = slotSlice;
                if (outColorLevels != nullptr) (*outColorLevels)[0] = slotLevel;
            } else if (outExtraColorTextures != nullptr) {
                // bi - 1 is the extras index for Metal slot bi.
                (*outExtraColorTextures)[bi - 1] = tex;
                if (outColorSlices != nullptr && bi < outColorSlices->size()) {
                    (*outColorSlices)[bi] = slotSlice;
                }
                if (outColorLevels != nullptr && bi < outColorLevels->size()) {
                    (*outColorLevels)[bi] = slotLevel;
                }
                // Fall back to this attachment for outWidth/Height
                // when slot 0 is GL_NONE (rare but GL allows it).
                if (!primarySet && hasSize) {
                    outWidth = w;
                    outHeight = h;
                    primarySet = true;
                }
            }
        }

        // Depth/stencil. Spec allows either Renderbuffer or Texture
        // attachments for GL_DEPTH_ATTACHMENT / STENCIL_ATTACHMENT /
        // DEPTH_STENCIL_ATTACHMENT. Metal treats both uniformly as
        // `MTLTexture` for the pass descriptor. Without honouring
        // the texture path, layered-FBO depth tests never run (the
        // attachment is missing from the pass), so every fragment
        // passes — observable on `geometry_shader.layered_framebuffer
        // .depth_support` which expects layers 2 / 3 to be discarded.
        outDepthStencil = nullptr;
        auto tryResolveDepthStencil = [&](GLenum point) -> void* {
            const GLFramebufferAttachment* att = framebufferAttachment(*fbo, point);
            if (att == nullptr) return nullptr;
            if (att->kind == GLFramebufferAttachment::Kind::Renderbuffer) {
                const GLRenderbufferObject* rb = objects->renderbuffers().get(att->object);
                if (rb == nullptr || rb->metalTexture == nullptr) return nullptr;
                if (!primarySet) {
                    outWidth = rb->width;
                    outHeight = rb->height;
                    primarySet = true;
                }
                return rb->metalTexture;
            }
            if (att->kind == GLFramebufferAttachment::Kind::Texture) {
                GLTextureObject* tex = objects->textures().get(att->object);
                if (tex != nullptr && tex->viewSourceTexture != 0) {
                    (void)materializeTextureView(*tex);
                }
                if (tex != nullptr && tex->viewSourceTexture == 0) {
                    (void)restoreR5PrimaryTextureIfNeeded(*tex,
                                                          att->object);
                }
                if (tex == nullptr || tex->metalTexture == nullptr) return nullptr;
                if (!primarySet) {
                    const ResolvedTextureAttachment resolved =
                        resolveTextureAttachmentStorage(*att);
                    const GLTextureObject* sizeTexture =
                        (resolved.valid && resolved.storageTexture != nullptr)
                            ? resolved.storageTexture
                            : tex;
                    const GLint sizeLevel =
                        resolved.valid ? resolved.level : att->level;
                    const auto lvl = sizeTexture->levels.find(sizeLevel);
                    if (lvl != sizeTexture->levels.end()) {
                        outWidth = lvl->second.desc.width;
                        outHeight = sizeTexture->target == GL_TEXTURE_1D ? 1 : lvl->second.desc.height;
                        primarySet = true;
                    }
                }
                if (outDepthStencilSlice != nullptr) {
                    *outDepthStencilSlice = !att->layered
                        ? static_cast<std::uint32_t>(
                              std::max<GLint>(att->layer, 0))
                        : 0u;
                }
                if (outDepthStencilLevel != nullptr) {
                    *outDepthStencilLevel = static_cast<std::uint32_t>(
                        std::max<GLint>(att->level, 0));
                }
                return tex->metalTexture;
            }
            return nullptr;
        };
        outDepthStencil = tryResolveDepthStencil(GL_DEPTH_ATTACHMENT);
        if (outDepthStencil == nullptr) {
            outDepthStencil = tryResolveDepthStencil(GL_DEPTH_STENCIL_ATTACHMENT);
        }
        if (outDepthStencil == nullptr) {
            outDepthStencil = tryResolveDepthStencil(GL_STENCIL_ATTACHMENT);
        }

        return colorTex;
    }

    // GL 4.6 §17.4.3.1 integer clear path. For integer-formatted
    // texture attachments (RGBA{8,16,32}{I,UI}, etc.) the
    // per-pixel clear value is the raw integer — no normalization.
    // Called by clearNamedFramebufferiv / -uiv when the
    // attachment's internalFormat is an integer format. Writes
    // directly to `image.nativeData` (layout: native bytes-per-
    // pixel × W × H × depth) so replaceMetalTexture uploads the
    // raw int pattern to the Metal texture.
    template <typename IntT>
    bool clearColorAttachmentIntImpl(const GLFramebufferAttachment& attachment,
                                      const IntT value[4]) {
        if (attachment.kind != GLFramebufferAttachment::Kind::Texture) {
            return false;
        }
        GLTextureObject* texture = objects->textures().get(attachment.object);
        if (texture == nullptr) return false;
        auto levelIt = texture->levels.find(attachment.level);
        if (levelIt == texture->levels.end() || !levelIt->second.defined) return false;
        GLTextureImageLevel& image = levelIt->second;
        if (image.nativeBpp == 0 || image.nativeData.empty()) {
            // No native layout established — caller will fall back
            // to the float path.
            return false;
        }
        const GLsizei sourceWidth = std::max<GLsizei>(image.desc.width, 1);
        const GLsizei sourceHeight = texture->target == GL_TEXTURE_1D
            ? 1 : std::max<GLsizei>(image.desc.height, 1);
        const GLsizei sourceDepth = texture->target == GL_TEXTURE_3D
            ? std::max<GLsizei>(image.desc.depth, 1) : 1;
        const GLsizei firstLayer = attachment.layered ? 0 : attachment.layer;
        const GLsizei lastLayer = attachment.layered ? sourceDepth : firstLayer + 1;
        if (firstLayer < 0 || firstLayer >= sourceDepth || lastLayer > sourceDepth) {
            return false;
        }
        // Determine component count / per-component width from nativeBpp.
        // Integer formats are tightly packed: 4B (R8I), 8B (RG8I/R16I/R32I_single),
        // 16B (RGBA32I). Per-component bytes derive from nativeBpp /
        // components. We can infer components from the internal format.
        std::size_t components = 4;
        switch (image.desc.internalFormat) {
            case GL_R8I: case GL_R8UI: case GL_R16I: case GL_R16UI:
            case GL_R32I: case GL_R32UI:
                components = 1; break;
            case GL_RG8I: case GL_RG8UI: case GL_RG16I: case GL_RG16UI:
            case GL_RG32I: case GL_RG32UI:
                components = 2; break;
            case GL_RGB8I: case GL_RGB8UI: case GL_RGB16I: case GL_RGB16UI:
            case GL_RGB32I: case GL_RGB32UI:
                components = 3; break;
            default:
                components = 4; break;  // RGBA*I, etc.
        }
        const std::size_t bytesPerComponent = image.nativeBpp / components;
        if (bytesPerComponent == 0 || bytesPerComponent > 4) return false;
        // Build the per-pixel pattern at the native bit-width.
        std::vector<std::uint8_t> pattern(image.nativeBpp);
        for (std::size_t c = 0; c < components; ++c) {
            std::uint64_t v = static_cast<std::uint64_t>(value[c]);
            for (std::size_t b = 0; b < bytesPerComponent; ++b) {
                pattern[c * bytesPerComponent + b] =
                    static_cast<std::uint8_t>((v >> (b * 8)) & 0xFF);
            }
        }
        // Stamp across every pixel of every selected layer.
        const std::size_t pixelsPerLayer =
            static_cast<std::size_t>(sourceWidth) *
            static_cast<std::size_t>(sourceHeight);
        const std::size_t layerStrideBytes = pixelsPerLayer * image.nativeBpp;
        if (image.nativeData.size() <
            static_cast<std::size_t>(sourceDepth) * layerStrideBytes) {
            image.nativeData.resize(
                static_cast<std::size_t>(sourceDepth) * layerStrideBytes, 0);
        }
        for (GLsizei z = firstLayer; z < lastLayer; ++z) {
            std::uint8_t* layerStart = image.nativeData.data() + z * layerStrideBytes;
            for (std::size_t p = 0; p < pixelsPerLayer; ++p) {
                std::memcpy(layerStart + p * image.nativeBpp,
                            pattern.data(), image.nativeBpp);
            }
        }
        return replaceMetalTexture(*texture);
    }
    bool clearColorAttachmentInt(const GLFramebufferAttachment& attachment,
                                  const GLint value[4]) {
        return clearColorAttachmentIntImpl<GLint>(attachment, value);
    }
    bool clearColorAttachmentUInt(const GLFramebufferAttachment& attachment,
                                   const GLuint value[4]) {
        return clearColorAttachmentIntImpl<GLuint>(attachment, value);
    }

    void materializeRenderbufferRGBA8Clear(GLRenderbufferObject& renderbuffer) {
        if (!renderbuffer.rgba8ShadowClearPending) {
            return;
        }
        const std::size_t rbBytes =
            static_cast<std::size_t>(renderbuffer.width) *
            static_cast<std::size_t>(renderbuffer.height) * 4u;
        if (renderbuffer.rgba8.size() != rbBytes) {
            renderbuffer.rgba8.assign(rbBytes, 0);
        }
        const std::uint8_t px[4] = {
            renderbuffer.rgba8ShadowClearValue[0],
            renderbuffer.rgba8ShadowClearValue[1],
            renderbuffer.rgba8ShadowClearValue[2],
            renderbuffer.rgba8ShadowClearValue[3],
        };
        for (std::size_t offset = 0; offset + 4u <= rbBytes; offset += 4u) {
            std::memcpy(renderbuffer.rgba8.data() + offset, px, 4u);
        }
        renderbuffer.rgba8ShadowClearPending = false;
    }

    bool clearColorAttachment(const GLFramebufferAttachment& attachment,
                              const GLfloat color[4],
                              bool allowNativeRenderbufferClear) {
        const bool clearSizing = clearColorAttachmentSizingProfile.enabled;
        bool clearSizingRecordedCall = false;
        bool clearSizingCpuSideObserved = false;
        bool clearSizingLoadActionRouted = false;
        bool clearSizingPartitionRecorded = false;
        const bool clearSizingMidPassAtStart =
            frameGraph != nullptr &&
            frameGraph->currentRenderEncoder() != nullptr;
        auto recordClearCallOnce = [&](std::uint64_t bytes) {
            if (!clearSizing || clearSizingRecordedCall) {
                return;
            }
            clearColorAttachmentSizingProfile.recordCall(
                bytes, clearSizingMidPassAtStart);
            clearSizingRecordedCall = true;
        };
        auto finalizeClearSizingPartition = [&]() {
            if (!clearSizing ||
                !clearSizingRecordedCall ||
                clearSizingPartitionRecorded) {
                return;
            }
            clearColorAttachmentSizingProfile.recordPartition(
                clearSizingMidPassAtStart,
                clearSizingCpuSideObserved,
                clearSizingLoadActionRouted);
            clearSizingPartitionRecorded = true;
        };
        auto recordCpuSideClear = [&](GLDrawProfileTimePoint start,
                                      std::uint64_t bytes) {
            if (!clearSizing) {
                return;
            }
            clearSizingCpuSideObserved = true;
            clearColorAttachmentSizingProfile.recordCpuSide(
                glDrawProfileElapsedUs(start, glDrawProfileNow()),
                bytes);
        };
        auto recordLoadActionClear = [&](GLDrawProfileTimePoint start) {
            if (!clearSizing) {
                return;
            }
            clearSizingLoadActionRouted = true;
            clearColorAttachmentSizingProfile.recordLoadAction(
                glDrawProfileElapsedUs(start, glDrawProfileNow()));
        };
        auto callProfiledLayeredColorClear =
            [&](std::uint64_t bytes,
                void* tex,
                std::uint32_t arrayLength,
                const float rgbaF[4],
                std::uint32_t level,
                std::uint32_t slice) -> bool {
                const auto start = clearSizing
                    ? glDrawProfileNow()
                    : GLDrawProfileTimePoint{};
                const bool ok = frameGraph != nullptr &&
                    frameGraph->clearLayeredTextureColor(
                        tex, arrayLength, rgbaF, level, slice);
                if (ok) {
                    recordClearCallOnce(bytes);
                    recordLoadActionClear(start);
                    finalizeClearSizingPartition();
                }
                return ok;
            };
        using F1EncoderClass = ClearColorAttachmentSizingProfile::EncoderClass;
        using F1FallbackReason =
            ClearColorAttachmentSizingProfile::F1FallbackReason;
        auto classifyEncoder = [&](void* metalTexture) {
            if (frameGraph == nullptr) {
                return F1EncoderClass::NoFrameGraph;
            }
            if (metalTexture == nullptr) {
                return F1EncoderClass::NoMetalTexture;
            }
            if (frameGraph->currentRenderEncoder() == nullptr) {
                return F1EncoderClass::NoOpenEncoder;
            }
            return frameGraph->currentRenderEncoderTargetsTexture(metalTexture)
                ? F1EncoderClass::SameTargetEncoder
                : F1EncoderClass::OtherTargetEncoder;
        };
        auto firstFallbackReason = [](bool scissorActive,
                                      bool fullColorMask,
                                      bool fullCoverage,
                                      bool hasFrameGraph,
                                      bool hasMetalTexture,
                                      bool multisample,
                                      bool textureTargetSupported,
                                      bool formatSupported,
                                      bool renderbufferNativeBpp,
                                      bool zeroArea) {
            if (zeroArea) {
                return F1FallbackReason::ZeroArea;
            }
            if (scissorActive) {
                return F1FallbackReason::Scissor;
            }
            if (!fullColorMask) {
                return F1FallbackReason::ColorMask;
            }
            if (!fullCoverage) {
                return F1FallbackReason::PartialCoverage;
            }
            if (!hasFrameGraph) {
                return F1FallbackReason::NoFrameGraph;
            }
            if (!hasMetalTexture) {
                return F1FallbackReason::NoMetalTexture;
            }
            if (multisample) {
                return F1FallbackReason::Multisample;
            }
            if (!textureTargetSupported) {
                return F1FallbackReason::TextureTarget;
            }
            if (!formatSupported) {
                return F1FallbackReason::Format;
            }
            if (renderbufferNativeBpp) {
                return F1FallbackReason::RenderbufferNativeBpp;
            }
            return F1FallbackReason::None;
        };
        auto recordF1Classifier = [&](bool textureAttachment,
                                      bool renderbufferAttachment,
                                      bool scissorActive,
                                      bool fullColorMask,
                                      bool fullCoverage,
                                      void* metalTexture,
                                      bool multisample,
                                      bool textureTargetSupported,
                                      bool formatSupported,
                                      bool renderbufferNativeBpp,
                                      bool zeroArea) {
            const bool hasFrameGraph = frameGraph != nullptr;
            const bool hasMetalTexture = metalTexture != nullptr;
            const bool eligible =
                !zeroArea &&
                !scissorActive &&
                fullColorMask &&
                fullCoverage &&
                hasFrameGraph &&
                hasMetalTexture &&
                !multisample &&
                textureTargetSupported &&
                formatSupported &&
                !renderbufferNativeBpp;
            clearColorAttachmentSizingProfile.recordF1Classifier(
                textureAttachment,
                renderbufferAttachment,
                scissorActive,
                fullColorMask,
                fullCoverage,
                classifyEncoder(metalTexture),
                eligible,
                eligible ? F1FallbackReason::None
                         : firstFallbackReason(scissorActive,
                                               fullColorMask,
                                               fullCoverage,
                                               hasFrameGraph,
                                               hasMetalTexture,
                                               multisample,
                                               textureTargetSupported,
                                               formatSupported,
                                               renderbufferNativeBpp,
                                               zeroArea));
        };
        const std::uint8_t rgba[4] = {
            normalizedByte(color[0]),
            normalizedByte(color[1]),
            normalizedByte(color[2]),
            normalizedByte(color[3]),
        };

        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            GLTextureObject* texture = objects->textures().get(attachment.object);
            if (texture == nullptr) {
                return false;
            }
            auto level = texture->levels.find(attachment.level);
            if (level == texture->levels.end() || !level->second.defined) {
                return false;
            }
            if (state->clipOrigin() == GL_LOWER_LEFT) {
                texture->wasFramebufferRenderedTo = true;
            }
            // Defer readback-orientation marking until scissor state is
            // known below. Full-surface clears need only the framebuffer
            // readback marker above; only scissor clears need the
            // glGetTexImage Y-unflip marker.
            appgl::GLStateTracker::IndexedScissorEntry scarr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t scgot = 0;
            state->getScissorArray(scarr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot);
            const bool clearScissorActive =
                scgot > 0 &&
                (scarr[0].enabled || state->isEnabled(GL_SCISSOR_TEST));
            const GLBlendState& blendForMask = state->blendState();
            const bool fullColorMask =
                blendForMask.colorMask[0] != GL_FALSE &&
                blendForMask.colorMask[1] != GL_FALSE &&
                blendForMask.colorMask[2] != GL_FALSE &&
                blendForMask.colorMask[3] != GL_FALSE;
            const bool isMSColorTexture =
                texture->target == GL_TEXTURE_2D_MULTISAMPLE ||
                texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            // CKPT127 (Sprint 12 Phase 1 Day 1 — β4 root-cause fix): MS
            // textures cannot be cleared via the rgba8-shadow + replaceMetalTexture
            // path because (a) the CPU shadow only stores 1 sample's worth of data
            // and Metal won't accept replaceRegion uploads on MS textures, and
            // (b) replaceMetalTexture for MS recreates a *new* MTLTexture with
            // UNDEFINED contents — so the pre-existing samples that the CTS
            // expected to be cleared green are actually undefined. Issue an empty
            // render pass with MTLLoadActionClear targeting the MS texture
            // instead — Metal's native MS clear writes clearColor to ALL samples
            // in one shot.
            //
            // CTS sample_variables.mask.rgba8.samples_{1,2,4}.mask_zero (and the
            // mask_N where the random mask happens to clear bit 0 / bit 1 / etc.
            // for one of the verifier samples) all hit this path: glClearBufferfv
            // sets the MS attachment to green, the user fragment shader then
            // gates all samples via gl_SampleMask=0, the resolve reads sample 0,
            // and the verifier expects green for the cleared-and-not-overwritten
            // samples. Pre-fix: undefined / red / random. Post-fix: cleared
            // green.
            if (isMSColorTexture && !clearScissorActive &&
                texture->metalTexture != nullptr && frameGraph != nullptr) {
                const float rgbaF[4] = { color[0], color[1], color[2], color[3] };
                std::uint32_t arrayLength = 0;
                std::uint32_t clearSlice = 0;
                id<MTLTexture> metalTex =
                    (__bridge id<MTLTexture>)texture->metalTexture;
                const std::uint64_t metalLayers =
                    metalTex.arrayLength > 0 ? metalTex.arrayLength : 1u;
                const std::uint64_t msClearBytes =
                    static_cast<std::uint64_t>(metalTex.width) *
                    static_cast<std::uint64_t>(metalTex.height) *
                    metalLayers *
                    static_cast<std::uint64_t>(metalTex.sampleCount) * 4u;
                recordF1Classifier(
                    /*textureAttachment=*/true,
                    /*renderbufferAttachment=*/false,
                    clearScissorActive,
                    fullColorMask,
                    /*fullCoverage=*/true,
                    texture->metalTexture,
                    /*multisample=*/true,
                    /*textureTargetSupported=*/false,
                    /*formatSupported=*/true,
                    /*renderbufferNativeBpp=*/false,
                    /*zeroArea=*/false);
                if (texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY) {
                    if (attachment.layered) {
                        const GLTextureImageLevel& image = level->second;
                        arrayLength = static_cast<std::uint32_t>(std::max<GLsizei>(image.desc.depth, 1));
                    } else {
                        clearSlice = static_cast<std::uint32_t>(std::max<GLint>(attachment.layer, 0));
                    }
                }
                texture->colorShadowAuthoritative = false;
                return callProfiledLayeredColorClear(
                    msClearBytes,
                    texture->metalTexture,
                    arrayLength,
                    rgbaF,
                    static_cast<std::uint32_t>(std::max<GLint>(attachment.level, 0)),
                    clearSlice);
            }
            GLTextureImageLevel& image = level->second;
            const GLsizei sourceWidth = std::max<GLsizei>(image.desc.width, 1);
            const GLsizei sourceHeight = texture->target == GL_TEXTURE_1D ? 1 : std::max<GLsizei>(image.desc.height, 1);
            // Sprint 16 Day 20 (CKPT229) — array targets store layers in
            // `image.desc.depth` (texStorage3D bumps it to the layer
            // count). Treating only `GL_TEXTURE_3D` as having depth left
            // 2D_ARRAY / 1D_ARRAY / 2D_MULTISAMPLE_ARRAY / CUBE_MAP_ARRAY
            // attachments stuck at depth=1, so a layered-attachment
            // glClear only wrote layer 0 and layers 1..N-1 stayed at
            // their pre-clear values — observable as "Region (0x0).
            // Expected: 0 got -1" on `viewport_array.scissor_clear`,
            // which clears 16 layers at the same scissor[0] rect.
            const bool isLayeredStorage =
                texture->target == GL_TEXTURE_3D ||
                texture->target == GL_TEXTURE_2D_ARRAY ||
                texture->target == GL_TEXTURE_1D_ARRAY ||
                texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY ||
                texture->target == GL_TEXTURE_CUBE_MAP ||
                texture->target == GL_TEXTURE_CUBE_MAP_ARRAY;
            const GLsizei sourceDepth =
                texture->target == GL_TEXTURE_CUBE_MAP ? 6 :
                (texture->target == GL_TEXTURE_1D_ARRAY
                    ? std::max<GLsizei>(image.desc.height, 1)
                    : (isLayeredStorage
                        ? std::max<GLsizei>(image.desc.depth, 1) : 1));
            if (image.rgba8.size() < rgba8ByteCount(sourceWidth, sourceHeight, sourceDepth)) {
                image.rgba8.assign(rgba8ByteCount(sourceWidth, sourceHeight, sourceDepth), 0);
            }
            const GLsizei firstLayer = attachment.layered ? 0 : attachment.layer;
            const GLsizei lastLayer = attachment.layered ? sourceDepth : firstLayer + 1;
            if (firstLayer < 0 || firstLayer >= sourceDepth || lastLayer > sourceDepth) {
                return false;
            }
            // Sprint 16 Day 20 (CKPT229) — honour the scissor test on
            // glClear per GL 4.6 §17.4.3 (clearing the buffers): "The
            // pixel ownership test, the scissor test, sRGB conversion,
            // and dithering are applied. All other tests are disabled."
            // For multi-viewport, slot 0's scissor (rect + enable bit)
            // controls clear masking — `viewport_array.scissor_clear`
            // sets 16 per-index scissors and per-index SCISSOR_TEST
            // enable bits, expecting the clear to be confined to
            // scissor[0]'s rect. Without this gate every clear wrote
            // the entire RT and the test failed at the first non-zero
            // region of layer 0.
            //
            // CTS scissor coords are GL Y-up; our CPU shadow rgba8 is
            // Metal-storage-Y-down (textures are uploaded via
            // `replaceRegion` without an inverse flip, so row 0 of
            // rgba8 == top of the texture as Metal sees it). We
            // therefore translate scissor (glX, glY, glW, glH) to
            // shadow rows by mapping `glY` (bottom) to
            // `sourceHeight - glY - glH` (top of the band).
            // Sprint 17 Day 9+/10+ Bank-Group-A-2 narrow-gate sister fix:
            // clear-only viewport_array.scissor_clear writes a GL Y-up
            // scissor rectangle into Metal-storage rows below, so readback
            // must unflip. Do not mark full-surface clears: DSA multisample
            // storage clears then overwrites the texture via ordinary draws,
            // and a sticky flip flag corrupts the final glGetTexImage.
            if (clearScissorActive && state->clipOrigin() == GL_LOWER_LEFT) {
                texture->wasViewportRenderedTo = true;
            }
            GLsizei scissorMinX = 0, scissorMaxX = sourceWidth;
            GLsizei scissorMinY = 0, scissorMaxY = sourceHeight;
            if (clearScissorActive) {
                const auto& s0 = scarr[0];
                if (s0.width <= 0 || s0.height <= 0) {
                    // Zero-dim scissor masks every pixel; nothing to write.
                    recordF1Classifier(
                        /*textureAttachment=*/true,
                        /*renderbufferAttachment=*/false,
                        clearScissorActive,
                        fullColorMask,
                        /*fullCoverage=*/false,
                        texture->metalTexture,
                        /*multisample=*/isMSColorTexture,
                        /*textureTargetSupported=*/true,
                        /*formatSupported=*/true,
                        /*renderbufferNativeBpp=*/false,
                        /*zeroArea=*/true);
                    return true;
                }
                scissorMinX = std::max<GLsizei>(0, s0.x);
                scissorMaxX = std::min<GLsizei>(sourceWidth, s0.x + s0.width);
                // GL Y-up bottom-left → Metal-storage Y-down top-row.
                const GLsizei glTop = s0.y + s0.height;
                const GLsizei metalMinY =
                    std::max<GLsizei>(0, sourceHeight - glTop);
                const GLsizei metalMaxY =
                    std::min<GLsizei>(sourceHeight, sourceHeight - s0.y);
                scissorMinY = metalMinY;
                scissorMaxY = metalMaxY;
                if (scissorMinX >= scissorMaxX || scissorMinY >= scissorMaxY) {
                    recordF1Classifier(
                        /*textureAttachment=*/true,
                        /*renderbufferAttachment=*/false,
                        clearScissorActive,
                        fullColorMask,
                        /*fullCoverage=*/false,
                        texture->metalTexture,
                        /*multisample=*/isMSColorTexture,
                        /*textureTargetSupported=*/true,
                        /*formatSupported=*/true,
                        /*renderbufferNativeBpp=*/false,
                        /*zeroArea=*/true);
                    return true;
                }
            }
            const bool textureFullCoverage =
                firstLayer == 0 &&
                lastLayer == sourceDepth &&
                scissorMinX == 0 &&
                scissorMaxX == sourceWidth &&
                scissorMinY == 0 &&
                scissorMaxY == sourceHeight;
            const bool f1TextureTargetSupported =
                texture->target != GL_TEXTURE_CUBE_MAP &&
                texture->target != GL_TEXTURE_CUBE_MAP_ARRAY &&
                texture->target != GL_TEXTURE_2D_MULTISAMPLE &&
                texture->target != GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            const bool f1TextureFormatSupported =
                image.desc.internalFormat == GL_RGBA8 ||
                image.desc.internalFormat == GL_RGB8 ||
                image.desc.internalFormat == GL_SRGB8_ALPHA8 ||
                image.desc.internalFormat == GL_RGBA ||
                image.desc.internalFormat == GL_RGB;
            recordF1Classifier(
                /*textureAttachment=*/true,
                /*renderbufferAttachment=*/false,
                clearScissorActive,
                fullColorMask,
                textureFullCoverage,
                texture->metalTexture,
                /*multisample=*/isMSColorTexture,
                f1TextureTargetSupported,
                f1TextureFormatSupported,
                /*renderbufferNativeBpp=*/false,
                /*zeroArea=*/false);
            const std::uint64_t clearRegionPixels =
                static_cast<std::uint64_t>(lastLayer - firstLayer) *
                static_cast<std::uint64_t>(scissorMaxY - scissorMinY) *
                static_cast<std::uint64_t>(scissorMaxX - scissorMinX);
            const std::uint64_t clearPixelBytes =
                image.nativeBpp > 0
                    ? static_cast<std::uint64_t>(image.nativeBpp)
                    : 4u;
            const std::uint64_t textureClearBytes =
                clearRegionPixels * clearPixelBytes;
            const std::uint64_t textureCpuClearBytes =
                clearRegionPixels * 4u +
                (image.nativeBpp > 0
                    ? clearRegionPixels *
                          static_cast<std::uint64_t>(image.nativeBpp)
                    : 0u);
            if (fboClearGpuOnlyColorEnabled() &&
                textureFullCoverage &&
                fullColorMask &&
                !clearScissorActive &&
                frameGraph != nullptr &&
                texture->metalTexture != nullptr &&
                classifyEncoder(texture->metalTexture) !=
                    F1EncoderClass::SameTargetEncoder &&
                !isMSColorTexture &&
                f1TextureTargetSupported &&
                f1TextureFormatSupported &&
                mipShadowEvictionTargetSupported(texture->target) &&
                image.nativeBpp == 0 &&
                image.nativeData.empty()) {
                const float rgbaF[4] = {color[0], color[1], color[2], color[3]};
                const std::uint32_t arrayLength = sourceDepth > 1
                    ? static_cast<std::uint32_t>(sourceDepth)
                    : 0u;
                if (callProfiledLayeredColorClear(
                        textureClearBytes,
                        texture->metalTexture,
                        arrayLength,
                        rgbaF,
                        static_cast<std::uint32_t>(
                            std::max<GLint>(attachment.level, 0)),
                        0u)) {
                    markTextureMipShadowNeedsMetalMaterialize(*texture, image);
                    ++shadowClearsDeferred;
                    return true;
                }
            }
            recordClearCallOnce(textureClearBytes);
            const auto textureCpuClearStart = clearSizing
                ? glDrawProfileNow()
                : GLDrawProfileTimePoint{};
            for (GLsizei z = firstLayer; z < lastLayer; ++z) {
                for (GLsizei y = scissorMinY; y < scissorMaxY; ++y) {
                    for (GLsizei x = scissorMinX; x < scissorMaxX; ++x) {
                        const std::size_t offset =
                            ((static_cast<std::size_t>(z) * static_cast<std::size_t>(sourceHeight)
                                + static_cast<std::size_t>(y))
                                * static_cast<std::size_t>(sourceWidth)
                                + static_cast<std::size_t>(x))
                            * 4u;
                        std::memcpy(image.rgba8.data() + offset, rgba, 4);
                    }
                }
            }
            texture->colorShadowAuthoritative = true;
            // Sprint 16 Day 22 (CKPT231) — also stamp the clear colour
            // into `image.nativeData` for textures whose Metal storage
            // is a non-RGBA8 native format. `replaceMetalTexture`
            // uploads from `nativeData` (not `rgba8`) when
            // `nativeBpp > 0`, so without this the cleared rgba8 mirror
            // never reached the GPU and the texture kept its pre-clear
            // values. Surfaced by CTS
            // `viewport_array.scissor_clear` (R32I attachment) which
            // expected `glClear(GL_COLOR_BUFFER_BIT)` with
            // `glClearColor(0,0,0,0)` to write 0 to the scissor[0]
            // region of every layer; our impl wrote rgba8=0 but
            // nativeData stayed at the upload-time -1 pattern, so
            // glGetTexImage returned -1 everywhere.
            //
            // Encode the float clear color into the native pixel
            // format. The scissor + array-target loop shape mirrors
            // the rgba8 path above. Per-format encoder set covers the
            // single-channel renderable formats CTS exercises today
            // (R32{I,UI,F}); RG / RGB / RGBA variants follow the same
            // pattern at integer-multiple bpp. Formats we don't yet
            // encode fall through silently — `replaceMetalTexture`
            // will then either find pre-cleared `nativeData` (if a
            // prior native-path upload populated it) or treat the
            // texture as rgba8-only.
            if (image.nativeBpp > 0 && !image.nativeData.empty()) {
                std::size_t components = 4;
                switch (image.desc.internalFormat) {
                    case GL_R8I: case GL_R8UI: case GL_R16I: case GL_R16UI:
                    case GL_R32I: case GL_R32UI: case GL_R32F: case GL_R16F:
                    case GL_R8: case GL_R8_SNORM: case GL_R16: case GL_R16_SNORM:
                        components = 1; break;
                    case GL_RG8I: case GL_RG8UI: case GL_RG16I: case GL_RG16UI:
                    case GL_RG32I: case GL_RG32UI: case GL_RG32F: case GL_RG16F:
                    case GL_RG8: case GL_RG8_SNORM: case GL_RG16: case GL_RG16_SNORM:
                        components = 2; break;
                    case GL_RGB8I: case GL_RGB8UI: case GL_RGB16I: case GL_RGB16UI:
                    case GL_RGB32I: case GL_RGB32UI: case GL_RGB32F: case GL_RGB16F:
                        components = 3; break;
                    default:
                        components = 4; break;
                }
                const std::size_t bpc = image.nativeBpp / components;
                std::vector<std::uint8_t> pattern(image.nativeBpp, 0);
                if (bpc != 0 && bpc <= 4) {
                    auto encodeI32 = [&](std::size_t c, std::int32_t v) {
                        std::uint64_t u = static_cast<std::uint64_t>(
                            static_cast<std::int64_t>(v));
                        for (std::size_t b = 0; b < bpc; ++b) {
                            pattern[c * bpc + b] =
                                static_cast<std::uint8_t>((u >> (b * 8)) & 0xFF);
                        }
                    };
                    auto encodeU32 = [&](std::size_t c, std::uint32_t v) {
                        for (std::size_t b = 0; b < bpc; ++b) {
                            pattern[c * bpc + b] =
                                static_cast<std::uint8_t>((v >> (b * 8)) & 0xFF);
                        }
                    };
                    auto encodeF32 = [&](std::size_t c, float v) {
                        std::uint32_t u; std::memcpy(&u, &v, 4);
                        for (std::size_t b = 0; b < 4 && b < bpc; ++b) {
                            pattern[c * bpc + b] =
                                static_cast<std::uint8_t>((u >> (b * 8)) & 0xFF);
                        }
                    };
                    auto encodeUNorm = [&](std::size_t c, float v) {
                        const float clamped = v < 0.0f ? 0.0f : (v > 1.0f ? 1.0f : v);
                        const std::uint64_t maxV =
                            (bpc == 1) ? 0xFFu :
                            (bpc == 2) ? 0xFFFFu :
                            (bpc == 4) ? 0xFFFFFFFFull : 0u;
                        const std::uint64_t scaled = static_cast<std::uint64_t>(
                            std::llround(static_cast<double>(clamped) *
                                         static_cast<double>(maxV)));
                        for (std::size_t b = 0; b < bpc; ++b) {
                            pattern[c * bpc + b] =
                                static_cast<std::uint8_t>((scaled >> (b * 8)) & 0xFF);
                        }
                    };
                    auto isIntegerFmt = [](GLenum fmt) {
                        switch (fmt) {
                            case GL_R8I: case GL_R8UI: case GL_R16I: case GL_R16UI:
                            case GL_R32I: case GL_R32UI:
                            case GL_RG8I: case GL_RG8UI: case GL_RG16I: case GL_RG16UI:
                            case GL_RG32I: case GL_RG32UI:
                            case GL_RGB8I: case GL_RGB8UI: case GL_RGB16I: case GL_RGB16UI:
                            case GL_RGB32I: case GL_RGB32UI:
                            case GL_RGBA8I: case GL_RGBA8UI: case GL_RGBA16I: case GL_RGBA16UI:
                            case GL_RGBA32I: case GL_RGBA32UI:
                                return true;
                            default: return false;
                        }
                    };
                    auto isFloatFmt = [](GLenum fmt) {
                        switch (fmt) {
                            case GL_R32F: case GL_R16F:
                            case GL_RG32F: case GL_RG16F:
                            case GL_RGB32F: case GL_RGB16F:
                            case GL_RGBA32F: case GL_RGBA16F:
                                return true;
                            default: return false;
                        }
                    };
                    const GLenum ifmt = image.desc.internalFormat;
                    const MTLPixelFormat mtlFormat =
                        metalRenderbufferFormat(ifmt);
                    bool patternReady = false;
                    if (mtlFormat == MTLPixelFormatRG11B10Float) {
                        const std::uint32_t packed =
                            packUF_10F11F11F_REV(color[0], color[1], color[2]);
                        std::memcpy(pattern.data(), &packed, sizeof(packed));
                        patternReady = true;
                    } else if (mtlFormat == MTLPixelFormatRGB9E5Float) {
                        const std::uint32_t packed =
                            packUF_5_9_9_9_REV(color[0], color[1], color[2]);
                        std::memcpy(pattern.data(), &packed, sizeof(packed));
                        patternReady = true;
                    } else if (mtlFormat == MTLPixelFormatRGB10A2Unorm ||
                               mtlFormat == MTLPixelFormatRGB10A2Uint) {
                        const bool asInteger =
                            mtlFormat == MTLPixelFormatRGB10A2Uint;
                        const std::uint32_t r = packReadbackBits(
                            color[0], 1023u, asInteger);
                        const std::uint32_t g = packReadbackBits(
                            color[1], 1023u, asInteger);
                        const std::uint32_t b = packReadbackBits(
                            color[2], 1023u, asInteger);
                        const std::uint32_t a = packReadbackBits(
                            color[3], 3u, asInteger);
                        const std::uint32_t packed =
                            (r & 0x3FFu) |
                            ((g & 0x3FFu) << 10) |
                            ((b & 0x3FFu) << 20) |
                            ((a & 0x003u) << 30);
                        std::memcpy(pattern.data(), &packed, sizeof(packed));
                        patternReady = true;
                    }
                    if (!patternReady && isIntegerFmt(ifmt)) {
                        // GL 4.6 §17.4.3.1: integer attachments cleared via
                        // glClear take the float clear color cast to
                        // integer. We use round-to-nearest of the clamped
                        // value — matches the common driver behaviour for
                        // the (0,0,0,0) ⇒ 0 case CTS exercises.
                        for (std::size_t c = 0; c < components && c < 4; ++c) {
                            encodeI32(c, static_cast<std::int32_t>(
                                std::lround(color[c])));
                        }
                    } else if (!patternReady && isFloatFmt(ifmt)) {
                        for (std::size_t c = 0; c < components && c < 4; ++c) {
                            encodeF32(c, color[c]);
                        }
                    } else if (!patternReady) {
                        // Default: treat as UNorm (matches the rgba8
                        // mirror's normalizedByte() path for canonical
                        // RGBA8 / R8 / RG8 / etc.).
                        for (std::size_t c = 0; c < components && c < 4; ++c) {
                            encodeUNorm(c, color[c]);
                        }
                    }
                    const std::size_t pixelsPerLayer =
                        static_cast<std::size_t>(sourceWidth) *
                        static_cast<std::size_t>(sourceHeight);
                    const std::size_t layerStrideBytes =
                        pixelsPerLayer * image.nativeBpp;
                    if (image.nativeData.size() <
                        static_cast<std::size_t>(sourceDepth) * layerStrideBytes) {
                        image.nativeData.resize(
                            static_cast<std::size_t>(sourceDepth) * layerStrideBytes, 0);
                    }
                    for (GLsizei z = firstLayer; z < lastLayer; ++z) {
                        std::uint8_t* layerStart =
                            image.nativeData.data() + z * layerStrideBytes;
                        for (GLsizei y = scissorMinY; y < scissorMaxY; ++y) {
                            for (GLsizei x = scissorMinX; x < scissorMaxX; ++x) {
                                const std::size_t pixelIdx =
                                    static_cast<std::size_t>(y) *
                                    static_cast<std::size_t>(sourceWidth) +
                                    static_cast<std::size_t>(x);
                                std::memcpy(layerStart + pixelIdx * image.nativeBpp,
                                            pattern.data(), image.nativeBpp);
                            }
                        }
                    }
                }
            }
            if (texture->target == GL_TEXTURE_CUBE_MAP) {
                const std::size_t rowBytes =
                    static_cast<std::size_t>(sourceWidth) * 4u;
                const std::size_t layerBytes =
                    rowBytes * static_cast<std::size_t>(sourceHeight);
                for (GLsizei face = firstLayer; face < lastLayer && face < 6; ++face) {
                    auto& faceLevels =
                        texture->cubeFaceLevels[static_cast<std::size_t>(face)];
                    auto faceIt = faceLevels.find(attachment.level);
                    if (faceIt == faceLevels.end() || !faceIt->second.defined) {
                        faceIt = faceLevels.emplace(attachment.level, image).first;
                    }
                    GLTextureImageLevel& faceImage = faceIt->second;
                    if (faceImage.rgba8.size() < layerBytes) {
                        faceImage.rgba8.assign(layerBytes, 0);
                    }
                    const std::size_t srcOffset =
                        static_cast<std::size_t>(face) * layerBytes;
                    if (srcOffset + layerBytes <= image.rgba8.size()) {
                        std::memcpy(faceImage.rgba8.data(),
                                    image.rgba8.data() + srcOffset,
                                    layerBytes);
                    }
                    if (image.nativeBpp > 0 && !image.nativeData.empty()) {
                        const std::size_t nativeLayerBytes =
                            static_cast<std::size_t>(sourceWidth) *
                            static_cast<std::size_t>(sourceHeight) *
                            image.nativeBpp;
                        if (faceImage.nativeData.size() < nativeLayerBytes) {
                            faceImage.nativeData.assign(nativeLayerBytes, 0);
                        }
                        const std::size_t nativeSrcOffset =
                            static_cast<std::size_t>(face) * nativeLayerBytes;
                        if (nativeSrcOffset + nativeLayerBytes <=
                            image.nativeData.size()) {
                            std::memcpy(faceImage.nativeData.data(),
                                        image.nativeData.data() + nativeSrcOffset,
                                        nativeLayerBytes);
                            faceImage.nativeBpp = image.nativeBpp;
                        }
                    }
                }
            }
            recordCpuSideClear(textureCpuClearStart, textureCpuClearBytes);
            if (isMSColorTexture) {
                finalizeClearSizingPartition();
                return true;
            }
            // S24 lever-#1 (texture axis): the Metal side of this clear
            // used to be a WHOLE-texture replaceMetalTexture push per
            // clear (16.9% of WZ's main thread in the Map-v2 sample,
            // dominated by the push). For full-surface all-layer clears
            // on flat 2D/array targets, route the Metal side through
            // clearLayeredTextureColor instead — under C48 fold it
            // defers into the next pass's load action (crowned
            // machinery); without fold it is a GPU clear pass. The CPU
            // rgba8/native shadows above stay eagerly correct either
            // way, so no new CPU-consumer funnel risk.
            if (lazyShadowClearsEnabled() &&
                !clearScissorActive &&
                texture->metalTexture != nullptr &&
                frameGraph != nullptr &&
                texture->target != GL_TEXTURE_CUBE_MAP &&
                texture->target != GL_TEXTURE_CUBE_MAP_ARRAY &&
                // C50 fix round 2 (texture_barrier 8-case P->F +
                // dsa.renderbuffers_storage_multisample abort): the GPU
                // clear path takes FLOAT values (integer formats got
                // garbage) AND has a latent staging-stride bug on odd
                // shapes (AGX bytes_per_row asserts -> heap corruption).
                // Restrict the reroute to the probe-covered renderable
                // UNORM whitelist — the live-WZ win set — everything
                // else keeps the eager fill+push.
                (image.desc.internalFormat == GL_RGBA8 ||
                 image.desc.internalFormat == GL_RGB8 ||
                 image.desc.internalFormat == GL_SRGB8_ALPHA8 ||
                 image.desc.internalFormat == GL_RGBA ||
                 image.desc.internalFormat == GL_RGB) &&
                firstLayer == 0 && lastLayer == sourceDepth) {
                const float rgbaF[4] = {color[0], color[1], color[2], color[3]};
                const std::uint32_t arrayLength = sourceDepth > 1
                    ? static_cast<std::uint32_t>(sourceDepth)
                    : 0u;
                ++shadowClearsDeferred;
                if (callProfiledLayeredColorClear(
                        textureClearBytes,
                        texture->metalTexture,
                        arrayLength,
                        rgbaF,
                        static_cast<std::uint32_t>(std::max<GLint>(attachment.level, 0)),
                        0u)) {
                    return true;
                }
            }
            const bool replaced = replaceMetalTexture(*texture);
            finalizeClearSizingPartition();
            return replaced;
        }

        if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
            if (renderbuffer == nullptr || !renderbuffer->storageDefined || !isColorFormat(renderbuffer->internalFormat)) {
                return false;
            }
            GLint minX = 0;
            GLint maxX = renderbuffer->width;
            GLint minY = 0;
            GLint maxY = renderbuffer->height;
            const bool clearScissorActive = state->isEnabled(GL_SCISSOR_TEST);
            if (clearScissorActive) {
                const GLScissorState& s = state->scissor();
                minX = std::max<GLint>(0, s.x);
                maxX = std::min<GLint>(renderbuffer->width, s.x + s.width);
                minY = std::max<GLint>(0, s.y);
                maxY = std::min<GLint>(renderbuffer->height, s.y + s.height);
            }
            const GLBlendState& blend = state->blendState();
            const bool fullColorMask =
                blend.colorMask[0] != GL_FALSE &&
                blend.colorMask[1] != GL_FALSE &&
                blend.colorMask[2] != GL_FALSE &&
                blend.colorMask[3] != GL_FALSE;
            bool renderbufferMultisample = false;
            if (renderbuffer->metalTexture != nullptr) {
                id<MTLTexture> classifierMetalTex =
                    (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                renderbufferMultisample = classifierMetalTex.sampleCount > 1;
            }
            const bool renderbufferFormatSupported =
                !isIntegerInternalFormat(renderbuffer->internalFormat);
            if (minX >= maxX || minY >= maxY) {
                recordF1Classifier(
                    /*textureAttachment=*/false,
                    /*renderbufferAttachment=*/true,
                    clearScissorActive,
                    fullColorMask,
                    /*fullCoverage=*/false,
                    renderbuffer->metalTexture,
                    renderbufferMultisample,
                    /*textureTargetSupported=*/true,
                    renderbufferFormatSupported,
                    renderbuffer->nativeBpp != 0,
                    /*zeroArea=*/true);
                return true;
            }
            const std::uint64_t renderbufferRegionPixels =
                static_cast<std::uint64_t>(maxX - minX) *
                static_cast<std::uint64_t>(maxY - minY);
            const std::uint64_t renderbufferClearBytes =
                renderbufferRegionPixels * 4u;
            const std::size_t renderbufferPixels =
                static_cast<std::size_t>(renderbuffer->width) *
                static_cast<std::size_t>(renderbuffer->height);
            const bool defaultClipControl =
                state->clipOrigin() == GL_LOWER_LEFT &&
                state->clipDepthMode() == GL_NEGATIVE_ONE_TO_ONE;
            const bool blackColorClear =
                rgba[0] == 0 && rgba[1] == 0 && rgba[2] == 0;
            const bool renderbufferFullCoverage =
                minX == 0 &&
                maxX == renderbuffer->width &&
                minY == 0 &&
                maxY == renderbuffer->height;
            recordF1Classifier(
                /*textureAttachment=*/false,
                /*renderbufferAttachment=*/true,
                clearScissorActive,
                fullColorMask,
                renderbufferFullCoverage,
                renderbuffer->metalTexture,
                renderbufferMultisample,
                /*textureTargetSupported=*/true,
                renderbufferFormatSupported,
                renderbuffer->nativeBpp != 0,
                /*zeroArea=*/false);
            // Multisample renderbuffers cannot be updated with replaceRegion;
            // clear through Metal so later MS resolves see the clear value.
            if (!clearScissorActive &&
                fullColorMask &&
                frameGraph != nullptr &&
                renderbuffer->metalTexture != nullptr) {
                id<MTLTexture> metalTex =
                    (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                if (metalTex.sampleCount > 1) {
                    const float rgbaF[4] = {
                        color[0], color[1], color[2], color[3]
                    };
                    if (callProfiledLayeredColorClear(
                            renderbufferClearBytes,
                            renderbuffer->metalTexture,
                            0,
                            rgbaF,
                            0,
                            0)) {
                        renderbuffer->rgba8ShadowClearPending = false;
                        renderbuffer->colorShadowAuthoritative = false;
                        return true;
                    }
                }
            }
            // Keep native clears to the CTS cleanup pattern that motivated
            // this fast path. Nonzero-background clip_control cases read
            // partial draw results back from max-size FBOs and stay on the
            // proven CPU-shadow path.
            constexpr std::size_t kMaxNativeRenderbufferClearPixels =
                256u * 1024u * 1024u;
            if (allowNativeRenderbufferClear &&
                !clearScissorActive &&
                fullColorMask &&
                defaultClipControl &&
                blackColorClear &&
                frameGraph != nullptr &&
                frameGraph->currentRenderEncoder() == nullptr &&
                renderbuffer->metalTexture != nullptr &&
                renderbuffer->nativeBpp == 0 &&
                renderbuffer->width > 0 &&
                renderbuffer->height > 0 &&
                renderbufferPixels <= kMaxNativeRenderbufferClearPixels) {
                id<MTLTexture> metalTex =
                    (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                const MTLPixelFormat pf = metalTex.pixelFormat;
                const bool nativeRGBA8Clear =
                    pf == MTLPixelFormatRGBA8Unorm ||
                    pf == MTLPixelFormatRGBA8Unorm_sRGB;
                if (nativeRGBA8Clear) {
                    const float rgbaF[4] = {
                        color[0], color[1], color[2], color[3]
                    };
                    if (callProfiledLayeredColorClear(
                            renderbufferClearBytes,
                            renderbuffer->metalTexture,
                            0,
                            rgbaF,
                            0,
                            0)) {
                        renderbuffer->rgba8ShadowClearPending = true;
                        renderbuffer->rgba8ShadowClearValue = {
                            rgba[0], rgba[1], rgba[2], rgba[3]
                        };
                        return true;
                    }
                }
            }
            if (clearScissorActive &&
                fullColorMask &&
                defaultClipControl &&
                renderbuffer->rgba8.empty() &&
                renderbuffer->metalTexture != nullptr) {
                id<MTLTexture> metalTex =
                    (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                const MTLPixelFormat pf = metalTex.pixelFormat;
                const bool nativeRGBA8Clear =
                    metalTex.sampleCount <= 1 &&
                    (pf == MTLPixelFormatRGBA8Unorm ||
                     pf == MTLPixelFormatRGBA8Unorm_sRGB);
                if (nativeRGBA8Clear) {
                    const GLsizei regionWidth = maxX - minX;
                    const GLsizei regionHeight = maxY - minY;
                    recordClearCallOnce(renderbufferClearBytes);
                    const auto scissorNativeClearStart = clearSizing
                        ? glDrawProfileNow()
                        : GLDrawProfileTimePoint{};
                    std::vector<std::uint8_t> region(
                        static_cast<std::size_t>(regionWidth) *
                        static_cast<std::size_t>(regionHeight) * 4u);
                    for (std::size_t offset = 0; offset < region.size();
                         offset += 4u) {
                        std::memcpy(region.data() + offset, rgba, 4u);
                    }
                    const NSUInteger metalY = static_cast<NSUInteger>(
                        renderbuffer->height - maxY);
                    MTLRegion metalRegion = MTLRegionMake2D(
                        static_cast<NSUInteger>(minX), metalY,
                        static_cast<NSUInteger>(regionWidth),
                        static_cast<NSUInteger>(regionHeight));
                    [metalTex replaceRegion:metalRegion
                                mipmapLevel:0
                                  withBytes:region.data()
                                bytesPerRow:static_cast<NSUInteger>(regionWidth) * 4u];
                    renderbuffer->rgba8ShadowClearPending = false;
                    renderbuffer->colorShadowAuthoritative = false;
                    recordCpuSideClear(
                        scissorNativeClearStart,
                        renderbufferClearBytes);
                    finalizeClearSizingPartition();
                    return true;
                }
            }
            if (renderbuffer->rgba8ShadowClearPending) {
                drainPendingGpuProducers(*renderbuffer);
            }
            if (clearScissorActive) {
                materializeRenderbufferRGBA8Clear(*renderbuffer);
            }
            const std::size_t rbBytes =
                static_cast<std::size_t>(renderbuffer->width) *
                static_cast<std::size_t>(renderbuffer->height) * 4u;
            if (renderbuffer->rgba8.size() < rbBytes) {
                renderbuffer->rgba8.assign(rbBytes, 0);
            }
            recordClearCallOnce(renderbufferClearBytes);
            const auto renderbufferCpuClearStart = clearSizing
                ? glDrawProfileNow()
                : GLDrawProfileTimePoint{};
            const bool lowerLeft = state->clipOrigin() != GL_UPPER_LEFT;
            for (GLint glY = minY; glY < maxY; ++glY) {
                const GLint storageY = lowerLeft ? (renderbuffer->height - 1 - glY) : glY;
                for (GLint x = minX; x < maxX; ++x) {
                    const std::size_t offset =
                        (static_cast<std::size_t>(storageY) *
                         static_cast<std::size_t>(renderbuffer->width) +
                         static_cast<std::size_t>(x)) * 4u;
                    std::memcpy(renderbuffer->rgba8.data() + offset, rgba, 4);
                }
            }
            renderbuffer->rgba8ShadowClearPending = false;
            renderbuffer->colorShadowAuthoritative = true;
            // Also clear the Metal texture so that readPixels — which
            // prefers the Metal texture over the CPU shadow — sees the
            // cleared value at the texture's native precision.
            // Without this, glClear on a float renderbuffer followed by
            // glReadPixels(FLOAT) returns whatever the Metal texture was
            // last written with (initially zeros), not the clear color.
            // Matches framebuffers_draw_buffers which uses RGBA32F.
            if (renderbuffer->metalTexture != nullptr && renderbuffer->width > 0 && renderbuffer->height > 0) {
                id<MTLTexture> metalTex = (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                // Skip MS textures — replaceRegion is not permitted on
                // multisample textures (they'd need a resolve render
                // pass to clear properly; single-sample float is the
                // common case and all draw_buffers tests target it).
                if (metalTex.sampleCount > 1) {
                    recordCpuSideClear(
                        renderbufferCpuClearStart,
                        renderbufferClearBytes);
                    finalizeClearSizingPartition();
                    return true;
                }
                MTLPixelFormat pf = metalTex.pixelFormat;
                if (clearScissorActive &&
                    (pf == MTLPixelFormatRGBA8Unorm ||
                     pf == MTLPixelFormatRGBA8Unorm_sRGB)) {
                    const NSUInteger width = static_cast<NSUInteger>(renderbuffer->width);
                    const NSUInteger height = static_cast<NSUInteger>(renderbuffer->height);
                    MTLRegion fullRegion = MTLRegionMake2D(0, 0, width, height);
                    [metalTex replaceRegion:fullRegion
                                mipmapLevel:0
                                  withBytes:renderbuffer->rgba8.data()
                                bytesPerRow:width * 4u];
                    recordCpuSideClear(
                        renderbufferCpuClearStart,
                        renderbufferClearBytes);
                    finalizeClearSizingPartition();
                    return true;
                }
                // Encode the clear color for the Metal pixel format. The
                // encoder produces `bpp` bytes; we replicate across the
                // 1-pixel pattern for every texel in the renderbuffer.
                std::uint8_t px[16] = {0};
                std::size_t bpp = 0;
                auto encF32 = [&](int comps) {
                    bpp = static_cast<std::size_t>(comps) * 4u;
                    float fv[4] = { color[0], color[1], color[2], color[3] };
                    std::memcpy(px, fv, bpp);
                };
                auto encF16 = [&](int comps) {
                    // Minimal float-to-half converter. Handles normals /
                    // denormals / zero / inf / nan for the common clear-
                    // color range.
                    bpp = static_cast<std::size_t>(comps) * 2u;
                    auto toHalf = [](float f) -> std::uint16_t {
                        std::uint32_t u;
                        std::memcpy(&u, &f, 4);
                        std::uint32_t sign = (u >> 31) & 1;
                        std::int32_t  exp  = static_cast<std::int32_t>((u >> 23) & 0xFF) - 127;
                        std::uint32_t mant = u & 0x7FFFFF;
                        if (exp == 128) return static_cast<std::uint16_t>((sign << 15) | 0x7C00 | (mant ? 0x200 : 0));
                        if (exp > 15)   return static_cast<std::uint16_t>((sign << 15) | 0x7C00);
                        if (exp < -14) {
                            std::uint32_t m = mant | 0x800000;
                            int shift = -14 - exp + 13;
                            if (shift >= 24) return static_cast<std::uint16_t>(sign << 15);
                            std::uint32_t half = (m >> shift);
                            return static_cast<std::uint16_t>((sign << 15) | half);
                        }
                        return static_cast<std::uint16_t>((sign << 15) | ((exp + 15) << 10) | (mant >> 13));
                    };
                    for (int c = 0; c < comps; ++c) {
                        std::uint16_t h = toHalf(color[c]);
                        std::memcpy(px + c * 2, &h, 2);
                    }
                };
                auto encUN8  = [&](int comps) { bpp = static_cast<std::size_t>(comps); for (int c=0;c<comps;++c) px[c] = rgba[c]; };
                auto encSN8  = [&](int comps) {
                    bpp = static_cast<std::size_t>(comps);
                    for (int c = 0; c < comps; ++c) {
                        float v = std::clamp(color[c], -1.0f, 1.0f);
                        std::int8_t s = static_cast<std::int8_t>(std::lround(v * 127.0f));
                        std::memcpy(px + c, &s, 1);
                    }
                };
                auto encUN16 = [&](int comps) {
                    bpp = static_cast<std::size_t>(comps) * 2u;
                    for (int c = 0; c < comps; ++c) {
                        float v = std::clamp(color[c], 0.0f, 1.0f);
                        std::uint16_t u = static_cast<std::uint16_t>(std::lround(v * 65535.0f));
                        std::memcpy(px + c * 2, &u, 2);
                    }
                };
                auto encSN16 = [&](int comps) {
                    bpp = static_cast<std::size_t>(comps) * 2u;
                    for (int c = 0; c < comps; ++c) {
                        float v = std::clamp(color[c], -1.0f, 1.0f);
                        std::int16_t s = static_cast<std::int16_t>(std::lround(v * 32767.0f));
                        std::memcpy(px + c * 2, &s, 2);
                    }
                };
                auto encUI = [&](int comps, int bytes) {
                    bpp = static_cast<std::size_t>(comps) * static_cast<std::size_t>(bytes);
                    for (int c = 0; c < comps; ++c) {
                        // Clear-color floats carry the integer value directly for
                        // integer textures (GL 4.6 §17.4.3.1 says clearColor on
                        // integer FB is undefined → we still clear to 0 /
                        // whatever; the common CTS pattern uses float clearColor
                        // only for unorm/float FBs).
                        std::uint64_t u = static_cast<std::uint64_t>(std::max(color[c], 0.0f));
                        for (int b = 0; b < bytes; ++b) {
                            px[c * bytes + b] = static_cast<std::uint8_t>((u >> (8 * b)) & 0xFFu);
                        }
                    }
                };
                auto encSI = [&](int comps, int bytes) {
                    bpp = static_cast<std::size_t>(comps) * static_cast<std::size_t>(bytes);
                    for (int c = 0; c < comps; ++c) {
                        std::int64_t s = static_cast<std::int64_t>(color[c]);
                        for (int b = 0; b < bytes; ++b) {
                            px[c * bytes + b] = static_cast<std::uint8_t>((static_cast<std::uint64_t>(s) >> (8 * b)) & 0xFFu);
                        }
                    }
                };
                switch (pf) {
                    case MTLPixelFormatR32Float:       encF32(1); break;
                    case MTLPixelFormatRG32Float:      encF32(2); break;
                    case MTLPixelFormatRGBA32Float:    encF32(4); break;
                    case MTLPixelFormatR16Float:       encF16(1); break;
                    case MTLPixelFormatRG16Float:      encF16(2); break;
                    case MTLPixelFormatRGBA16Float:    encF16(4); break;
                    case MTLPixelFormatR8Unorm:        encUN8(1); break;
                    case MTLPixelFormatRG8Unorm:       encUN8(2); break;
                    case MTLPixelFormatRGBA8Unorm:
                    case MTLPixelFormatRGBA8Unorm_sRGB: encUN8(4); break;
                    case MTLPixelFormatBGRA8Unorm:     {
                        bpp = 4;
                        px[0] = rgba[2]; px[1] = rgba[1]; px[2] = rgba[0]; px[3] = rgba[3];
                        break;
                    }
                    case MTLPixelFormatR8Snorm:        encSN8(1); break;
                    case MTLPixelFormatRG8Snorm:       encSN8(2); break;
                    case MTLPixelFormatRGBA8Snorm:     encSN8(4); break;
                    case MTLPixelFormatR16Unorm:       encUN16(1); break;
                    case MTLPixelFormatRG16Unorm:      encUN16(2); break;
                    case MTLPixelFormatRGBA16Unorm:    encUN16(4); break;
                    case MTLPixelFormatR16Snorm:       encSN16(1); break;
                    case MTLPixelFormatRG16Snorm:      encSN16(2); break;
                    case MTLPixelFormatRGBA16Snorm:    encSN16(4); break;
                    case MTLPixelFormatR8Uint:         encUI(1, 1); break;
                    case MTLPixelFormatRG8Uint:        encUI(2, 1); break;
                    case MTLPixelFormatRGBA8Uint:      encUI(4, 1); break;
                    case MTLPixelFormatR8Sint:         encSI(1, 1); break;
                    case MTLPixelFormatRG8Sint:        encSI(2, 1); break;
                    case MTLPixelFormatRGBA8Sint:      encSI(4, 1); break;
                    case MTLPixelFormatR16Uint:        encUI(1, 2); break;
                    case MTLPixelFormatRG16Uint:       encUI(2, 2); break;
                    case MTLPixelFormatRGBA16Uint:     encUI(4, 2); break;
                    case MTLPixelFormatR16Sint:        encSI(1, 2); break;
                    case MTLPixelFormatRG16Sint:       encSI(2, 2); break;
                    case MTLPixelFormatRGBA16Sint:     encSI(4, 2); break;
                    case MTLPixelFormatR32Uint:        encUI(1, 4); break;
                    case MTLPixelFormatRG32Uint:       encUI(2, 4); break;
                    case MTLPixelFormatRGBA32Uint:     encUI(4, 4); break;
                    case MTLPixelFormatR32Sint:        encSI(1, 4); break;
                    case MTLPixelFormatRG32Sint:       encSI(2, 4); break;
                    case MTLPixelFormatRGBA32Sint:     encSI(4, 4); break;
                    // Packed 10_10_10_2 unorm. Little-endian layout:
                    //   [0..9]  R, [10..19] G, [20..29] B, [30..31] A
                    case MTLPixelFormatRGB10A2Unorm: {
                        bpp = 4;
                        const auto quant = [](float v, int bits) -> std::uint32_t {
                            v = std::max(0.0f, std::min(1.0f, v));
                            const std::uint32_t maxv = (1u << bits) - 1u;
                            return static_cast<std::uint32_t>(v * maxv + 0.5f);
                        };
                        const std::uint32_t r = quant(color[0], 10);
                        const std::uint32_t g = quant(color[1], 10);
                        const std::uint32_t b = quant(color[2], 10);
                        const std::uint32_t a = quant(color[3], 2);
                        const std::uint32_t packed =
                            (r & 0x3FF) |
                            ((g & 0x3FF) << 10) |
                            ((b & 0x3FF) << 20) |
                            ((a & 0x003) << 30);
                        std::memcpy(px, &packed, 4);
                        break;
                    }
                    // Packed 10_10_10_2 uint — same bit layout, integer values.
                    case MTLPixelFormatRGB10A2Uint: {
                        bpp = 4;
                        const auto clampU = [](float v, std::uint32_t maxv) -> std::uint32_t {
                            if (v <= 0.0f) return 0u;
                            if (v >= static_cast<float>(maxv)) return maxv;
                            return static_cast<std::uint32_t>(v);
                        };
                        const std::uint32_t r = clampU(color[0], 0x3FFu);
                        const std::uint32_t g = clampU(color[1], 0x3FFu);
                        const std::uint32_t b = clampU(color[2], 0x3FFu);
                        const std::uint32_t a = clampU(color[3], 0x003u);
                        const std::uint32_t packed =
                            (r & 0x3FF) |
                            ((g & 0x3FF) << 10) |
                            ((b & 0x3FF) << 20) |
                            ((a & 0x003) << 30);
                        std::memcpy(px, &packed, 4);
                        break;
                    }
                    // Packed R11F_G11F_B10F. R and G are 11-bit floats
                    // (5e6m, no sign, no NaN/Inf for clear), B is 10-bit
                    // float (5e5m). Packed LSB-first: R | G<<11 | B<<22.
                    case MTLPixelFormatRG11B10Float: {
                        bpp = 4;
                        auto toFloat11 = [](float f) -> std::uint32_t {
                            // 11-bit unsigned float: 5-bit biased exp
                            // (bias 15), 6-bit mantissa, no sign.
                            if (f <= 0.0f || std::isnan(f)) return 0u;
                            std::uint32_t u;
                            std::memcpy(&u, &f, 4);
                            std::int32_t exp = static_cast<std::int32_t>((u >> 23) & 0xFF) - 127;
                            std::uint32_t mant = u & 0x7FFFFF;
                            if (exp > 15) return 0x7BF;  // largest finite
                            if (exp < -14) return 0u;    // flush denorm to 0
                            const std::uint32_t exp11 =
                                static_cast<std::uint32_t>(exp + 15);
                            const std::uint32_t mant6 = mant >> 17;
                            return ((exp11 & 0x1F) << 6) | (mant6 & 0x3F);
                        };
                        auto toFloat10 = [](float f) -> std::uint32_t {
                            if (f <= 0.0f || std::isnan(f)) return 0u;
                            std::uint32_t u;
                            std::memcpy(&u, &f, 4);
                            std::int32_t exp = static_cast<std::int32_t>((u >> 23) & 0xFF) - 127;
                            std::uint32_t mant = u & 0x7FFFFF;
                            if (exp > 15) return 0x3DF;
                            if (exp < -14) return 0u;
                            const std::uint32_t exp10 =
                                static_cast<std::uint32_t>(exp + 15);
                            const std::uint32_t mant5 = mant >> 18;
                            return ((exp10 & 0x1F) << 5) | (mant5 & 0x1F);
                        };
                        const std::uint32_t r = toFloat11(color[0]);
                        const std::uint32_t g = toFloat11(color[1]);
                        const std::uint32_t b = toFloat10(color[2]);
                        const std::uint32_t packed =
                            (r & 0x7FF) |
                            ((g & 0x7FF) << 11) |
                            ((b & 0x3FF) << 22);
                        std::memcpy(px, &packed, 4);
                        break;
                    }
                    default:
                        // Unsupported pixel format — the rgba8 shadow
                        // already holds the cleared value, so readPixels
                        // through the rgba8 fallback path still works
                        // for this renderbuffer when Metal-tex readback
                        // doesn't match any format above.
                        recordCpuSideClear(
                            renderbufferCpuClearStart,
                            renderbufferClearBytes);
                        finalizeClearSizingPartition();
                        return true;
                }
                if (bpp == 0) {
                    recordCpuSideClear(
                        renderbufferCpuClearStart,
                        renderbufferClearBytes);
                    finalizeClearSizingPartition();
                    return true;
                }
                // Build a full-texture buffer by replicating the encoded
                // pixel across every texel, then a single replaceRegion
                // uploads the whole thing.
                const NSUInteger width = static_cast<NSUInteger>(renderbuffer->width);
                const NSUInteger height = static_cast<NSUInteger>(renderbuffer->height);
                const NSUInteger bytesPerRow = width * static_cast<NSUInteger>(bpp);
                std::vector<std::uint8_t> buf(bytesPerRow * height);
                for (NSUInteger i = 0; i < buf.size(); i += bpp) {
                    std::memcpy(buf.data() + i, px, bpp);
                }
                MTLRegion fullRegion = MTLRegionMake2D(0, 0, width, height);
                [metalTex replaceRegion:fullRegion
                            mipmapLevel:0
                              withBytes:buf.data()
                            bytesPerRow:bytesPerRow];
            }
            recordCpuSideClear(
                renderbufferCpuClearStart,
                renderbufferClearBytes);
            finalizeClearSizingPartition();
            return true;
        }

        return false;
    }

    bool handleAdvancedBlendDraw(GLProgramObject* program, const char* caller, bool& handled) {
        handled = false;
        if (program == nullptr || !state->isEnabled(GL_BLEND)) {
            return false;
        }
        const GLBlendState& blend = state->blendState();
        if (!isAdvancedBlendEquationKHR(blend.equationRGB)) {
            return false;
        }
        handled = true;

        const GLenum mode = blend.equationRGB;
        if (blend.equationAlpha != mode) {
            owner->pushError(GL_INVALID_OPERATION);
            return false;
        }
        const std::uint32_t requiredBit = advancedBlendModeBit(mode);
        if (!program->advancedBlendSupportAll &&
            (program->advancedBlendSupportMask & requiredBit) == 0) {
            owner->pushError(GL_INVALID_OPERATION);
            return false;
        }

        const GLuint drawFboName = state->boundDrawFramebuffer();
        const bool defaultTarget = drawFboName == 0;
        GLFramebufferAttachment* attachment = nullptr;
        if (!defaultTarget) {
            GLFramebufferObject* fbo = objects->framebuffers().get(drawFboName);
            if (fbo == nullptr) {
                owner->pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                return false;
            }

            GLenum drawAttachment = GL_NONE;
            int activeDrawBuffers = 0;
            for (GLenum drawBuffer : fbo->drawBuffers) {
                if (drawBuffer == GL_NONE) continue;
                ++activeDrawBuffers;
                if (drawAttachment == GL_NONE) {
                    drawAttachment = drawBuffer;
                }
            }
            if (activeDrawBuffers > 1) {
                owner->pushError(GL_INVALID_OPERATION);
                return false;
            }
            if (drawAttachment == GL_NONE) {
                return true;
            }

            auto attIt = fbo->attachments.find(drawAttachment);
            if (attIt == fbo->attachments.end() ||
                attIt->second.kind == GLFramebufferAttachment::Kind::None) {
                owner->pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                return false;
            }
            attachment = &attIt->second;
        }

        AdvancedBlendColor src{};
        bool haveSrc = false;
        for (const auto& uniform : program->uniforms) {
            if ((uniform.name == "uSrcCol" || uniform.name == "uMultCol") &&
                uniform.type == GL_FLOAT_VEC4 && uniform.location >= 0) {
                auto valueIt = program->uniformValues.find(uniform.location);
                if (valueIt != program->uniformValues.end() &&
                    valueIt->second.floats.size() >= 4) {
                    src = {
                        valueIt->second.floats[0],
                        valueIt->second.floats[1],
                        valueIt->second.floats[2],
                        valueIt->second.floats[3],
                    };
                    haveSrc = true;
                    break;
                }
            }
        }
        if (!haveSrc) {
            APPGL_LOG(SHADER, @"%s advanced blend skipped: source colour uniform not found", caller);
            owner->pushError(GL_INVALID_OPERATION);
            return false;
        }

        std::vector<std::uint8_t>* rgba8 = nullptr;
        GLsizei targetWidth = 0;
        GLsizei targetHeight = 0;
        GLTextureObject* textureTarget = nullptr;
        GLRenderbufferObject* renderbufferTarget = nullptr;
        if (defaultTarget) {
            ensureDefaultFramebufferShadow();
            targetWidth = defaultFramebufferShadowWidth;
            targetHeight = defaultFramebufferShadowHeight;
            rgba8 = &defaultFramebufferRGBA8;
        } else if (attachment->kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            renderbufferTarget = objects->renderbuffers().get(attachment->object);
            if (renderbufferTarget == nullptr || !renderbufferTarget->storageDefined) {
                owner->pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                return false;
            }
            targetWidth = renderbufferTarget->width;
            targetHeight = renderbufferTarget->height;
            materializeRenderbufferRGBA8Clear(*renderbufferTarget);
            rgba8 = &renderbufferTarget->rgba8;
        } else if (attachment->kind == GLFramebufferAttachment::Kind::Texture) {
            textureTarget = objects->textures().get(attachment->object);
            if (textureTarget == nullptr) {
                owner->pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                return false;
            }
            auto levelIt = textureTarget->levels.find(attachment->level);
            if (levelIt == textureTarget->levels.end() || !levelIt->second.defined) {
                owner->pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                return false;
            }
            targetWidth = levelIt->second.desc.width;
            targetHeight = textureTarget->target == GL_TEXTURE_1D ? 1 : levelIt->second.desc.height;
            rgba8 = &levelIt->second.rgba8;
            if (state->clipOrigin() == GL_LOWER_LEFT) {
                textureTarget->wasFramebufferRenderedTo = true;
            }
        }
        if (rgba8 == nullptr || targetWidth <= 0 || targetHeight <= 0) {
            owner->pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
            return false;
        }
        const std::size_t neededBytes =
            static_cast<std::size_t>(targetWidth) *
            static_cast<std::size_t>(targetHeight) * 4u;
        if (rgba8->size() < neededBytes) {
            rgba8->assign(neededBytes, 0);
        }

        GLint minX = 0;
        GLint maxX = targetWidth;
        GLint minY = 0;
        GLint maxY = targetHeight;
        if (state->isEnabled(GL_SCISSOR_TEST)) {
            const GLScissorState& s = state->scissor();
            minX = std::max<GLint>(0, s.x);
            maxX = std::min<GLint>(targetWidth, s.x + s.width);
            minY = std::max<GLint>(0, s.y);
            maxY = std::min<GLint>(targetHeight, s.y + s.height);
        }
        if (minX >= maxX || minY >= maxY) {
            return true;
        }

        const bool lowerLeft = state->clipOrigin() != GL_UPPER_LEFT;
        for (GLint glY = minY; glY < maxY; ++glY) {
            const GLint storageY =
                defaultTarget ? glY : (lowerLeft ? (targetHeight - 1 - glY) : glY);
            for (GLint x = minX; x < maxX; ++x) {
                const std::size_t offset =
                    (static_cast<std::size_t>(storageY) *
                     static_cast<std::size_t>(targetWidth) +
                     static_cast<std::size_t>(x)) * 4u;
                const AdvancedBlendColor dst{
                    static_cast<float>((*rgba8)[offset + 0]) / 255.0f,
                    static_cast<float>((*rgba8)[offset + 1]) / 255.0f,
                    static_cast<float>((*rgba8)[offset + 2]) / 255.0f,
                    static_cast<float>((*rgba8)[offset + 3]) / 255.0f,
                };
                const AdvancedBlendColor out = advancedBlendEvaluate(mode, src, dst);
                if (blend.colorMask[0] != GL_FALSE) (*rgba8)[offset + 0] = normalizedByte(out.r);
                if (blend.colorMask[1] != GL_FALSE) (*rgba8)[offset + 1] = normalizedByte(out.g);
                if (blend.colorMask[2] != GL_FALSE) (*rgba8)[offset + 2] = normalizedByte(out.b);
                if (blend.colorMask[3] != GL_FALSE) (*rgba8)[offset + 3] = normalizedByte(out.a);
            }
        }

        if (textureTarget != nullptr) {
            return replaceMetalTexture(*textureTarget);
        }
        if (renderbufferTarget != nullptr && renderbufferTarget->metalTexture != nullptr) {
            id<MTLTexture> metalTex = (__bridge id<MTLTexture>)renderbufferTarget->metalTexture;
            if (metalTex.sampleCount <= 1 &&
                (metalTex.pixelFormat == MTLPixelFormatRGBA8Unorm ||
                 metalTex.pixelFormat == MTLPixelFormatRGBA8Unorm_sRGB)) {
                // C48: this direct replaceRegion bypasses the frame
                // graph — a still-pending deferred clear folded by a
                // LATER GPU draw would wipe these CPU-blended texels
                // (Sweep B KHR blend_equation_advanced.test_coherency
                // P→F: res all-zeros). Land the deferred clear first.
                if (frameGraph != nullptr) {
                    frameGraph->materializePendingFboClearsForTexture(
                        renderbufferTarget->metalTexture);
                }
                MTLRegion fullRegion = MTLRegionMake2D(
                    0, 0,
                    static_cast<NSUInteger>(targetWidth),
                    static_cast<NSUInteger>(targetHeight));
                [metalTex replaceRegion:fullRegion
                            mipmapLevel:0
                              withBytes:rgba8->data()
                            bytesPerRow:static_cast<NSUInteger>(targetWidth) * 4u];
            }
        }
        return true;
    }

    GLsizei textureFramebufferLayerCount(const GLTextureObject& texture,
                                         const GLTextureImageLevel& image) const {
        switch (texture.target) {
            case GL_TEXTURE_3D:
            case GL_TEXTURE_2D_ARRAY:
            case GL_TEXTURE_2D_MULTISAMPLE_ARRAY:
            case GL_TEXTURE_CUBE_MAP_ARRAY:
                return std::max<GLsizei>(image.desc.depth, 1);
            case GL_TEXTURE_1D_ARRAY:
                return std::max<GLsizei>(image.desc.height, 1);
            case GL_TEXTURE_CUBE_MAP:
                return 6;
            default:
                return 1;
        }
    }

    GLsizei textureFramebufferLayerIndex(const GLTextureObject& texture,
                                         const GLFramebufferAttachment& attachment) const {
        switch (texture.target) {
            case GL_TEXTURE_3D:
            case GL_TEXTURE_2D_ARRAY:
            case GL_TEXTURE_1D_ARRAY:
            case GL_TEXTURE_2D_MULTISAMPLE_ARRAY:
            case GL_TEXTURE_CUBE_MAP:
            case GL_TEXTURE_CUBE_MAP_ARRAY:
                return attachment.layer;
            default:
                return 0;
        }
    }

    std::size_t depthStencilNativeBpp(GLenum internalFormat) const {
        switch (internalFormat) {
            case GL_DEPTH32F_STENCIL8:
                return 8;
            case GL_DEPTH24_STENCIL8:
                return 4;
            case GL_STENCIL_INDEX8:
                return 1;
            default:
                return 4;
        }
    }

    bool ensureDepthStencilNativeShadow(GLTextureImageLevel& image,
                                        GLsizei width,
                                        GLsizei height,
                                        GLsizei layers) const {
        if (width <= 0 || height <= 0 || layers <= 0) {
            return false;
        }
        if (image.nativeBpp == 0) {
            image.nativeBpp = depthStencilNativeBpp(image.desc.internalFormat);
        }
        if (image.nativeBpp == 0) {
            return false;
        }
        const std::size_t required =
            static_cast<std::size_t>(width) *
            static_cast<std::size_t>(height) *
            static_cast<std::size_t>(layers) *
            image.nativeBpp;
        if (image.nativeData.size() < required) {
            image.nativeData.resize(required, 0);
        }
        return true;
    }

    std::size_t nativeShadowOffset(const GLTextureImageLevel& image,
                                   GLsizei width,
                                   GLsizei height,
                                   GLsizei layer,
                                   GLsizei x,
                                   GLsizei y) const {
        return (((static_cast<std::size_t>(layer) *
                  static_cast<std::size_t>(height) +
                  static_cast<std::size_t>(y)) *
                 static_cast<std::size_t>(width)) +
                static_cast<std::size_t>(x)) * image.nativeBpp;
    }

    void storeNativeDepth(GLTextureImageLevel& image, std::size_t offset,
                          GLfloat depth) const {
        const float d = std::clamp(depth, 0.0f, 1.0f);
        switch (image.desc.internalFormat) {
            case GL_DEPTH24_STENCIL8: {
                std::uint32_t packed = 0;
                if (offset + sizeof(packed) <= image.nativeData.size()) {
                    std::memcpy(&packed, image.nativeData.data() + offset,
                                sizeof(packed));
                }
                const std::uint32_t stencil = packed & 0xFF000000u;
                const std::uint32_t depth24 =
                    packReadbackBits(static_cast<double>(d), 0x00FFFFFFu, false);
                packed = (depth24 & 0x00FFFFFFu) | stencil;
                if (offset + sizeof(packed) <= image.nativeData.size()) {
                    std::memcpy(image.nativeData.data() + offset, &packed,
                                sizeof(packed));
                }
                break;
            }
            case GL_DEPTH32F_STENCIL8:
                if (offset + sizeof(d) <= image.nativeData.size()) {
                    std::memcpy(image.nativeData.data() + offset, &d, sizeof(d));
                }
                break;
            default:
                if (offset + sizeof(d) <= image.nativeData.size()) {
                    std::memcpy(image.nativeData.data() + offset, &d, sizeof(d));
                }
                break;
        }
    }

    void storeNativeStencil(GLTextureImageLevel& image, std::size_t offset,
                            std::uint8_t stencil) const {
        switch (image.desc.internalFormat) {
            case GL_DEPTH24_STENCIL8: {
                if (offset + 4u <= image.nativeData.size()) {
                    image.nativeData[offset + 3u] = stencil;
                }
                break;
            }
            case GL_DEPTH32F_STENCIL8:
                if (offset + 5u <= image.nativeData.size()) {
                    image.nativeData[offset + 4u] = stencil;
                }
                break;
            default:
                if (offset < image.nativeData.size()) {
                    image.nativeData[offset] = stencil;
                }
                break;
        }
    }

    GLfloat loadNativeDepth(const GLTextureImageLevel& image,
                            std::size_t offset) const {
        switch (image.desc.internalFormat) {
            case GL_DEPTH24_STENCIL8: {
                std::uint32_t packed = 0;
                if (offset + sizeof(packed) <= image.nativeData.size()) {
                    std::memcpy(&packed, image.nativeData.data() + offset,
                                sizeof(packed));
                }
                return static_cast<GLfloat>(packed & 0x00FFFFFFu) /
                       static_cast<GLfloat>(0x00FFFFFFu);
            }
            default: {
                float depth = 0.0f;
                if (offset + sizeof(depth) <= image.nativeData.size()) {
                    std::memcpy(&depth, image.nativeData.data() + offset,
                                sizeof(depth));
                }
                return depth;
            }
        }
    }

    std::uint8_t loadNativeStencil(const GLTextureImageLevel& image,
                                   std::size_t offset) const {
        switch (image.desc.internalFormat) {
            case GL_DEPTH24_STENCIL8:
                return offset + 3u < image.nativeData.size()
                    ? image.nativeData[offset + 3u] : 0;
            case GL_DEPTH32F_STENCIL8:
                return offset + 4u < image.nativeData.size()
                    ? image.nativeData[offset + 4u] : 0;
            default:
                return offset < image.nativeData.size()
                    ? image.nativeData[offset] : 0;
        }
    }

    bool clearDepthAttachment(const GLFramebufferAttachment& attachment, GLdouble value) {
        const auto depth = static_cast<GLfloat>(std::clamp(value, 0.0, 1.0));
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            // GL 4.6 §17.4.3: clear on a texture-backed depth attachment.
            // Dispatch to the frame graph's layered-clear helper which
            // issues an empty render pass with MTLLoadActionClear, so
            // the Metal texture actually gets stamped with the clear
            // value. Without this, the Metal texture stays at its
            // initial (zero) contents; subsequent draws see zeros as
            // depth, and `GL_LESS` discards every fragment, producing
            // the all-black output we saw on `layered_framebuffer.
            // depth_support`.
            GLTextureObject* texture = objects->textures().get(attachment.object);
            if (texture == nullptr) {
                return false;
            }
            auto level = texture->levels.find(attachment.level);
            if (level == texture->levels.end()) {
                return true; // texStorage may not have populated the map yet
            }
            if (!isDepthFormat(level->second.desc.internalFormat)) {
                return false;
            }
            // Determine the target mip/slice. FramebufferTextureLayer clears
            // one attached layer; whole-texture layered attachments clear all
            // Metal slices at the selected mip level.
            std::uint32_t arrayLen = 0;
            const std::uint32_t mipLevel =
                static_cast<std::uint32_t>(std::max<GLint>(attachment.level, 0));
            const std::uint32_t slice =
                attachment.layered ? 0u
                                   : static_cast<std::uint32_t>(std::max<GLint>(attachment.layer, 0));
            if (attachment.layered) {
                GLsizei layers = std::max<GLsizei>(level->second.desc.depth, 1);
                if (texture->target == GL_TEXTURE_CUBE_MAP) {
                    layers = 6;
                } else if (texture->target != GL_TEXTURE_3D &&
                           texture->target != GL_TEXTURE_2D_ARRAY &&
                           texture->target != GL_TEXTURE_2D_MULTISAMPLE_ARRAY &&
                           texture->target != GL_TEXTURE_CUBE_MAP_ARRAY) {
                    layers = std::max<GLsizei>(texture->desc.layers, 1);
                }
                if (layers > 1) arrayLen = static_cast<std::uint32_t>(layers);
            }
            const bool clearScissorActive = state->isEnabled(GL_SCISSOR_TEST);
            const bool isMSTexture =
                texture->target == GL_TEXTURE_2D_MULTISAMPLE ||
                texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            if (clearScissorActive || isMSTexture) {
                GLTextureImageLevel& image = level->second;
                const GLsizei width = std::max<GLsizei>(image.desc.width, 1);
                const GLsizei height =
                    texture->target == GL_TEXTURE_1D ? 1
                    : std::max<GLsizei>(image.desc.height, 1);
                const GLsizei layerCount =
                    textureFramebufferLayerCount(*texture, image);
                const GLsizei firstLayer = attachment.layered
                    ? 0 : textureFramebufferLayerIndex(*texture, attachment);
                const GLsizei lastLayer = attachment.layered
                    ? layerCount : firstLayer + 1;
                if (firstLayer < 0 || firstLayer >= layerCount ||
                    lastLayer > layerCount) {
                    return false;
                }
                if (!ensureDepthStencilNativeShadow(
                        image, width, height, layerCount)) {
                    return false;
                }
                GLint minX = 0, maxX = width;
                GLint minY = 0, maxY = height;
                if (clearScissorActive) {
                    const GLScissorState& s = state->scissor();
                    if (s.width <= 0 || s.height <= 0) {
                        return true;
                    }
                    minX = std::max<GLint>(0, s.x);
                    maxX = std::min<GLint>(width, s.x + s.width);
                    minY = std::max<GLint>(0, s.y);
                    maxY = std::min<GLint>(height, s.y + s.height);
                    if (minX >= maxX || minY >= maxY) {
                        return true;
                    }
                }
                const bool lowerLeft = state->clipOrigin() != GL_UPPER_LEFT;
                for (GLsizei layerIndex = firstLayer;
                     layerIndex < lastLayer; ++layerIndex) {
                    for (GLint glY = minY; glY < maxY; ++glY) {
                        const GLint storageY =
                            lowerLeft ? (height - 1 - glY) : glY;
                        for (GLint x = minX; x < maxX; ++x) {
                            const std::size_t offset = nativeShadowOffset(
                                image, width, height, layerIndex, x, storageY);
                            storeNativeDepth(image, offset, depth);
                        }
                    }
                }
                if (lowerLeft) {
                    texture->wasFramebufferRenderedTo = true;
                }
                texture->depthStencilShadowAuthoritative = true;
                if (isMSTexture) {
                    return true;
                }
                return replaceMetalTexture(*texture);
            }
            if (frameGraph != nullptr && texture->metalTexture != nullptr) {
                texture->depthStencilShadowAuthoritative = false;
                maybeDropStaleDepth32FRgba8ShadowForAttachment(
                    *texture, attachment);
                return frameGraph->clearTextureDepth(
                    texture->metalTexture, mipLevel, slice, arrayLen, depth);
            }
            return true;
        }
        if (attachment.kind != GLFramebufferAttachment::Kind::Renderbuffer) {
            return false;
        }
        GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
        if (renderbuffer == nullptr || !renderbuffer->storageDefined || !isDepthFormat(renderbuffer->internalFormat)) {
            return false;
        }
        GLint minX = 0, maxX = renderbuffer->width;
        GLint minY = 0, maxY = renderbuffer->height;
        const bool clearScissorActive = state->isEnabled(GL_SCISSOR_TEST);
        if (clearScissorActive) {
            const GLScissorState& s = state->scissor();
            if (s.width <= 0 || s.height <= 0) {
                return true;
            }
            minX = std::max<GLint>(0, s.x);
            maxX = std::min<GLint>(renderbuffer->width, s.x + s.width);
            minY = std::max<GLint>(0, s.y);
            maxY = std::min<GLint>(renderbuffer->height, s.y + s.height);
            if (minX >= maxX || minY >= maxY) {
                return true;
            }
        }
        bool metalClearApplied = false;
        if (frameGraph != nullptr && renderbuffer->metalTexture != nullptr) {
            id<MTLTexture> metalTex =
                (__bridge id<MTLTexture>)renderbuffer->metalTexture;
            // Depth RB clears must reach Metal before a draw; for MS
            // renderbuffers this is the only legal way to seed every sample.
            if (!clearScissorActive &&
                frameGraph->clearLayeredTextureDepth(renderbuffer->metalTexture, 0, depth)) {
                renderbuffer->wasMetalDepthRendered = true;
                metalClearApplied = true;
                if (metalTex.sampleCount <= 1) {
                    return true;
                }
            }
        }
        const GLsizei regionWidth = maxX - minX;
        const GLsizei regionHeight = maxY - minY;
        if (renderbuffer->depth32.empty()) {
            std::vector<GLfloat> region(
                static_cast<std::size_t>(regionWidth) *
                static_cast<std::size_t>(regionHeight), depth);
            if (mirrorDepthRenderbufferRegionToMetal(
                    *renderbuffer, minX, minY, regionWidth, regionHeight,
                    region.data())) {
                return true;
            }
        }
        const std::size_t depthPixels =
            static_cast<std::size_t>(renderbuffer->width) *
            static_cast<std::size_t>(renderbuffer->height);
        if (renderbuffer->depth32.size() < depthPixels) {
            renderbuffer->depth32.assign(depthPixels, 0.0f);
        }
        for (GLint y = minY; y < maxY; ++y) {
            for (GLint x = minX; x < maxX; ++x) {
                renderbuffer->depth32[
                    static_cast<std::size_t>(y) *
                    static_cast<std::size_t>(renderbuffer->width) +
                    static_cast<std::size_t>(x)] = depth;
            }
        }
        std::vector<GLfloat> region(
            static_cast<std::size_t>(regionWidth) *
            static_cast<std::size_t>(regionHeight));
        for (GLsizei row = 0; row < regionHeight; ++row) {
            const GLfloat* src =
                renderbuffer->depth32.data() +
                static_cast<std::size_t>(minY + row) *
                static_cast<std::size_t>(renderbuffer->width) +
                static_cast<std::size_t>(minX);
            std::memcpy(region.data() +
                        static_cast<std::size_t>(row) *
                        static_cast<std::size_t>(regionWidth),
                        src,
                        static_cast<std::size_t>(regionWidth) *
                        sizeof(GLfloat));
        }
        const bool mirroredDepth = metalClearApplied ||
            mirrorDepthRenderbufferRegionToMetal(
                *renderbuffer, minX, minY, regionWidth, regionHeight,
                region.data());
        if (!mirroredDepth) {
            renderbuffer->wasMetalDepthRendered = false;
        }
        return true;
    }

    bool clearStencilAttachment(const GLFramebufferAttachment& attachment, GLint value) {
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            // Stencil clear on a texture-backed attachment — same
            // MTLLoadActionClear dispatch as clearDepthAttachment.
            // DEPTH_STENCIL formats (e.g. DEPTH32F_STENCIL8) are valid
            // for both depth and stencil attachments.
            GLTextureObject* texture = objects->textures().get(attachment.object);
            if (texture == nullptr) {
                return false;
            }
            auto level = texture->levels.find(attachment.level);
            if (level == texture->levels.end()) {
                return true;
            }
            if (!isStencilFormat(level->second.desc.internalFormat)) {
                return false;
            }
            std::uint32_t arrayLen = 0;
            const std::uint32_t mipLevel =
                static_cast<std::uint32_t>(std::max<GLint>(attachment.level, 0));
            const std::uint32_t slice =
                attachment.layered ? 0u
                                   : static_cast<std::uint32_t>(std::max<GLint>(attachment.layer, 0));
            if (attachment.layered) {
                GLsizei layers = std::max<GLsizei>(level->second.desc.depth, 1);
                if (texture->target == GL_TEXTURE_CUBE_MAP) {
                    layers = 6;
                } else if (texture->target != GL_TEXTURE_3D &&
                           texture->target != GL_TEXTURE_2D_ARRAY &&
                           texture->target != GL_TEXTURE_2D_MULTISAMPLE_ARRAY &&
                           texture->target != GL_TEXTURE_CUBE_MAP_ARRAY) {
                    layers = std::max<GLsizei>(texture->desc.layers, 1);
                }
                if (layers > 1) arrayLen = static_cast<std::uint32_t>(layers);
            }
            const bool clearScissorActive = state->isEnabled(GL_SCISSOR_TEST);
            const bool isMSTexture =
                texture->target == GL_TEXTURE_2D_MULTISAMPLE ||
                texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            if (clearScissorActive || isMSTexture) {
                GLTextureImageLevel& image = level->second;
                const GLsizei width = std::max<GLsizei>(image.desc.width, 1);
                const GLsizei height =
                    texture->target == GL_TEXTURE_1D ? 1
                    : std::max<GLsizei>(image.desc.height, 1);
                const GLsizei layerCount =
                    textureFramebufferLayerCount(*texture, image);
                const GLsizei firstLayer = attachment.layered
                    ? 0 : textureFramebufferLayerIndex(*texture, attachment);
                const GLsizei lastLayer = attachment.layered
                    ? layerCount : firstLayer + 1;
                if (firstLayer < 0 || firstLayer >= layerCount ||
                    lastLayer > layerCount) {
                    return false;
                }
                if (!ensureDepthStencilNativeShadow(
                        image, width, height, layerCount)) {
                    return false;
                }
                GLint minX = 0, maxX = width;
                GLint minY = 0, maxY = height;
                if (clearScissorActive) {
                    const GLScissorState& s = state->scissor();
                    if (s.width <= 0 || s.height <= 0) {
                        return true;
                    }
                    minX = std::max<GLint>(0, s.x);
                    maxX = std::min<GLint>(width, s.x + s.width);
                    minY = std::max<GLint>(0, s.y);
                    maxY = std::min<GLint>(height, s.y + s.height);
                    if (minX >= maxX || minY >= maxY) {
                        return true;
                    }
                }
                const bool lowerLeft = state->clipOrigin() != GL_UPPER_LEFT;
                const std::uint8_t stencil =
                    static_cast<std::uint8_t>(value & 0xff);
                for (GLsizei layerIndex = firstLayer;
                     layerIndex < lastLayer; ++layerIndex) {
                    for (GLint glY = minY; glY < maxY; ++glY) {
                        const GLint storageY =
                            lowerLeft ? (height - 1 - glY) : glY;
                        for (GLint x = minX; x < maxX; ++x) {
                            const std::size_t offset = nativeShadowOffset(
                                image, width, height, layerIndex, x, storageY);
                            storeNativeStencil(image, offset, stencil);
                        }
                    }
                }
                if (lowerLeft) {
                    texture->wasFramebufferRenderedTo = true;
                }
                texture->depthStencilShadowAuthoritative = true;
                if (isMSTexture) {
                    return true;
                }
                return replaceMetalTexture(*texture);
            }
            if (frameGraph != nullptr && texture->metalTexture != nullptr) {
                texture->depthStencilShadowAuthoritative = false;
                maybeDropStaleDepth32FRgba8ShadowForAttachment(
                    *texture, attachment);
                return frameGraph->clearTextureStencil(
                    texture->metalTexture, mipLevel, slice, arrayLen,
                    static_cast<std::uint32_t>(value));
            }
            return true;
        }
        if (attachment.kind != GLFramebufferAttachment::Kind::Renderbuffer) {
            return false;
        }
        GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
        if (renderbuffer == nullptr || !renderbuffer->storageDefined || !isStencilFormat(renderbuffer->internalFormat)) {
            return false;
        }
        GLint minX = 0, maxX = renderbuffer->width;
        GLint minY = 0, maxY = renderbuffer->height;
        if (state->isEnabled(GL_SCISSOR_TEST)) {
            const GLScissorState& s = state->scissor();
            if (s.width <= 0 || s.height <= 0) {
                return true;
            }
            minX = std::max<GLint>(0, s.x);
            maxX = std::min<GLint>(renderbuffer->width, s.x + s.width);
            minY = std::max<GLint>(0, s.y);
            maxY = std::min<GLint>(renderbuffer->height, s.y + s.height);
            if (minX >= maxX || minY >= maxY) {
                return true;
            }
        }
        const std::uint8_t stencilValue =
            static_cast<std::uint8_t>(value & 0xff);
        const GLsizei regionWidth = maxX - minX;
        const GLsizei regionHeight = maxY - minY;
        bool metalClearApplied = false;
        if (frameGraph != nullptr && renderbuffer->metalTexture != nullptr &&
            !state->isEnabled(GL_SCISSOR_TEST) &&
            frameGraph->clearLayeredTextureStencil(
                renderbuffer->metalTexture, 0,
                static_cast<std::uint32_t>(stencilValue))) {
            renderbuffer->wasMetalStencilRendered = true;
            metalClearApplied = true;
            id<MTLTexture> metalTex =
                (__bridge id<MTLTexture>)renderbuffer->metalTexture;
            if (metalTex.sampleCount <= 1) {
                return true;
            }
        }
        if (renderbuffer->stencil8.empty()) {
            std::vector<std::uint8_t> region(
                static_cast<std::size_t>(regionWidth) *
                static_cast<std::size_t>(regionHeight),
                stencilValue);
            if (mirrorStencilRenderbufferRegionToMetal(
                    *renderbuffer, minX, minY, regionWidth, regionHeight,
                    region.data())) {
                renderbuffer->wasMetalStencilRendered = true;
                return true;
            }
        }
        const std::size_t stencilPixels =
            static_cast<std::size_t>(renderbuffer->width) *
            static_cast<std::size_t>(renderbuffer->height);
        if (renderbuffer->stencil8.size() < stencilPixels) {
            renderbuffer->stencil8.assign(stencilPixels, 0);
        }
        for (GLint y = minY; y < maxY; ++y) {
            for (GLint x = minX; x < maxX; ++x) {
                renderbuffer->stencil8[
                    static_cast<std::size_t>(y) *
                    static_cast<std::size_t>(renderbuffer->width) +
                    static_cast<std::size_t>(x)] = stencilValue;
            }
        }
        std::vector<std::uint8_t> region(
            static_cast<std::size_t>(regionWidth) *
            static_cast<std::size_t>(regionHeight));
        for (GLsizei row = 0; row < regionHeight; ++row) {
            const std::uint8_t* src =
                renderbuffer->stencil8.data() +
                static_cast<std::size_t>(minY + row) *
                static_cast<std::size_t>(renderbuffer->width) +
                static_cast<std::size_t>(minX);
            std::memcpy(region.data() +
                        static_cast<std::size_t>(row) *
                        static_cast<std::size_t>(regionWidth),
                        src,
                        static_cast<std::size_t>(regionWidth));
        }
        const bool mirroredStencil = metalClearApplied ||
            mirrorStencilRenderbufferRegionToMetal(
                *renderbuffer, minX, minY, regionWidth, regionHeight,
                region.data());
        renderbuffer->wasMetalStencilRendered = mirroredStencil;
        return true;
    }

    bool clearBoundFramebuffer(GLbitfield mask) {
        const GLuint framebufferName = state->boundDrawFramebuffer();
        GLFramebufferObject* framebuffer = objects->framebuffers().get(framebufferName);
        if (framebufferName == 0 || framebuffer == nullptr || !framebuffer->instantiated || framebufferStatus(*framebuffer) != GL_FRAMEBUFFER_COMPLETE) {
            return false;
        }

        GpuResourceWriteSet clearWrites;
        if ((mask & GL_COLOR_BUFFER_BIT) != 0) {
            if (clearColorAttachmentSizingProfile.enabled) {
                std::uint64_t activeColorSlots = 0;
                for (GLenum buffer : framebuffer->drawBuffers) {
                    if (buffer == GL_NONE) {
                        continue;
                    }
                    if (framebufferAttachment(*framebuffer, buffer) != nullptr) {
                        ++activeColorSlots;
                    }
                }
                clearColorAttachmentSizingProfile.recordFramebufferColorClear(
                    activeColorSlots);
            }
            for (GLenum buffer : framebuffer->drawBuffers) {
                if (buffer == GL_NONE) {
                    continue;
                }
                const GLFramebufferAttachment* attachment = framebufferAttachment(*framebuffer, buffer);
                if (attachment != nullptr &&
                    !clearColorAttachment(*attachment,
                                          state->clearState().color,
                                          true)) {
                    return false;
                }
                if (attachment != nullptr) {
                    appendAttachmentWrite(clearWrites, *attachment,
                                          kProducerClearWrite |
                                          kProducerFboColorWrite);
                }
            }
        }
        if ((mask & GL_DEPTH_BUFFER_BIT) != 0) {
            const GLFramebufferAttachment* attachment = framebufferAttachment(*framebuffer, GL_DEPTH_ATTACHMENT);
            if (attachment != nullptr && !clearDepthAttachment(*attachment, state->clearState().depth)) {
                return false;
            }
            if (attachment != nullptr) {
                appendAttachmentWrite(clearWrites, *attachment,
                                      kProducerClearWrite |
                                      kProducerFboDepthStencilWrite);
            }
        }
        if ((mask & GL_STENCIL_BUFFER_BIT) != 0) {
            const GLFramebufferAttachment* attachment = framebufferAttachment(*framebuffer, GL_STENCIL_ATTACHMENT);
            if (attachment != nullptr && !clearStencilAttachment(*attachment, state->clearState().stencil)) {
                return false;
            }
            if (attachment != nullptr) {
                appendAttachmentWrite(clearWrites, *attachment,
                                      kProducerClearWrite |
                                      kProducerFboDepthStencilWrite);
            }
        }
        markGpuResourceWrites(clearWrites);
        return true;
    }

    bool readColorAttachmentPixels(const GLFramebufferAttachment& attachment, GLint x, GLint y, GLsizei width, GLsizei height, void* pixels) const {
        drainFramebufferAttachmentProducer(attachment);

        // RC-A02: Try reading from the actual Metal texture first (has GPU-
        // rendered data).  Fall back to CPU shadow if no Metal texture exists.
        id<MTLTexture> metalTex = nil;
        GLsizei sourceWidth = 0;
        GLsizei sourceHeight = 0;
        NSUInteger metalMipLevel = 0;
        NSUInteger metalSlice = 0;
        bool sourceNeedsFboYFlip = true;

        // For 3D textures, `attachment.layer` is a Z coordinate into
        // the texture region, not a Metal slice index. Track separately
        // so the Metal-read path below can use MTLRegionMake3D.
        bool is3DTexture = false;
        NSUInteger depthSlice = 0;
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            const ResolvedTextureAttachment resolved =
                resolveTextureAttachmentStorage(attachment);
            const GLTextureObject* texture = resolved.storageTexture;
            if (!resolved.valid || texture == nullptr) return false;
            const auto level = texture->levels.find(resolved.level);
            if (level == texture->levels.end() || !level->second.defined) return false;
            sourceWidth = std::max<GLsizei>(level->second.desc.width, 1);
            sourceHeight = texture->target == GL_TEXTURE_1D ? 1 : std::max<GLsizei>(level->second.desc.height, 1);
            metalMipLevel = static_cast<NSUInteger>(resolved.level);
            if (texture->target == GL_TEXTURE_3D) {
                // 3D texture: Metal has a single slice; depth-layer
                // goes into the region's Z coordinate.
                is3DTexture = true;
                depthSlice = static_cast<NSUInteger>(std::max<GLint>(resolved.layer, 0));
                metalSlice = 0;
            } else {
                metalSlice = static_cast<NSUInteger>(std::max<GLint>(resolved.layer, 0));
            }
            if (texture->metalTexture != nullptr) {
                metalTex = (__bridge id<MTLTexture>)texture->metalTexture;
            }
            sourceNeedsFboYFlip =
                texture->wasFramebufferRenderedTo ||
                texture->wasViewportRenderedTo;
            // If no Metal texture, try CPU shadow
            const bool preferTextureShadow =
                texture->colorShadowAuthoritative &&
                !level->second.rgba8.empty();
            if (metalTex == nil || preferTextureShadow) {
                if (level->second.rgba8.empty()) return false;
                const std::uint8_t* source = level->second.rgba8.data();
                GLsizei sourceLayer = 0;
                GLsizei sourceLayers = 1;
                if (texture->target == GL_TEXTURE_3D ||
                    texture->target == GL_TEXTURE_2D_ARRAY ||
                    texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY ||
                    texture->target == GL_TEXTURE_CUBE_MAP ||
                    texture->target == GL_TEXTURE_CUBE_MAP_ARRAY) {
                    sourceLayer = resolved.layer;
                    sourceLayers = texture->target == GL_TEXTURE_CUBE_MAP
                        ? 6 : std::max<GLsizei>(level->second.desc.depth, 1);
                } else if (texture->target == GL_TEXTURE_1D_ARRAY) {
                    sourceLayer = resolved.layer;
                    sourceLayers = std::max<GLsizei>(level->second.desc.height, 1);
                }
                if (sourceLayer < 0 || sourceLayer >= sourceLayers)
                    return false;
                const bool yFlipCpuReadback =
                    sourceNeedsFboYFlip &&
                    state->clipOrigin() != GL_UPPER_LEFT;
                auto* out = static_cast<std::uint8_t*>(pixels);
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const GLint srcX = x + col;
                        const GLint glY = y + row;
                        const GLint srcY = yFlipCpuReadback
                            ? (sourceHeight - 1 - glY) : glY;
                        const std::size_t dstOffset = static_cast<std::size_t>(row * width + col) * 4u;
                        if (srcX < 0 || srcY < 0 || srcX >= sourceWidth || srcY >= sourceHeight) {
                            std::memset(out + dstOffset, 0, 4);
                            continue;
                        }
                        const std::size_t srcOffset =
                            ((static_cast<std::size_t>(sourceLayer) * static_cast<std::size_t>(sourceHeight)
                                + static_cast<std::size_t>(srcY))
                                * static_cast<std::size_t>(sourceWidth)
                                + static_cast<std::size_t>(srcX))
                            * 4u;
                        std::memcpy(out + dstOffset, source + srcOffset, 4);
                    }
                }
                return true;
            }
        } else if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            const GLRenderbufferObject* rb = objects->renderbuffers().get(attachment.object);
            if (rb == nullptr || !rb->storageDefined) return false;
            sourceWidth = rb->width;
            sourceHeight = rb->height;
            if (rb->metalTexture != nullptr) {
                metalTex = (__bridge id<MTLTexture>)rb->metalTexture;
            }
            sourceNeedsFboYFlip = rb->framebufferReadbackYFlip;
            const bool preferRenderbufferShadow =
                metalTex != nil && metalTex.sampleCount > 1 &&
                rb->colorShadowAuthoritative;
            if (metalTex == nil || preferRenderbufferShadow) {
                if (rb->rgba8.empty()) return false;
                const std::uint8_t* source = rb->rgba8.data();
                const bool yFlipCpuReadback =
                    sourceNeedsFboYFlip &&
                    state->clipOrigin() != GL_UPPER_LEFT;
                auto* out = static_cast<std::uint8_t*>(pixels);
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const GLint srcX = x + col;
                        const GLint glY = y + row;
                        const GLint srcY = yFlipCpuReadback
                            ? (sourceHeight - 1 - glY) : glY;
                        const std::size_t dstOffset = static_cast<std::size_t>(row * width + col) * 4u;
                        if (srcX < 0 || srcY < 0 || srcX >= sourceWidth || srcY >= sourceHeight) {
                            std::memset(out + dstOffset, 0, 4);
                            continue;
                        }
                        const std::size_t srcOffset =
                            (static_cast<std::size_t>(srcY) * static_cast<std::size_t>(sourceWidth)
                                + static_cast<std::size_t>(srcX))
                            * 4u;
                        std::memcpy(out + dstOffset, source + srcOffset, 4);
                    }
                }
                return true;
            }
        } else {
            return false;
        }

        // Read from the Metal texture — this has the actual GPU-rendered data.
        // The texture may be RGBA8 or BGRA8; we handle both.
        const bool isBGRA = (metalTex.pixelFormat == MTLPixelFormatBGRA8Unorm);
        const NSUInteger bytesPerRow = static_cast<NSUInteger>(sourceWidth) * 4u;

        // Phase 6-1c: if the source is multisample, Metal's
        // `-getBytes:` is invalid on it — we have to resolve first.
        // Create a single-sample temp texture matching the MS source's
        // pixel format / size, run a zero-draw render pass with
        // MTLStoreActionMultisampleResolve to trigger the implicit
        // resolve, and read from the temp. Non-MS textures fall
        // through to the direct getBytes path unchanged.
        //
        // Sprint 17 Day 2 (CKPT237) [Probe C — h2DM-5b fix]: for
        // 2DMSArray sources (`MTLTextureType2DMultisampleArray`), route
        // the caller's requested source slice through the resolve pass
        // while keeping the single-slice 2D destination shape (cheap
        // 1× alloc; one-pass resolve per readback). The source-slice
        // selection on `colorAttachments[0].slice` reads from the
        // requested array layer; `resolveSlice = 0` writes to the
        // single-slice destination; readback then reads slice 0 of
        // the destination regardless of the source's array-layer index.
        //
        // Pre-Probe-C bug (Sprint 17 Day 1 Track A capture + Day 2
        // Track A2 validation-layer-enabled finding + B2 source-grounded
        // localisation): the resolve always read sourceSlice=0 and wrote
        // to a single-slice 2D destination, then `getBytes(slice=metalSlice)`
        // on a destination with arrayLength=1 produced
        // `_validateGetBytes:75: slice(N) must be < (1)` Metal API
        // validation assertion for any non-zero source layer (the
        // `attachment.layer` from glFramebufferTextureLayer-style
        // bindings on layered MS textures).
        //
        // Sister-pattern preservation: plain 2DMS (non-array) sources
        // keep `sourceIsArray = false` → both source-slice and
        // destination-slice indices stay at 0 → behaviour identical
        // to pre-Probe-C (B2 §8.3 sister-pattern verified correct).
        id<MTLTexture> readTex = metalTex;
        if (metalTex.sampleCount > 1 && device != nil && commandQueue != nil) {
            const bool sourceIsArray =
                metalTex.textureType == MTLTextureType2DMultisampleArray;
            id<MTLTexture> resolvedTex = nil;
            @autoreleasepool {
                MTLTextureDescriptor* tempDesc = [MTLTextureDescriptor
                    texture2DDescriptorWithPixelFormat:metalTex.pixelFormat
                                                width:metalTex.width
                                               height:metalTex.height
                                            mipmapped:NO];
                tempDesc.storageMode = MTLStorageModeShared;
                tempDesc.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
                resolvedTex = [device newTextureWithDescriptor:tempDesc];
            }
            if (resolvedTex != nil) {
                MTLRenderPassDescriptor* rpd = [MTLRenderPassDescriptor renderPassDescriptor];
                rpd.colorAttachments[0].texture = metalTex;
                // For 2DMSArray sources, read the caller's requested
                // slice (metalSlice = attachment.layer per line ~6952);
                // for plain 2DMS, slice is always 0.
                rpd.colorAttachments[0].slice =
                    sourceIsArray ? metalSlice : 0;
                rpd.colorAttachments[0].loadAction = MTLLoadActionLoad;
                rpd.colorAttachments[0].storeAction = MTLStoreActionMultisampleResolve;
                rpd.colorAttachments[0].resolveTexture = resolvedTex;
                rpd.colorAttachments[0].resolveLevel = 0;
                rpd.colorAttachments[0].resolveSlice = 0;
                auto resolveLease = makeCommandBuffer(AppGLCommandReason::FlushForReadback);
                id<MTLCommandBuffer> cb = resolveLease.get();
                id<MTLRenderCommandEncoder> enc =
                    [cb renderCommandEncoderWithDescriptor:rpd];
                [enc endEncoding];
                resolveLease.commitAndWait(AppGLCommandReason::FlushForReadback);
                readTex = resolvedTex;
                // After resolve, the destination is single-slice 2D
                // and contains the data from the source's requested
                // slice. Override metalSlice to 0 for the getBytes
                // call below — reading slice 0 of the destination is
                // always valid (arrayLength=1).
                if (sourceIsArray) {
                    metalSlice = 0;
                }
            }
        }

        const bool yFlipReadback =
            sourceNeedsFboYFlip &&
            state->clipOrigin() != GL_UPPER_LEFT;
        if (readTex.pixelFormat == MTLPixelFormatR8Unorm) {
            const NSUInteger nativeBytesPerRow =
                static_cast<NSUInteger>(sourceWidth);
            std::vector<std::uint8_t> nativeLevel(
                static_cast<std::size_t>(sourceWidth) *
                static_cast<std::size_t>(sourceHeight));
            MTLRegion nativeRegion = is3DTexture
                ? MTLRegionMake3D(0, 0, depthSlice,
                    static_cast<NSUInteger>(sourceWidth),
                    static_cast<NSUInteger>(sourceHeight), 1)
                : MTLRegionMake2D(0, 0,
                    static_cast<NSUInteger>(sourceWidth),
                    static_cast<NSUInteger>(sourceHeight));
            [readTex getBytes:nativeLevel.data()
                   bytesPerRow:nativeBytesPerRow
                bytesPerImage:0
                   fromRegion:nativeRegion
                  mipmapLevel:metalMipLevel
                        slice:metalSlice];

            auto* out = static_cast<std::uint8_t*>(pixels);
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint srcX = x + col;
                    const GLint glY = y + row;
                    const GLint srcY = yFlipReadback ? (sourceHeight - 1 - glY) : glY;
                    const std::size_t dstOffset =
                        static_cast<std::size_t>(row * width + col) * 4u;
                    if (srcX < 0 || srcY < 0 ||
                        srcX >= sourceWidth || srcY >= sourceHeight) {
                        out[dstOffset + 0] = 0;
                    } else {
                        out[dstOffset + 0] = nativeLevel[
                            static_cast<std::size_t>(srcY) *
                            static_cast<std::size_t>(sourceWidth) +
                            static_cast<std::size_t>(srcX)];
                    }
                    out[dstOffset + 1] = 0;
                    out[dstOffset + 2] = 0;
                    out[dstOffset + 3] = 255;
                }
            }
            return true;
        }

        // Read the entire mip level into a temporary buffer, then extract
        // the requested rectangle.
        std::vector<std::uint8_t> fullLevel(static_cast<std::size_t>(sourceWidth) * static_cast<std::size_t>(sourceHeight) * 4u);
        MTLRegion fullRegion = is3DTexture
            ? MTLRegionMake3D(0, 0, depthSlice,
                static_cast<NSUInteger>(sourceWidth),
                static_cast<NSUInteger>(sourceHeight), 1)
            : MTLRegionMake2D(0, 0,
                static_cast<NSUInteger>(sourceWidth),
                static_cast<NSUInteger>(sourceHeight));
        [readTex getBytes:fullLevel.data()
               bytesPerRow:bytesPerRow
            bytesPerImage:0
               fromRegion:fullRegion
              mipmapLevel:metalMipLevel
                    slice:metalSlice];

        // FBO readback Y-flips only when the attachment was actually
        // rendered/cleared through an FBO producer under LOWER_LEFT.
        // Texture-kind attachments use wasFramebufferRenderedTo here;
        // glGetTexImage intentionally stays on wasViewportRenderedTo.
        auto* out = static_cast<std::uint8_t*>(pixels);
        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const GLint srcX = x + col;
                const GLint glY = y + row;
                const GLint srcY = yFlipReadback ? (sourceHeight - 1 - glY) : glY;
                const std::size_t dstOffset = static_cast<std::size_t>(row * width + col) * 4u;
                if (srcX < 0 || srcY < 0 || srcX >= sourceWidth || srcY >= sourceHeight) {
                    std::memset(out + dstOffset, 0, 4);
                    continue;
                }
                const std::size_t srcOffset =
                    (static_cast<std::size_t>(srcY) * static_cast<std::size_t>(sourceWidth)
                        + static_cast<std::size_t>(srcX))
                    * 4u;
                if (isBGRA) {
                    // BGRA → RGBA swizzle
                    out[dstOffset + 0] = fullLevel[srcOffset + 2]; // R←B
                    out[dstOffset + 1] = fullLevel[srcOffset + 1]; // G←G
                    out[dstOffset + 2] = fullLevel[srcOffset + 0]; // B←R
                    out[dstOffset + 3] = fullLevel[srcOffset + 3]; // A←A
                } else {
                    std::memcpy(out + dstOffset, fullLevel.data() + srcOffset, 4);
                }
            }
        }
        return true;
    }

    enum class DepthReadbackConsumer : std::uint8_t {
        Other,
        SyncNative,
        Rgba8SubImage,
        AttachmentReadback
    };

    void recordDepthReadbackCall(MTLPixelFormat pixelFormat,
                                 std::uint64_t rawBytes,
                                 DepthReadbackConsumer consumer) const {
        auto& diag = depth32fReadback;
        ++diag.readbackCalls;
        if (pixelFormat == MTLPixelFormatDepth32Float) {
            ++diag.readbackDepth32FCalls;
        } else if (pixelFormat == MTLPixelFormatDepth32Float_Stencil8) {
            ++diag.readbackDepth32FS8Calls;
        }
        diag.readbackRawBytes += rawBytes;
        diag.readbackRawMaxBytes =
            std::max(diag.readbackRawMaxBytes, rawBytes);
        switch (consumer) {
            case DepthReadbackConsumer::SyncNative:
                ++diag.readbackConsumerSyncCalls;
                break;
            case DepthReadbackConsumer::Rgba8SubImage:
                ++diag.readbackConsumerRgba8SubImageCalls;
                break;
            case DepthReadbackConsumer::AttachmentReadback:
                ++diag.readbackConsumerAttachmentCalls;
                break;
            case DepthReadbackConsumer::Other:
            default:
                ++diag.readbackConsumerOtherCalls;
                break;
        }
    }

    void recordDepthReadbackStaging(std::uint64_t stagingBytes) const {
        auto& diag = depth32fReadback;
        ++diag.readbackStagingCalls;
        diag.readbackStagingBytes += stagingBytes;
        diag.readbackStagingMaxBytes =
            std::max(diag.readbackStagingMaxBytes, stagingBytes);
    }

    // Sprint 17 Day 7+ Bank-Group-A B-revised: shared depth-readback
    // helper for both Renderbuffer-kind and Texture-kind paths. Handles
    // Metal-texture getBytes (Shared/Managed) or blit-to-staging
    // (Private; default on Apple Silicon for depth textures), depth-
    // format → GLfloat conversion, and Y-flip gated on clipOrigin.
    bool readDepthFromMetalTexture(id<MTLTexture> metalTex,
                                   NSUInteger mipLevel,
                                   NSUInteger sourceSlice,
                                   GLint x, GLint y,
                                   GLsizei width, GLsizei height,
                                   void* pixels,
                                   bool yFlipDepthReadback,
                                   DepthReadbackConsumer consumer =
                                       DepthReadbackConsumer::Other) const {
        if (metalTex == nil) return false;
        const MTLPixelFormat pf = metalTex.pixelFormat;
        const NSUInteger texWidth = mipDimensionAtLevel(metalTex.width, mipLevel);
        const NSUInteger texHeight = mipDimensionAtLevel(metalTex.height, mipLevel);
        // Raw-bytes read depends on the extracted depth-plane width. Metal
        // depth-stencil textures must be blitted with the depth-plane option;
        // copying them as an interleaved texture gives undefined packed bytes
        // and broke GL_DEPTH_STENCIL glReadPixels/readback staging.
        NSUInteger srcBpp = 0;
        MTLBlitOption depthStencilBlitOptions = 0;
        switch (pf) {
            case MTLPixelFormatDepth32Float:                srcBpp = 4; break;
            case MTLPixelFormatDepth16Unorm:                srcBpp = 2; break;
            case MTLPixelFormatDepth32Float_Stencil8:
                srcBpp = 4;
                depthStencilBlitOptions = MTLBlitOptionDepthFromDepthStencil;
                break;
            case MTLPixelFormatDepth24Unorm_Stencil8:
                srcBpp = 4;
                depthStencilBlitOptions = MTLBlitOptionDepthFromDepthStencil;
                break;
            default:
                // Unknown depth-format mapping — bail safely so
                // the caller reports INVALID_FRAMEBUFFER_OPERATION
                // rather than returning garbage bytes.
                return false;
        }
        NSUInteger readX = 0;
        NSUInteger readY = 0;
        NSUInteger readWidth = texWidth;
        NSUInteger readHeight = texHeight;
        if (x >= 0 && y >= 0 && width > 0 && height > 0 &&
            static_cast<NSUInteger>(x) + static_cast<NSUInteger>(width) <= texWidth &&
            static_cast<NSUInteger>(y) + static_cast<NSUInteger>(height) <= texHeight) {
            readX = static_cast<NSUInteger>(x);
            readY = yFlipDepthReadback
                ? texHeight - static_cast<NSUInteger>(y + height)
                : static_cast<NSUInteger>(y);
            readWidth = static_cast<NSUInteger>(width);
            readHeight = static_cast<NSUInteger>(height);
        }
        const NSUInteger bytesPerRow = readWidth * srcBpp;
        const NSUInteger rawByteCount = bytesPerRow * readHeight;
        recordDepthReadbackCall(
            pf,
            static_cast<std::uint64_t>(rawByteCount),
            consumer);
        std::vector<std::uint8_t> raw(rawByteCount);
        const bool requiresDepthPlaneBlit = (depthStencilBlitOptions != 0);
        // Two read paths depending on the Metal storage mode:
        //   - Shared/Managed: direct `getBytes:` works.
        //   - Private: can't read directly on the CPU; blit the
        //     texture into a shared staging buffer via a
        //     blitCommandEncoder, then memcpy the contents.
        //   (Apple Silicon Metal defaults depth textures to
        //   Private, so the blit path is the common one here.)
        if (metalTex.storageMode != MTLStorageModePrivate &&
            !requiresDepthPlaneBlit) {
            MTLRegion region = MTLRegionMake2D(readX, readY,
                                                readWidth, readHeight);
            if (sourceSlice == 0 &&
                metalTex.textureType != MTLTextureType2DArray &&
                metalTex.textureType != MTLTextureType2DMultisampleArray) {
                [metalTex getBytes:raw.data()
                       bytesPerRow:bytesPerRow
                        fromRegion:region
                       mipmapLevel:mipLevel];
            } else {
                [metalTex getBytes:raw.data()
                       bytesPerRow:bytesPerRow
                     bytesPerImage:bytesPerRow * readHeight
                        fromRegion:region
                       mipmapLevel:mipLevel
                             slice:sourceSlice];
            }
        } else {
            id<MTLDevice> mtlDevice = device;
            id<MTLCommandQueue> mtlQueue = commandQueue;
            if (mtlDevice == nil || mtlQueue == nil) {
                return false;
            }
            const NSUInteger stagingSize = rawByteCount;
            id<MTLBuffer> staging = [mtlDevice newBufferWithLength:stagingSize
                                                          options:MTLResourceStorageModeShared];
            if (staging == nil) return false;
            recordDepthReadbackStaging(
                static_cast<std::uint64_t>(stagingSize));
            auto readbackLease = makeCommandBuffer(AppGLCommandReason::FlushForReadback);
            id<MTLCommandBuffer> cmd = readbackLease.get();
            if (cmd == nil) return false;
            id<MTLBlitCommandEncoder> blit = [cmd blitCommandEncoder];
            if (blit == nil) return false;
            MTLRegion region = MTLRegionMake2D(readX, readY,
                                                readWidth, readHeight);
            [blit copyFromTexture:metalTex
                      sourceSlice:sourceSlice
                      sourceLevel:mipLevel
                     sourceOrigin:region.origin
                       sourceSize:region.size
                         toBuffer:staging
                destinationOffset:0
           destinationBytesPerRow:bytesPerRow
         destinationBytesPerImage:stagingSize
                         options:depthStencilBlitOptions];
            [blit endEncoding];
            readbackLease.commitAndWait(AppGLCommandReason::FlushForReadback);
            std::memcpy(raw.data(), [staging contents], stagingSize);
        }
        auto readDepth = [&](NSUInteger srcX, NSUInteger srcY) -> float {
            if (srcX < readX || srcY < readY ||
                srcX >= readX + readWidth ||
                srcY >= readY + readHeight) {
                return 0.0f;
            }
            const NSUInteger localX = srcX - readX;
            const NSUInteger localY = srcY - readY;
            const std::uint8_t* srcPixel =
                raw.data() + (localY * readWidth + localX) * srcBpp;
            switch (pf) {
                case MTLPixelFormatDepth32Float: {
                    float v; std::memcpy(&v, srcPixel, 4); return v;
                }
                case MTLPixelFormatDepth16Unorm: {
                    std::uint16_t v; std::memcpy(&v, srcPixel, 2);
                    return static_cast<float>(v) / 65535.0f;
                }
                case MTLPixelFormatDepth32Float_Stencil8: {
                    float v; std::memcpy(&v, srcPixel, 4); return v;
                }
                case MTLPixelFormatDepth24Unorm_Stencil8: {
                    // Metal lays D24S8 as D24 in low 24 bits of
                    // the 32-bit word on MTLPixelFormatDepth24-
                    // Unorm_Stencil8.
                    std::uint32_t v; std::memcpy(&v, srcPixel, 4);
                    return static_cast<float>(v & 0x00FFFFFF) / static_cast<float>(0x00FFFFFF);
                }
                default: return 0.0f;
            }
        };
        auto* out = static_cast<GLfloat*>(pixels);
        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const GLint srcX = x + col;
                const GLint glY = y + row;
                // GL row 0 = bottom; Metal row 0 = top.
                const GLint srcY = yFlipDepthReadback
                    ? (static_cast<GLint>(texHeight) - 1 - glY)
                    : glY;
                const std::size_t dstOffset = static_cast<std::size_t>(row * width + col);
                if (srcX < 0 || srcY < 0 ||
                    static_cast<NSUInteger>(srcX) >= texWidth ||
                    static_cast<NSUInteger>(srcY) >= texHeight) {
                    out[dstOffset] = 0.0f;
                    continue;
                }
                out[dstOffset] = readDepth(static_cast<NSUInteger>(srcX),
                                           static_cast<NSUInteger>(srcY));
            }
        }
        return true;
    }

    bool syncDepth32FTextureLevelNativeFromMetal(GLTextureObject& object,
                                                 GLint level) {
        if (object.desc.internalFormat != GL_DEPTH_COMPONENT32F ||
            object.metalTexture == nullptr) {
            return false;
        }
        if (object.target == GL_TEXTURE_3D ||
            object.target == GL_TEXTURE_CUBE_MAP ||
            object.target == GL_TEXTURE_CUBE_MAP_ARRAY) {
            return false;
        }
        auto levelIt = object.levels.find(level);
        if (levelIt == object.levels.end() || !levelIt->second.defined) {
            return false;
        }
        GLTextureImageLevel& image = levelIt->second;
        if (!isDepth32FTextureShadowDropShape(image)) {
            return false;
        }
        id<MTLTexture> metalTex = (__bridge id<MTLTexture>)object.metalTexture;
        if (metalTex == nil ||
            static_cast<NSUInteger>(level) >=
                nonZeroMipLevelCount(metalTex.mipmapLevelCount)) {
            return false;
        }

        GLsizei width = std::max<GLsizei>(image.desc.width, 1);
        GLsizei height = std::max<GLsizei>(image.desc.height, 1);
        GLsizei slices = 1;
        switch (object.target) {
            case GL_TEXTURE_1D:
            case GL_TEXTURE_RECTANGLE:
            case GL_TEXTURE_2D:
                height = object.target == GL_TEXTURE_1D ? 1 : height;
                slices = 1;
                break;
            case GL_TEXTURE_1D_ARRAY:
                height = 1;
                slices = std::max<GLsizei>(
                    std::max<GLsizei>(image.desc.height, image.desc.layers), 1);
                break;
            case GL_TEXTURE_2D_ARRAY:
                slices = std::max<GLsizei>(
                    std::max<GLsizei>(image.desc.depth, image.desc.layers), 1);
                break;
            default:
                return false;
        }

        const std::size_t requiredBytes =
            static_cast<std::size_t>(width) *
            static_cast<std::size_t>(height) *
            static_cast<std::size_t>(slices) * sizeof(float);
        auto& diag = depth32fReadback;
        ++diag.syncCalls;
        auto failSync = [&]() {
            ++diag.syncFailures;
            return false;
        };
        if (image.nativeData.size() < requiredBytes) {
            return failSync();
        }

        drainPendingGpuProducers(object);
        const std::uint64_t nativeBytes =
            static_cast<std::uint64_t>(requiredBytes);
        const std::uint64_t depthValueBytes =
            static_cast<std::uint64_t>(width) *
            static_cast<std::uint64_t>(height) *
            static_cast<std::uint64_t>(sizeof(GLfloat));
        diag.syncNativeBytes += nativeBytes;
        diag.syncNativeMaxBytes =
            std::max(diag.syncNativeMaxBytes, nativeBytes);
        diag.syncDepthValueBytes += depthValueBytes;
        diag.syncDepthValueMaxBytes =
            std::max(diag.syncDepthValueMaxBytes, depthValueBytes);
        diag.syncSlices += static_cast<std::uint64_t>(slices);
        std::vector<GLfloat> depthValues(
            static_cast<std::size_t>(width) *
            static_cast<std::size_t>(height),
            0.0f);
        const bool slicedTarget =
            object.target == GL_TEXTURE_1D_ARRAY ||
            object.target == GL_TEXTURE_2D_ARRAY;
        for (GLsizei slice = 0; slice < slices; ++slice) {
            const NSUInteger sourceSlice =
                slicedTarget ? static_cast<NSUInteger>(slice) : 0u;
            if (!readDepthFromMetalTexture(metalTex,
                                           static_cast<NSUInteger>(level),
                                           sourceSlice,
                                           0,
                                           0,
                                           width,
                                           height,
                                           depthValues.data(),
                                           false,
                                           DepthReadbackConsumer::SyncNative)) {
                return failSync();
            }
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const std::size_t nativeOffset =
                        nativeShadowOffset(image, width, height, slice, col, row);
                    if (nativeOffset + sizeof(float) > image.nativeData.size()) {
                        return failSync();
                    }
                    const GLfloat depthValue =
                        depthValues[static_cast<std::size_t>(row * width + col)];
                    std::memcpy(image.nativeData.data() + nativeOffset,
                                &depthValue,
                                sizeof(depthValue));
                }
            }
        }
        object.depthStencilShadowAuthoritative = true;
        ++diag.syncSuccesses;
        return true;
    }

    bool copyDepth32FTextureSubImageMetalAsRGBA8(
        GLTextureObject& object,
        GLint level,
        GLint xoffset,
        GLint yoffset,
        GLint zoffset,
        GLsizei width,
        GLsizei height,
        GLsizei depth,
        const GLPixelStoreState& packStore,
        void* pixels) const {
        if (width == 0 || height == 0 || depth == 0) {
            return true;
        }
        if (pixels == nullptr || object.metalTexture == nullptr) {
            return false;
        }
        switch (object.target) {
            case GL_TEXTURE_3D:
            case GL_TEXTURE_1D_ARRAY:
                return false;
            default:
                break;
        }
        id<MTLTexture> metalTex = (__bridge id<MTLTexture>)object.metalTexture;
        if (metalTex == nil ||
            static_cast<NSUInteger>(level) >=
                nonZeroMipLevelCount(metalTex.mipmapLevelCount)) {
            return false;
        }
        drainPendingGpuProducers(object);
        const std::size_t dstPixelBytes = 4u;
        const std::size_t dstRowStridePixels = packStore.packRowLength > 0
            ? static_cast<std::size_t>(packStore.packRowLength)
            : static_cast<std::size_t>(width);
        const std::size_t dstRowBytes = alignByteCount(
            dstRowStridePixels * dstPixelBytes, packStore.packAlignment);
        const std::size_t dstImageHeight = packStore.packImageHeight > 0
            ? static_cast<std::size_t>(packStore.packImageHeight)
            : static_cast<std::size_t>(height);
        const std::size_t dstSliceBytes = dstRowBytes * dstImageHeight;
        auto& diag = depth32fReadback;
        ++diag.rgba8SubImageCalls;
        auto failRgba8SubImage = [&]() {
            ++diag.rgba8SubImageFailures;
            return false;
        };
        const std::uint64_t rgba8OutputBytes =
            static_cast<std::uint64_t>(dstSliceBytes) *
            static_cast<std::uint64_t>(depth);
        const std::uint64_t rgba8DepthValueBytes =
            static_cast<std::uint64_t>(width) *
            static_cast<std::uint64_t>(height) *
            static_cast<std::uint64_t>(depth) *
            static_cast<std::uint64_t>(sizeof(GLfloat));
        diag.rgba8SubImageOutputBytes += rgba8OutputBytes;
        diag.rgba8SubImageDepthValueBytes += rgba8DepthValueBytes;
        diag.rgba8SubImageSlices += static_cast<std::uint64_t>(depth);
        auto* dstBase = static_cast<std::uint8_t*>(pixels) +
            static_cast<std::size_t>(packStore.packSkipImages) * dstSliceBytes +
            static_cast<std::size_t>(packStore.packSkipRows) * dstRowBytes +
            static_cast<std::size_t>(packStore.packSkipPixels) * dstPixelBytes;
        const bool yFlipDepthReadback =
            (object.wasFramebufferRenderedTo ||
             object.wasViewportRenderedTo) &&
            state->clipOrigin() != GL_UPPER_LEFT;
        auto copySlice = [&](NSUInteger sourceSlice, GLsizei dstZ) {
            std::vector<GLfloat> depthValues(
                static_cast<std::size_t>(width) *
                static_cast<std::size_t>(height),
                0.0f);
            if (!readDepthFromMetalTexture(
                    metalTex,
                    static_cast<NSUInteger>(level),
                    sourceSlice,
                    xoffset,
                    yoffset,
                    width,
                    height,
                    depthValues.data(),
                    yFlipDepthReadback,
                    DepthReadbackConsumer::Rgba8SubImage)) {
                return false;
            }
            for (GLsizei row = 0; row < height; ++row) {
                std::uint8_t* dstRow = dstBase +
                    static_cast<std::size_t>(dstZ) * dstSliceBytes +
                    static_cast<std::size_t>(row) * dstRowBytes;
                for (GLsizei col = 0; col < width; ++col) {
                    const GLfloat depthValue =
                        depthValues[static_cast<std::size_t>(
                            row * width + col)];
                    std::uint8_t* dstPixel =
                        dstRow + static_cast<std::size_t>(col) * dstPixelBytes;
                    dstPixel[0] = normalizedByte(depthValue);
                    dstPixel[1] = 0u;
                    dstPixel[2] = 0u;
                    dstPixel[3] = 255u;
                }
            }
            return true;
        };
        if (object.target == GL_TEXTURE_CUBE_MAP) {
            for (GLsizei slice = 0; slice < depth; ++slice) {
                const GLint face = zoffset + slice;
                if (face < 0 || face >= 6 ||
                    !copySlice(static_cast<NSUInteger>(face), slice)) {
                    return failRgba8SubImage();
                }
            }
            ++diag.rgba8SubImageSuccesses;
            return true;
        }
        const bool slicedTarget =
            object.target == GL_TEXTURE_2D_ARRAY ||
            object.target == GL_TEXTURE_CUBE_MAP_ARRAY;
        for (GLsizei slice = 0; slice < depth; ++slice) {
            const NSUInteger sourceSlice = slicedTarget
                ? static_cast<NSUInteger>(zoffset + slice)
                : 0u;
            if (!copySlice(sourceSlice, slice)) {
                return failRgba8SubImage();
            }
        }
        ++diag.rgba8SubImageSuccesses;
        return true;
    }

    bool readStencilFromMetalTexture(id<MTLTexture> metalTex,
                                     NSUInteger mipLevel,
                                     NSUInteger sourceSlice,
                                     GLint x, GLint y,
                                     GLsizei width, GLsizei height,
                                     void* pixels,
                                     bool yFlipStencilReadback) const {
        if (metalTex == nil) {
            return false;
        }
        const MTLPixelFormat pf = metalTex.pixelFormat;
        MTLBlitOption stencilOption = 0;
        if (pf == MTLPixelFormatDepth24Unorm_Stencil8 ||
            pf == MTLPixelFormatDepth32Float_Stencil8) {
            stencilOption = MTLBlitOptionStencilFromDepthStencil;
        } else if (pf != MTLPixelFormatStencil8) {
            return false;
        }
        id<MTLDevice> mtlDevice = device;
        id<MTLCommandQueue> mtlQueue = commandQueue;
        if (mtlDevice == nil || mtlQueue == nil) {
            return false;
        }
        const NSUInteger texWidth =
            mipDimensionAtLevel(metalTex.width, mipLevel);
        const NSUInteger texHeight =
            mipDimensionAtLevel(metalTex.height, mipLevel);
        NSUInteger readX = 0;
        NSUInteger readY = 0;
        NSUInteger readWidth = texWidth;
        NSUInteger readHeight = texHeight;
        if (x >= 0 && y >= 0 && width > 0 && height > 0 &&
            static_cast<NSUInteger>(x) + static_cast<NSUInteger>(width) <= texWidth &&
            static_cast<NSUInteger>(y) + static_cast<NSUInteger>(height) <= texHeight) {
            readX = static_cast<NSUInteger>(x);
            readY = yFlipStencilReadback
                ? texHeight - static_cast<NSUInteger>(y + height)
                : static_cast<NSUInteger>(y);
            readWidth = static_cast<NSUInteger>(width);
            readHeight = static_cast<NSUInteger>(height);
        }
        const NSUInteger bytesPerRow = readWidth;
        const NSUInteger stagingSize = bytesPerRow * readHeight;
        id<MTLBuffer> staging =
            [mtlDevice newBufferWithLength:stagingSize
                                   options:MTLResourceStorageModeShared];
        if (staging == nil) {
            return false;
        }
        auto readbackLease = makeCommandBuffer(AppGLCommandReason::FlushForReadback);
        id<MTLCommandBuffer> cmd = readbackLease.get();
        if (cmd == nil) {
            return false;
        }
        id<MTLBlitCommandEncoder> blit = [cmd blitCommandEncoder];
        if (blit == nil) {
            return false;
        }
        MTLRegion region = MTLRegionMake2D(readX, readY, readWidth, readHeight);
        [blit copyFromTexture:metalTex
                  sourceSlice:sourceSlice
                  sourceLevel:mipLevel
                 sourceOrigin:region.origin
                   sourceSize:region.size
                     toBuffer:staging
            destinationOffset:0
       destinationBytesPerRow:bytesPerRow
     destinationBytesPerImage:stagingSize
                      options:stencilOption];
        [blit endEncoding];
        readbackLease.commitAndWait(AppGLCommandReason::FlushForReadback);
        std::vector<std::uint8_t> raw(stagingSize);
        std::memcpy(raw.data(), [staging contents], stagingSize);

        auto readStencil = [&](NSUInteger srcX, NSUInteger srcY) -> std::uint8_t {
            if (srcX < readX || srcY < readY ||
                srcX >= readX + readWidth ||
                srcY >= readY + readHeight) {
                return 0;
            }
            const NSUInteger localX = srcX - readX;
            const NSUInteger localY = srcY - readY;
            return raw[localY * readWidth + localX];
        };
        auto* out = static_cast<std::uint8_t*>(pixels);
        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const GLint srcX = x + col;
                const GLint glY = y + row;
                const GLint srcY = yFlipStencilReadback
                    ? (static_cast<GLint>(texHeight) - 1 - glY)
                    : glY;
                const std::size_t dstOffset =
                    static_cast<std::size_t>(row * width + col);
                if (srcX < 0 || srcY < 0 ||
                    static_cast<NSUInteger>(srcX) >= texWidth ||
                    static_cast<NSUInteger>(srcY) >= texHeight) {
                    out[dstOffset] = 0;
                    continue;
                }
                out[dstOffset] = readStencil(static_cast<NSUInteger>(srcX),
                                             static_cast<NSUInteger>(srcY));
            }
        }
        return true;
    }

    bool readDepthAttachmentPixels(const GLFramebufferAttachment& attachment, GLint x, GLint y, GLsizei width, GLsizei height, void* pixels) const {
        drainFramebufferAttachmentProducer(attachment);

        if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            const GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
            if (renderbuffer == nullptr || !renderbuffer->storageDefined) {
                return false;
            }
            // Sprint 17 Day 7+ Bank-Group-A B-revised: prefer the
            // Metal-texture read path over the CPU shadow `depth32`.
            // The shadow only captures `glClearDepth` initialisation
            // (line 6841) and `writeDepthAttachmentPixels` (CPU
            // glBlitFramebuffer path), NOT in-render-pass depth
            // output — Metal writes those to `metalTexture` directly
            // and the shadow stays at the cleared value. CTS
            // `clip_control.depth_mode_zero_to_one` /
            // `_one_to_one` exercise this with `glClearDepth(0.5)`,
            // a depth-gradient draw, then `glReadPixels(GL_DEPTH_-
            // COMPONENT, GL_FLOAT, …)` — pre-fix the readback
            // returned 0.5 everywhere (max-diff = 0.5) instead of
            // the rendered gradient.
            // Sprint 17 Day 9+ Bank-Group-A-1 narrow-gate (regression-
            // debt #1+#2): only prefer the Metal-texture path when this
            // RB has actually been written by a Metal render pass.
            // Pre-narrow `6ba6aad` always-prefers-metal logic regressed
            // CTS `direct_state_access.framebuffers_blit` +
            // `renderbuffers_storage` — those tests use glClearBufferfv
            // (CPU-shadow-only path) followed by readback, with no
            // render pass; the Metal texture stayed at its default
            // zero state and the read returned 0 instead of the cleared
            // 0.5. Narrowing on `wasMetalDepthRendered` preserves
            // Bank-Group-A-1 `clip_control.depth_mode_one_to_one` (sets
            // the flag via the post-render encodeTranslatedDrawAndMark-
            // Fbo helper) while restoring CPU-shadow read for clear-
            // only RBs.
            if (renderbuffer->metalTexture != nullptr &&
                renderbuffer->wasMetalDepthRendered) {
                id<MTLTexture> metalTex = (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                const bool yFlipDepthReadback =
                    renderbuffer->framebufferReadbackYFlip &&
                    state->clipOrigin() != GL_UPPER_LEFT;
                if (readDepthFromMetalTexture(metalTex, /*mipLevel*/0, /*sourceSlice*/0,
                                              x, y, width, height, pixels,
                                              yFlipDepthReadback,
                                              DepthReadbackConsumer::AttachmentReadback)) {
                    return true;
                }
                // Fall through to CPU shadow path on Metal-readback
                // failure (storage mode mismatch, queue unavailable,
                // unknown depth format) so well-tested CPU-blit
                // pipelines that still rely on the shadow stay
                // functional.
            }
            // CPU shadow fallback — preserves CPU-blit code path
            // (writeDepthAttachmentPixels at line ~7536) and the
            // glClearDepth-only no-render scenario.
            if (renderbuffer->depth32.empty()) return false;
            auto* out = static_cast<GLfloat*>(pixels);
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint srcX = x + col;
                    const GLint srcY = y + row;
                    const std::size_t dstOffset = static_cast<std::size_t>(row * width + col);
                    if (srcX < 0 || srcY < 0 || srcX >= renderbuffer->width || srcY >= renderbuffer->height) {
                        out[dstOffset] = 0.0f;
                        continue;
                    }
                    out[dstOffset] = renderbuffer->depth32[static_cast<std::size_t>(srcY) * static_cast<std::size_t>(renderbuffer->width) + static_cast<std::size_t>(srcX)];
                }
            }
            return true;
        }
        // Texture-backed depth attachment (GL 3.2+ depth textures).
        // CTS `polygon_offset_clamp.PolygonOffsetClamp{MinMax,ZeroInfinity}`
        // attaches a GL_DEPTH_COMPONENT24 / GL_DEPTH_COMPONENT32F texture
        // and reads back the rendered depth via
        // `glReadPixels(… GL_DEPTH_COMPONENT, GL_FLOAT, …)`. The old
        // renderbuffer-only path immediately returned false, which
        // surfaced as `GL_INVALID_FRAMEBUFFER_OPERATION`.
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            const GLTextureObject* tex = objects->textures().get(attachment.object);
            if (tex == nullptr) return false;
            const auto levelIt = tex->levels.find(attachment.level);
            if (levelIt == tex->levels.end() || !levelIt->second.defined) {
                return false;
            }
            const GLTextureImageLevel& image = levelIt->second;
            if (tex->depthStencilShadowAuthoritative &&
                image.nativeBpp > 0 && !image.nativeData.empty()) {
                const GLsizei sourceWidth =
                    std::max<GLsizei>(image.desc.width, 1);
                const GLsizei sourceHeight =
                    tex->target == GL_TEXTURE_1D ? 1 :
                    std::max<GLsizei>(image.desc.height, 1);
                const GLsizei sourceLayers =
                    textureFramebufferLayerCount(*tex, image);
                const GLsizei sourceLayer =
                    textureFramebufferLayerIndex(*tex, attachment);
                if (sourceLayer < 0 || sourceLayer >= sourceLayers) {
                    return false;
                }
                const bool yFlipDepthReadback =
                    (tex->wasFramebufferRenderedTo ||
                     tex->wasViewportRenderedTo) &&
                    state->clipOrigin() != GL_UPPER_LEFT;
                auto* out = static_cast<GLfloat*>(pixels);
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const GLint srcX = x + col;
                        const GLint glY = y + row;
                        const GLint srcY = yFlipDepthReadback
                            ? (sourceHeight - 1 - glY) : glY;
                        const std::size_t dstOffset =
                            static_cast<std::size_t>(row * width + col);
                        if (srcX < 0 || srcY < 0 ||
                            srcX >= sourceWidth || srcY >= sourceHeight) {
                            out[dstOffset] = 0.0f;
                            continue;
                        }
                        const std::size_t nativeOffset = nativeShadowOffset(
                            image, sourceWidth, sourceHeight, sourceLayer,
                            srcX, srcY);
                        out[dstOffset] = loadNativeDepth(image, nativeOffset);
                    }
                }
                return true;
            }
            if (tex->metalTexture == nullptr) return false;
            id<MTLTexture> metalTex = (__bridge id<MTLTexture>)tex->metalTexture;
            const NSUInteger mipLevel = static_cast<NSUInteger>(std::max<GLint>(attachment.level, 0));
            const MTLTextureType texType = metalTex.textureType;
            const NSUInteger sourceSlice =
                (texType == MTLTextureType2DArray ||
                 texType == MTLTextureType2DMultisampleArray ||
                 texType == MTLTextureTypeCube ||
                 texType == MTLTextureTypeCubeArray)
                    ? static_cast<NSUInteger>(std::max<GLint>(attachment.layer, 0))
                    : 0;
            const bool yFlipDepthReadback =
                (tex->wasFramebufferRenderedTo || tex->wasViewportRenderedTo) &&
                state->clipOrigin() != GL_UPPER_LEFT;
            return readDepthFromMetalTexture(metalTex, mipLevel, sourceSlice,
                                             x, y, width, height, pixels,
                                             yFlipDepthReadback,
                                             DepthReadbackConsumer::AttachmentReadback);
        }
        return false;
    }

    bool readStencilAttachmentPixels(const GLFramebufferAttachment& attachment, GLint x, GLint y, GLsizei width, GLsizei height, void* pixels) const {
        drainFramebufferAttachmentProducer(attachment);

        if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            const GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
            if (renderbuffer == nullptr || !renderbuffer->storageDefined) {
                return false;
            }
            if (renderbuffer->metalTexture != nullptr &&
                renderbuffer->wasMetalStencilRendered &&
                device != nil && commandQueue != nil) {
                id<MTLTexture> metalTex = (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                const bool yFlipStencilReadback =
                    state->clipOrigin() != GL_UPPER_LEFT;
                if (readStencilFromMetalTexture(metalTex, /*mipLevel*/0,
                                                /*sourceSlice*/0,
                                                x, y, width, height, pixels,
                                                yFlipStencilReadback)) {
                    return true;
                }
            }
            if (renderbuffer->stencil8.empty()) {
                return false;
            }
            auto* out = static_cast<std::uint8_t*>(pixels);
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint srcX = x + col;
                    const GLint srcY = y + row;
                    const std::size_t dstOffset = static_cast<std::size_t>(row * width + col);
                    if (srcX < 0 || srcY < 0 || srcX >= renderbuffer->width || srcY >= renderbuffer->height) {
                        out[dstOffset] = 0;
                        continue;
                    }
                    out[dstOffset] = renderbuffer->stencil8[static_cast<std::size_t>(srcY) * static_cast<std::size_t>(renderbuffer->width) + static_cast<std::size_t>(srcX)];
                }
            }
            return true;
        }
        // Sprint 15 Day 34 (CKPT207): Texture-kind depth-stencil attachment
        // stencil readback. Sister-pattern reuse from Day 31 (CKPT204)
        // GL_DEPTH_STENCIL handler: blit with `MTLBlitOptionStencilFromDepthStencil`
        // to extract stencil into a separate buffer (Metal's depth-stencil
        // getBytes layout isn't directly addressable for stencil-only).
        // Pre-patch this case rejected outright via the Renderbuffer-only
        // gate and pushed GL_INVALID_FRAMEBUFFER_OPERATION at the
        // readPixels site (line 9123). CTS
        // packed_pixels.pbo_rectangle.depth*_stencil8_format_*  surfaces
        // these as "Valid format used but glReadPixels failed" for output =
        // [GL_STENCIL_INDEX, *].
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            const GLTextureObject* tex = objects->textures().get(attachment.object);
            if (tex == nullptr) return false;
            const auto levelIt = tex->levels.find(attachment.level);
            if (levelIt == tex->levels.end() || !levelIt->second.defined) {
                return false;
            }
            const GLTextureImageLevel& image = levelIt->second;
            if (tex->depthStencilShadowAuthoritative &&
                image.nativeBpp > 0 && !image.nativeData.empty()) {
                const GLsizei sourceWidth =
                    std::max<GLsizei>(image.desc.width, 1);
                const GLsizei sourceHeight =
                    tex->target == GL_TEXTURE_1D ? 1 :
                    std::max<GLsizei>(image.desc.height, 1);
                const GLsizei sourceLayers =
                    textureFramebufferLayerCount(*tex, image);
                const GLsizei sourceLayer =
                    textureFramebufferLayerIndex(*tex, attachment);
                if (sourceLayer < 0 || sourceLayer >= sourceLayers) {
                    return false;
                }
                const bool yFlipStencilReadback =
                    (tex->wasFramebufferRenderedTo ||
                     tex->wasViewportRenderedTo) &&
                    state->clipOrigin() != GL_UPPER_LEFT;
                auto* out = static_cast<std::uint8_t*>(pixels);
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const GLint srcX = x + col;
                        const GLint glY = y + row;
                        const GLint srcY = yFlipStencilReadback
                            ? (sourceHeight - 1 - glY) : glY;
                        const std::size_t dstOffset =
                            static_cast<std::size_t>(row * width + col);
                        if (srcX < 0 || srcY < 0 ||
                            srcX >= sourceWidth || srcY >= sourceHeight) {
                            out[dstOffset] = 0;
                            continue;
                        }
                        const std::size_t nativeOffset = nativeShadowOffset(
                            image, sourceWidth, sourceHeight, sourceLayer,
                            srcX, srcY);
                        out[dstOffset] = loadNativeStencil(image, nativeOffset);
                    }
                }
                return true;
            }
            if (tex->metalTexture == nullptr) return false;
            id<MTLTexture> metalTex = (__bridge id<MTLTexture>)tex->metalTexture;
            const NSUInteger metalMipLevel =
                static_cast<NSUInteger>(attachment.level);
            const MTLTextureType texType = metalTex.textureType;
            const NSUInteger sourceSlice =
                (texType == MTLTextureType2DArray ||
                 texType == MTLTextureType2DMultisampleArray ||
                 texType == MTLTextureTypeCube ||
                 texType == MTLTextureTypeCubeArray)
                    ? static_cast<NSUInteger>(std::max<GLint>(attachment.layer, 0))
                    : 0;
            const bool yFlipStencilReadback =
                (tex->wasFramebufferRenderedTo || tex->wasViewportRenderedTo) &&
                state->clipOrigin() != GL_UPPER_LEFT;
            return readStencilFromMetalTexture(metalTex, metalMipLevel,
                                               sourceSlice, x, y, width,
                                               height, pixels,
                                               yFlipStencilReadback);
        }
        return false;
    }

    // Write helpers for blitFramebuffer. They mirror readXxxAttachmentPixels and
    // commit pixels into the attachment's CPU shadow store (and re-upload to Metal
    // for color textures so subsequent samples see the blitted pixels).
    bool encodeColorNativePixelFromRGBA8(MTLPixelFormat mtlFormat,
                                         const std::uint8_t rgba[4],
                                         std::uint8_t* dst,
                                         std::size_t dstBytes) {
        const NativeFormatInfo info = nativeFormatInfo(mtlFormat);
        if (info.bytesPerPixel <= 0 ||
            dstBytes < static_cast<std::size_t>(info.bytesPerPixel)) {
            return false;
        }
        std::memset(dst, 0, static_cast<std::size_t>(info.bytesPerPixel));
        if (info.channels <= 0) {
            const double r = static_cast<double>(rgba[0]) / 255.0;
            const double g = static_cast<double>(rgba[1]) / 255.0;
            const double b = static_cast<double>(rgba[2]) / 255.0;
            const double a = static_cast<double>(rgba[3]) / 255.0;
            std::uint32_t packed = 0;
            if (mtlFormat == MTLPixelFormatRG11B10Float) {
                packed = packUF_10F11F11F_REV(r, g, b);
            } else if (mtlFormat == MTLPixelFormatRGB9E5Float) {
                packed = packUF_5_9_9_9_REV(r, g, b);
            } else if (mtlFormat == MTLPixelFormatRGB10A2Unorm ||
                       mtlFormat == MTLPixelFormatRGB10A2Uint) {
                const bool asInteger =
                    mtlFormat == MTLPixelFormatRGB10A2Uint;
                const std::uint32_t pr = packReadbackBits(r, 1023u, asInteger);
                const std::uint32_t pg = packReadbackBits(g, 1023u, asInteger);
                const std::uint32_t pb = packReadbackBits(b, 1023u, asInteger);
                const std::uint32_t pa = packReadbackBits(a, 3u, asInteger);
                packed = (pr & 0x3FFu) |
                         ((pg & 0x3FFu) << 10) |
                         ((pb & 0x3FFu) << 20) |
                         ((pa & 0x003u) << 30);
            } else {
                return false;
            }
            std::memcpy(dst, &packed, sizeof(packed));
            return true;
        }
        for (int c = 0; c < info.channels && c < 4; ++c) {
            const double value =
                (info.compType == NativeFormatInfo::UInt ||
                 info.compType == NativeFormatInfo::SInt)
                    ? static_cast<double>(rgba[c])
                    : static_cast<double>(rgba[c]) / 255.0;
            writeNativeComponent(
                dst + static_cast<std::size_t>(c * info.bytesPerChannel),
                info.compType,
                info.bytesPerChannel,
                value);
        }
        return true;
    }

    bool storeColorNativePixelFromRGBA8(GLTextureImageLevel& image,
                                        GLsizei width,
                                        GLsizei height,
                                        GLsizei layer,
                                        GLsizei x,
                                        GLsizei y,
                                        const std::uint8_t rgba[4]) {
        if (image.nativeBpp == 0) {
            const MTLPixelFormat mtlFormat =
                metalRenderbufferFormat(image.desc.internalFormat);
            const NativeFormatInfo info = nativeFormatInfo(mtlFormat);
            if (info.bytesPerPixel <= 0) {
                return false;
            }
            image.nativeBpp = static_cast<std::size_t>(info.bytesPerPixel);
        }
        if (image.nativeData.empty()) {
            const std::size_t required =
                static_cast<std::size_t>(width) *
                static_cast<std::size_t>(height) *
                static_cast<std::size_t>(std::max<GLsizei>(layer + 1, 1)) *
                image.nativeBpp;
            image.nativeData.assign(required, 0);
        }
        const MTLPixelFormat mtlFormat =
            metalRenderbufferFormat(image.desc.internalFormat);
        const NativeFormatInfo info = nativeFormatInfo(mtlFormat);
        if (info.bytesPerPixel <= 0 ||
            image.nativeBpp != static_cast<std::size_t>(info.bytesPerPixel)) {
            return false;
        }
        const std::size_t required =
            static_cast<std::size_t>(width) *
            static_cast<std::size_t>(height) *
            static_cast<std::size_t>(std::max<GLsizei>(layer + 1, 1)) *
            image.nativeBpp;
        if (image.nativeData.size() < required) {
            image.nativeData.resize(required, 0);
        }
        const std::size_t nativeOffset =
            (((static_cast<std::size_t>(layer) *
               static_cast<std::size_t>(height) +
               static_cast<std::size_t>(y)) *
              static_cast<std::size_t>(width)) +
             static_cast<std::size_t>(x)) * image.nativeBpp;
        if (nativeOffset + image.nativeBpp > image.nativeData.size()) {
            return false;
        }
        return encodeColorNativePixelFromRGBA8(
            mtlFormat, rgba, image.nativeData.data() + nativeOffset,
            image.nativeBpp);
    }

    bool writeColorAttachmentPixels(const GLFramebufferAttachment& attachment, GLint x, GLint y, GLsizei width, GLsizei height, const std::uint8_t* pixels) {
        std::uint8_t* dest = nullptr;
        GLsizei destWidth = 0;
        GLsizei destHeight = 0;
        GLsizei destLayer = 0;
        GLTextureObject* writableTexture = nullptr;
        GLTextureImageLevel* writableImage = nullptr;
        GLuint writableTextureName = 0;

        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            const ResolvedTextureAttachment resolved =
                resolveTextureAttachmentStorage(attachment);
            writableTexture = resolved.storageTexture;
            if (!resolved.valid || writableTexture == nullptr) {
                return false;
            }
            writableTextureName = resolved.storageName;
            auto level = writableTexture->levels.find(resolved.level);
            if (level == writableTexture->levels.end() || !level->second.defined) {
                return false;
            }
            const GLsizei sourceWidth = std::max<GLsizei>(level->second.desc.width, 1);
            const GLsizei sourceHeight = writableTexture->target == GL_TEXTURE_1D ? 1 : std::max<GLsizei>(level->second.desc.height, 1);
            const GLsizei sourceDepth =
                (writableTexture->target == GL_TEXTURE_3D ||
                 writableTexture->target == GL_TEXTURE_2D_ARRAY ||
                 writableTexture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY ||
                 writableTexture->target == GL_TEXTURE_CUBE_MAP_ARRAY)
                    ? std::max<GLsizei>(level->second.desc.depth, 1)
                    : (writableTexture->target == GL_TEXTURE_1D_ARRAY
                        ? std::max<GLsizei>(level->second.desc.height, 1)
                        : (writableTexture->target == GL_TEXTURE_CUBE_MAP ? 6 : 1));
            if (!materializeTextureMipShadowFromMetal(
                    *writableTexture,
                    resolved.level,
                    TextureMipShadowMaterializeConsumer::TexSubImage)) {
                return false;
            }
            if (level->second.rgba8.size() <
                rgba8ByteCount(sourceWidth, sourceHeight, sourceDepth)) {
                level->second.rgba8.assign(rgba8ByteCount(sourceWidth, sourceHeight, sourceDepth), 0);
            }
            writableImage = &level->second;
            destLayer =
                (writableTexture->target == GL_TEXTURE_3D ||
                 writableTexture->target == GL_TEXTURE_2D_ARRAY ||
                 writableTexture->target == GL_TEXTURE_1D_ARRAY ||
                 writableTexture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY ||
                 writableTexture->target == GL_TEXTURE_CUBE_MAP ||
                 writableTexture->target == GL_TEXTURE_CUBE_MAP_ARRAY)
                    ? resolved.layer : 0;
            if (destLayer < 0 || destLayer >= sourceDepth) {
                return false;
            }
            dest = level->second.rgba8.data();
            destWidth = sourceWidth;
            destHeight = sourceHeight;
            if (state->clipOrigin() == GL_LOWER_LEFT) {
                writableTexture->wasFramebufferRenderedTo = true;
            }
        } else if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
            if (renderbuffer == nullptr || !renderbuffer->storageDefined || !isColorFormat(renderbuffer->internalFormat)) {
                return false;
            }
            if (renderbuffer->rgba8.empty() &&
                renderbuffer->metalTexture != nullptr) {
                id<MTLTexture> metalTex =
                    (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                const MTLPixelFormat pf = metalTex.pixelFormat;
                if (metalTex.sampleCount <= 1 &&
                    (pf == MTLPixelFormatRGBA8Unorm ||
                     pf == MTLPixelFormatRGBA8Unorm_sRGB)) {
                    std::vector<std::uint8_t> flipped(
                        static_cast<std::size_t>(width) *
                        static_cast<std::size_t>(height) * 4u);
                    for (GLsizei row = 0; row < height; ++row) {
                        const std::size_t srcOff =
                            static_cast<std::size_t>(row) *
                            static_cast<std::size_t>(width) * 4u;
                        const std::size_t dstOff =
                            static_cast<std::size_t>(height - 1 - row) *
                            static_cast<std::size_t>(width) * 4u;
                        std::memcpy(flipped.data() + dstOff, pixels + srcOff,
                                    static_cast<std::size_t>(width) * 4u);
                    }
                    const NSUInteger metalY = static_cast<NSUInteger>(
                        renderbuffer->height - (y + height));
                    MTLRegion region = MTLRegionMake2D(
                        static_cast<NSUInteger>(x),
                        metalY,
                        static_cast<NSUInteger>(width),
                        static_cast<NSUInteger>(height));
                    [metalTex replaceRegion:region
                                mipmapLevel:0
                                  withBytes:flipped.data()
                                bytesPerRow:static_cast<NSUInteger>(width) * 4u];
                    renderbuffer->rgba8ShadowClearPending = false;
                    renderbuffer->colorShadowAuthoritative = false;
                    return true;
                }
            }
            materializeRenderbufferRGBA8Clear(*renderbuffer);
            if (renderbuffer->rgba8.empty()) {
                renderbuffer->rgba8.assign(static_cast<std::size_t>(renderbuffer->width) * static_cast<std::size_t>(renderbuffer->height) * 4u, 0);
            }
            dest = renderbuffer->rgba8.data();
            destWidth = renderbuffer->width;
            destHeight = renderbuffer->height;
            // Scope the metalTexture update below to this branch; needed
            // so glBlitFramebuffer's shadow-only write is visible to the
            // subsequent glReadPixels → Metal-texture readback path.
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint dstX = x + col;
                    const GLint dstY = y + row;
                    if (dstX < 0 || dstY < 0 || dstX >= destWidth || dstY >= destHeight) {
                        continue;
                    }
                    const std::size_t srcOffset = static_cast<std::size_t>(row * width + col) * 4u;
                    const std::size_t dstOffset =
                        (static_cast<std::size_t>(dstY) *
                         static_cast<std::size_t>(destWidth) +
                         static_cast<std::size_t>(dstX)) * 4u;
                    std::memcpy(dest + dstOffset, pixels + srcOffset, 4);
                }
            }
            // Mirror the shadow write to the Metal texture so readback
            // from the Metal side sees the blitted pixels. Metal textures
            // store row 0 at the top but our shadow/GL coord puts y=0
            // at the bottom; readColorAttachmentPixels applies the
            // Y-flip when reading from the Metal texture, so we must
            // Y-flip here too (write GL y=N to Metal row sourceHeight-
            // 1-N) to keep the two sides consistent.
            if (renderbuffer->metalTexture != nullptr) {
                id<MTLTexture> metalTex = (__bridge id<MTLTexture>)renderbuffer->metalTexture;
                if (metalTex.sampleCount <= 1) {
                    const MTLPixelFormat pf = metalTex.pixelFormat;
                    if (pf == MTLPixelFormatRGBA8Unorm ||
                        pf == MTLPixelFormatRGBA8Unorm_sRGB ||
                        pf == MTLPixelFormatBGRA8Unorm ||
                        pf == MTLPixelFormatBGRA8Unorm_sRGB) {
                        // Build the Y-flipped upload buffer. For each
                        // GL row in [y, y+height), the Metal row is
                        // (destHeight - 1 - glRow).
                        std::vector<std::uint8_t> flipped(
                            static_cast<std::size_t>(width) *
                            static_cast<std::size_t>(height) * 4u);
                        for (GLsizei row = 0; row < height; ++row) {
                            const std::size_t srcOff =
                                static_cast<std::size_t>(row) *
                                static_cast<std::size_t>(width) * 4u;
                            const std::size_t dstOff =
                                static_cast<std::size_t>(height - 1 - row) *
                                static_cast<std::size_t>(width) * 4u;
                            std::memcpy(&flipped[dstOff], pixels + srcOff,
                                        static_cast<std::size_t>(width) * 4u);
                        }
                        const NSUInteger bytesPerRow =
                            static_cast<NSUInteger>(width) * 4u;
                        const NSUInteger metalY = static_cast<NSUInteger>(
                            destHeight - (y + height));
                        MTLRegion region = MTLRegionMake2D(
                            static_cast<NSUInteger>(x),
                            metalY,
                            static_cast<NSUInteger>(width),
                            static_cast<NSUInteger>(height));
                        [metalTex replaceRegion:region
                                    mipmapLevel:0
                                      withBytes:flipped.data()
                                    bytesPerRow:bytesPerRow];
                    } else {
                        const NativeFormatInfo nativeInfo =
                            nativeFormatInfo(pf);
                        if (nativeInfo.bytesPerPixel > 0) {
                            const std::size_t nativeBpp =
                                static_cast<std::size_t>(
                                    nativeInfo.bytesPerPixel);
                            constexpr GLsizei kRowsPerUpload = 32;
                            for (GLsizei chunkY = 0; chunkY < height;
                                 chunkY += kRowsPerUpload) {
                                const GLsizei chunkRows =
                                    std::min<GLsizei>(
                                        kRowsPerUpload, height - chunkY);
                                std::vector<std::uint8_t> nativeChunk(
                                    static_cast<std::size_t>(width) *
                                    static_cast<std::size_t>(chunkRows) *
                                    nativeBpp);
                                for (GLsizei row = 0; row < chunkRows; ++row) {
                                    const GLsizei srcRow = chunkY + row;
                                    const GLsizei uploadRow =
                                        chunkRows - 1 - row;
                                    for (GLsizei col = 0; col < width; ++col) {
                                        const std::size_t srcOff =
                                            (static_cast<std::size_t>(srcRow) *
                                             static_cast<std::size_t>(width) +
                                             static_cast<std::size_t>(col)) * 4u;
                                        const std::size_t dstOff =
                                            (static_cast<std::size_t>(uploadRow) *
                                             static_cast<std::size_t>(width) +
                                             static_cast<std::size_t>(col)) *
                                            nativeBpp;
                                        (void)encodeColorNativePixelFromRGBA8(
                                            pf, pixels + srcOff,
                                            nativeChunk.data() + dstOff,
                                            nativeBpp);
                                    }
                                }
                                const NSUInteger metalY =
                                    static_cast<NSUInteger>(
                                        destHeight - (y + chunkY + chunkRows));
                                MTLRegion region = MTLRegionMake2D(
                                    static_cast<NSUInteger>(x),
                                    metalY,
                                    static_cast<NSUInteger>(width),
                                    static_cast<NSUInteger>(chunkRows));
                                [metalTex replaceRegion:region
                                            mipmapLevel:0
                                              withBytes:nativeChunk.data()
                                            bytesPerRow:static_cast<NSUInteger>(width) *
                                                        nativeBpp];
                            }
                        }
                    }
                }
            }
            renderbuffer->colorShadowAuthoritative = true;
            return true;
        } else {
            return false;
        }

        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const GLint dstX = x + col;
                const GLint dstY = y + row;
                if (dstX < 0 || dstY < 0 || dstX >= destWidth || dstY >= destHeight) {
                    continue;
                }
                const GLint storageY = state->clipOrigin() == GL_UPPER_LEFT
                    ? dstY : (destHeight - 1 - dstY);
                const std::size_t srcOffset = static_cast<std::size_t>(row * width + col) * 4u;
                const std::size_t dstOffset =
                    ((static_cast<std::size_t>(destLayer) * static_cast<std::size_t>(destHeight)
                        + static_cast<std::size_t>(storageY))
                        * static_cast<std::size_t>(destWidth)
                        + static_cast<std::size_t>(dstX))
                    * 4u;
                std::memcpy(dest + dstOffset, pixels + srcOffset, 4);
                if (writableImage != nullptr && writableImage->nativeBpp > 0) {
                    (void)storeColorNativePixelFromRGBA8(
                        *writableImage, destWidth, destHeight, destLayer,
                        dstX, storageY, pixels + srcOffset);
                }
            }
        }

        if (writableTexture != nullptr) {
            writableTexture->colorShadowAuthoritative = true;
            return replaceMetalTexture(*writableTexture, writableTextureName);
        }
        return true;
    }

    bool writeDepthAttachmentPixels(const GLFramebufferAttachment& attachment, GLint x, GLint y, GLsizei width, GLsizei height, const GLfloat* pixels) {
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            GLTextureObject* texture = objects->textures().get(attachment.object);
            if (texture == nullptr) {
                return false;
            }
            auto levelIt = texture->levels.find(attachment.level);
            if (levelIt == texture->levels.end() || !levelIt->second.defined ||
                !isDepthFormat(levelIt->second.desc.internalFormat)) {
                return false;
            }
            GLTextureImageLevel& image = levelIt->second;
            const GLsizei destWidth = std::max<GLsizei>(image.desc.width, 1);
            const GLsizei destHeight = texture->target == GL_TEXTURE_1D
                ? 1 : std::max<GLsizei>(image.desc.height, 1);
            const GLsizei layerCount =
                textureFramebufferLayerCount(*texture, image);
            const GLsizei destLayer =
                textureFramebufferLayerIndex(*texture, attachment);
            if (destLayer < 0 || destLayer >= layerCount ||
                !ensureDepthStencilNativeShadow(
                    image, destWidth, destHeight, layerCount)) {
                return false;
            }
            const bool lowerLeft = state->clipOrigin() != GL_UPPER_LEFT;
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint dstX = x + col;
                    const GLint dstY = y + row;
                    if (dstX < 0 || dstY < 0 ||
                        dstX >= destWidth || dstY >= destHeight) {
                        continue;
                    }
                    const GLint storageY =
                        lowerLeft ? (destHeight - 1 - dstY) : dstY;
                    const std::size_t nativeOffset = nativeShadowOffset(
                        image, destWidth, destHeight, destLayer, dstX, storageY);
                    storeNativeDepth(
                        image, nativeOffset,
                        pixels[static_cast<std::size_t>(row * width + col)]);
                }
            }
            if (lowerLeft) {
                texture->wasFramebufferRenderedTo = true;
            }
            texture->depthStencilShadowAuthoritative = true;
            if (texture->target == GL_TEXTURE_2D_MULTISAMPLE ||
                texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY) {
                return true;
            }
            return replaceMetalTexture(*texture) || texture->depthStencilShadowAuthoritative;
        }
        if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
            if (renderbuffer == nullptr || !renderbuffer->storageDefined || !isDepthFormat(renderbuffer->internalFormat)) {
                return false;
            }
            if (renderbuffer->depth32.empty() &&
                mirrorDepthRenderbufferRegionToMetal(
                    *renderbuffer, x, y, width, height, pixels)) {
                return true;
            }
            if (renderbuffer->depth32.empty()) {
                renderbuffer->depth32.assign(static_cast<std::size_t>(renderbuffer->width) * static_cast<std::size_t>(renderbuffer->height), 0.0f);
            }
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint dstX = x + col;
                    const GLint dstY = y + row;
                    if (dstX < 0 || dstY < 0 || dstX >= renderbuffer->width || dstY >= renderbuffer->height) {
                        continue;
                    }
                    renderbuffer->depth32[
                        static_cast<std::size_t>(dstY) * static_cast<std::size_t>(renderbuffer->width) + static_cast<std::size_t>(dstX)
                    ] = pixels[static_cast<std::size_t>(row * width + col)];
                }
            }
            const bool mirroredDepth =
                mirrorDepthRenderbufferRegionToMetal(*renderbuffer, x, y,
                                                     width, height, pixels);
            if (!mirroredDepth) {
                renderbuffer->wasMetalDepthRendered = false;
            }
            return true;
        }
        return false;
    }

    bool writeStencilAttachmentPixels(const GLFramebufferAttachment& attachment, GLint x, GLint y, GLsizei width, GLsizei height, const std::uint8_t* pixels) {
        if (attachment.kind == GLFramebufferAttachment::Kind::Texture) {
            GLTextureObject* texture = objects->textures().get(attachment.object);
            if (texture == nullptr) {
                return false;
            }
            auto levelIt = texture->levels.find(attachment.level);
            if (levelIt == texture->levels.end() || !levelIt->second.defined ||
                !isStencilFormat(levelIt->second.desc.internalFormat)) {
                return false;
            }
            GLTextureImageLevel& image = levelIt->second;
            const GLsizei destWidth = std::max<GLsizei>(image.desc.width, 1);
            const GLsizei destHeight = texture->target == GL_TEXTURE_1D
                ? 1 : std::max<GLsizei>(image.desc.height, 1);
            const GLsizei layerCount =
                textureFramebufferLayerCount(*texture, image);
            const GLsizei destLayer =
                textureFramebufferLayerIndex(*texture, attachment);
            if (destLayer < 0 || destLayer >= layerCount ||
                !ensureDepthStencilNativeShadow(
                    image, destWidth, destHeight, layerCount)) {
                return false;
            }
            const bool lowerLeft = state->clipOrigin() != GL_UPPER_LEFT;
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint dstX = x + col;
                    const GLint dstY = y + row;
                    if (dstX < 0 || dstY < 0 ||
                        dstX >= destWidth || dstY >= destHeight) {
                        continue;
                    }
                    const GLint storageY =
                        lowerLeft ? (destHeight - 1 - dstY) : dstY;
                    const std::size_t nativeOffset = nativeShadowOffset(
                        image, destWidth, destHeight, destLayer, dstX, storageY);
                    storeNativeStencil(
                        image, nativeOffset,
                        pixels[static_cast<std::size_t>(row * width + col)]);
                }
            }
            if (lowerLeft) {
                texture->wasFramebufferRenderedTo = true;
            }
            texture->depthStencilShadowAuthoritative = true;
            if (texture->target == GL_TEXTURE_2D_MULTISAMPLE ||
                texture->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY) {
                return true;
            }
            return replaceMetalTexture(*texture) || texture->depthStencilShadowAuthoritative;
        }
        if (attachment.kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            GLRenderbufferObject* renderbuffer = objects->renderbuffers().get(attachment.object);
            if (renderbuffer == nullptr || !renderbuffer->storageDefined || !isStencilFormat(renderbuffer->internalFormat)) {
                return false;
            }
            if (renderbuffer->stencil8.empty() &&
                mirrorStencilRenderbufferRegionToMetal(
                    *renderbuffer, x, y, width, height, pixels)) {
                renderbuffer->wasMetalStencilRendered = true;
                return true;
            }
            if (renderbuffer->stencil8.empty()) {
                renderbuffer->stencil8.assign(static_cast<std::size_t>(renderbuffer->width) * static_cast<std::size_t>(renderbuffer->height), 0);
            }
            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const GLint dstX = x + col;
                    const GLint dstY = y + row;
                    if (dstX < 0 || dstY < 0 || dstX >= renderbuffer->width || dstY >= renderbuffer->height) {
                        continue;
                    }
                    renderbuffer->stencil8[
                        static_cast<std::size_t>(dstY) * static_cast<std::size_t>(renderbuffer->width) + static_cast<std::size_t>(dstX)
                    ] = pixels[static_cast<std::size_t>(row * width + col)];
                }
            }
            const bool mirroredStencil =
                mirrorStencilRenderbufferRegionToMetal(*renderbuffer, x, y,
                                                       width, height, pixels);
            renderbuffer->wasMetalStencilRendered = mirroredStencil;
            return true;
        }
        return false;
    }

    // Phase A blit: nearest-only, integer-clamped CPU copy between attached images.
    // Scaling and linear filtering land alongside the Metal compute path in a later
    // group; for the bootstrap-bridge surface we just need a correct 1:1 copy that
    // honors the COLOR/DEPTH/STENCIL mask plumbing and the read/draw bindings.
    bool blitFramebuffer(GLint srcX0, GLint srcY0, GLint srcX1, GLint srcY1, GLint dstX0, GLint dstY0, GLint dstX1, GLint dstY1, GLbitfield mask, GLenum filter) {
        if (filter != GL_NEAREST && filter != GL_LINEAR) {
            return false;
        }
        // C48: blit sources must observe deferred FBO clears and blit
        // destinations must not be overwritten by a later-materialized
        // one — land them all before any blit sub-path encodes.
        if (frameGraph != nullptr) {
            const bool materialized =
                frameGraph->materializeAllPendingFboClears();
            if (materialized) {
                frameGraph->flushForReadback();
            }
        }
        const GLbitfield kSupportedMask = GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT | GL_STENCIL_BUFFER_BIT;
        if ((mask & ~kSupportedMask) != 0 || mask == 0) {
            return false;
        }

        const GLuint readName = state->boundReadFramebuffer();
        const GLuint drawName = state->boundDrawFramebuffer();
        const GLFramebufferObject* readFb = objects->framebuffers().get(readName);
        GLFramebufferObject* drawFb =
            drawName == 0 ? nullptr : objects->framebuffers().get(drawName);
        const bool drawDefaultFramebuffer = (drawName == 0);
        if (readName == 0 || readFb == nullptr ||
            (!drawDefaultFramebuffer && drawFb == nullptr)) {
            return false;
        }
        if (drawDefaultFramebuffer &&
            (mask & (GL_DEPTH_BUFFER_BIT | GL_STENCIL_BUFFER_BIT)) != 0) {
            return false;
        }
        if (framebufferStatus(*readFb) != GL_FRAMEBUFFER_COMPLETE ||
            (!drawDefaultFramebuffer &&
             framebufferStatus(*drawFb) != GL_FRAMEBUFFER_COMPLETE)) {
            return false;
        }

        const GLint srcX = std::min(srcX0, srcX1);
        const GLint srcY = std::min(srcY0, srcY1);
        const GLsizei copyWidth = static_cast<GLsizei>(std::abs(srcX1 - srcX0));
        const GLsizei copyHeight = static_cast<GLsizei>(std::abs(srcY1 - srcY0));
        const GLint dstX = std::min(dstX0, dstX1);
        const GLint dstY = std::min(dstY0, dstY1);
        const GLsizei dstWidth = static_cast<GLsizei>(std::abs(dstX1 - dstX0));
        const GLsizei dstHeight = static_cast<GLsizei>(std::abs(dstY1 - dstY0));
        if (copyWidth <= 0 || copyHeight <= 0) {
            return true;  // empty blit is a no-op success per spec
        }
        // GL 4.6 §18.3.1 — blit supports scaling via filter parameter.
        // Implement nearest-neighbor scaling via CPU-side staging for
        // size mismatches: read src pixels, resample, write to dst.
        // Linear-filtering scaling follows the same path but with
        // bilinear interpolation (implemented for color only; GL
        // requires DEPTH/STENCIL blits to use NEAREST).
        const bool needsScale = (dstWidth != copyWidth || dstHeight != copyHeight);
        auto sampleSrcIndex = [&](GLsizei dx, GLsizei dy,
                                  GLsizei& sx, GLsizei& sy) {
            if (!needsScale) {
                sx = dx;
                sy = dy;
                return;
            }
            // Nearest sample: map dst pixel center to src pixel.
            // Use (dx + 0.5) * srcW / dstW - 0.5 → floor.
            const double u = (static_cast<double>(dx) + 0.5) *
                             static_cast<double>(copyWidth) /
                             static_cast<double>(dstWidth);
            const double v = (static_cast<double>(dy) + 0.5) *
                             static_cast<double>(copyHeight) /
                             static_cast<double>(dstHeight);
            sx = std::min(static_cast<GLsizei>(u), copyWidth - 1);
            sy = std::min(static_cast<GLsizei>(v), copyHeight - 1);
            if (sx < 0) sx = 0;
            if (sy < 0) sy = 0;
        };
        struct BlitWriteWindow {
            GLint x = 0;
            GLint y = 0;
            GLsizei width = 0;
            GLsizei height = 0;
            GLsizei srcOffsetX = 0;
            GLsizei srcOffsetY = 0;
            bool empty = false;
        };
        auto computeWriteWindow = [&]() {
            BlitWriteWindow window;
            window.x = dstX;
            window.y = dstY;
            window.width = dstWidth;
            window.height = dstHeight;
            if (state->isEnabled(GL_SCISSOR_TEST)) {
                const GLScissorState& s = state->scissor();
                const GLint clipMinX = std::max<GLint>(dstX, s.x);
                const GLint clipMinY = std::max<GLint>(dstY, s.y);
                const GLint clipMaxX = std::min<GLint>(dstX + dstWidth,
                                                       s.x + s.width);
                const GLint clipMaxY = std::min<GLint>(dstY + dstHeight,
                                                       s.y + s.height);
                if (s.width <= 0 || s.height <= 0 ||
                    clipMinX >= clipMaxX || clipMinY >= clipMaxY) {
                    window.empty = true;
                    window.width = 0;
                    window.height = 0;
                    return window;
                }
                window.x = clipMinX;
                window.y = clipMinY;
                window.width = static_cast<GLsizei>(clipMaxX - clipMinX);
                window.height = static_cast<GLsizei>(clipMaxY - clipMinY);
                window.srcOffsetX =
                    static_cast<GLsizei>(clipMinX - dstX);
                window.srcOffsetY =
                    static_cast<GLsizei>(clipMinY - dstY);
