    GLsizei viewportHeight = 720;

    // RC-A02: compute the minimum drawable size that covers the viewport
    // extent (offset + dimensions).  Used by draw paths and setViewport.
    GLsizei drawableSurfaceWidth() const {
        return static_cast<GLsizei>(std::max(0, viewportX)) + viewportWidth;
    }
    GLsizei drawableSurfaceHeight() const {
        return static_cast<GLsizei>(std::max(0, viewportY)) + viewportHeight;
    }
    GLsizei defaultDrawableRequestWidth() const {
        return defaultDrawableGrowOnlyEnabled()
            ? std::max<GLsizei>(viewportWidth, 1)
            : drawableSurfaceWidth();
    }
    GLsizei defaultDrawableRequestHeight() const {
        return defaultDrawableGrowOnlyEnabled()
            ? std::max<GLsizei>(viewportHeight, 1)
            : drawableSurfaceHeight();
    }

    void invalidateDefaultFramebufferShadow() {
        defaultFramebufferShadowValid = false;
    }

    // S24 lever-#1 (lazy shadow clears): full-surface unmasked unscissored
    // FB0 clears record a pending fill instead of running the per-pixel
    // loop (40.7% of WZ's main thread in the Map-v2 sample). Every shadow
    // consumer reaches the bytes through ensureDefaultFramebufferShadow,
    // which materializes the pending fill first. The Metal side is
    // untouched (FB0 clears were already loadAction-based).
    bool defaultFbShadowClearPending = false;
    std::array<std::uint8_t, 4> defaultFbShadowClearRGBA = {0, 0, 0, 0};
    std::uint64_t shadowClearsDeferred = 0;
    std::uint64_t shadowClearsCoalesced = 0;
    std::uint64_t shadowClearsMaterialized = 0;
    std::uint64_t shadowClearMaterializeBytes = 0;

    static bool isIntegerInternalFormat(GLenum fmt) {
        switch (fmt) {
            case GL_R8I: case GL_R8UI: case GL_R16I: case GL_R16UI:
            case GL_R32I: case GL_R32UI:
            case GL_RG8I: case GL_RG8UI: case GL_RG16I: case GL_RG16UI:
            case GL_RG32I: case GL_RG32UI:
            case GL_RGB8I: case GL_RGB8UI: case GL_RGB16I: case GL_RGB16UI:
            case GL_RGB32I: case GL_RGB32UI:
            case GL_RGBA8I: case GL_RGBA8UI: case GL_RGBA16I: case GL_RGBA16UI:
            case GL_RGBA32I: case GL_RGBA32UI:
                return true;
            default:
                return false;
        }
    }

    static bool lazyShadowClearsEnabled() {
        // C50 CROWNED 2026-06-10 (+79% live: 42→75fps): default-ON.
        // Per-call reads so probes can toggle per arm; cost is trivial
        // next to the fill it replaces.
        const char* dis = std::getenv("APPGL_DISABLE_LAZY_SHADOW_CLEARS");
        if (dis != nullptr && dis[0] != '\0' && dis[0] != '0') {
            return false;
        }
        const char* raw = std::getenv("APPGL_ENABLE_LAZY_SHADOW_CLEARS");
        return raw == nullptr || raw[0] == '\0' || raw[0] != '0';
    }

    static bool fboClearGpuOnlyColorEnabled() {
        const char* raw = std::getenv("APPGL_ENABLE_FBO_CLEAR_GPU_ONLY_COLOR");
        return raw == nullptr || raw[0] == '\0' || raw[0] != '0';
    }

    void materializeDefaultFbShadowClear() {
        if (!defaultFbShadowClearPending) {
            return;
        }
        defaultFbShadowClearPending = false;
        std::uint8_t* bytes = defaultFramebufferRGBA8.data();
        const std::size_t pixelCount = defaultFramebufferRGBA8.size() / 4u;
        for (std::size_t i = 0; i < pixelCount; ++i) {
            std::memcpy(bytes + i * 4u, defaultFbShadowClearRGBA.data(), 4u);
        }
        ++shadowClearsMaterialized;
        shadowClearMaterializeBytes += defaultFramebufferRGBA8.size();
    }

    void ensureDefaultFramebufferShadow(bool materializePendingClear = true) {
        const GLsizei requestedWidth =
            std::max<GLsizei>(defaultDrawableRequestWidth(), 1);
        const GLsizei requestedHeight =
            std::max<GLsizei>(defaultDrawableRequestHeight(), 1);
        const GLsizei width = defaultDrawableGrowOnlyEnabled()
            ? std::max<GLsizei>(requestedWidth, defaultFramebufferShadowWidth)
            : requestedWidth;
        const GLsizei height = defaultDrawableGrowOnlyEnabled()
            ? std::max<GLsizei>(requestedHeight, defaultFramebufferShadowHeight)
            : requestedHeight;
        const std::size_t byteCount =
            static_cast<std::size_t>(width) *
            static_cast<std::size_t>(height) * 4u;
        if (defaultFramebufferShadowWidth != width ||
            defaultFramebufferShadowHeight != height ||
            defaultFramebufferRGBA8.size() != byteCount) {
            std::vector<std::uint8_t> resized(byteCount, 0);
            const GLsizei copyWidth =
                std::min(defaultFramebufferShadowWidth, width);
            const GLsizei copyHeight =
                std::min(defaultFramebufferShadowHeight, height);
            for (GLsizei row = 0; row < copyHeight; ++row) {
                const std::size_t srcOffset =
                    static_cast<std::size_t>(row) *
                    static_cast<std::size_t>(defaultFramebufferShadowWidth) * 4u;
                const std::size_t dstOffset =
                    static_cast<std::size_t>(row) *
                    static_cast<std::size_t>(width) * 4u;
                std::memcpy(resized.data() + dstOffset,
                            defaultFramebufferRGBA8.data() + srcOffset,
                            static_cast<std::size_t>(copyWidth) * 4u);
            }
            defaultFramebufferRGBA8.swap(resized);
            defaultFramebufferShadowWidth = width;
            defaultFramebufferShadowHeight = height;
        }
        defaultFramebufferShadowValid = true;
        if (materializePendingClear) {
            materializeDefaultFbShadowClear();
        }
    }

    void ensureDefaultDrawableForViewportExtent() {
        if (frameGraph == nullptr) {
            return;
        }
        // Resize-gate fix (S24): viewports set while a non-default
        // framebuffer is bound belong to the FBO pass and must not size
        // the WINDOW drawable — Warzone's shadow-pass viewport was
        // hard-resizing the drawable twice per frame (depth-texture
        // recreate + invalidate/drainAll each time). The draw-site
        // ensure hooks re-evaluate with the then-current viewport when
        // FB0 is next drawn, so no stale-size hole exists.
        // Flicker triage round 3: APPGL_TRIAGE_DISABLE_RESIZE_GATE=1
        // restores the pre-f15e56d behavior (FBO-bound viewports size
        // the drawable again) so a single build can A/B the gate live
        // and headlessly. Diagnostic only — never set in production.
        static const bool triageDisableResizeGate =
            std::getenv("APPGL_TRIAGE_DISABLE_RESIZE_GATE") != nullptr;
        if (!triageDisableResizeGate &&
            state->boundDrawFramebuffer() != 0) {
            return;
        }
        const GLsizei width = defaultDrawableRequestWidth();
        const GLsizei height = defaultDrawableRequestHeight();
        if (defaultDrawableGrowOnlyEnabled()) {
            frameGraph->ensureDrawableSizeAtLeast(width, height);
        } else {
            frameGraph->resizeDrawable(width, height);
        }
    }

    void applyDefaultFramebufferColorClear() {
        ensureDefaultFramebufferShadow(/*materializePendingClear=*/false);
        const GLBlendState& blendForMask = state->blendState();
        const bool fullUnmasked =
            !state->isEnabled(GL_SCISSOR_TEST) &&
            blendForMask.colorMask[0] != GL_FALSE &&
            blendForMask.colorMask[1] != GL_FALSE &&
            blendForMask.colorMask[2] != GL_FALSE &&
            blendForMask.colorMask[3] != GL_FALSE;
        if (lazyShadowClearsEnabled() && fullUnmasked) {
            if (defaultFbShadowClearPending) {
                ++shadowClearsCoalesced;  // last full clear wins
            }
            defaultFbShadowClearRGBA = {
                normalizedByte(state->clearState().color[0]),
                normalizedByte(state->clearState().color[1]),
                normalizedByte(state->clearState().color[2]),
                normalizedByte(state->clearState().color[3]),
            };
            defaultFbShadowClearPending = true;
            // The shadow is logically valid: pending fill + bytes.
            defaultFramebufferShadowValid = true;
            ++shadowClearsDeferred;
            return;
        }
        // Partial/masked clears apply on top of materialized contents.
        materializeDefaultFbShadowClear();
        const std::uint8_t rgba[4] = {
            normalizedByte(state->clearState().color[0]),
            normalizedByte(state->clearState().color[1]),
            normalizedByte(state->clearState().color[2]),
            normalizedByte(state->clearState().color[3]),
        };

        GLsizei minX = 0;
        GLsizei maxX = defaultFramebufferShadowWidth;
        GLsizei minY = 0;
        GLsizei maxY = defaultFramebufferShadowHeight;
        if (state->isEnabled(GL_SCISSOR_TEST)) {
            const GLScissorState& s = state->scissor();
            minX = std::max<GLsizei>(0, s.x);
            maxX = std::min<GLsizei>(defaultFramebufferShadowWidth,
                                     s.x + s.width);
            minY = std::max<GLsizei>(0, s.y);
            maxY = std::min<GLsizei>(defaultFramebufferShadowHeight,
                                     s.y + s.height);
        }
        if (minX >= maxX || minY >= maxY) {
            return;
        }

        const GLBlendState& blend = state->blendState();
        for (GLsizei y = minY; y < maxY; ++y) {
            for (GLsizei x = minX; x < maxX; ++x) {
                const std::size_t offset =
                    (static_cast<std::size_t>(y) *
                     static_cast<std::size_t>(defaultFramebufferShadowWidth) +
                     static_cast<std::size_t>(x)) * 4u;
                for (int c = 0; c < 4; ++c) {
                    if (blend.colorMask[c] != GL_FALSE) {
                        defaultFramebufferRGBA8[offset + static_cast<std::size_t>(c)] =
                            rgba[c];
                    }
                }
            }
        }
    }

    bool copyDefaultFramebufferShadowPixels(
        GLint x,
        GLint y,
        GLsizei width,
        GLsizei height,
        void* outPixels
    ) const {
        if (!defaultFramebufferShadowValid || outPixels == nullptr ||
            width < 0 || height < 0) {
            return false;
        }
        if (defaultDrawableGrowOnlyEnabled() &&
            (x < 0 || y < 0 ||
             x + width > defaultFramebufferShadowWidth ||
             y + height > defaultFramebufferShadowHeight)) {
            return false;
        }
        auto* bytes = static_cast<std::uint8_t*>(outPixels);
        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const GLint srcX = x + col;
                const GLint srcY = y + row;
                const std::size_t dstOffset =
                    static_cast<std::size_t>(row * width + col) * 4u;
                if (srcX < 0 || srcY < 0 ||
                    srcX >= defaultFramebufferShadowWidth ||
                    srcY >= defaultFramebufferShadowHeight) {
                    std::memset(bytes + dstOffset, 0, 4);
                    continue;
                }
                const std::size_t srcOffset =
                    (static_cast<std::size_t>(srcY) *
                     static_cast<std::size_t>(defaultFramebufferShadowWidth) +
                     static_cast<std::size_t>(srcX)) * 4u;
                std::memcpy(bytes + dstOffset,
                            defaultFramebufferRGBA8.data() + srcOffset, 4);
            }
        }
        return true;
    }

    GLDEBUGPROC debugCallback = nullptr;
    const void* debugUserParam = nullptr;
