GLContext::PipelineCacheMetrics GLContext::pipelineCacheMetrics() const {
    PipelineCacheMetrics result;
    if (impl_->frameGraph) {
        auto m = impl_->frameGraph->pipelineCacheMetrics();
        result.hits = m.hits;
        result.misses = m.misses;
        // Phase 8X Group 4d follow-up⁴ — forward the new build counters.
        result.buildAttempts = m.buildAttempts;
        result.buildFailures = m.buildFailures;
        result.cumulativeBuildMillis = m.cumulativeBuildMillis;
    }
    return result;
}

void GLContext::resetPipelineCacheMetrics() {
    if (impl_->frameGraph) {
        impl_->frameGraph->resetPipelineCacheMetrics();
    }
}

std::uint64_t GLContext::metalAllocatedBytes() const {
    const std::uint64_t deviceBytes =
        metalDeviceCurrentAllocatedBytes(impl_->device);
    if (deviceBytes != 0) {
        return deviceBytes;
    }
    if (impl_->frameGraph) {
        return impl_->frameGraph->metalAllocatedBytes();
    }
    return 0;
}

std::string GLContext::framePacingDiagnosticsJson() const {
    return impl_->frameGraph != nullptr
        ? impl_->frameGraph->framePacingDiagnosticsJson()
        : std::string();
}

std::string GLContext::drawProfileDiagnosticsJson() const {
    const std::string gl = impl_->drawPathProfile.diagnosticsJson();
    const std::string bindingConstructionSizing =
        impl_->bindingConstructionSizingProfile.diagnosticsJson();
    const std::string clearColorAttachmentSizing =
        impl_->clearColorAttachmentSizingProfile.diagnosticsJson();
    const std::string submit = impl_->frameGraph != nullptr
        ? impl_->frameGraph->drawSubmitProfileDiagnosticsJson()
        : std::string();
    if (gl.empty() && bindingConstructionSizing.empty() &&
        clearColorAttachmentSizing.empty() && submit.empty()) {
        return std::string();
    }
    std::string out = "{";
    if (!gl.empty()) {
        out += "\"gl\":";
        out += gl;
    }
    if (!bindingConstructionSizing.empty()) {
        if (!gl.empty()) {
            out += ",";
        }
        out += "\"bindingConstructionSizing\":";
        out += bindingConstructionSizing;
    }
    if (!clearColorAttachmentSizing.empty()) {
        if (!gl.empty() || !bindingConstructionSizing.empty()) {
            out += ",";
        }
        out += "\"clearColorAttachmentSizing\":";
        out += clearColorAttachmentSizing;
    }
    if (!submit.empty()) {
        if (!gl.empty() || !bindingConstructionSizing.empty() ||
            !clearColorAttachmentSizing.empty()) {
            out += ",";
        }
        out += "\"submit\":";
        out += submit;
    }
    out += "}";
    return out;
}

GLContext::MetalResourceInventory GLContext::metalResourceInventory() const {
    MetalResourceInventory inventory;
    inventory.deviceAllocatedBytes = metalAllocatedBytes();
    const std::uint64_t directRecommendedWorkingSetBytes =
        metalDeviceRecommendedWorkingSetBytes(impl_->device);
    if (directRecommendedWorkingSetBytes != 0) {
        inventory.pressure.recommendedWorkingSetBytes =
            directRecommendedWorkingSetBytes;
        inventory.pressure.recommendedWorkingSetAvailable = 1;
    }
    inventory.r5DryRun.dryRunPasses = 1;
    inventory.r5Touches = impl_->r5Touches;
    inventory.r5Eviction = impl_->r5Eviction;
    inventory.r5Ordering.resourceUseSerial = impl_->r5ResourceUseSerial;
    inventory.r5Ordering.boundarySerial = impl_->r5BoundarySerial;
    inventory.r5Ordering.rowLimit = kMetalR5ResidencyRawRowLimit;
    inventory.r5Ordering.candidateLimit = kMetalR5ResidencyCandidateLimit;
    const bool r8Enabled = r8HeapSegmentationEnabled();
    if (r8Enabled) {
        inventory.r8HeapSegmentation.enabled = 1;
        inventory.r8HeapSegmentation.dryRunPasses = 1;
        inventory.r8HeapBuckets.reserve(
            static_cast<std::size_t>(kMetalR8HeapBucketLimit));
    }
    auto finalizePressureInputs = [&]() {
        inventory.pressure.currentAllocatedBytes = inventory.deviceAllocatedBytes;
        inventory.pressure.trackedHostHeapBytes = inventory.residency.hostBytes;
        inventory.pressure.trackedHostCacheBytes =
            inventory.hostCaches.totalBytes;
        const auto processMemory = sampleProcessMemorySnapshot();
        inventory.pressure.processResidentBytes =
            processMemory.residentBytes;
        inventory.pressure.processResidentAvailable =
            processMemory.residentAvailable;
        inventory.pressure.processPhysicalFootprintBytes =
            processMemory.physicalFootprintBytes;
        inventory.pressure.processPhysicalFootprintAvailable =
            processMemory.physicalFootprintAvailable;
        inventory.pressure.processHeapBytes = processMemory.heapBytes;
        inventory.pressure.processHeapAvailable =
            processMemory.heapAvailable;
        inventory.pressure.processHeapBlocksInUse =
            processMemory.heapBlocksInUse;
        inventory.pressure.processHeapMaxBytesInUse =
            processMemory.heapMaxBytesInUse;
        inventory.pressure.processHeapAllocatedBytes =
            processMemory.heapAllocatedBytes;
        auto saturatedSubtract = [](std::uint64_t lhs,
                                    std::uint64_t rhs) {
            return lhs > rhs ? lhs - rhs : 0;
        };
        inventory.pressure.processHeapMinusTrackedHostCacheBytes =
            saturatedSubtract(processMemory.heapBytes,
                              inventory.hostCaches.totalBytes);
        inventory.pressure.processHeapAllocatedMinusTrackedHostCacheBytes =
            saturatedSubtract(processMemory.heapAllocatedBytes,
                              inventory.hostCaches.totalBytes);
        inventory.pressure.processHeapAllZonesBytes =
            processMemory.heapAllZonesBytes;
        inventory.pressure.processHeapAllZonesBlocksInUse =
            processMemory.heapAllZonesBlocksInUse;
        inventory.pressure.processHeapAllZonesMaxBytesInUse =
            processMemory.heapAllZonesMaxBytesInUse;
        inventory.pressure.processHeapAllZonesAllocatedBytes =
            processMemory.heapAllZonesAllocatedBytes;
        inventory.pressure.processHeapAllZonesCount =
            processMemory.heapAllZonesCount;
        inventory.pressure.processHeapNonDefaultZoneBytes =
            processMemory.heapNonDefaultZoneBytes;
        inventory.pressure.processHeapNonDefaultZoneBlocksInUse =
            processMemory.heapNonDefaultZoneBlocksInUse;
        inventory.pressure.processHeapNonDefaultZoneAllocatedBytes =
            processMemory.heapNonDefaultZoneAllocatedBytes;
        const auto machPorts = sampleProcessMachPortSnapshot();
        inventory.pressure.processMachPortsEnabled = machPorts.enabled;
        inventory.pressure.processMachPortsAvailable = machPorts.available;
        inventory.pressure.processMachPortSampleKernReturn =
            machPorts.kernReturn;
        inventory.pressure.processMachPortNames = machPorts.names;
        inventory.pressure.processMachPortTypeNames = machPorts.typeNames;
        inventory.pressure.processMachPortTypeCountMismatch =
            machPorts.typeCountMismatch;
        inventory.pressure.processMachPortSendNames = machPorts.sendNames;
        inventory.pressure.processMachPortReceiveNames =
            machPorts.receiveNames;
        inventory.pressure.processMachPortSendOnceNames =
            machPorts.sendOnceNames;
        inventory.pressure.processMachPortPortSetNames =
            machPorts.portSetNames;
        inventory.pressure.processMachPortDeadNameNames =
            machPorts.deadNameNames;
        inventory.pressure.processMachPortDnRequestNames =
            machPorts.dnRequestNames;
        inventory.pressure.processMachPortSpRequestNames =
            machPorts.spRequestNames;
        inventory.pressure.processMachPortSpRequestDelayedNames =
            machPorts.spRequestDelayedNames;
        inventory.pressure.processMachPortGuardedNames =
            machPorts.guardedNames;
        inventory.pressure.processMachPortImmovableReceiveNames =
            machPorts.immovableReceiveNames;
        inventory.pressure.processMachPortUnknownTypeNames =
            machPorts.unknownTypeNames;
        inventory.pressure.processMachPortUnknownTypeMask =
            machPorts.unknownTypeMask;
        inventory.mallocZoneLimit = processMemory.mallocZoneLimit;
        inventory.mallocZoneRows = processMemory.mallocZoneRows;
        inventory.mallocZonesTruncated = processMemory.mallocZonesTruncated;
        inventory.topMallocZones = processMemory.topMallocZones;
        const auto counters = commandSubmissionDebugCounters();
        inventory.commandBuffers = counters;
        inventory.pressure.cbPressureReserveSlots = counters.pressureReserve;
        inventory.pressure.cbPressureSoftCapSlots = counters.pressureSoftCap;
        inventory.pressure.cbPressureFlushCount = counters.pressureFlushCount;
        inventory.pressure.cbCurrentInFlight = counters.currentInFlight;
        inventory.pressure.cbInFlightBound = counters.inFlightBound;
        if (impl_->frameGraph) {
            const auto pacing = impl_->frameGraph->framePacingSnapshot();
            inventory.pacingFrames = pacing.frames;
            inventory.pacingFrameTimeUsTotal = pacing.frameTimeUsTotal;
            inventory.pacingFrameTimeUsSquaredTotal =
                pacing.frameTimeUsSquaredTotal;
            inventory.pacingFrameTimeUsMax = pacing.frameTimeUsMax;
            inventory.pacingInterPresentGapUsStdDev =
                pacing.interPresentGapUsStdDev;
            inventory.pacingInterPresentGapUsCoV =
                pacing.interPresentGapUsCoV;
            inventory.pacingHitch25 = pacing.hitch25Count;
            inventory.pacingHitch50 = pacing.hitch50Count;
            inventory.pacingHitch100 = pacing.hitch100Count;
            inventory.pacingDrawableWaitUs = pacing.drawableWaitUsTotal;
            inventory.pacingDrawableWaitCount = pacing.drawableWaitCount;
            inventory.parallelTranslatedDraws = pacing.parallelTranslatedDraws;
            inventory.parallelCandidateDraws = pacing.parallelCandidateDraws;
            inventory.parallelEncodedDraws = pacing.parallelEncodedDraws;
            inventory.parallelDescriptorEncodedDraws =
                pacing.descriptorEncodedDraws;
            inventory.parallelFboBoundaryDraws = pacing.fboBoundaryDraws;
            inventory.parallelBatchCount = pacing.parallelBatchCount;
            inventory.parallelMaxBatchSize = pacing.maxBatchSize;
            inventory.copyHeadroomEnabled = pacing.copyHeadroomEnabled;
            inventory.copyHeadroomFb0Draws = pacing.chFb0Draws;
            inventory.copyHeadroomFb0FillSuccesses = pacing.chFb0FillSuccesses;
            inventory.copyHeadroomFb0FillUsTotal = pacing.chFb0FillUsTotal;
            inventory.copyHeadroomFb0Retains = pacing.chFb0Retains;
            inventory.copyHeadroomFboDraws = pacing.chFboDraws;
            inventory.copyHeadroomFboUniformBytes = pacing.chFboUniformBytes;
            inventory.copyHeadroomArenaDrains = pacing.chArenaDrains;
            inventory.copyHeadroomArenaLive = pacing.chArenaLive;
            inventory.w2PlanMemoHits = pacing.w2PlanMemoHits;
            inventory.w2PlanMemoMisses = pacing.w2PlanMemoMisses;
            inventory.w2PlanMemoBuildFails = pacing.w2PlanMemoBuildFails;
            inventory.w2PlanMemoEvictions = pacing.w2PlanMemoEvictions;
            inventory.w2PlanMemoSize = pacing.w2PlanMemoSize;
            inventory.w2PlanMemoPeak = pacing.w2PlanMemoPeak;
            inventory.w2PlanVerifyMismatches = pacing.w2PlanVerifyMismatches;
            inventory.defaultUniformGenerationBindCacheLookups =
                pacing.defaultUniformGenerationBindCacheLookups;
            inventory.defaultUniformGenerationBindCacheHits =
                pacing.defaultUniformGenerationBindCacheHits;
            inventory.defaultUniformGenerationBindCacheActiveHits =
                pacing.defaultUniformGenerationBindCacheActiveHits;
            inventory.defaultUniformGenerationBindCacheRebinds =
                pacing.defaultUniformGenerationBindCacheRebinds;
            inventory.defaultUniformGenerationBindCacheMisses =
                pacing.defaultUniformGenerationBindCacheMisses;
            inventory.defaultUniformGenerationBindCacheStores =
                pacing.defaultUniformGenerationBindCacheStores;
            inventory.defaultUniformGenerationBindCacheEvictions =
                pacing.defaultUniformGenerationBindCacheEvictions;
            inventory.defaultUniformGenerationBindCacheLiveEntries =
                pacing.defaultUniformGenerationBindCacheLiveEntries;
            inventory.defaultUniformGenerationBindCachePeakEntries =
                pacing.defaultUniformGenerationBindCachePeakEntries;
            inventory.defaultUniformGenerationBindCacheCapacity =
                pacing.defaultUniformGenerationBindCacheCapacity;
            inventory.defaultUniformGenerationBindCacheActiveInvalidations =
                pacing.defaultUniformGenerationBindCacheActiveInvalidations;
            inventory.defaultUniformGenerationBindCacheResetInvalidations =
                pacing.defaultUniformGenerationBindCacheResetInvalidations;
            inventory.defaultUniformGenerationBindCacheResetInvalidatedEntries =
                pacing.defaultUniformGenerationBindCacheResetInvalidatedEntries;
            inventory.defaultUniformGenerationBindCacheObsDraws =
                pacing.defaultUniformGenerationBindCacheObsDraws;
            inventory.defaultUniformGenerationBindCacheObsBindSkipHits =
                pacing.defaultUniformGenerationBindCacheObsBindSkipHits;
            inventory.defaultUniformGenerationBindCacheObsGenerationHits =
                pacing.defaultUniformGenerationBindCacheObsGenerationHits;
            inventory.defaultUniformGenerationBindCacheObsHashFreeRebindHits =
                pacing.defaultUniformGenerationBindCacheObsHashFreeRebindHits;
            inventory.defaultUniformGenerationBindCacheObsMisses =
                pacing.defaultUniformGenerationBindCacheObsMisses;
            inventory.defaultUniformGenerationBindCacheObsHashesSkippedOnMiss =
                pacing.defaultUniformGenerationBindCacheObsHashesSkippedOnMiss;
            inventory.defaultUniformGenerationBindCacheObsHashesRun =
                pacing.defaultUniformGenerationBindCacheObsHashesRun;
        }
    };
    auto finalizeR8HeapSegmentation = [&]() {
        if (!r8Enabled) {
            return;
        }
        auto& r8 = inventory.r8HeapSegmentation;
        r8.rowsTruncated = inventory.r5Ordering.rowsTruncated;
        r8.reconstructionSuccesses =
            inventory.r5Eviction.textureViewRebuildsAfterR5Evict +
            inventory.r5Eviction.swizzledViewRebuildsAfterR5Evict +
            inventory.r5Eviction.expandedIndexRebuildsAfterR5Evict +
            inventory.r5Eviction.primaryReconstructions;
        r8.reconstructionFailures =
            inventory.r5Eviction.reconstructionFailures;
        r8.deviceAllocatedBytesBefore = inventory.deviceAllocatedBytes;
        r8.deviceAllocatedBytesAfter = inventory.deviceAllocatedBytes;
        r8.deviceAllocatedBytesDelta = 0;
        r8.deviceBytesFreed = 0;
        r8.osPressure = inventory.pressure.osPressure;
        r8.memoryClass = inventory.pressure.memoryClass;
        r8.pendingPressurePeak = inventory.pressure.pendingPressurePeak;
        r8.warningEventCount = inventory.pressure.warningEventCount;
        r8.criticalEventCount = inventory.pressure.criticalEventCount;
        r8.criticalPressureExhaustionLatches =
            inventory.r5Eviction.criticalPressureExhaustionLatches;
        r8.criticalPressureOOMErrors =
            inventory.r5Eviction.criticalPressureOOMErrors;
        r8.criticalPressureNoCandidateLatches =
            inventory.r5Eviction.criticalPressureNoCandidateLatches;
        r8.criticalPressureNoReliefLatches =
            inventory.r5Eviction.criticalPressureNoReliefLatches;
        r8.criticalPressureBudgetExhaustedLatches =
            inventory.r5Eviction.criticalPressureBudgetExhaustedLatches;
        r8.criticalPressureStillCriticalLatches =
            inventory.r5Eviction.criticalPressureStillCriticalLatches;
        finalizeR8HeapSegmentationSummary(r8, inventory.r8HeapBuckets);
    };
    std::uint64_t frameGraphResidencyBufferBytes = 0;
    std::uint64_t frameGraphResidencyTextureBytes = 0;
    std::uint64_t frameGraphResidencyDrawableTextureBytes = 0;
    if (impl_->frameGraph) {
        inventory.libraryCacheEntries = impl_->frameGraph->mslLibraryCacheEntries();
        const auto frameGraphMetal = impl_->frameGraph->internalMetalResourceInventory();
        frameGraphResidencyBufferBytes = frameGraphMetal.bufferBytes;
        frameGraphResidencyTextureBytes = frameGraphMetal.textureBytes;
        frameGraphResidencyDrawableTextureBytes =
            frameGraphMetal.drawableTextureBytes;
        inventory.frameGraphBufferCount = frameGraphMetal.bufferCount;
        inventory.frameGraphBufferBytes = frameGraphMetal.bufferBytes;
        inventory.frameGraphTextureCount = frameGraphMetal.textureCount;
        inventory.frameGraphTextureBytes = frameGraphMetal.textureBytes;
        inventory.frameGraphDrawableCount = frameGraphMetal.drawableCount;
        inventory.frameGraphDrawableTextureBytes = frameGraphMetal.drawableTextureBytes;
        inventory.frameGraphDrawableAcquireCalls =
            frameGraphMetal.drawableAcquireCalls;
        inventory.frameGraphDrawableAcquireHits =
            frameGraphMetal.drawableAcquireHits;
        inventory.frameGraphDrawableAcquireSuccesses =
            frameGraphMetal.drawableAcquireSuccesses;
        inventory.frameGraphDrawableAcquireFailures =
            frameGraphMetal.drawableAcquireFailures;
        inventory.frameGraphDrawablePresentCalls =
            frameGraphMetal.drawablePresentCalls;
        inventory.frameGraphPresentCalls =
            frameGraphMetal.presentCalls;
        inventory.shadowClearsDeferred = impl_->shadowClearsDeferred;
        inventory.shadowClearsCoalesced = impl_->shadowClearsCoalesced;
        inventory.shadowClearsMaterialized = impl_->shadowClearsMaterialized;
        inventory.shadowClearMaterializeBytes = impl_->shadowClearMaterializeBytes;
        inventory.prepMemoHits = impl_->prepMemoHits;
        inventory.prepMemoPlanKeyReuses = impl_->prepMemoPlanKeyReuses;
        for (int d = 0; d < 6; ++d) {
            inventory.prepMemoBustsByDomain[d] = impl_->prepMemoBustsByDomain[d];
        }
        if (impl_->state) {
            for (unsigned d = 0; d < appgl::GLStateTracker::kDomainCount; ++d) {
                inventory.stateDomainGenerations[d] = impl_->state->domainGeneration(d);
            }
        }
        if (impl_->frameGraph != nullptr) {
            inventory.orderedTextureUploads =
                impl_->frameGraph->orderedTextureUploadCount();
        }
        inventory.samplerResolveCacheHits = impl_->samplerResolveCacheHits;
        inventory.samplerResolveCacheMisses = impl_->samplerResolveCacheMisses;
        inventory.samplerResolveCacheBusts = impl_->samplerResolveCacheBusts;
