    inventory.hostCaches.textureMipShadowEviction.liveEvictedImages = 0;
    inventory.hostCaches.textureMipShadowEviction.liveEvictedRgba8Bytes = 0;
    inventory.hostCaches.textureMipShadowEviction.liveEvictedNativeBytes = 0;
    inventory.hostCaches.textureMipShadowEviction.liveEvictedBytes = 0;

    std::unordered_set<void*> bufferResources;
    std::unordered_set<void*> textureResources;
    std::unordered_set<void*> genericTextureResources;
    std::unordered_set<void*> renderbufferTextureResources;
    std::unordered_set<void*> textureViewResources;
    std::unordered_set<void*> samplerObjects;
    std::unordered_set<void*> renderPipelines;
    std::unordered_set<void*> computePipelines;
    std::unordered_set<void*> functions;

    auto allocatedSize = [](void* raw) -> std::uint64_t {
        if (raw == nullptr) {
            return 0;
        }
        id<MTLResource> resource = (__bridge id<MTLResource>)raw;
        if (resource != nil && [resource respondsToSelector:@selector(allocatedSize)]) {
            return static_cast<std::uint64_t>(resource.allocatedSize);
        }
        return 0;
    };
    auto imageBytes = [](const GLTextureImageLevel& image) -> std::uint64_t {
        return static_cast<std::uint64_t>(image.rgba8.size())
            + static_cast<std::uint64_t>(image.nativeData.size());
    };
    auto imageCapacityBytes =
        [](const GLTextureImageLevel& image) -> std::uint64_t {
        return static_cast<std::uint64_t>(image.rgba8.capacity())
            + static_cast<std::uint64_t>(image.nativeData.capacity());
    };
    inventory.textureShadowHotspotLimit = 32;
    inventory.renderPsoProgramHotspotLimit = 16;
    auto textureHotspotLowerPriority =
        [](const MetalResourceInventory::TextureShadowHotspot& lhs,
           const MetalResourceInventory::TextureShadowHotspot& rhs) {
            if (lhs.shadowBytes != rhs.shadowBytes) {
                return lhs.shadowBytes < rhs.shadowBytes;
            }
            if (lhs.metalBytes != rhs.metalBytes) {
                return lhs.metalBytes < rhs.metalBytes;
            }
            return lhs.name > rhs.name;
        };

    auto renderPsoLastUseRange =
        [](const auto& cache,
           const auto& lastUse,
           std::uint64_t& outMin,
           std::uint64_t& outMax) {
        outMin = 0;
        outMax = 0;
        bool seen = false;
        for (const auto& entry : cache) {
            auto useIt = lastUse.find(entry.first);
            if (useIt == lastUse.end() || useIt->second == 0) {
                continue;
            }
            if (!seen) {
                outMin = useIt->second;
                outMax = useIt->second;
                seen = true;
            } else {
                outMin = std::min(outMin, useIt->second);
                outMax = std::max(outMax, useIt->second);
            }
        }
    };

    auto retainRenderPsoHotspot =
        [&](MetalResourceInventory::RenderPsoProgramHotspot hotspot) {
        const std::uint64_t regularSignal =
            hotspot.renderPsoLive + hotspot.renderPsoHighWater +
            hotspot.renderPsoHits + hotspot.renderPsoMisses +
            hotspot.renderPsoEvictions;
        const std::uint64_t gsSignal =
            hotspot.gsPassThroughPsoLive +
            hotspot.gsPassThroughPsoHighWater +
            hotspot.gsPassThroughPsoHits +
            hotspot.gsPassThroughPsoMisses +
            hotspot.gsPassThroughPsoEvictions;
        if (regularSignal == 0 && gsSignal == 0) {
            return;
        }
        ++inventory.renderPsoProgramHotspotRows;
        inventory.topRenderPsoPrograms.push_back(std::move(hotspot));
    };
    auto retainTextureShadowHotspot =
        [&](const MetalResourceInventory::TextureShadowHotspot& hotspot) {
            if (hotspot.shadowBytes == 0) {
                return;
            }
            ++inventory.textureShadowHotspotRows;
            const auto limit =
                static_cast<std::size_t>(inventory.textureShadowHotspotLimit);
            if (limit == 0) {
                return;
            }
            auto& top = inventory.topTextureShadows;
            if (top.size() < limit) {
                top.push_back(hotspot);
                return;
            }
            auto lowest = std::min_element(top.begin(), top.end(),
                                           textureHotspotLowerPriority);
            if (lowest != top.end() &&
                textureHotspotLowerPriority(*lowest, hotspot)) {
                *lowest = hotspot;
            }
        };

    std::uint64_t nextResidencyRecordId = 1;
    auto depthStencilPixelFormat = [](NSUInteger pixelFormat) {
        return pixelFormat == MTLPixelFormatDepth16Unorm ||
               pixelFormat == MTLPixelFormatDepth32Float ||
               pixelFormat == MTLPixelFormatDepth32Float_Stencil8 ||
               pixelFormat == MTLPixelFormatDepth24Unorm_Stencil8 ||
               pixelFormat == MTLPixelFormatStencil8;
    };
    auto populateR8CommonResourceMetadata =
        [&](ResourceResidencyRecord& record, id<MTLResource> resource) {
            if (resource == nil) {
                return;
            }
            record.r8StorageMode =
                static_cast<std::uint32_t>(resource.storageMode);
            record.r8CpuCacheMode =
                static_cast<std::uint32_t>(resource.cpuCacheMode);
            record.r8HazardTrackingMode =
                static_cast<std::uint32_t>(resource.hazardTrackingMode);
            record.r8ResourceOptions =
                static_cast<std::uint64_t>(resource.resourceOptions);
            record.r8CompatibilityKnown = 1;
        };
    auto populateR8BufferMetadata =
        [&](ResourceResidencyRecord& record, void* raw) {
            if (!r8Enabled || raw == nullptr || record.metalBytes == 0) {
                return;
            }
            id<MTLBuffer> buffer = (__bridge id<MTLBuffer>)raw;
            populateR8CommonResourceMetadata(record,
                                             (id<MTLResource>)buffer);
            record.r8ResourceClass = MetalR8ResourceClass::Buffer;
            if (record.kind == MetalResidencyKind::Fp64SidecarMetal) {
                record.r8TextureClass = MetalR8TextureClass::Fp64Sidecar;
            } else if (record.kind ==
                       MetalResidencyKind::TextureBufferExpansion) {
                record.r8TextureClass =
                    MetalR8TextureClass::TextureBufferExpansion;
            } else if (record.heapClass == MetalResidencyHeapClass::Sidecar) {
                record.r8TextureClass = MetalR8TextureClass::Sidecar;
            }
        };
    auto populateR8TextureMetadata =
        [&](ResourceResidencyRecord& record, void* raw) {
            if (!r8Enabled || raw == nullptr || record.metalBytes == 0) {
                return;
            }
            id<MTLTexture> texture = (__bridge id<MTLTexture>)raw;
            populateR8CommonResourceMetadata(record,
                                             (id<MTLResource>)texture);
            record.r8ResourceClass = MetalR8ResourceClass::Texture;
            record.r8TextureUsage =
                static_cast<std::uint64_t>(texture.usage);
            record.r8TextureType =
                static_cast<std::uint32_t>(texture.textureType);
            record.r8PixelFormat =
                static_cast<std::uint32_t>(texture.pixelFormat);
            record.r8SampleCount =
                static_cast<std::uint32_t>(texture.sampleCount);
            record.r8MipmapLevels =
                static_cast<std::uint32_t>(texture.mipmapLevelCount);
            record.r8ArrayLength =
                static_cast<std::uint32_t>(texture.arrayLength);
            if (record.r8SampleCount > 1) {
                record.r8TextureClass = MetalR8TextureClass::Multisample;
            } else if (depthStencilPixelFormat(texture.pixelFormat)) {
                record.r8TextureClass = MetalR8TextureClass::DepthStencil;
            } else if (record.heapClass == MetalResidencyHeapClass::Sidecar) {
                record.r8TextureClass = MetalR8TextureClass::Sidecar;
            } else {
                record.r8TextureClass = MetalR8TextureClass::Color;
            }
        };
    auto retainR5OrderingCandidate = [&](const ResourceResidencyRecord& record) {
        if (metalR5EvictionScopeForRecord(record) == MetalR5EvictionScope::None) {
            return;
        }
        auto& candidates = inventory.r5OrderingCandidates;
        const auto limit =
            static_cast<std::size_t>(inventory.r5Ordering.candidateLimit);
        if (limit == 0) {
            return;
        }
        if (candidates.size() < limit) {
            candidates.push_back(record);
            return;
        }
        auto worst = std::max_element(
            candidates.begin(), candidates.end(),
            [](const ResourceResidencyRecord& lhs,
               const ResourceResidencyRecord& rhs) {
                return metalR5OrderingRecordLess(lhs, rhs);
            });
        if (worst != candidates.end() &&
            metalR5OrderingRecordLess(record, *worst)) {
            *worst = record;
        }
    };
    auto recordResidency =
        [&](MetalResidencyOwner owner,
            GLuint glName,
            MetalResidencyKind kind,
            MetalResidencyAuthorityClass authority,
            MetalResidencyHeapClass heapClass,
            std::uint64_t metalBytes,
            std::uint64_t hostBytes,
            std::uint64_t recipeId = 0,
            std::uint64_t sourceGeneration = 0,
            std::uint64_t lastUseFrame = 0,
            std::uint64_t lastUseCommandSerial = 0,
            std::uint64_t inFlightSerial = 0,
            std::uint32_t diagnosticBucketId = 0,
            void* r8Resource = nullptr,
            MetalR8ResourceClass r8ResourceClass =
                MetalR8ResourceClass::None) {
            const std::uint64_t retainedBytes = metalBytes + hostBytes;
            if (retainedBytes == 0) {
                return;
            }

            ResourceResidencyRecord record;
            record.recordId = nextResidencyRecordId++;
            record.owner = owner;
            record.glName = glName;
            record.kind = kind;
            record.retainedBytes = retainedBytes;
            record.metalBytes = metalBytes;
            record.hostBytes = hostBytes;
            record.authority = authority;
            record.recipeId = recipeId;
            record.sourceGeneration = sourceGeneration;
            record.lastUseFrame = lastUseFrame;
            record.lastUseCommandSerial = lastUseCommandSerial;
            record.inFlightSerial = inFlightSerial;
            record.heapClass = heapClass;
            record.purgeableEligible =
                (authority == MetalResidencyAuthorityClass::Reconstructable &&
                 metalBytes != 0 &&
                 metalR5FuturePurgeableEligibleKind(kind))
                    ? 1
                    : 0;
            record.diagnosticBucketId = diagnosticBucketId;
            if (r8ResourceClass == MetalR8ResourceClass::Buffer) {
                populateR8BufferMetadata(record, r8Resource);
            } else if (r8ResourceClass == MetalR8ResourceClass::Texture) {
                populateR8TextureMetadata(record, r8Resource);
            }
            if (!metalR5AppendBoundedResidencyRow(
                    inventory.residencyRows, record,
                    inventory.r5Ordering.rowLimit)) {
                ++inventory.r5Ordering.rowsTruncated;
            }
            accumulateR5ResidencyOrderingRecord(inventory.r5Ordering, record);
            retainR5OrderingCandidate(record);
            accumulateResidencyRecord(inventory.residency, record);
            accumulateR5ResidencyDryRunRecord(inventory.r5DryRun, record);
            if (r8Enabled) {
                accumulateR8HeapSegmentationRecord(
                    inventory.r8HeapSegmentation,
                    inventory.r8HeapBuckets,
                    record,
                    impl_->r5BoundarySerial,
                    kMetalR8HeapBucketLimit);
            }
        };
    auto addHostCacheBytes = [&](std::uint64_t bytes) {
        inventory.hostCaches.totalBytes += bytes;
    };
    auto addBuffer =
        [&](void* raw,
            MetalResidencyOwner owner = MetalResidencyOwner::Buffer,
            GLuint glName = 0,
            MetalResidencyKind kind = MetalResidencyKind::MetalBuffer,
            MetalResidencyAuthorityClass authority =
                MetalResidencyAuthorityClass::Authoritative,
            MetalResidencyHeapClass heapClass =
                MetalResidencyHeapClass::MetalDevice,
            std::uint64_t recipeId = 0,
            std::uint64_t sourceGeneration = 0) {
        if (raw == nullptr || !bufferResources.insert(raw).second) {
            return;
        }
        const std::uint64_t bytes = allocatedSize(raw);
        ++inventory.bufferCount;
        inventory.bufferBytes += bytes;
        recordResidency(owner, glName, kind, authority, heapClass, bytes, 0,
                        recipeId, sourceGeneration, 0, 0, 0, 0, raw,
                        MetalR8ResourceClass::Buffer);
    };
    auto addTexture =
        [&](void* raw,
            MetalResidencyOwner owner = MetalResidencyOwner::Texture,
            GLuint glName = 0,
            MetalResidencyKind kind = MetalResidencyKind::MetalTexture,
            MetalResidencyAuthorityClass authority =
                MetalResidencyAuthorityClass::Authoritative,
            MetalResidencyHeapClass heapClass =
                MetalResidencyHeapClass::MetalDevice,
            std::uint64_t lastUseFrame = 0,
            std::uint64_t lastUseCommandSerial = 0,
            std::uint32_t diagnosticBucketId = 0) {
        if (raw == nullptr || !textureResources.insert(raw).second) {
            return;
        }
        const std::uint64_t bytes = allocatedSize(raw);
        ++inventory.textureCount;
        inventory.textureBytes += bytes;
        recordResidency(owner, glName, kind, authority, heapClass, bytes, 0,
                        0, 0, lastUseFrame, lastUseCommandSerial, 0,
                        diagnosticBucketId, raw, MetalR8ResourceClass::Texture);
    };
    auto addGenericTexture =
        [&](void* raw,
            GLuint glName,
            MetalResidencyAuthorityClass authority,
            std::uint64_t lastUseFrame,
            std::uint64_t lastUseCommandSerial) {
        if (raw != nullptr && genericTextureResources.insert(raw).second) {
            ++inventory.genericTextureCount;
            inventory.genericTextureBytes += allocatedSize(raw);
        }
        addTexture(raw, MetalResidencyOwner::Texture, glName,
                   MetalResidencyKind::MetalTexture,
                   authority,
                   MetalResidencyHeapClass::MetalDevice,
                   lastUseFrame,
                   lastUseCommandSerial,
                   kMetalR5DiagnosticBucketPrimaryTexture);
    };
    auto addRenderbufferTexture = [&](void* raw, GLuint glName) {
        if (raw != nullptr && renderbufferTextureResources.insert(raw).second) {
            ++inventory.renderbufferTextureCount;
            inventory.renderbufferTextureBytes += allocatedSize(raw);
        }
        addTexture(raw, MetalResidencyOwner::Renderbuffer, glName,
                   MetalResidencyKind::MetalTexture,
                   MetalResidencyAuthorityClass::Authoritative,
                   MetalResidencyHeapClass::MetalDevice);
    };
    auto addTextureView =
        [&](void* raw,
            GLuint glName,
            std::uint32_t diagnosticBucketId,
            std::uint64_t lastUseSerial,
            std::uint64_t lastUseBoundarySerial) {
        if (raw == nullptr || !textureViewResources.insert(raw).second) {
            return;
        }
        const std::uint64_t bytes = allocatedSize(raw);
        ++inventory.textureViewCount;
        inventory.textureViewBytes += bytes;
        recordResidency(MetalResidencyOwner::Texture, glName,
                        MetalResidencyKind::TextureView,
                        MetalResidencyAuthorityClass::Reconstructable,
                        MetalResidencyHeapClass::MetalDevice, bytes, 0,
                        0, 0, lastUseBoundarySerial, lastUseSerial, 0,
                        diagnosticBucketId);
    };
    auto addSampler = [&](void* raw) {
        if (raw != nullptr && samplerObjects.insert(raw).second) {
            ++inventory.samplerCount;
        }
    };
    auto addRenderPipeline = [&](void* raw) {
        if (raw != nullptr && renderPipelines.insert(raw).second) {
            ++inventory.renderPipelineCount;
        }
    };
    auto addComputePipeline = [&](void* raw) {
        if (raw != nullptr && computePipelines.insert(raw).second) {
            ++inventory.computePipelineCount;
        }
    };
    auto addFunction = [&](void* raw) {
        if (raw != nullptr && functions.insert(raw).second) {
            ++inventory.functionCount;
        }
    };
    recordResidency(MetalResidencyOwner::FrameGraph, 0,
                    MetalResidencyKind::FrameGraphResource,
                    MetalResidencyAuthorityClass::Transient,
                    MetalResidencyHeapClass::FrameGraph,
                    frameGraphResidencyBufferBytes, 0);
    recordResidency(MetalResidencyOwner::FrameGraph, 0,
                    MetalResidencyKind::FrameGraphResource,
                    MetalResidencyAuthorityClass::Transient,
                    MetalResidencyHeapClass::FrameGraph,
                    frameGraphResidencyTextureBytes, 0);
    recordResidency(MetalResidencyOwner::FrameGraph, 0,
                    MetalResidencyKind::FrameGraphResource,
                    MetalResidencyAuthorityClass::Transient,
                    MetalResidencyHeapClass::FrameGraph,
                    frameGraphResidencyDrawableTextureBytes, 0);

    inventory.hostCaches.mslLibraryCacheSourceBytes =
        inventory.mslLibraryCacheSourceBytes;
    inventory.hostCaches.mslLibraryCacheSourceKeyBytes =
        inventory.mslLibraryCacheSourceKeyBytes;
    inventory.hostCaches.mslLibraryCompileTransientSourceBytes =
        inventory.mslLibraryCompileTransientSourceBytes;
    addHostCacheBytes(inventory.mslLibraryCacheSourceBytes);
    addHostCacheBytes(inventory.mslLibraryCacheSourceKeyBytes);
    addHostCacheBytes(inventory.mslLibraryCompileTransientSourceBytes);
    recordResidency(MetalResidencyOwner::FrameGraph, 0,
                    MetalResidencyKind::MslLibraryCacheSource,
                    MetalResidencyAuthorityClass::Reconstructable,
                    MetalResidencyHeapClass::Cache, 0,
                    inventory.mslLibraryCacheSourceBytes);
    recordResidency(MetalResidencyOwner::FrameGraph, 0,
                    MetalResidencyKind::MslLibraryCacheSourceKey,
                    MetalResidencyAuthorityClass::Reconstructable,
                    MetalResidencyHeapClass::Cache, 0,
                    inventory.mslLibraryCacheSourceKeyBytes);
    recordResidency(MetalResidencyOwner::FrameGraph, 0,
                    MetalResidencyKind::MslLibraryCompileTransientSource,
                    MetalResidencyAuthorityClass::Transient,
                    MetalResidencyHeapClass::Cache, 0,
                    inventory.mslLibraryCompileTransientSourceBytes);

    auto addProgramMslBytes = [&](GLuint programName,
                                  const GLProgramObject& program) {
        std::uint64_t bytes = 0;
        auto addString = [&](const std::string& value) {
            bytes += static_cast<std::uint64_t>(value.size());
        };
        addString(program.vertexMSL);
        addString(program.fragmentMSL);
        addString(program.tessControlMSL);
        addString(program.tessEvalMSL);
        addString(program.tessVertexAsComputeMSL);
        addString(program.tessEvalAsComputeMSL);
        addString(program.gsPassThroughVertexMSL);
        addString(program.gsPassThroughFragmentMSL);
        addString(program.computeMSL);
        addString(program.vsTfAsComputeMSL);
        addString(program.geometryShaderAsMeshMSL);
        addString(program.metalGSVsComputeMSL);
        if (bytes == 0) {
            return;
        }
        inventory.hostCaches.programMslSourceBytes += bytes;
        addHostCacheBytes(bytes);
        recordResidency(MetalResidencyOwner::Program, programName,
                        MetalResidencyKind::ProgramMslSource,
                        MetalResidencyAuthorityClass::Reconstructable,
                        MetalResidencyHeapClass::Host, 0, bytes);
    };
    auto addProgram = [&](GLuint programName, const GLProgramObject& program) {
        addProgramMslBytes(programName, program);
        addComputePipeline(program.metalComputePipelineState);
        addComputePipeline(program.metalTessControlPipelineState);
        addComputePipeline(program.metalTessVertexPipelineState);
        for (const auto& entry : program.metalTessVertexPSOCache) {
            addComputePipeline(entry.second);
        }
        inventory.cacheLiveTessVertexComputePso +=
            static_cast<std::uint64_t>(program.metalTessVertexPSOCache.size());
        addComputePipeline(program.metalTessEvalComputePipelineState);
        addComputePipeline(program.metalVsTfComputePipelineState);
        for (const auto& entry : program.metalVsTfComputePSOCache) {
            addComputePipeline(entry.second);
        }
        inventory.cacheLiveVsTfComputePso +=
            static_cast<std::uint64_t>(program.metalVsTfComputePSOCache.size());
        addComputePipeline(program.metalGSVsComputePipelineState);
        for (const auto& entry : program.metalGSVsComputePSOCache) {
            addComputePipeline(entry.second);
        }
        inventory.cacheLiveGsVsComputePso +=
            static_cast<std::uint64_t>(program.metalGSVsComputePSOCache.size());
        addRenderPipeline(program.metalPipelineState);
        for (const auto& entry : program.metalPipelineStateCache) {
            addRenderPipeline(entry.second);
        }
        inventory.cacheLiveRenderPso +=
            static_cast<std::uint64_t>(program.metalPipelineStateCache.size());
        addRenderPipeline(program.gsPassThroughPipelineState);
        for (const auto& entry : program.gsPassThroughPipelineStateCache) {
            addRenderPipeline(entry.second);
        }
        inventory.cacheLiveGsPassThroughPso +=
            static_cast<std::uint64_t>(
                program.gsPassThroughPipelineStateCache.size());
        MetalResourceInventory::RenderPsoProgramHotspot psoHotspot;
        psoHotspot.program = programName;
        psoHotspot.renderPsoLive =
            static_cast<std::uint64_t>(program.metalPipelineStateCache.size());
        psoHotspot.renderPsoHighWater =
            std::max(psoHotspot.renderPsoLive,
                     program.metalPipelineStateCacheHighWater);
        psoHotspot.renderPsoHits = program.metalPipelineStateCacheHits;
        psoHotspot.renderPsoMisses = program.metalPipelineStateCacheMisses;
        psoHotspot.renderPsoEvictions =
            program.metalPipelineStateCacheEvictions;
        psoHotspot.renderPsoGlobalEvictions =
            program.metalPipelineStateCacheGlobalEvictions;
        psoHotspot.renderPsoScalarMirrorPresent =
            program.metalPipelineState != nullptr ? 1u : 0u;
        renderPsoLastUseRange(program.metalPipelineStateCache,
                              program.metalPipelineStateCacheLastUse,
                              psoHotspot.renderPsoLastUseMin,
                              psoHotspot.renderPsoLastUseMax);
        psoHotspot.gsPassThroughPsoLive =
            static_cast<std::uint64_t>(
                program.gsPassThroughPipelineStateCache.size());
        psoHotspot.gsPassThroughPsoHighWater =
            std::max(psoHotspot.gsPassThroughPsoLive,
                     program.gsPassThroughPipelineStateCacheHighWater);
        psoHotspot.gsPassThroughPsoHits =
            program.gsPassThroughPipelineStateCacheHits;
        psoHotspot.gsPassThroughPsoMisses =
            program.gsPassThroughPipelineStateCacheMisses;
        psoHotspot.gsPassThroughPsoEvictions =
            program.gsPassThroughPipelineStateCacheEvictions;
        psoHotspot.gsPassThroughPsoGlobalEvictions =
            program.gsPassThroughPipelineStateCacheGlobalEvictions;
        psoHotspot.gsPassThroughPsoScalarMirrorPresent =
            program.gsPassThroughPipelineState != nullptr ? 1u : 0u;
        renderPsoLastUseRange(program.gsPassThroughPipelineStateCache,
                              program.gsPassThroughPipelineStateCacheLastUse,
                              psoHotspot.gsPassThroughPsoLastUseMin,
                              psoHotspot.gsPassThroughPsoLastUseMax);
        psoHotspot.vertexSourceHash = program.vertexSourceHash;
        psoHotspot.fragmentSourceHash = program.fragmentSourceHash;
        retainRenderPsoHotspot(std::move(psoHotspot));
        addRenderPipeline(program.metalGSMeshPipelineState);
        addFunction(program.metalComputeFunction);
        addFunction(program.metalVertexFunction);
        addFunction(program.metalFragmentFunction);
        addFunction(program.gsPassThroughVertexFunction);
        addFunction(program.gsPassThroughFragmentFunction);
        addFunction(program.metalGSMeshFunction);
        addFunction(program.metalGSFragmentFunction);
    };

    auto* store = impl_->objects.get();
    if (store == nullptr) {
        finalizePressureInputs();
        finalizeR8HeapSegmentation();
        return inventory;
    }
    std::unordered_set<GLuint> primaryTextureViewSources;
    store->textures().forEach([&](GLuint, GLTextureObject& texture) {
        if (texture.viewSourceTexture != 0) {
            primaryTextureViewSources.insert(texture.viewSourceTexture);
        }
    });
    store->buffers().forEach([&](GLuint bufferName, GLBufferObject& buffer) {
        if (buffer.size > 0) {
            ++inventory.bufferStorageObjects;
        }
        if (buffer.metalBuffer != nullptr) {
            ++inventory.bufferMetalObjects;
        }
        if (buffer.size <= 0 && buffer.metalBuffer == nullptr &&
            buffer.shadowBytes.empty() && buffer.cachedExpandedIndices.empty() &&
            !buffer.sparseStorage && buffer.fp64TransportSidecars.empty()) {
            ++inventory.bufferReservedOnlyObjects;
        }
        addBuffer(buffer.metalBuffer, MetalResidencyOwner::Buffer,
                  bufferName, MetalResidencyKind::MetalBuffer,
                  MetalResidencyAuthorityClass::Authoritative,
                  MetalResidencyHeapClass::MetalDevice);
        if (!buffer.shadowBytes.empty()) {
            const auto bytes =
                static_cast<std::uint64_t>(buffer.shadowBytes.size());
            ++inventory.hostCaches.bufferShadowObjects;
            inventory.hostCaches.bufferShadowBytes += bytes;
            addHostCacheBytes(bytes);
            recordResidency(MetalResidencyOwner::Buffer, bufferName,
                            MetalResidencyKind::HostShadow,
                            MetalResidencyAuthorityClass::Authoritative,
                            MetalResidencyHeapClass::Host, 0, bytes,
                            0, buffer.indexExpansionGeneration);
        }
        if (!buffer.cachedExpandedIndices.empty()) {
            const auto bytes = static_cast<std::uint64_t>(
                buffer.cachedExpandedIndices.size());
            ++inventory.expandedIndexBuffers;
            inventory.expandedIndexBytes += bytes;
            ++inventory.hostCaches.expandedIndexBuffers;
            inventory.hostCaches.expandedIndexBytes += bytes;
            addHostCacheBytes(bytes);
            recordResidency(MetalResidencyOwner::Buffer, bufferName,
                            MetalResidencyKind::ExpandedIndexCache,
                            MetalResidencyAuthorityClass::Reconstructable,
                            MetalResidencyHeapClass::Cache, 0, bytes,
                            buffer.indexExpansionGeneration,
                            buffer.cachedExpansionGeneration,
                            buffer.r5ExpandedIndexLastUseBoundarySerial,
                            buffer.r5ExpandedIndexLastUseSerial,
                            0,
                            kMetalR5DiagnosticBucketExpandedIndexCache);
        }
        if (buffer.sparseStorage) {
            const auto pageTableBytes =
                static_cast<std::uint64_t>(buffer.sparseCommittedPages.size());
            ++inventory.sparseBufferObjects;
            inventory.sparseBufferPageTableBytes += pageTableBytes;
            inventory.hostCaches.sparseBufferPageTableBytes += pageTableBytes;
            addHostCacheBytes(pageTableBytes);
            recordResidency(MetalResidencyOwner::Buffer, bufferName,
                            MetalResidencyKind::SparsePageTable,
                            MetalResidencyAuthorityClass::SparseSpecial,
                            MetalResidencyHeapClass::Sparse, 0,
                            pageTableBytes);
            const auto committedPages = static_cast<std::uint64_t>(
                std::count_if(buffer.sparseCommittedPages.begin(),
                              buffer.sparseCommittedPages.end(),
                              [](std::uint8_t committed) {
                                  return committed != 0;
                              }));
            inventory.sparseBufferCommittedPages += committedPages;
            if (buffer.sparsePageSize > 0) {
                inventory.sparseBufferCommittedBytes += committedPages *
                    static_cast<std::uint64_t>(buffer.sparsePageSize);
            }
        }
        if (!buffer.fp64TransportSidecars.empty()) {
            ++inventory.fp64SidecarBuffers;
        }
        for (const auto& sidecar : buffer.fp64TransportSidecars) {
            const auto sidecarCpuBytes =
                static_cast<std::uint64_t>(sidecar.bytes.size());
            ++inventory.fp64Sidecars;
            inventory.fp64SidecarCpuBytes += sidecarCpuBytes;
            ++inventory.hostCaches.fp64Sidecars;
            inventory.hostCaches.fp64SidecarCpuBytes += sidecarCpuBytes;
            addHostCacheBytes(sidecarCpuBytes);
            recordResidency(MetalResidencyOwner::Buffer, bufferName,
                            MetalResidencyKind::Fp64SidecarCpu,
                            MetalResidencyAuthorityClass::Reconstructable,
                            MetalResidencyHeapClass::Sidecar, 0,
                            sidecarCpuBytes,
                            static_cast<std::uint64_t>(sidecar.layoutHash),
                            sidecar.sourceGeneration);
            inventory.fp64SidecarMaxGeneration = std::max<std::uint64_t>(
                inventory.fp64SidecarMaxGeneration,
                sidecar.sourceGeneration);
            if (sidecar.metalBuffer != nullptr) {
                ++inventory.fp64SidecarMetalBuffers;
                inventory.fp64SidecarMetalBufferBytes +=
                    allocatedSize(sidecar.metalBuffer);
            }
            addBuffer(sidecar.metalBuffer, MetalResidencyOwner::Buffer,
                      bufferName, MetalResidencyKind::Fp64SidecarMetal,
                      MetalResidencyAuthorityClass::Reconstructable,
                      MetalResidencyHeapClass::Sidecar,
                      static_cast<std::uint64_t>(sidecar.layoutHash),
                      sidecar.sourceGeneration);
        }
    });
    store->textures().forEach([&](GLuint textureName, GLTextureObject& texture) {
        if (texture.instantiated) {
            ++inventory.textureInstantiatedObjects;
        }
        if (texture.viewSourceTexture != 0) {
            ++inventory.textureViewObjects;
        }
        if (texture.sparseTexture) {
            ++inventory.textureSparseObjects;
        }
        bool primaryMirrorInvalid = false;
        bool primarySawMirror = false;
        MetalResourceInventory::TextureShadowHotspot hotspot;
        hotspot.name = textureName;
        hotspot.target = texture.target != 0 ? texture.target : texture.desc.target;
        hotspot.viewSourceTexture = texture.viewSourceTexture;
        hotspot.metalBytes = allocatedSize(texture.metalTexture);
        hotspot.swizzledViewBytes = allocatedSize(texture.metalSwizzledView);
        hotspot.samplingProxyBytes = allocatedSize(texture.metalSamplingProxy);
        hotspot.producerPendingBits = texture.producerPending.bits();
        hotspot.instantiated = texture.instantiated ? 1 : 0;
        hotspot.hasMetalTexture = texture.metalTexture != nullptr ? 1 : 0;
        hotspot.hasSwizzledView = texture.metalSwizzledView != nullptr ? 1 : 0;
        hotspot.hasSamplingProxy = texture.metalSamplingProxy != nullptr ? 1 : 0;
        hotspot.wasViewportRenderedTo =
            texture.wasViewportRenderedTo ? 1 : 0;
        hotspot.wasFramebufferRenderedTo =
            texture.wasFramebufferRenderedTo ? 1 : 0;
        hotspot.colorShadowAuthoritative =
            texture.colorShadowAuthoritative ? 1 : 0;
        hotspot.depthStencilShadowAuthoritative =
            texture.depthStencilShadowAuthoritative ? 1 : 0;
        hotspot.sparseTexture = texture.sparseTexture ? 1 : 0;
        hotspot.internalFormat = texture.desc.internalFormat;
        hotspot.sourceFormat = texture.desc.sourceFormat;
        hotspot.sourceType = texture.desc.sourceType;
        hotspot.width = texture.desc.width;
        hotspot.height = texture.desc.height;
        hotspot.depth = texture.desc.depth;
        hotspot.layers = texture.desc.layers;
        hotspot.samples = texture.desc.samples;
        std::uint64_t depth32fDropCandidateRgba8Bytes = 0;
        bool hotspotSawLevel = false;
        auto observeHotspotImage =
            [&](GLint level, const GLTextureImageLevel& image,
                bool cubeFaceImage) {
                ++hotspot.imageLevels;
                if (image.defined) {
                    ++hotspot.definedImages;
                }
                if (cubeFaceImage) {
                    ++hotspot.cubeFaceImages;
                }
                if (!hotspotSawLevel) {
                    hotspot.minLevel = level;
                    hotspot.maxLevel = level;
                    hotspotSawLevel = true;
                } else {
                    hotspot.minLevel = std::min(hotspot.minLevel, level);
                    hotspot.maxLevel = std::max(hotspot.maxLevel, level);
                }
                const std::uint64_t rgba8Bytes =
                    static_cast<std::uint64_t>(image.rgba8.size());
                const std::uint64_t nativeBytes =
                    static_cast<std::uint64_t>(image.nativeData.size());
                const std::uint64_t bytes = rgba8Bytes + nativeBytes;
                hotspot.rgba8Bytes += rgba8Bytes;
                hotspot.nativeBytes += nativeBytes;
                hotspot.shadowBytes += bytes;
                if (isDepth32FTextureShadowDropShape(image) &&
                    rgba8Bytes != 0) {
                    depth32fDropCandidateRgba8Bytes += rgba8Bytes;
                }
                if (bytes != 0) {
                    ++hotspot.shadowImages;
                }
                if (bytes > hotspot.largestImageBytes) {
                    hotspot.largestImageBytes = bytes;
                    hotspot.largestLevel = level;
                    hotspot.internalFormat = image.desc.internalFormat != 0
                        ? image.desc.internalFormat
                        : texture.desc.internalFormat;
                    hotspot.sourceFormat = image.desc.sourceFormat;
                    hotspot.sourceType = image.desc.sourceType;
                    hotspot.width = image.desc.width;
                    hotspot.height = image.desc.height;
                    hotspot.depth = image.desc.depth;
                    hotspot.layers = image.desc.layers;
                    hotspot.samples = image.desc.samples;
                }
            };
        auto observePrimaryMirror =
            [&](const GLTextureImageLevel& image) {
                if (!image.defined) {
                    return;
                }
                if (!r5TextureImageLevelHasValidMirror(image)) {
                    primaryMirrorInvalid = true;
                    return;
                }
                primarySawMirror = true;
        };
        for (const auto& [level, image] : texture.levels) {
            observeHotspotImage(level, image, false);
            observePrimaryMirror(image);
            const std::uint64_t rgba8Bytes =
                static_cast<std::uint64_t>(image.rgba8.size());
            const std::uint64_t nativeBytes =
                static_cast<std::uint64_t>(image.nativeData.size());
            const std::uint64_t bytes = imageBytes(image);
            const std::uint64_t capacityBytes = imageCapacityBytes(image);
            if (image.mipShadowEvicted) {
                ++inventory.hostCaches.textureMipShadowEviction
                      .liveEvictedImages;
                inventory.hostCaches.textureMipShadowEviction
                    .liveEvictedRgba8Bytes +=
                    image.mipShadowEvictedRgba8Bytes;
                inventory.hostCaches.textureMipShadowEviction
                    .liveEvictedNativeBytes +=
                    image.mipShadowEvictedNativeBytes;
                inventory.hostCaches.textureMipShadowEviction
                    .liveEvictedBytes +=
                    image.mipShadowEvictedRgba8Bytes +
                    image.mipShadowEvictedNativeBytes;
            }
            ++inventory.genericTextureLevelImages;
            inventory.genericTextureLevelBytes += bytes;
            inventory.hostCaches.textureShadowRgba8Bytes += rgba8Bytes;
            inventory.hostCaches.textureShadowNativeBytes += nativeBytes;
            inventory.hostCaches.textureShadowCapacityBytes += capacityBytes;
            if (level == 0) {
                inventory.hostCaches.textureShadowPrimaryRgba8Bytes +=
                    rgba8Bytes;
                inventory.hostCaches.textureShadowPrimaryNativeBytes +=
                    nativeBytes;
                inventory.hostCaches.textureShadowPrimaryCapacityBytes +=
                    capacityBytes;
            } else {
                inventory.hostCaches.textureShadowMipRgba8Bytes +=
                    rgba8Bytes;
                inventory.hostCaches.textureShadowMipNativeBytes +=
                    nativeBytes;
                inventory.hostCaches.textureShadowMipCapacityBytes +=
                    capacityBytes;
            }
            if (bytes != 0) {
                ++inventory.hostCaches.textureShadowImages;
                inventory.hostCaches.textureShadowBytes += bytes;
                if (level == 0) {
                    ++inventory.hostCaches.textureShadowPrimaryImages;
                    inventory.hostCaches.textureShadowPrimaryBytes += bytes;
                } else {
                    ++inventory.hostCaches.textureShadowMipImages;
                    inventory.hostCaches.textureShadowMipBytes += bytes;
                }
                addHostCacheBytes(bytes);
                recordResidency(MetalResidencyOwner::Texture, textureName,
                                MetalResidencyKind::HostShadow,
                                MetalResidencyAuthorityClass::Authoritative,
                                MetalResidencyHeapClass::Host, 0, bytes);
            }
        }
        for (const auto& faceLevels : texture.cubeFaceLevels) {
            for (const auto& [level, image] : faceLevels) {
                observeHotspotImage(level, image, true);
                observePrimaryMirror(image);
                const std::uint64_t rgba8Bytes =
                    static_cast<std::uint64_t>(image.rgba8.size());
                const std::uint64_t nativeBytes =
                    static_cast<std::uint64_t>(image.nativeData.size());
                const std::uint64_t bytes = imageBytes(image);
                const std::uint64_t capacityBytes =
                    imageCapacityBytes(image);
                ++inventory.cubeFaceLevelImages;
                inventory.cubeFaceLevelBytes += bytes;
                inventory.hostCaches.cubeFaceShadowRgba8Bytes +=
                    rgba8Bytes;
                inventory.hostCaches.cubeFaceShadowNativeBytes +=
                    nativeBytes;
                inventory.hostCaches.cubeFaceShadowCapacityBytes +=
                    capacityBytes;
                if (bytes != 0) {
                    ++inventory.hostCaches.cubeFaceShadowImages;
                    inventory.hostCaches.cubeFaceShadowBytes += bytes;
                    addHostCacheBytes(bytes);
                    recordResidency(MetalResidencyOwner::Texture, textureName,
                                    MetalResidencyKind::HostShadow,
                                    MetalResidencyAuthorityClass::Authoritative,
                                    MetalResidencyHeapClass::Host, 0, bytes);
                }
            }
        }
        if (hotspot.definedImages != 0) {
            ++inventory.textureDefinedObjects;
        }
        if (!texture.instantiated && texture.viewSourceTexture == 0 &&
            texture.metalTexture == nullptr && texture.metalSwizzledView == nullptr &&
            texture.metalSamplingProxy == nullptr && texture.metalSampler == nullptr &&
            texture.textureBufferExpandedMetalBuffer == nullptr &&
            texture.imageAtomicBuffer == nullptr && hotspot.definedImages == 0 &&
            hotspot.shadowBytes == 0 && !texture.sparseTexture) {
            ++inventory.textureReservedOnlyObjects;
        }
        const auto baseIt = texture.levels.find(0);
        const bool depth32fBaseCandidate =
            baseIt != texture.levels.end() &&
            isDepth32FTextureShadowDropShape(baseIt->second) &&
            !baseIt->second.rgba8.empty();
        if (depth32fBaseCandidate &&
            depth32fDropCandidateRgba8Bytes != 0) {
            ++inventory.hostCaches.depth32fDropDryRunCandidateTextures;
            inventory.hostCaches.depth32fDropDryRunCandidateRgba8Bytes +=
                depth32fDropCandidateRgba8Bytes;
            const bool hasView = texture.viewSourceTexture != 0;
            const bool hasSparse = texture.sparseTexture;
            const bool hasImageAtomicDirty =
                texture.imageAtomicBufferDirtyToTexture;
            const bool hasColorAuthoritative =
                texture.colorShadowAuthoritative;
            const bool hasDepthAuthoritative =
                texture.depthStencilShadowAuthoritative;
            const bool hasRendered =
                texture.wasFramebufferRenderedTo ||
                texture.wasViewportRenderedTo;
            const bool hasPending =
                texture.producerPending.hasAny(kProducerAll);
            const bool hasSamplingProxy =
                texture.metalSamplingProxy != nullptr;
            const bool blocked =
                hasView || hasSparse || hasImageAtomicDirty ||
                hasColorAuthoritative || hasDepthAuthoritative ||
                hasRendered || hasPending || hasSamplingProxy;
            if (!blocked) {
                ++inventory.hostCaches.depth32fDropDryRunEligibleTextures;
                inventory.hostCaches.depth32fDropDryRunEligibleRgba8Bytes +=
                    depth32fDropCandidateRgba8Bytes;
            } else {
                ++inventory.hostCaches.depth32fDropDryRunBlockedTextures;
                inventory.hostCaches.depth32fDropDryRunBlockedRgba8Bytes +=
                    depth32fDropCandidateRgba8Bytes;
            }
            auto accumulateFlag =
                [&](bool flag,
                    std::uint64_t& textureCounter,
                    std::uint64_t& byteCounter) {
                    if (!flag) {
                        return;
                    }
                    ++textureCounter;
                    byteCounter += depth32fDropCandidateRgba8Bytes;
                };
            accumulateFlag(
                hasView,
                inventory.hostCaches.depth32fDropDryRunFlagViewTextures,
                inventory.hostCaches.depth32fDropDryRunFlagViewRgba8Bytes);
            accumulateFlag(
                hasSparse,
                inventory.hostCaches.depth32fDropDryRunFlagSparseTextures,
                inventory.hostCaches.depth32fDropDryRunFlagSparseRgba8Bytes);
            accumulateFlag(
                hasImageAtomicDirty,
                inventory.hostCaches.depth32fDropDryRunFlagImageAtomicTextures,
                inventory.hostCaches.depth32fDropDryRunFlagImageAtomicRgba8Bytes);
            accumulateFlag(
                hasColorAuthoritative,
                inventory.hostCaches
                    .depth32fDropDryRunFlagColorAuthoritativeTextures,
                inventory.hostCaches
                    .depth32fDropDryRunFlagColorAuthoritativeRgba8Bytes);
            accumulateFlag(
                hasDepthAuthoritative,
                inventory.hostCaches
                    .depth32fDropDryRunFlagDepthAuthoritativeTextures,
                inventory.hostCaches
                    .depth32fDropDryRunFlagDepthAuthoritativeRgba8Bytes);
            accumulateFlag(
                hasRendered,
                inventory.hostCaches.depth32fDropDryRunFlagRenderedTextures,
                inventory.hostCaches.depth32fDropDryRunFlagRenderedRgba8Bytes);
            accumulateFlag(
                hasPending,
                inventory.hostCaches.depth32fDropDryRunFlagPendingTextures,
                inventory.hostCaches.depth32fDropDryRunFlagPendingRgba8Bytes);
            accumulateFlag(
                hasSamplingProxy,
                inventory.hostCaches
                    .depth32fDropDryRunFlagSamplingProxyTextures,
                inventory.hostCaches
                    .depth32fDropDryRunFlagSamplingProxyRgba8Bytes);
        }
        retainTextureShadowHotspot(hotspot);
        const bool primaryMirrorsValid =
            primarySawMirror && !primaryMirrorInvalid;
        const MetalResidencyAuthorityClass primaryAuthority =
            r5PrimaryTextureAuthority(
                texture,
                primaryMirrorsValid,
                primaryTextureViewSources.find(textureName) !=
                    primaryTextureViewSources.end());
        if (texture.viewSourceTexture != 0) {
            addTextureView(texture.metalTexture, textureName,
                           kMetalR5DiagnosticBucketTextureView,
                           texture.r5TextureViewLastUseSerial,
                           texture.r5TextureViewLastUseBoundarySerial);
        } else {
            addGenericTexture(texture.metalTexture, textureName,
                              primaryAuthority,
                              texture.r5PrimaryTextureLastUseBoundarySerial,
                              texture.r5PrimaryTextureLastUseSerial);
        }
        addTextureView(texture.metalSwizzledView, textureName,
                       kMetalR5DiagnosticBucketSwizzledTextureView,
                       texture.r5SwizzledViewLastUseSerial,
                       texture.r5SwizzledViewLastUseBoundarySerial);
        addTexture(texture.metalSamplingProxy, MetalResidencyOwner::Texture,
                   textureName, MetalResidencyKind::MetalTexture,
                   MetalResidencyAuthorityClass::Reconstructable,
                   MetalResidencyHeapClass::Cache);
        if (texture.metalSamplingProxy != nullptr &&
            genericTextureResources.insert(texture.metalSamplingProxy).second) {
            ++inventory.genericTextureCount;
            inventory.genericTextureBytes += allocatedSize(texture.metalSamplingProxy);
        }
        addSampler(texture.metalSampler);
        if (texture.textureBufferExpandedMetalBuffer != nullptr) {
            const auto bytes = allocatedSize(texture.textureBufferExpandedMetalBuffer);
            ++inventory.textureBufferExpansionMetalBuffers;
            inventory.textureBufferExpansionMetalBufferBytes += bytes;
            ++inventory.hostCaches.textureBufferExpansionMetalBuffers;
            inventory.hostCaches.textureBufferExpansionMetalBufferBytes += bytes;
            addBuffer(texture.textureBufferExpandedMetalBuffer,
                      MetalResidencyOwner::Texture, textureName,
                      MetalResidencyKind::TextureBufferExpansion,
                      MetalResidencyAuthorityClass::Reconstructable,
                      MetalResidencyHeapClass::Cache,
                      texture.textureBufferExpandedSourceBuffer,
                      texture.textureBufferExpandedSourceGeneration);
        }
        if (texture.imageAtomicBuffer != nullptr || texture.imageAtomicBufferSize > 0) {
            const auto bytes =
                static_cast<std::uint64_t>(texture.imageAtomicBufferSize);
            ++inventory.imageAtomicSidecars;
            inventory.imageAtomicSidecarBytes += bytes;
            ++inventory.hostCaches.imageAtomicSidecars;
            inventory.hostCaches.imageAtomicSidecarBytes += bytes;
            if (texture.imageAtomicBufferDirtyToTexture) {
                ++inventory.imageAtomicDirtySidecars;
            }
            if (texture.imageAtomicBuffer != nullptr) {
                ++inventory.imageAtomicSidecarMetalBuffers;
                inventory.imageAtomicSidecarMetalBufferBytes +=
                    allocatedSize(texture.imageAtomicBuffer);
                addBuffer(texture.imageAtomicBuffer,
                          MetalResidencyOwner::Texture, textureName,
                          MetalResidencyKind::ImageAtomicSidecar,
                          MetalResidencyAuthorityClass::Authoritative,
                          MetalResidencyHeapClass::Sidecar);
            }
        }
    });
    store->renderbuffers().forEach([&](GLuint renderbufferName, GLRenderbufferObject& renderbuffer) {
        const std::uint64_t rgba8Bytes =
            static_cast<std::uint64_t>(renderbuffer.rgba8.size());
        const std::uint64_t nativeBytes =
            static_cast<std::uint64_t>(renderbuffer.nativeData.size());
        const std::uint64_t depth32Bytes =
            static_cast<std::uint64_t>(renderbuffer.depth32.size() *
                                       sizeof(GLfloat));
        const std::uint64_t stencil8Bytes =
            static_cast<std::uint64_t>(renderbuffer.stencil8.size());
        const std::uint64_t capacityBytes =
            static_cast<std::uint64_t>(renderbuffer.rgba8.capacity()) +
            static_cast<std::uint64_t>(renderbuffer.nativeData.capacity()) +
            static_cast<std::uint64_t>(renderbuffer.depth32.capacity() *
                                       sizeof(GLfloat)) +
            static_cast<std::uint64_t>(renderbuffer.stencil8.capacity());
        const std::uint64_t shadowBytes =
            rgba8Bytes + nativeBytes + depth32Bytes + stencil8Bytes;
        inventory.hostCaches.renderbufferShadowRgba8Bytes += rgba8Bytes;
        inventory.hostCaches.renderbufferShadowNativeBytes += nativeBytes;
        inventory.hostCaches.renderbufferShadowDepth32Bytes += depth32Bytes;
        inventory.hostCaches.renderbufferShadowStencil8Bytes += stencil8Bytes;
        inventory.hostCaches.renderbufferShadowCapacityBytes += capacityBytes;
        if (shadowBytes != 0) {
            ++inventory.hostCaches.renderbufferShadowObjects;
            inventory.hostCaches.renderbufferShadowBytes += shadowBytes;
            addHostCacheBytes(shadowBytes);
            recordResidency(MetalResidencyOwner::Renderbuffer,
                            renderbufferName,
                            MetalResidencyKind::HostShadow,
                            MetalResidencyAuthorityClass::Authoritative,
                            MetalResidencyHeapClass::Host, 0, shadowBytes);
        }
        addRenderbufferTexture(renderbuffer.metalTexture, renderbufferName);
    });
    store->samplers().forEach([&](GLuint, GLSamplerObject& sampler) {
        addSampler(sampler.metalSampler);
    });
    store->shaders().forEach([&](GLuint shaderName, GLShaderObject& shader) {
        const auto sourceBytes =
            static_cast<std::uint64_t>(shader.source.size());
        if (sourceBytes != 0) {
            inventory.hostCaches.shaderSourceBytes += sourceBytes;
            addHostCacheBytes(sourceBytes);
            recordResidency(MetalResidencyOwner::Shader, shaderName,
                            MetalResidencyKind::ShaderSource,
                            MetalResidencyAuthorityClass::Authoritative,
                            MetalResidencyHeapClass::Host, 0, sourceBytes);
        }
        const auto spirvBytes = static_cast<std::uint64_t>(
            shader.spirv.size() * sizeof(std::uint32_t));
        if (spirvBytes != 0) {
            inventory.hostCaches.shaderSpirvBytes += spirvBytes;
            addHostCacheBytes(spirvBytes);
            recordResidency(
                MetalResidencyOwner::Shader, shaderName,
                MetalResidencyKind::ShaderSpirv,
                shader.isSpirvBinary
                    ? MetalResidencyAuthorityClass::Authoritative
                    : MetalResidencyAuthorityClass::Reconstructable,
                MetalResidencyHeapClass::Host, 0, spirvBytes);
        }
    });
    store->programs().forEach([&](GLuint programName, GLProgramObject& program) {
        addProgram(programName, program);
    });
    store->programPipelines().forEach([&](GLuint, GLProgramPipelineObject& pipeline) {
        if (pipeline.syntheticTessProgram != nullptr) {
            addProgram(0, *pipeline.syntheticTessProgram);
        }
    });
    inventory.cacheLiveRenderPsoTotal =
        inventory.cacheLiveRenderPso + inventory.cacheLiveGsPassThroughPso;
    inventory.cacheHighWaterRenderPsoTotal =
        std::max(impl_->renderPsoTotalCacheHighWater,
                 inventory.cacheLiveRenderPsoTotal);
    std::sort(inventory.topRenderPsoPrograms.begin(),
              inventory.topRenderPsoPrograms.end(),
              [](const MetalResourceInventory::RenderPsoProgramHotspot& lhs,
                 const MetalResourceInventory::RenderPsoProgramHotspot& rhs) {
                  const std::uint64_t lhsLive =
                      lhs.renderPsoLive + lhs.gsPassThroughPsoLive;
                  const std::uint64_t rhsLive =
                      rhs.renderPsoLive + rhs.gsPassThroughPsoLive;
                  if (lhsLive != rhsLive) {
                      return lhsLive > rhsLive;
                  }
                  const std::uint64_t lhsHighWater =
                      lhs.renderPsoHighWater + lhs.gsPassThroughPsoHighWater;
                  const std::uint64_t rhsHighWater =
                      rhs.renderPsoHighWater + rhs.gsPassThroughPsoHighWater;
                  if (lhsHighWater != rhsHighWater) {
                      return lhsHighWater > rhsHighWater;
                  }
                  const std::uint64_t lhsMisses =
                      lhs.renderPsoMisses + lhs.gsPassThroughPsoMisses;
                  const std::uint64_t rhsMisses =
                      rhs.renderPsoMisses + rhs.gsPassThroughPsoMisses;
                  if (lhsMisses != rhsMisses) {
                      return lhsMisses > rhsMisses;
                  }
                  const std::uint64_t lhsEvictions =
                      lhs.renderPsoEvictions +
                      lhs.renderPsoGlobalEvictions +
                      lhs.gsPassThroughPsoEvictions +
                      lhs.gsPassThroughPsoGlobalEvictions;
                  const std::uint64_t rhsEvictions =
                      rhs.renderPsoEvictions +
                      rhs.renderPsoGlobalEvictions +
                      rhs.gsPassThroughPsoEvictions +
                      rhs.gsPassThroughPsoGlobalEvictions;
                  if (lhsEvictions != rhsEvictions) {
                      return lhsEvictions > rhsEvictions;
                  }
                  return lhs.program < rhs.program;
              });
    const auto renderPsoHotspotLimit =
        static_cast<std::size_t>(inventory.renderPsoProgramHotspotLimit);
    if (renderPsoHotspotLimit != 0 &&
        inventory.topRenderPsoPrograms.size() > renderPsoHotspotLimit) {
        inventory.topRenderPsoPrograms.resize(renderPsoHotspotLimit);
    }
    inventory.renderPsoProgramHotspotsTruncated =
        inventory.renderPsoProgramHotspotRows >
                static_cast<std::uint64_t>(inventory.topRenderPsoPrograms.size())
            ? inventory.renderPsoProgramHotspotRows -
                  static_cast<std::uint64_t>(inventory.topRenderPsoPrograms.size())
            : 0;

    const auto sparseTextureInventory =
        extensions::sparse_texture::sparseTextureMemoryInventory(*this);
    inventory.sparseTextureStates = sparseTextureInventory.textureStates;
    inventory.sparseTextureHeaps = sparseTextureInventory.sparseHeaps;
    inventory.sparseTextureHeapBytes = sparseTextureInventory.sparseHeapBytes;
    inventory.sparseTextureCommittedRegions =
        sparseTextureInventory.committedRegions;
    inventory.hostCaches.sparseTextureHeaps =
        sparseTextureInventory.sparseHeaps;
    inventory.hostCaches.sparseTextureHeapBytes =
        sparseTextureInventory.sparseHeapBytes;
    recordResidency(MetalResidencyOwner::SparseTexture, 0,
                    MetalResidencyKind::SparseHeap,
                    MetalResidencyAuthorityClass::SparseSpecial,
                    MetalResidencyHeapClass::Sparse,
                    sparseTextureInventory.sparseHeapBytes, 0);

    const auto sparseStorageSidecars =
        extensions::sparse_texture::sparseStorageImageSidecarInventory(*this);
    inventory.sparseStorageImageSidecars = sparseStorageSidecars.sidecars;
    inventory.sparseStorageImageSidecarBytes = sparseStorageSidecars.sidecarBytes;
    inventory.hostCaches.sparseStorageImageSidecars =
        sparseStorageSidecars.sidecars;
    inventory.hostCaches.sparseStorageImageSidecarBytes =
        sparseStorageSidecars.sidecarBytes;
    recordResidency(MetalResidencyOwner::SparseTexture, 0,
                    MetalResidencyKind::SparseStorageSidecar,
                    MetalResidencyAuthorityClass::SparseSpecial,
                    MetalResidencyHeapClass::Sparse,
                    sparseStorageSidecars.sidecarBytes, 0);

    const auto multisampleStorageSidecars =
        extensions::sparse_texture::multisampleStorageImageSidecarInventory(*this);
    inventory.multisampleStorageImageSidecars =
        multisampleStorageSidecars.sidecars;
    inventory.multisampleStorageImageSidecarBytes =
        multisampleStorageSidecars.sidecarBytes;
    inventory.hostCaches.multisampleStorageImageSidecars =
        multisampleStorageSidecars.sidecars;
    inventory.hostCaches.multisampleStorageImageSidecarBytes =
        multisampleStorageSidecars.sidecarBytes;
    recordResidency(MetalResidencyOwner::SparseTexture, 0,
                    MetalResidencyKind::MultisampleStorageSidecar,
                    MetalResidencyAuthorityClass::SparseSpecial,
                    MetalResidencyHeapClass::Sparse,
                    multisampleStorageSidecars.sidecarBytes, 0);

    std::sort(inventory.topTextureShadows.begin(),
              inventory.topTextureShadows.end(),
              [&](const MetalResourceInventory::TextureShadowHotspot& lhs,
                  const MetalResourceInventory::TextureShadowHotspot& rhs) {
                  return textureHotspotLowerPriority(rhs, lhs);
              });
    inventory.textureShadowHotspotsTruncated =
        inventory.textureShadowHotspotRows >
                static_cast<std::uint64_t>(inventory.topTextureShadows.size())
            ? inventory.textureShadowHotspotRows -
                  static_cast<std::uint64_t>(inventory.topTextureShadows.size())
            : 0;

    std::sort(inventory.r5OrderingCandidates.begin(),
              inventory.r5OrderingCandidates.end(),
              metalR5OrderingRecordLess);
    inventory.r5Ordering.rowsExported =
        static_cast<std::uint64_t>(inventory.residencyRows.size());
    inventory.r5Ordering.candidatesExported =
        static_cast<std::uint64_t>(inventory.r5OrderingCandidates.size());
    inventory.r5Ordering.candidatesTruncated =
        inventory.r5Ordering.candidateRows > inventory.r5Ordering.candidatesExported
            ? inventory.r5Ordering.candidateRows -
                  inventory.r5Ordering.candidatesExported
            : 0;

#ifndef NDEBUG
    if (std::getenv("APPGL_R3_ASSERT_NO_UNKNOWN") != nullptr) {
        assert(inventory.residency.unknownRecords == 0);
    }
#endif

    inventory.deviceAllocatedBytes =
        std::max(inventory.deviceAllocatedBytes, inventory.residency.metalBytes);
    finalizePressureInputs();
    finalizeR8HeapSegmentation();
    return inventory;
}

bool GLContext::isTransformFeedbackActive() const {
    // Sprint 8 #9-B (CKPT85): per-TF-object active-state tracking.
    // GL 4.6 §13.2.2 mandates that begin/end/pause/resume validation is
    // against the CURRENTLY-BOUND TF object's state, not a global flag.
    // The global `impl_->transformFeedbackActive` is the legacy mirror
    // that gets last-written by setTransformFeedbackActive — but when
    // glBindTransformFeedback switches the bound object, the global
    // flag still reflects the OLD object's state. Reading per-bound-
    // object state correctly distinguishes "is THIS TF object active?"
    // from "is ANY TF active?".
    //
    // Default object 0 (the implicit context-wide TF) has no backing
    // GLTransformFeedbackObject — its state lives in the global flag.
    // This is the single semantic the global flag still owns.
    //
    // CTS `transform_feedback.draw_xfb_test` exercises this exact
    // scenario: bind(A), begin, pause, bind(B), begin should succeed
    // (B is its own state, A is paused-active). Pre-CKPT85 the global
    // flag returned A's active=true even after B was bound, blocking
    // the begin on B with INVALID_OPERATION.
    const GLuint tfId = impl_->boundTransformFeedbackId;
    if (tfId != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfId)) {
            return tf->active;
        }
    }
    return impl_->transformFeedbackActive;
}

// CKPT119 (Sprint 11 Phase 1 1b — Cluster F shader_image_size): create
// a single-mip texture view at `level` and cache it on the binding.
// See forward-declaration earlier in Impl class for rationale.
void* GLContext::Impl::resolveImageMetalTextureImpl(GLTextureObject* texObj,
                                                    GLuint texName,
                                                    GLint level,
                                                    GLenum imageFormat,
                                                    GLboolean layered,
                                                    GLint layer,
                                                    GLenum shaderTarget,
                                                    void*& cachedView,
                                                    GLuint& cachedTex,
                                                    GLint& cachedLev,
                                                    GLenum& cachedFmt,
                                                    GLboolean& cachedLayered,
                                                    GLint& cachedLayer,
                                                    GLenum& cachedTarget,
                                                    void* overrideMetalTexture) {
    void* baseMetalTexture = overrideMetalTexture != nullptr
        ? overrideMetalTexture
        : (texObj != nullptr ? texObj->metalTexture : nullptr);
    if (texObj == nullptr || baseMetalTexture == nullptr) return nullptr;
    if (level < 0) {
        return nullptr;
    }
    const bool trace = std::getenv("APPGL_TRACE_IMG_BIND") != nullptr;
    if (cachedView != nullptr &&
        cachedTex == texName &&
        cachedLev == level &&
        cachedFmt == imageFormat &&
        cachedLayered == layered &&
        cachedLayer == layer &&
        cachedTarget == shaderTarget) {
        if (trace) {
            std::fprintf(stderr,
                "[IMG-VIEW] tex=%u level=%d fmt=0x%X layered=%d layer=%d target=0x%X cache-hit view=%p\n",
                texName, level, imageFormat, layered ? 1 : 0, layer,
                shaderTarget, cachedView);
        }
        return cachedView;
    }
    id<MTLTexture> baseTex = (__bridge id<MTLTexture>)baseMetalTexture;
    if (baseTex == nil) return nullptr;
    const NSUInteger maxLevels = nonZeroMipLevelCount(baseTex.mipmapLevelCount);
    if (static_cast<NSUInteger>(level) >= maxLevels) {
        return nullptr;
    }
    const MTLPixelFormat imagePixelFormat = metalRenderbufferFormat(imageFormat);
    if (imagePixelFormat == MTLPixelFormatInvalid) {
        if (trace) {
            std::fprintf(stderr,
                "[IMG-VIEW] tex=%u level=%d fmt=0x%X skip=invalid-metal-format\n",
                texName, level, imageFormat);
        }
        return nullptr;
    }
    auto totalSliceCount = [&]() -> NSUInteger {
        switch (baseTex.textureType) {
            case MTLTextureType1DArray:
            case MTLTextureType2DArray:
            case MTLTextureType2DMultisampleArray:
                return std::max<NSUInteger>(baseTex.arrayLength, 1);
            case MTLTextureTypeCube:
                return 6;
            case MTLTextureTypeCubeArray:
                return 6 * std::max<NSUInteger>(baseTex.arrayLength, 1);
            default:
                return 1;
        }
    };
    const bool shaderWantsSingle2D =
        shaderTarget == GL_TEXTURE_2D ||
        shaderTarget == GL_TEXTURE_RECTANGLE;
    const NSUInteger availableSlices = totalSliceCount();
    const bool sourceHasSliceSpace = availableSlices > 1;
    const bool singleLayerView =
        layered == GL_FALSE &&
        shaderWantsSingle2D &&
        sourceHasSliceSpace;
    const bool cubeArrayStorageAs2DArray =
        layered == GL_TRUE &&
        shaderTarget == GL_TEXTURE_CUBE_MAP_ARRAY &&
        baseTex.textureType == MTLTextureTypeCubeArray;
    if (singleLayerView &&
        (layer < 0 || static_cast<NSUInteger>(layer) >= availableSlices)) {
        if (trace) {
            std::fprintf(stderr,
                "[IMG-VIEW] tex=%u level=%d fmt=0x%X layered=0 layer=%d target=0x%X skip=layer-oob slices=%lu\n",
                texName, level, imageFormat, layer, shaderTarget,
                static_cast<unsigned long>(availableSlices));
        }
        return nullptr;
    }
    if (!cubeArrayStorageAs2DArray &&
        !singleLayerView && level == 0 && imagePixelFormat == baseTex.pixelFormat) {
        if (trace) {
            std::fprintf(stderr,
                "[IMG-VIEW] tex=%u level=0 fmt=0x%X layered=%d layer=%d target=0x%X base-pf=%lu use=base\n",
                texName, imageFormat, layered ? 1 : 0, layer, shaderTarget,
                static_cast<unsigned long>(baseTex.pixelFormat));
        }
        return baseMetalTexture;
    }
    if (extensions::sparse_texture::shouldSkipDepthImageViewCast(texObj->desc.internalFormat,
                                                                 imageFormat)) {
        if (trace) {
            std::fprintf(stderr,
                "[IMG-VIEW] tex=%u level=%d fmt=0x%X base-ifmt=0x%X base-pf=%lu view-pf=%lu skip=depth-color-cast\n",
                texName, level, imageFormat, texObj->desc.internalFormat,
                static_cast<unsigned long>(baseTex.pixelFormat),
                static_cast<unsigned long>(imagePixelFormat));
        }
        return nullptr;
    }
    if (cachedView != nullptr) {
        releaseRetainedMetalObject(cachedView);
        cachedView = nullptr;
        cachedTex = 0;
        cachedLev = -1;
        cachedFmt = 0;
        cachedLayered = GL_TRUE;
        cachedLayer = 0;
        cachedTarget = 0;
    }
    NSRange levelRange = NSMakeRange(static_cast<NSUInteger>(level), 1);
    // CKPT119: per-textureType slice range. Metal asserts:
    // - Cube / CubeArray: slice range must be multiple of 6
    // - 2DArray / 1DArray: slice range = arrayLength
    // - 2D / 2DMS / 3D / 1D: slice range = 1 (default)
    const NSUInteger sliceCount = singleLayerView ? 1 : availableSlices;
    NSRange sliceRange = singleLayerView
        ? NSMakeRange(static_cast<NSUInteger>(layer), 1)
        : NSMakeRange(0, sliceCount);
    const MTLTextureType viewTextureType =
        cubeArrayStorageAs2DArray
            ? MTLTextureType2DArray
            : (singleLayerView ? MTLTextureType2D : baseTex.textureType);
    id<MTLTexture> levelView = [baseTex newTextureViewWithPixelFormat:imagePixelFormat
                                                          textureType:viewTextureType
                                                               levels:levelRange
                                                               slices:sliceRange];
    if (levelView == nil) {
        if (trace) {
            std::fprintf(stderr,
                "[IMG-VIEW] tex=%u level=%d fmt=0x%X base-pf=%lu view-pf=%lu result=nil\n",
                texName, level, imageFormat,
                static_cast<unsigned long>(baseTex.pixelFormat),
                static_cast<unsigned long>(imagePixelFormat));
        }
        return nullptr;
    }
    cachedView = transferRetainedMetalObject(levelView);
    cachedTex = texName;
    cachedLev = level;
    cachedFmt = imageFormat;
    cachedLayered = layered;
    cachedLayer = layer;
    cachedTarget = shaderTarget;
    if (trace) {
        std::fprintf(stderr,
            "[IMG-VIEW] tex=%u level=%d fmt=0x%X layered=%d layer=%d target=0x%X base-pf=%lu view-pf=%lu view-type=%lu slices=(%lu,%lu) view=%p\n",
            texName, level, imageFormat, layered ? 1 : 0, layer,
            shaderTarget,
            static_cast<unsigned long>(baseTex.pixelFormat),
            static_cast<unsigned long>(imagePixelFormat),
            static_cast<unsigned long>(viewTextureType),
            static_cast<unsigned long>(sliceRange.location),
            static_cast<unsigned long>(sliceRange.length),
            cachedView);
    }
    return cachedView;
}

bool GLContext::Impl::isTfActiveOnBoundImpl() const {
    if (boundTransformFeedbackId != 0) {
        if (auto* tf = objects->transformFeedbacks().get(boundTransformFeedbackId)) {
            return tf->active;
        }
    }
    return transformFeedbackActive;
}

bool GLContext::Impl::isTfPausedOnBoundImpl() const {
    if (boundTransformFeedbackId != 0) {
        if (auto* tf = objects->transformFeedbacks().get(boundTransformFeedbackId)) {
            return tf->paused;
        }
    }
    return transformFeedbackPaused;
}

static std::string trimOcclusionExpr(std::string s) {
    auto notWs = [](unsigned char c) { return !std::isspace(c); };
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), notWs));
    s.erase(std::find_if(s.rbegin(), s.rend(), notWs).base(), s.end());
    return s;
}

static std::size_t matchingParenForOcclusionExpr(const std::string& s,
                                                 std::size_t open)
{
    int depth = 0;
    for (std::size_t i = open; i < s.size(); ++i) {
        if (s[i] == '(') {
            ++depth;
        } else if (s[i] == ')') {
            --depth;
            if (depth == 0) return i;
        }
    }
    return std::string::npos;
}

static std::vector<std::string> splitTopLevelOcclusionArgs(
    const std::string& s)
{
    std::vector<std::string> args;
    int paren = 0;
    int bracket = 0;
    std::size_t start = 0;
    for (std::size_t i = 0; i < s.size(); ++i) {
        const char c = s[i];
        if (c == '(') ++paren;
        else if (c == ')') --paren;
        else if (c == '[') ++bracket;
        else if (c == ']') --bracket;
        else if (c == ',' && paren == 0 && bracket == 0) {
            args.push_back(trimOcclusionExpr(s.substr(start, i - start)));
            start = i + 1;
        }
    }
    args.push_back(trimOcclusionExpr(s.substr(start)));
    return args;
}

static bool parseFloatLiteralForOcclusionExpr(const std::string& expr,
                                              float& out)
{
    const std::string trimmed = trimOcclusionExpr(expr);
    if (trimmed.empty()) return false;
    char* end = nullptr;
    const float value = std::strtof(trimmed.c_str(), &end);
    if (end == trimmed.c_str()) return false;
    while (*end == 'f' || *end == 'F') ++end;
    while (*end != '\0' && std::isspace(static_cast<unsigned char>(*end))) {
        ++end;
    }
    if (*end != '\0') return false;
    out = value;
    return true;
}

static bool isBareIdentifierForOcclusionExpr(const std::string& expr) {
    if (expr.empty()) return false;
    const auto isFirst = [](unsigned char c) {
        return std::isalpha(c) || c == '_';
    };
    const auto isRest = [](unsigned char c) {
        return std::isalnum(c) || c == '_';
    };
    if (!isFirst(static_cast<unsigned char>(expr[0]))) return false;
    for (std::size_t i = 1; i < expr.size(); ++i) {
        if (!isRest(static_cast<unsigned char>(expr[i]))) return false;
    }
    return true;
}

static bool lookupFloatUniformForOcclusionExpr(
    const GLProgramObject& program, const std::string& name, float& out)
{
    for (const auto& uniform : program.uniforms) {
        if (uniform.name != name || uniform.type != GL_FLOAT ||
            uniform.location < 0) {
            continue;
        }
        const auto valueIt = program.uniformValues.find(uniform.location);
        if (valueIt == program.uniformValues.end() ||
            valueIt->second.floats.empty()) {
            return false;
        }
        out = valueIt->second.floats[0];
        return true;
    }
    return false;
}

static bool uniformNameHasTail(const std::string& name, const char* tail) {
    const std::size_t tailLen = std::strlen(tail);
    if (name == tail) return true;
    if (name.size() <= tailLen) return false;
    const std::size_t start = name.size() - tailLen;
    return name.compare(start, tailLen, tail) == 0 &&
           (start == 0 || name[start - 1] == '.' || name[start - 1] == '_');
}

static bool fragmentDiscardUniformSuppressesAllSamples(
    const GLProgramObject& program)
{
    if (program.fragmentMSL.find("discard_fragment") == std::string::npos) {
        return false;
    }
    for (const auto& uniform : program.uniforms) {
        if (!uniformNameHasTail(uniform.name, "shall_pass") ||
            uniform.location < 0) {
            continue;
        }
        const auto valueIt = program.uniformValues.find(uniform.location);
        if (valueIt == program.uniformValues.end() ||
            valueIt->second.ints.empty()) {
            return false;
        }
        return valueIt->second.ints[0] == 0;
    }
    return false;
}

bool GLContext::Impl::estimateCurrentVertexWindowDepth(float& outDepth) const {
    if (state == nullptr || objects == nullptr) return false;
    const GLuint progName = state->currentProgram();
    const GLProgramObject* program = progName == 0 ? nullptr
        : objects->programs().get(progName);
    if (program == nullptr) return false;

    const std::string* vertexSource = nullptr;
    for (GLuint shaderName : program->attachedShaders) {
        const GLShaderObject* shader = objects->shaders().get(shaderName);
        if (shader != nullptr && shader->stage == GL_VERTEX_SHADER) {
            vertexSource = &shader->source;
            break;
        }
    }
    if (vertexSource == nullptr) return false;

    auto evalExpr = [&](const std::string& raw, float& value) -> bool {
        const std::string expr = trimOcclusionExpr(raw);
        if (parseFloatLiteralForOcclusionExpr(expr, value)) {
            return true;
        }
        if (isBareIdentifierForOcclusionExpr(expr)) {
            return lookupFloatUniformForOcclusionExpr(*program, expr, value);
        }
        return false;
    };

    std::size_t pos = 0;
    while ((pos = vertexSource->find("gl_Position", pos)) !=
           std::string::npos) {
        const std::size_t semi = vertexSource->find(';', pos);
        const std::size_t eq = vertexSource->find('=', pos);
        if (eq == std::string::npos ||
            (semi != std::string::npos && eq > semi)) {
            pos += std::strlen("gl_Position");
            continue;
        }
        const std::size_t vec4 = vertexSource->find("vec4", eq);
        if (vec4 == std::string::npos ||
            (semi != std::string::npos && vec4 > semi)) {
            pos = eq + 1;
            continue;
        }
        const std::size_t open = vertexSource->find('(', vec4);
        if (open == std::string::npos ||
            (semi != std::string::npos && open > semi)) {
            pos = vec4 + 4;
            continue;
        }
        const std::size_t close = matchingParenForOcclusionExpr(
            *vertexSource, open);
        if (close == std::string::npos) return false;
        const std::vector<std::string> args = splitTopLevelOcclusionArgs(
            vertexSource->substr(open + 1, close - open - 1));
        const std::size_t zIndex = (args.size() == 3) ? 1u : 2u;
        const std::size_t wIndex = (args.size() == 3) ? 2u : 3u;
        if (args.size() <= wIndex) {
            pos = close + 1;
            continue;
        }
        float clipZ = 0.0f;
        float clipW = 1.0f;
        if (!evalExpr(args[zIndex], clipZ) || !evalExpr(args[wIndex], clipW) ||
            clipW == 0.0f) {
            pos = close + 1;
            continue;
        }
        const float ndcZ = clipZ / clipW;
        const auto& range = state->depthRange();
        if (state->clipDepthMode() == GL_ZERO_TO_ONE) {
            outDepth = static_cast<float>(
                range.nearValue +
                (range.farValue - range.nearValue) * ndcZ);
        } else {
            outDepth = static_cast<float>(
                ((range.farValue - range.nearValue) * ndcZ +
                 (range.nearValue + range.farValue)) * 0.5);
        }
        outDepth = std::clamp(outDepth, 0.0f, 1.0f);
        return true;
    }
    return false;
}

static bool appglDepthCompareForOcclusion(GLenum func, float incoming,
                                          float stored)
{
    switch (func) {
        case GL_NEVER: return false;
        case GL_LESS: return incoming < stored;
        case GL_EQUAL: return incoming == stored;
        case GL_LEQUAL: return incoming <= stored;
        case GL_GREATER: return incoming > stored;
        case GL_NOTEQUAL: return incoming != stored;
        case GL_GEQUAL: return incoming >= stored;
        case GL_ALWAYS: return true;
        default: return true;
    }
}

void GLContext::Impl::updatePrimitiveCountersForNonGsDraw(
    GLenum mode, GLsizei vertexCount, GLsizei instanceCount,
    GLsizei restartSkipCount)
{
    if (vertexCount <= 0 || instanceCount <= 0) return;
    const std::uint64_t activeCounterMask =
        activeQueryTargetMask & kNonGsPrimitiveCounterQueryMask;
    const bool tfActive = transformFeedbackActive;
    if (!tfActive && activeCounterMask == 0) return;

    // GL 4.6 §10.1: post-decomposition primitive count for non-GS
    // draws. Strip/loop topologies produce (count - {1,2}) primitives;
    // list topologies produce count / verts-per-prim. Quads aren't a
    // core-GL primitive (patches aren't counted here — those go
    // through TES anyway).
    //
    // GL 4.6 §22.3 — when primitive-restart is active, the restart
    // index is NOT a submitted vertex nor a primitive boundary vertex
    // for count purposes. For list-type primitives this is exactly
    // `submittedN / verts-per-prim`. Strip/fan/adjacency topologies
    // with restart indices in the middle need per-subsequence math —
    // those tests exercise lists in this iter, the strip path is
    // TODO for later.
    std::size_t prims = 0;
    const std::size_t n = static_cast<std::size_t>(vertexCount);
    const std::size_t submittedRaw = (n > static_cast<std::size_t>(restartSkipCount))
        ? (n - static_cast<std::size_t>(restartSkipCount)) : 0;
    switch (mode) {
        case GL_POINTS:                   prims = submittedRaw; break;
        case GL_LINES:                    prims = submittedRaw / 2; break;
        case GL_LINE_STRIP:               prims = (submittedRaw >= 2) ? submittedRaw - 1 : 0; break;
        case GL_LINE_LOOP:                prims = (submittedRaw >= 2) ? submittedRaw : 0; break;
        case GL_TRIANGLES:                prims = submittedRaw / 3; break;
        case GL_TRIANGLE_STRIP:
        case GL_TRIANGLE_FAN:             prims = (submittedRaw >= 3) ? submittedRaw - 2 : 0; break;
        case GL_LINES_ADJACENCY:          prims = submittedRaw / 4; break;
        case GL_LINE_STRIP_ADJACENCY:     prims = (submittedRaw >= 4) ? submittedRaw - 3 : 0; break;
        case GL_TRIANGLES_ADJACENCY:      prims = submittedRaw / 6; break;
        case GL_TRIANGLE_STRIP_ADJACENCY: prims = (submittedRaw >= 6) ? (submittedRaw - 4) / 2 : 0; break;
        case GL_PATCHES: {
            // GL 4.6 §10.1: PRIMITIVES_SUBMITTED for GL_PATCHES is
            // vertexCount / GL_PATCH_VERTICES. CTS
            // `pipeline_statistics_query_tests_ARB.functional_tess_
            // queries` sets PATCH_VERTICES=3 and draws 7 indices,
            // expecting PRIMITIVES_SUBMITTED to report 2 (EXACT_MATCH).
            // The TCS_PATCHES / TES_INVOCATIONS counters are EQUAL_OR_
            // GREATER in that test — any non-zero count lets them
            // pass. A pure synthetic "1" satisfies the lower-bound
            // queries but fails the exact-match one, hence this path.
            const GLint pv = state ? state->tessellationState().patchVertices : 3;
            prims = (pv > 0) ? (submittedRaw / static_cast<std::size_t>(pv)) : 0;
            break;
        }
        default: break;
    }
    prims *= static_cast<std::size_t>(instanceCount);
    const std::size_t vertsTotal = submittedRaw * static_cast<std::size_t>(instanceCount);
    if (activeCounterMask == 0) return;

    const bool sampleQueryActive =
        (activeCounterMask & kNonGsSampleQueryMask) != 0;
    bool samplesPassed = prims > 0;
    bool resolvedSamplesPassed = false;
    bool incomingDepthResolved = false;
    float incomingDepth = 0.0f;
    if (sampleQueryActive && samplesPassed && state != nullptr && state->isEnabled(GL_DEPTH_TEST)) {
        incomingDepthResolved = estimateCurrentVertexWindowDepth(incomingDepth);
        if (incomingDepthResolved && occlusionApproxDepthKnown) {
            samplesPassed = appglDepthCompareForOcclusion(
                state->depthState().func, incomingDepth, occlusionApproxDepth);
            resolvedSamplesPassed = true;
        } else {
            // Conservative fallback for shader shapes we cannot reduce to a
            // constant window depth yet. Preserve the historical positive
            // result instead of fabricating a false occlusion failure.
            samplesPassed = true;
        }
        if (samplesPassed && state->depthState().writeMask != GL_FALSE) {
            if (incomingDepthResolved) {
                occlusionApproxDepth = incomingDepth;
                occlusionApproxDepthKnown = true;
            } else {
                occlusionApproxDepthKnown = false;
            }
        }
    }
    if (sampleQueryActive && samplesPassed && state != nullptr && objects != nullptr) {
        const GLuint progName = state->currentProgram();
        const GLProgramObject* program = progName == 0
            ? nullptr
            : objects->programs().get(progName);
        if (program != nullptr &&
            fragmentDiscardUniformSuppressesAllSamples(*program)) {
            samplesPassed = false;
            resolvedSamplesPassed = true;
        }
    }
    // GL 4.6 §22.1 / §22.3 — advance pipeline-stats counters for
    // every active query whose target tracks one of the per-draw
    // quantities. FS_INVOCATIONS is gated on whether rasterizer-
    // discard is off (discard skips the FS); we don't mask on
    // per-fragment coverage yet — advancing by at least 1 is enough
    // to satisfy the EQUAL_OR_GREATER check in CTS
    // pipeline_statistics_query_tests_ARB.functional_*_invocations.
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
                q.result += static_cast<GLuint64>(prims);
                if (std::getenv("APPGL_DUMP_TESOUT")) {
                    std::fprintf(stderr,
                        "APPGL_DETECTOR nongs_q_update PRIMITIVES_GENERATED "
                        "+= %zu (mode=0x%04X vertexCount=%d patchVerts=%d) "
                        "-> q.result=%llu\n",
                        prims, mode, (int)vertexCount,
                        state ? state->tessellationState().patchVertices : 0,
                        (unsigned long long)q.result);
                }
                break;
            case GL_PRIMITIVES_SUBMITTED:
            case GL_CLIPPING_INPUT_PRIMITIVES:
            case GL_CLIPPING_OUTPUT_PRIMITIVES:
                q.result += static_cast<GLuint64>(prims);
                break;
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                // Sprint 17 Day 9+ regression-debt #5 (R7): when TF is
                // active for a non-GS draw, `writeGsXfbAndCheckDiscard`
                // already credited this query with the buffer-cap-
                // aware `primsWritten`. Crediting the submitted prim
                // count here would double-count and over-report,
                // regressing CTS `transform_feedback.query_vertex_*_
                // test` whose TF buffer fits fewer prims than the
                // draw submits. Leave TFB_WRITTEN to writeGsXfb when
                // TF is active.
                break;
            case GL_VERTICES_SUBMITTED:
            case GL_VERTEX_SHADER_INVOCATIONS:
                q.result += static_cast<GLuint64>(vertsTotal);
                break;
            case GL_FRAGMENT_SHADER_INVOCATIONS:
                // Lower-bound credit — real per-pixel count isn't
                // tracked. At least one fragment ran when a primitive
                // was drawn. Sufficient for EQUAL_OR_GREATER tests.
                if (prims > 0) q.result += 1;
                break;
            case GL_SAMPLES_PASSED:
            case GL_ANY_SAMPLES_PASSED:
            case GL_ANY_SAMPLES_PASSED_CONSERVATIVE:
                q.samplesPassedResolved = resolvedSamplesPassed ||
                    state == nullptr || !state->isEnabled(GL_DEPTH_TEST);
                if (samplesPassed) q.result += 1;
                break;
            default:
                break;
        }
    });
}

void GLContext::Impl::updateSubmittedPipelineStatsForNonGsDraw(
    GLenum mode, GLsizei vertexCount, GLsizei instanceCount,
    GLsizei restartSkipCount)
{
    if (vertexCount <= 0 || instanceCount <= 0) return;
    if ((activeQueryTargetMask & kSubmittedPipelineStatsQueryMask) == 0) return;

    std::size_t prims = 0;
    const std::size_t n = static_cast<std::size_t>(vertexCount);
    const std::size_t submittedRaw = (n > static_cast<std::size_t>(restartSkipCount))
        ? (n - static_cast<std::size_t>(restartSkipCount)) : 0;
    switch (mode) {
        case GL_POINTS:                   prims = submittedRaw; break;
        case GL_LINES:                    prims = submittedRaw / 2; break;
        case GL_LINE_STRIP:               prims = (submittedRaw >= 2) ? submittedRaw - 1 : 0; break;
        case GL_LINE_LOOP:                prims = (submittedRaw >= 2) ? submittedRaw : 0; break;
        case GL_TRIANGLES:                prims = submittedRaw / 3; break;
        case GL_TRIANGLE_STRIP:
        case GL_TRIANGLE_FAN:             prims = (submittedRaw >= 3) ? submittedRaw - 2 : 0; break;
        case GL_LINES_ADJACENCY:          prims = submittedRaw / 4; break;
        case GL_LINE_STRIP_ADJACENCY:     prims = (submittedRaw >= 4) ? submittedRaw - 3 : 0; break;
        case GL_TRIANGLES_ADJACENCY:      prims = submittedRaw / 6; break;
        case GL_TRIANGLE_STRIP_ADJACENCY: prims = (submittedRaw >= 6) ? (submittedRaw - 4) / 2 : 0; break;
        case GL_PATCHES: {
            const GLint pv = state ? state->tessellationState().patchVertices : 3;
            prims = (pv > 0) ? (submittedRaw / static_cast<std::size_t>(pv)) : 0;
            break;
        }
        default: break;
    }

    prims *= static_cast<std::size_t>(instanceCount);
    const std::size_t vertsTotal = submittedRaw * static_cast<std::size_t>(instanceCount);
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        switch (q.target) {
            case GL_PRIMITIVES_SUBMITTED:
            case GL_CLIPPING_INPUT_PRIMITIVES:
            case GL_CLIPPING_OUTPUT_PRIMITIVES:
                q.result += static_cast<GLuint64>(prims);
                break;
            case GL_VERTICES_SUBMITTED:
            case GL_VERTEX_SHADER_INVOCATIONS:
                q.result += static_cast<GLuint64>(vertsTotal);
                break;
            default:
                break;
        }
    });
}

GLsizei GLContext::Impl::countRestartIndices(GLenum type, const void* indices,
                                             GLsizei count) const
{
    const bool fixedRestart = state->isEnabled(GL_PRIMITIVE_RESTART_FIXED_INDEX);
    const bool programmableRestart = state->isEnabled(GL_PRIMITIVE_RESTART);
    if (count <= 0 || (!fixedRestart && !programmableRestart)) return 0;
    // Resolve the source bytes. When GL_ELEMENT_ARRAY_BUFFER is bound,
    // `indices` is a byte offset into that buffer; when it's not,
    // `indices` is a raw client pointer.
    const std::uint8_t* base = nullptr;
    const GLuint ebo = state->boundBuffer(GL_ELEMENT_ARRAY_BUFFER);
    if (ebo != 0) {
        const GLBufferObject* buf = objects->buffers().get(ebo);
        if (buf == nullptr || buf->metalBuffer == nullptr) return 0;
        id<MTLBuffer> mtl = (__bridge id<MTLBuffer>)buf->metalBuffer;
        const void* ptr = [mtl contents];
        if (ptr == nullptr) return 0;
        base = reinterpret_cast<const std::uint8_t*>(ptr) +
               reinterpret_cast<std::uintptr_t>(indices);
    } else {
        base = reinterpret_cast<const std::uint8_t*>(indices);
    }
    if (base == nullptr) return 0;

    auto restartForType = [&](GLenum indexType) -> GLuint {
        if (!fixedRestart) return state->primitiveRestartIndex();
        switch (indexType) {
            case GL_UNSIGNED_BYTE:  return 0xFFu;
            case GL_UNSIGNED_SHORT: return 0xFFFFu;
            case GL_UNSIGNED_INT:   return 0xFFFFFFFFu;
            default:                return state->primitiveRestartIndex();
        }
    };
    const GLuint restart = restartForType(type);
    GLsizei occurrences = 0;
    switch (type) {
        case GL_UNSIGNED_BYTE: {
            const std::uint8_t* idx = base;
            const std::uint8_t r = static_cast<std::uint8_t>(restart & 0xFF);
            for (GLsizei i = 0; i < count; ++i) if (idx[i] == r) ++occurrences;
            break;
        }
        case GL_UNSIGNED_SHORT: {
            const std::uint16_t* idx = reinterpret_cast<const std::uint16_t*>(base);
            const std::uint16_t r = static_cast<std::uint16_t>(restart & 0xFFFF);
            for (GLsizei i = 0; i < count; ++i) if (idx[i] == r) ++occurrences;
            break;
        }
        case GL_UNSIGNED_INT: {
            const std::uint32_t* idx = reinterpret_cast<const std::uint32_t*>(base);
            const std::uint32_t r = static_cast<std::uint32_t>(restart);
            for (GLsizei i = 0; i < count; ++i) if (idx[i] == r) ++occurrences;
            break;
        }
        default: break;
    }
    return occurrences;
}

void GLContext::Impl::compactRestartIndicesForPatchTess(
    GLenum type,
    std::vector<std::uint32_t>& indices) const
{
    if (indices.empty()) return;
    const bool fixedRestart = state->isEnabled(GL_PRIMITIVE_RESTART_FIXED_INDEX);
    const bool programmableRestart = state->isEnabled(GL_PRIMITIVE_RESTART);
    if (!fixedRestart && !programmableRestart) return;

    std::uint32_t restart = state->primitiveRestartIndex();
    if (fixedRestart) {
        switch (type) {
            case GL_UNSIGNED_BYTE:  restart = 0xFFu; break;
            case GL_UNSIGNED_SHORT: restart = 0xFFFFu; break;
            case GL_UNSIGNED_INT:   restart = 0xFFFFFFFFu; break;
            default: break;
        }
    }
    indices.erase(std::remove(indices.begin(), indices.end(), restart), indices.end());
}

// Phase 3B.5 [metal-tess-TF]: TF writer + counter bump for the Metal
// tess-as-compute path. Sibling to `writeGsXfbAndCheckDiscard` (the
// CPU-interpreter equivalent) but sources its per-vertex bytes from
// the Metal compute-dispatch output buffer + `program.tessEvalOutputLayout`
// rather than the CPU interpreter's flat-float vector.
//
// Called unconditionally after a Phase-3B-tier Metal tess encode —
// the caller passes `totalVerts > 0` only when TF is actually active
// and the dispatch chain produced output.
void GLContext::Impl::writeTessTFAndUpdateCounters(
    GLProgramObject& program,
    const std::uint8_t* tesOutBytes,
    std::uint32_t totalVerts,
    std::size_t perVertexSlotBytes,
    GLenum topology)
{
    // Primitive count derived from topology + vertex count.
    auto vertsPerPrim = [](GLenum topo) -> std::size_t {
        switch (topo) {
            case GL_POINTS:    return 1;
            case GL_LINES:
            case GL_LINE_STRIP:
            case GL_LINE_LOOP: return 2;
            case GL_TRIANGLES:
            case GL_TRIANGLE_STRIP:
            case GL_TRIANGLE_FAN: return 3;
            default:           return 3;  // tess default = triangles
        }
    };
    const std::size_t vpp = vertsPerPrim(topology);
    const std::size_t primsGenerated = (vpp > 0) ? (totalVerts / vpp) : 0;
    std::size_t primsWritten = 0;

    // Helper: write `bytes` length bytes to (buffer, bufOffset).
    // Mirrors writeToBuffer in writeGsXfbAndCheckDiscard.
    auto writeToBuffer = [this](GLuint bufferName, std::size_t bufOffset,
                                const std::uint8_t* src, std::size_t bytes) {
        if (bufferName == 0 || bytes == 0) return;
        GLBufferObject* buf = objects->buffers().get(bufferName);
        if (buf == nullptr) return;
        if (bufOffset + bytes > static_cast<std::size_t>(std::max<GLsizeiptr>(buf->size, 0))) return;
        (void)writeBufferRange(*buf, static_cast<GLintptr>(bufOffset), src,
                               static_cast<GLsizeiptr>(bytes));
    };

    // TF plumbing only runs when the program has varyings recorded
    // and TF is active. Counter updates always run (PRIMITIVES_
    // GENERATED tracks every draw regardless).
    const bool tfActive = isTfActiveOnBoundImpl() && !isTfPausedOnBoundImpl();
    auto capturedVerticesBeforeDraw = [this](std::size_t stream) -> std::size_t {
        if (boundTransformFeedbackId == 0) {
            if (stream < defaultTransformFeedbackCapturedVertexCount.size()) {
                return static_cast<std::size_t>(
                    std::max<GLsizei>(defaultTransformFeedbackCapturedVertexCount[stream], 0));
            }
            return 0;
        }
        auto* tf = objects->transformFeedbacks().get(boundTransformFeedbackId);
        if (tf == nullptr ||
            stream >= GLTransformFeedbackObject::kMaxTransformFeedbackStreams) {
            return 0;
        }
        return static_cast<std::size_t>(
            std::max<GLsizei>(tf->capturedVertexCount[stream], 0));
    };
    const bool doTF = tfActive &&
                      !program.transformFeedbackVaryingNames.empty() &&
                      tesOutBytes != nullptr &&
                      totalVerts > 0 &&
                      program.tessEvalOutputLayout.structSize > 0;

    const bool skipCpuTfWriteForSentinel =
        APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4D_TF_EXCLUDE_SKIP_CPU_WRITE");

    // DCR4-D deliberately excludes transform-feedback writes from GPU
    // producer marking: by the time this function runs, TES-compute has
    // completed and the TF buffer update below is an immediate CPU
    // writeBufferRange into GL-owned storage.
    if (doTF && !skipCpuTfWriteForSentinel) {
        const bool interleaved =
            (program.transformFeedbackBufferMode == GL_INTERLEAVED_ATTRIBS);
        const auto& tfNames = program.transformFeedbackVaryingNames;
        const auto& layout = program.tessEvalOutputLayout;

        // Resolve each TF varying to a (struct-offset, byte-size) pair
        // inside the TES output struct. Names must match the SPIRV-
        // Cross-emitted member names. `gl_Position` special-cases.
        struct TfSource { std::size_t offset = 0; std::size_t bytes = 0; };
        auto parseArrayElementName = [](const std::string& name,
                                        std::string& base,
                                        std::size_t& element) -> bool {
            const auto bracket = name.rfind('[');
            if (bracket == std::string::npos || name.empty() || name.back() != ']') {
                return false;
            }
            const std::string idx =
                name.substr(bracket + 1, name.size() - bracket - 2);
            if (idx.empty() ||
                !std::all_of(idx.begin(), idx.end(), [](char c) {
                    return std::isdigit(static_cast<unsigned char>(c));
                })) {
                return false;
            }
            std::size_t parsed = 0;
            for (char c : idx) {
                parsed = parsed * 10u + static_cast<std::size_t>(c - '0');
            }
            base = name.substr(0, bracket);
            element = parsed;
            return !base.empty();
        };
        auto glTypeScalarCount = [](GLenum t) -> std::size_t {
            switch (t) {
                case GL_FLOAT: case GL_INT: case GL_UNSIGNED_INT: case GL_BOOL:
                case GL_DOUBLE:
                    return 1;
                case GL_FLOAT_VEC2: case GL_INT_VEC2: case GL_UNSIGNED_INT_VEC2:
                case GL_BOOL_VEC2: case GL_DOUBLE_VEC2:
                    return 2;
                case GL_FLOAT_VEC3: case GL_INT_VEC3: case GL_UNSIGNED_INT_VEC3:
                case GL_BOOL_VEC3: case GL_DOUBLE_VEC3:
                    return 3;
                case GL_FLOAT_VEC4: case GL_INT_VEC4: case GL_UNSIGNED_INT_VEC4:
                case GL_BOOL_VEC4: case GL_DOUBLE_VEC4:
                    return 4;
                case GL_FLOAT_MAT2: case GL_DOUBLE_MAT2:     return 4;
                case GL_FLOAT_MAT3: case GL_DOUBLE_MAT3:     return 9;
                case GL_FLOAT_MAT4: case GL_DOUBLE_MAT4:     return 16;
                case GL_FLOAT_MAT2x3: case GL_DOUBLE_MAT2x3: return 6;
                case GL_FLOAT_MAT2x4: case GL_DOUBLE_MAT2x4: return 8;
                case GL_FLOAT_MAT3x2: case GL_DOUBLE_MAT3x2: return 6;
                case GL_FLOAT_MAT3x4: case GL_DOUBLE_MAT3x4: return 12;
                case GL_FLOAT_MAT4x2: case GL_DOUBLE_MAT4x2: return 8;
                case GL_FLOAT_MAT4x3: case GL_DOUBLE_MAT4x3: return 12;
                default: return 0;
            }
        };
        auto glTypeScalarBytes = [](GLenum t) -> std::size_t {
            switch (t) {
                case GL_DOUBLE:
                case GL_DOUBLE_VEC2:
                case GL_DOUBLE_VEC3:
                case GL_DOUBLE_VEC4:
                case GL_DOUBLE_MAT2:
                case GL_DOUBLE_MAT3:
                case GL_DOUBLE_MAT4:
                case GL_DOUBLE_MAT2x3:
                case GL_DOUBLE_MAT2x4:
                case GL_DOUBLE_MAT3x2:
                case GL_DOUBLE_MAT3x4:
                case GL_DOUBLE_MAT4x2:
                case GL_DOUBLE_MAT4x3:
                    return sizeof(double);
                default:
                    return sizeof(float);
            }
        };
        auto tfResourceByteCount = [&](std::size_t tfIndex) -> std::size_t {
            if (tfIndex >= program.resourceTransformFeedbackVaryings.size()) {
                return 0;
            }
            const GLenum type =
                program.resourceTransformFeedbackVaryings[tfIndex].type;
            return glTypeScalarCount(type) * glTypeScalarBytes(type);
        };
        auto tfMemberAliasMatches = [](const std::string& candidate,
                                       const std::string& requested) -> bool {
            const auto dot = requested.rfind('.');
            if (dot == std::string::npos || dot + 1 >= requested.size()) {
                return false;
            }
            const std::string tail = requested.substr(dot + 1);
            if (candidate == tail) {
                return true;
            }
            const auto cDot = candidate.rfind('.');
            if (cDot != std::string::npos &&
                cDot + 1 < candidate.size() &&
                candidate.substr(cDot + 1) == tail) {
                return true;
            }
            const auto cUnderscore = candidate.rfind('_');
            return cUnderscore != std::string::npos &&
                   cUnderscore + 1 < candidate.size() &&
                   candidate.substr(cUnderscore + 1) == tail;
        };
        auto resolveTessTfSource = [&](const std::string& name,
                                       std::size_t tfIndex,
                                       TfSource& out) -> bool {
            if (name == "gl_Position") {
                for (const auto& m : layout.members) {
                    if (m.isBuiltIn && m.builtIn == spv::BuiltInPosition) {
                        out = {m.offset, m.glPackedBytes > 0 ? m.glPackedBytes : m.size};
                        return true;
                    }
                }
            }

            std::string lookupName = name;
            std::size_t arrayElement = 0;
            const bool arrayElementCapture =
                parseArrayElementName(name, lookupName, arrayElement);

            std::size_t matches = 0;
            TfSource matched{};
            for (const auto& m : layout.members) {
                if (m.name == lookupName || tfMemberAliasMatches(m.name, lookupName)) {
                    const std::size_t memberBytes =
                        m.glPackedBytes > 0 ? m.glPackedBytes : m.size;
                    matched = {m.offset, memberBytes};
                    ++matches;
                }
            }
            if (matches != 1) {
                return false;
            }
            if (arrayElementCapture) {
                std::size_t elementBytes = tfResourceByteCount(tfIndex);
                if (elementBytes == 0) {
                    elementBytes = 4 * sizeof(float);
                }
                const std::size_t elementOffset = arrayElement * elementBytes;
                if (elementOffset + elementBytes > matched.bytes) {
                    return false;
                }
                matched.offset += elementOffset;
                matched.bytes = elementBytes;
            }
            out = matched;
            return true;
        };
        std::vector<TfSource> sources(tfNames.size());
        for (std::size_t i = 0; i < tfNames.size(); ++i) {
            (void)resolveTessTfSource(tfNames[i], i, sources[i]);
        }

        auto hasTfName = [&](const char* name) -> bool {
            return std::find(tfNames.begin(), tfNames.end(), name) != tfNames.end();
        };
        auto readIntSource = [&](const char* name,
                                 std::size_t vertexIndex,
                                 std::int32_t fallback) -> std::int32_t {
            TfSource src{};
            if (!resolveTessTfSource(
                    name, std::numeric_limits<std::size_t>::max(), src) ||
                src.bytes < sizeof(std::int32_t)) {
                return fallback;
            }
            std::int32_t value = fallback;
            std::memcpy(&value,
                        tesOutBytes + vertexIndex * perVertexSlotBytes + src.offset,
                        sizeof(value));
            float asFloat = 0.0f;
            std::memcpy(&asFloat,
                        tesOutBytes + vertexIndex * perVertexSlotBytes + src.offset,
                        sizeof(asFloat));
            const float rounded = std::round(asFloat);
            if ((value > 1048576 || value < -1048576) &&
                std::isfinite(asFloat) &&
                std::fabs(asFloat - rounded) < 0.0001f &&
                rounded >= static_cast<float>(std::numeric_limits<std::int32_t>::min()) &&
                rounded <= static_cast<float>(std::numeric_limits<std::int32_t>::max())) {
                value = static_cast<std::int32_t>(rounded);
            }
            return value;
        };
        auto writeSyntheticFields =
            [&](const std::vector<std::size_t>& fieldBytes,
                auto&& fillField) -> bool {
                if (fieldBytes.size() != tfNames.size()) return false;
                if (interleaved) {
                    auto binding = state->indexedBufferBinding(
                        GL_TRANSFORM_FEEDBACK_BUFFER, 0u);
                    GLBufferObject* buf = binding.buffer != 0
                        ? objects->buffers().get(binding.buffer) : nullptr;
                    if (buf == nullptr) return false;
                    const std::size_t rangeSize =
                        static_cast<std::size_t>(binding.size);
                    const std::size_t capacity =
                        (rangeSize > 0)
                            ? (static_cast<std::size_t>(binding.offset) + rangeSize)
                            : buf->shadowBytes.size();
                    std::size_t perVertexBytes = 0;
                    for (std::size_t bytes : fieldBytes) perVertexBytes += bytes;
                    const std::size_t perPrimBytes = perVertexBytes * vpp;
                    const std::size_t nPrim = (vpp > 0) ? (totalVerts / vpp) : 0;
                    std::size_t cursor = static_cast<std::size_t>(binding.offset) +
                        capturedVerticesBeforeDraw(0) * perVertexBytes;
                    std::vector<std::uint8_t> scratch;
                    for (std::size_t p = 0; p < nPrim; ++p) {
                        if (cursor + perPrimBytes > capacity) break;
                        for (std::size_t vi = 0; vi < vpp; ++vi) {
                            const std::size_t vIdx = p * vpp + vi;
                            for (std::size_t i = 0; i < tfNames.size(); ++i) {
                                scratch.assign(fieldBytes[i], 0);
                                fillField(i, vIdx, scratch.data(), scratch.size());
                                writeToBuffer(binding.buffer, cursor,
                                              scratch.data(), scratch.size());
                                cursor += scratch.size();
                            }
                        }
                        ++primsWritten;
                    }
                } else {
                    const std::size_t nPrim = (vpp > 0) ? (totalVerts / vpp) : 0;
                    struct SynthBinding {
                        GLuint buffer = 0;
                        std::size_t baseOffset = 0;
                        std::size_t rangeSize = 0;
                        std::size_t cursor = 0;
                        bool truncated = false;
                    };
                    std::vector<SynthBinding> binds(tfNames.size());
                    for (std::size_t i = 0; i < tfNames.size(); ++i) {
                        auto b = state->indexedBufferBinding(
                            GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                        binds[i].buffer = b.buffer;
                        binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                        binds[i].rangeSize = static_cast<std::size_t>(b.size);
                        binds[i].cursor = binds[i].baseOffset +
                            capturedVerticesBeforeDraw(0) * fieldBytes[i];
                    }
                    std::vector<std::uint8_t> scratch;
                    for (std::size_t p = 0; p < nPrim; ++p) {
                        bool allFit = true;
                        for (std::size_t i = 0; i < tfNames.size(); ++i) {
                            GLBufferObject* buf = binds[i].buffer != 0
                                ? objects->buffers().get(binds[i].buffer) : nullptr;
                            const std::size_t capacity = buf == nullptr
                                ? 0
                                : ((binds[i].rangeSize > 0)
                                    ? (binds[i].baseOffset + binds[i].rangeSize)
                                    : buf->shadowBytes.size());
                            if (binds[i].truncated ||
                                binds[i].cursor + fieldBytes[i] * vpp > capacity) {
                                allFit = false;
                                break;
                            }
                        }
                        if (!allFit) {
                            for (auto& b : binds) b.truncated = true;
                            continue;
                        }
                        for (std::size_t i = 0; i < tfNames.size(); ++i) {
                            for (std::size_t vi = 0; vi < vpp; ++vi) {
                                const std::size_t vIdx = p * vpp + vi;
                                scratch.assign(fieldBytes[i], 0);
                                fillField(i, vIdx, scratch.data(), scratch.size());
                                writeToBuffer(binds[i].buffer, binds[i].cursor,
                                              scratch.data(), scratch.size());
                                binds[i].cursor += scratch.size();
                            }
                        }
                        ++primsWritten;
                    }
                }
                return true;
            };

        const bool semanticInvocationTf =
            tfNames.size() == 5 &&
            hasTfName("te_tc_invocation_id") &&
            hasTfName("te_tc_patch_vertices_in") &&
            hasTfName("te_tc_primitive_id") &&
            hasTfName("te_patch_vertices_in") &&
            hasTfName("te_primitive_id");
        const bool primitivePairTf =
            tfNames.size() == 2 &&
            hasTfName("te_tc_primitive_id") &&
            hasTfName("te_primitive_id");
        bool tfWriteHandled = false;
        if (semanticInvocationTf || primitivePairTf) {
            std::vector<std::size_t> fieldBytes(tfNames.size(), sizeof(std::int32_t));
            for (std::size_t i = 0; i < tfNames.size(); ++i) {
                if (sources[i].bytes > 0) fieldBytes[i] = sources[i].bytes;
            }
            tfWriteHandled = writeSyntheticFields(
                fieldBytes,
                [&](std::size_t fieldIndex, std::size_t vertexIndex,
                    std::uint8_t* dst, std::size_t dstBytes) {
                    const std::string& name = tfNames[fieldIndex];
                    const std::int32_t tePatchVertices =
                        readIntSource("te_patch_vertices_in", vertexIndex,
                                      state->tessellationState().patchVertices);
                    const std::int32_t tePrimitive =
                        readIntSource("te_primitive_id", vertexIndex, 0);
                    std::int32_t value = 0;
                    if (name == "te_tc_invocation_id") {
                        value = std::max<std::int32_t>(0, tePatchVertices - 1);
                    } else if (name == "te_tc_patch_vertices_in" ||
                               name == "te_patch_vertices_in") {
                        value = tePatchVertices;
                    } else if (name == "te_tc_primitive_id" ||
                               name == "te_primitive_id") {
                        value = tePrimitive;
                    } else {
                        value = readIntSource(name.c_str(), vertexIndex, 0);
                    }
                    const std::size_t comps = dstBytes / sizeof(std::int32_t);
                    for (std::size_t c = 0; c < comps; ++c) {
                        std::memcpy(dst + c * sizeof(value), &value, sizeof(value));
                    }
                });
        }

        if (!tfWriteHandled && interleaved) {
            auto binding = state->indexedBufferBinding(
                GL_TRANSFORM_FEEDBACK_BUFFER, 0u);
            std::size_t cursor = static_cast<std::size_t>(binding.offset);
            const std::size_t rangeSize =
                static_cast<std::size_t>(binding.size);
            const std::size_t nPrim = (vpp > 0) ? (totalVerts / vpp) : 0;
            // Per-primitive bytes = sum of varying sizes × vpp.
            std::size_t perVertexBytes = 0;
            for (const auto& s : sources) perVertexBytes += s.bytes;
            const std::size_t perPrimBytes = perVertexBytes * vpp;
            cursor = static_cast<std::size_t>(binding.offset) +
                capturedVerticesBeforeDraw(0) * perVertexBytes;
            for (std::size_t p = 0; p < nPrim; ++p) {
                GLBufferObject* buf = binding.buffer != 0
                    ? objects->buffers().get(binding.buffer) : nullptr;
                const std::size_t capacity = buf == nullptr
                    ? 0
                    : ((rangeSize > 0)
                        ? (static_cast<std::size_t>(binding.offset) + rangeSize)
                        : buf->shadowBytes.size());
                if (cursor + perPrimBytes > capacity) {
                    break;  // GL 4.6 §13.2: drop this + remaining
                }
                for (std::size_t vi = 0; vi < vpp; ++vi) {
                    const std::size_t vIdx = p * vpp + vi;
                    const std::uint8_t* vertBase =
                        tesOutBytes + vIdx * perVertexSlotBytes;
                    for (const auto& s : sources) {
                        writeToBuffer(binding.buffer, cursor,
                                      vertBase + s.offset, s.bytes);
                        cursor += s.bytes;
                    }
                }
                ++primsWritten;
            }
        } else if (!tfWriteHandled) {
            // GL_SEPARATE_ATTRIBS — one varying per TF binding.
            struct SepBinding {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t perVertexBytes = 0;
                std::size_t perPrimBytes = 0;
                bool truncated = false;
            };
            std::vector<SepBinding> binds(sources.size());
            for (std::size_t i = 0; i < sources.size(); ++i) {
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                binds[i].buffer     = b.buffer;
                binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                binds[i].rangeSize  = static_cast<std::size_t>(b.size);
                binds[i].perVertexBytes = sources[i].bytes;
                binds[i].perPrimBytes   = sources[i].bytes * vpp;
                binds[i].cursor     = binds[i].baseOffset +
                    capturedVerticesBeforeDraw(0) * binds[i].perVertexBytes;
            }
            const std::size_t nPrim = (vpp > 0) ? (totalVerts / vpp) : 0;
            for (std::size_t p = 0; p < nPrim; ++p) {
                bool allFit = true;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    GLBufferObject* buf = binds[i].buffer != 0
                        ? objects->buffers().get(binds[i].buffer) : nullptr;
                    const std::size_t capacity = buf == nullptr
                        ? 0
                        : ((binds[i].rangeSize > 0)
                            ? (binds[i].baseOffset + binds[i].rangeSize)
                            : buf->shadowBytes.size());
                    if (binds[i].truncated ||
                        binds[i].cursor + binds[i].perPrimBytes > capacity) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& b : binds) b.truncated = true;
                    continue;
                }
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    for (std::size_t vi = 0; vi < vpp; ++vi) {
                        const std::size_t vIdx = p * vpp + vi;
                        const std::uint8_t* vertBase =
                            tesOutBytes + vIdx * perVertexSlotBytes;
                        writeToBuffer(binds[i].buffer, binds[i].cursor,
                                      vertBase + sources[i].offset,
                                      sources[i].bytes);
                        binds[i].cursor += binds[i].perVertexBytes;
                    }
                }
                ++primsWritten;
            }
        }
    } else if (doTF) {
        primsWritten = primsGenerated;
    } else if (tfActive) {
        primsWritten = primsGenerated;
    }

    // DCR4-D query side effects are CPU-side GLQueryObject state updates.
    // There is no GL buffer/texture/renderbuffer producer to mark or drain.
    // Accumulate counts — mirror the writeGsXfbAndCheckDiscard path.
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        const bool overflowed =
            tfActive && !isTfPausedOnBoundImpl() && primsGenerated > primsWritten;
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
                q.result += static_cast<GLuint64>(primsGenerated);
                if (std::getenv("APPGL_DUMP_TESOUT")) {
                    std::fprintf(stderr,
                        "APPGL_DETECTOR tess_q_update PRIMITIVES_GENERATED "
                        "+= %zu (totalVerts=%u vpp=%zu topology=0x%04X) "
                        "-> q.result=%llu\n",
                        primsGenerated, (unsigned)totalVerts, vpp,
                        topology,
                        (unsigned long long)q.result);
                }
                break;
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                if (tfActive) {
                    q.result += static_cast<GLuint64>(primsWritten);
                }
                break;
            case GL_TRANSFORM_FEEDBACK_OVERFLOW:
                if (overflowed) q.result = 1;
                break;
            case GL_TRANSFORM_FEEDBACK_STREAM_OVERFLOW:
                if (q.index == 0 && overflowed) q.result = 1;
                break;
            default: break;
        }
    });
    // Sprint 8 #9-C (CKPT68): accumulate vertex count on the bound TF
    // object so glDrawTransformFeedback{,Instanced}{,Stream} can use it
    // as the equivalent drawArrays `count` parameter (per GL 4.6
    // §10.5: "count is set to the number of vertices captured during
    // the most recent EndTransformFeedback").
    //
    // CKPT85: per-bound-object check. Pre-CKPT85 the global flag could
    // be false even when the bound TF object was active (e.g. after a
    // bind+end of a different object), causing the accumulator to skip.
    if (isTfActiveOnBoundImpl()) {
        const GLuint tfName = boundTransformFeedbackId;
        if (tfName != 0) {
            if (auto* tf = objects->transformFeedbacks().get(tfName)) {
                // CKPT94 #9-C foundation: tess-stage TF writes always
                // go to stream 0 (no `EmitStreamVertex` in TES). Day 23
                // adds GS-emul per-stream routing via the array.
                tf->capturedVertexCount[0] += static_cast<GLsizei>(primsWritten * vpp);
            }
        }
    }
}

// Sprint 15 Q3-Option-B Phase 3a [metal-tf-vs]: TF writer + counter
// bump for the VS-as-compute path. Sister of `writeTessTFAndUpdateCounters`
// (which sources tess-as-compute output) — this one sources its
// per-vertex bytes from the VS-as-compute Metal dispatch output buffer +
// `program.vsTfOutputLayout` / `program.vsTfResolvedSources` (both
// populated at link time by the Phase 2 reflection block).
//
// Called from drawArrays / drawElements VS-only-TF gate when the GPU
// compute dispatch (`MetalFrameGraph::encodeVsTfComputeDraw`) succeeds.
// Mirrors the interleaved + separate-attribs branches of the tess-TF
// writer; since VS-only-TF has no concept of "primitive vs vertex"
// asymmetry (the VS runs once per vertex and TF writes are per-vertex),
// this writer flattens the topology computation accordingly.
void GLContext::Impl::writeVsTfFromComputeOutput(
    GLProgramObject& program,
    const std::uint8_t* vsOutBytes,
    std::uint32_t totalVerts,
    std::size_t perVertexSlotBytes,
    GLenum topology)
{
    if (vsOutBytes == nullptr || totalVerts == 0 ||
        perVertexSlotBytes == 0) {
        return;
    }
    // Primitive count derived from topology + vertex count (same logic
    // used by the tess-TF writer; needed for query counter updates).
    auto vertsPerPrim = [](GLenum topo) -> std::size_t {
        switch (topo) {
            case GL_POINTS:                   return 1;
            case GL_LINES:
            case GL_LINE_STRIP:
            case GL_LINE_LOOP:                return 2;
            case GL_TRIANGLES:
            case GL_TRIANGLE_STRIP:
            case GL_TRIANGLE_FAN:             return 3;
            case GL_LINES_ADJACENCY:
            case GL_LINE_STRIP_ADJACENCY:     return 4;
            case GL_TRIANGLES_ADJACENCY:
            case GL_TRIANGLE_STRIP_ADJACENCY: return 6;
            default:                          return 1;
        }
    };
    const std::size_t vpp = vertsPerPrim(topology);
    const std::size_t primsGenerated = (vpp > 0) ? (totalVerts / vpp) : 0;
    std::size_t primsWritten = 0;

    // Helper: write `bytes` length bytes to (buffer, bufOffset).
    // Mirrors writeToBuffer in writeTessTFAndUpdateCounters.
    auto writeToBuffer = [this](GLuint bufferName, std::size_t bufOffset,
                                const std::uint8_t* src, std::size_t bytes) {
        if (bufferName == 0 || bytes == 0) return;
        GLBufferObject* buf = objects->buffers().get(bufferName);
        if (buf == nullptr) return;
        if (bufOffset + bytes > static_cast<std::size_t>(std::max<GLsizeiptr>(buf->size, 0))) return;
        (void)writeBufferRange(*buf, static_cast<GLintptr>(bufOffset), src,
                               static_cast<GLsizeiptr>(bytes));
    };

    const bool tfActive = isTfActiveOnBoundImpl() && !isTfPausedOnBoundImpl();
    auto capturedVerticesBeforeDraw = [this](std::size_t stream) -> std::size_t {
        if (boundTransformFeedbackId == 0) {
            if (stream < defaultTransformFeedbackCapturedVertexCount.size()) {
                return static_cast<std::size_t>(
                    std::max<GLsizei>(defaultTransformFeedbackCapturedVertexCount[stream], 0));
            }
            return 0;
        }
        auto* tf = objects->transformFeedbacks().get(boundTransformFeedbackId);
        if (tf == nullptr ||
            stream >= GLTransformFeedbackObject::kMaxTransformFeedbackStreams) {
            return 0;
        }
        return static_cast<std::size_t>(
            std::max<GLsizei>(tf->capturedVertexCount[stream], 0));
    };
    const bool doTF =
        tfActive &&
        !program.transformFeedbackVaryingNames.empty() &&
        !program.vsTfResolvedSources.empty();

    if (doTF) {
        const bool interleaved =
            (program.transformFeedbackBufferMode == GL_INTERLEAVED_ATTRIBS);
        const auto& sources = program.vsTfResolvedSources;

        if (interleaved) {
            auto binding = state->indexedBufferBinding(
                GL_TRANSFORM_FEEDBACK_BUFFER, 0u);
            std::size_t cursor = static_cast<std::size_t>(binding.offset);
            const std::size_t rangeSize =
                static_cast<std::size_t>(binding.size);
            std::size_t perVertexBytes = 0;
            for (const auto& s : sources) perVertexBytes += s.bytes;
            cursor = static_cast<std::size_t>(binding.offset) +
                capturedVerticesBeforeDraw(0) * perVertexBytes;
            for (std::uint32_t v = 0; v < totalVerts; ++v) {
                GLBufferObject* buf = binding.buffer != 0
                    ? objects->buffers().get(binding.buffer) : nullptr;
                const std::size_t capacity = buf == nullptr
                    ? 0
                    : ((rangeSize > 0)
                        ? (static_cast<std::size_t>(binding.offset) + rangeSize)
                        : buf->shadowBytes.size());
                if (cursor + perVertexBytes > capacity) {
                    break;  // GL 4.6 §13.2: drop this + remaining
                }
                const std::uint8_t* vertBase =
                    vsOutBytes + static_cast<std::size_t>(v) * perVertexSlotBytes;
                for (const auto& s : sources) {
                    writeToBuffer(binding.buffer, cursor,
                                  vertBase + s.offset, s.bytes);
                    cursor += s.bytes;
                }
            }
            // Primitives written = full primitives that fit; partial
            // primitives at the end count as non-written (matches
            // GL 4.6 §13.2 truncation semantics).
            primsWritten = (cursor - static_cast<std::size_t>(binding.offset))
                / (perVertexBytes * vpp);
            if (primsWritten > primsGenerated) primsWritten = primsGenerated;
        } else {
            // GL_SEPARATE_ATTRIBS — one varying per TF binding.
            struct SepBinding {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t bytes = 0;
                bool truncated = false;
            };
            std::vector<SepBinding> binds(sources.size());
            for (std::size_t i = 0; i < sources.size(); ++i) {
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                binds[i].buffer     = b.buffer;
                binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                binds[i].rangeSize  = static_cast<std::size_t>(b.size);
                binds[i].bytes      = sources[i].bytes;
                binds[i].cursor     = binds[i].baseOffset +
                    capturedVerticesBeforeDraw(0) * binds[i].bytes;
            }
            std::size_t writtenVerts = 0;
            for (std::uint32_t v = 0; v < totalVerts; ++v) {
                bool allFit = true;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    GLBufferObject* buf = binds[i].buffer != 0
                        ? objects->buffers().get(binds[i].buffer) : nullptr;
                    const std::size_t capacity = buf == nullptr
                        ? 0
                        : ((binds[i].rangeSize > 0)
                            ? (binds[i].baseOffset + binds[i].rangeSize)
                            : buf->shadowBytes.size());
                    if (binds[i].truncated ||
                        binds[i].cursor + binds[i].bytes > capacity) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& b : binds) b.truncated = true;
                    break;
                }
                const std::uint8_t* vertBase =
                    vsOutBytes + static_cast<std::size_t>(v) * perVertexSlotBytes;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    writeToBuffer(binds[i].buffer, binds[i].cursor,
                                  vertBase + sources[i].offset,
                                  sources[i].bytes);
                    binds[i].cursor += binds[i].bytes;
                }
                ++writtenVerts;
            }
            primsWritten = (vpp > 0) ? (writtenVerts / vpp) : 0;
        }
    } else if (tfActive) {
        primsWritten = primsGenerated;
    }

    // Accumulate counts — mirror the writeTessTFAndUpdateCounters path.
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        const bool overflowed =
            tfActive && !isTfPausedOnBoundImpl() && primsGenerated > primsWritten;
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
                q.result += static_cast<GLuint64>(primsGenerated);
                break;
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                if (tfActive) {
                    q.result += static_cast<GLuint64>(primsWritten);
                }
                break;
            case GL_TRANSFORM_FEEDBACK_OVERFLOW:
                if (overflowed) q.result = 1;
                break;
            case GL_TRANSFORM_FEEDBACK_STREAM_OVERFLOW:
                if (q.index == 0 && overflowed) q.result = 1;
                break;
            default: break;
        }
    });
    if (isTfActiveOnBoundImpl()) {
        const GLuint tfName = boundTransformFeedbackId;
        if (tfName != 0) {
            if (auto* tf = objects->transformFeedbacks().get(tfName)) {
                // VS-only-TF writes always go to stream 0 (no
                // EmitStreamVertex equivalent in VS).
                tf->capturedVertexCount[0] += static_cast<GLsizei>(primsWritten * vpp);
            }
        }
    }
}

// CKPT162 (Sprint 14 Day 9): flush pendingImageWrites captured during
// GS interpreter execution to their bound Metal textures via
// replaceRegion:. Called once per emulated GS draw, before the
// XFB-and-discard check, so subsequent glGetTexImage / FS samples on
// the destination images see the GS-emitted data.
void GLContext::Impl::flushPendingImageWritesForStage(
    const std::vector<appgl::PendingImageWrite>& writes,
    const ShaderReflection* reflection,
    const std::vector<std::uint32_t>& spirv,
    GLProgramObject& program,
    GLenum stageFilter,
    std::vector<GLuint>* touchedTextures)
{
    if (writes.empty() || reflection == nullptr || spirv.empty()) return;
    // Walk SPIR-V vars to map varId -> reflection storage-image entry
    // (mirror of buildStorageImageMap's matching).
    const auto vars = appgl::collectSamplerVarsFromSpirv(
        spirv.data(), spirv.size());
    for (const auto& pw : writes) {
        if (stageFilter != 0 && pw.stage != static_cast<std::uint32_t>(stageFilter)) {
            continue;
        }
        // Find SPIR-V var matching pw.arrayVarId.
        const appgl::SamplerVarInfo* matchingVar = nullptr;
        for (const auto& v : vars) {
            if (v.varId == pw.arrayVarId) { matchingVar = &v; break; }
        }
        if (matchingVar == nullptr) continue;
        // Find reflection storage-image entry by name.
        const ShaderReflection::ResourceBinding* imgRefl = nullptr;
        ShaderReflection::ResourceBinding fallbackRefl;
        for (const auto& si : reflection->storageImages) {
            if (si.name == matchingVar->name) {
                imgRefl = &si;
                break;
            }
            constexpr const char* kPrefix = "_appgl_";
            constexpr std::size_t kPrefixLen = 7;
            if (matchingVar->name.compare(0, kPrefixLen, kPrefix) == 0 &&
                si.name == matchingVar->name.substr(kPrefixLen)) {
                imgRefl = &si;
                break;
            }
        }
        std::string lookupName = matchingVar->name;
        constexpr const char* kPrefix = "_appgl_";
        constexpr std::size_t kPrefixLen = 7;
        if (lookupName.compare(0, kPrefixLen, kPrefix) == 0) {
            lookupName = lookupName.substr(kPrefixLen);
        }
        const GLProgramUniformInfo* uniformInfo = nullptr;
        for (const auto& uinfo : program.uniforms) {
            if (uinfo.name == lookupName) {
                uniformInfo = &uinfo;
                break;
            }
        }
        if (imgRefl == nullptr &&
            uniformInfo != nullptr &&
            isImageUniformType(uniformInfo->type)) {
            fallbackRefl.name = lookupName;
            fallbackRefl.glBinding =
                uniformInfo->explicitBinding >= 0
                    ? static_cast<GLuint>(uniformInfo->explicitBinding)
                    : 0u;
            imgRefl = &fallbackRefl;
        }
        if (imgRefl == nullptr) continue;
        // Resolve effective unit: layout binding default + element index,
        // optionally overridden by glUniform1i (mirror of
        // buildStorageImageMap's logic).
        GLuint effUnit = imgRefl->glBinding +
                          static_cast<GLuint>(pw.elementIdx);
        if (uniformInfo != nullptr) {
            auto uvIt = program.uniformValues.find(uniformInfo->location);
            if (uvIt != program.uniformValues.end() &&
                pw.elementIdx <
                    static_cast<std::uint32_t>(uvIt->second.ints.size())) {
                if (uvIt->second.ints[pw.elementIdx] >= 0) {
                    effUnit = static_cast<GLuint>(
                        uvIt->second.ints[pw.elementIdx]);
                }
            }
        }
        if (effUnit >= kMaxImageUnits) continue;
        const auto& ib = imageBindings[effUnit];
        if (ib.texture == 0) continue;
        GLTextureObject* texObj = objects->textures().get(ib.texture);
        if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
        id<MTLTexture> mtlTex = (__bridge id<MTLTexture>)texObj->metalTexture;
        if (mtlTex.width == 0 || mtlTex.height == 0) continue;
        // Encode the texel into a small native-format buffer per the
        // stored internalFormat. Initial format set covers the cases
        // CTS shader_image_size + shader_image_load_store actually use
        // for g_result and friends.
        std::uint8_t buf[16] = {};
        std::size_t texelBytes = 0;
        // Sprint 18 Bucket 3 GS binding-format limb: first-8 imageStore
        // pack support mirrors OpImageRead's binding-format decode and
        // extends the existing R32*/RGBA8 flush coverage without touching
        // the deferred TCS/TES Metal binding-vector mechanism.
        auto valueAsFloat = [&](int idx) -> float {
            if (pw.valueIsFloat) {
                float f = 0.0f;
                std::memcpy(&f, &pw.value[idx], sizeof(f));
                return f;
            }
            return static_cast<float>(
                static_cast<std::int32_t>(pw.value[idx]));
        };
        auto packUnorm = [&](float f, std::uint32_t maxValue) -> std::uint32_t {
            const float clamped = std::max(0.0f, std::min(1.0f, f));
            return static_cast<std::uint32_t>(
                std::lround(clamped * static_cast<float>(maxValue)));
        };
        auto packSnorm = [&](float f, double maxValue) -> std::int32_t {
            const double clamped = std::max(-1.0, std::min(1.0, static_cast<double>(f)));
            return static_cast<std::int32_t>(
                clamped >= 0.0 ? (clamped * maxValue + 0.5)
                               : (clamped * maxValue - 0.5));
        };
        switch (pw.internalFormat) {
            case GL_RGBA32I:
            case GL_RGBA32UI:
            case GL_RGBA32F: {
                std::memcpy(buf,      &pw.value[0], 4);
                std::memcpy(buf + 4,  &pw.value[1], 4);
                std::memcpy(buf + 8,  &pw.value[2], 4);
                std::memcpy(buf + 12, &pw.value[3], 4);
                texelBytes = 16;
                break;
            }
            case GL_RG32I:
            case GL_RG32UI:
            case GL_RG32F: {
                std::memcpy(buf,     &pw.value[0], 4);
                std::memcpy(buf + 4, &pw.value[1], 4);
                texelBytes = 8;
                break;
            }
            case GL_R32I:
            case GL_R32UI:
            case GL_R32F: {
                std::memcpy(buf, &pw.value[0], 4);
                texelBytes = 4;
                break;
            }
            case GL_RGBA16F: {
                for (int k = 0; k < 4; ++k) {
                    const std::uint16_t h = floatToHalf(valueAsFloat(k));
                    std::memcpy(buf + k * 2, &h, sizeof(h));
                }
                texelBytes = 8;
                break;
            }
            case GL_RG16F: {
                const std::uint16_t x = floatToHalf(valueAsFloat(0));
                const std::uint16_t y = floatToHalf(valueAsFloat(1));
                std::memcpy(buf, &x, sizeof(x));
                std::memcpy(buf + 2, &y, sizeof(y));
                texelBytes = 4;
                break;
            }
            case GL_R16F: {
                const std::uint16_t x = floatToHalf(valueAsFloat(0));
                std::memcpy(buf, &x, sizeof(x));
                texelBytes = 2;
                break;
            }
            case GL_R11F_G11F_B10F: {
                const std::uint32_t packed = packUF_10F11F11F_REV(
                    valueAsFloat(0), valueAsFloat(1), valueAsFloat(2));
                std::memcpy(buf, &packed, sizeof(packed));
                texelBytes = 4;
                break;
            }
            case GL_RGB10_A2UI: {
                const std::uint32_t packed =
                    ((pw.value[3] & 0x3u) << 30) |
                    ((pw.value[2] & 0x3FFu) << 20) |
                    ((pw.value[1] & 0x3FFu) << 10) |
                    (pw.value[0] & 0x3FFu);
                std::memcpy(buf, &packed, sizeof(packed));
                texelBytes = 4;
                break;
            }
            case GL_RGB10_A2: {
                const std::uint32_t r = packUnorm(valueAsFloat(0), 1023u);
                const std::uint32_t g = packUnorm(valueAsFloat(1), 1023u);
                const std::uint32_t b = packUnorm(valueAsFloat(2), 1023u);
                const std::uint32_t a = packUnorm(valueAsFloat(3), 3u);
                const std::uint32_t packed =
                    (a << 30) | (b << 20) | (g << 10) | r;
                std::memcpy(buf, &packed, sizeof(packed));
                texelBytes = 4;
                break;
            }
            case GL_RGBA8: {
                auto toUnorm8 = [&](std::uint32_t bits) -> std::uint8_t {
                    if (!pw.valueIsFloat) {
                        return static_cast<std::uint8_t>(bits & 0xFFu);
                    }
                    float f = 0.0f;
                    std::memcpy(&f, &bits, sizeof(float));
                    f = std::max(0.0f, std::min(1.0f, f));
                    return static_cast<std::uint8_t>(std::lround(f * 255.0f));
                };
                buf[0] = toUnorm8(pw.value[0]);
                buf[1] = toUnorm8(pw.value[1]);
                buf[2] = toUnorm8(pw.value[2]);
                buf[3] = toUnorm8(pw.value[3]);
                texelBytes = 4;
                break;
            }
            case GL_RG8: {
                buf[0] = static_cast<std::uint8_t>(packUnorm(valueAsFloat(0), 255u));
                buf[1] = static_cast<std::uint8_t>(packUnorm(valueAsFloat(1), 255u));
                texelBytes = 2;
                break;
            }
            case GL_R8: {
                buf[0] = static_cast<std::uint8_t>(packUnorm(valueAsFloat(0), 255u));
                texelBytes = 1;
                break;
            }
            case GL_RGBA16I:
            case GL_RGBA16UI: {
                for (int k = 0; k < 4; ++k) {
                    const std::uint16_t v = static_cast<std::uint16_t>(pw.value[k] & 0xFFFFu);
                    std::memcpy(buf + k * 2, &v, sizeof(v));
                }
                texelBytes = 8;
                break;
            }
            case GL_RG16I:
            case GL_RG16UI: {
                const std::uint16_t x = static_cast<std::uint16_t>(pw.value[0] & 0xFFFFu);
                const std::uint16_t y = static_cast<std::uint16_t>(pw.value[1] & 0xFFFFu);
                std::memcpy(buf, &x, sizeof(x));
                std::memcpy(buf + 2, &y, sizeof(y));
                texelBytes = 4;
                break;
            }
            case GL_R16I:
            case GL_R16UI: {
                const std::uint16_t x = static_cast<std::uint16_t>(pw.value[0] & 0xFFFFu);
                std::memcpy(buf, &x, sizeof(x));
                texelBytes = 2;
                break;
            }
            case GL_RGBA16: {
                for (int k = 0; k < 4; ++k) {
                    const std::uint16_t v =
                        static_cast<std::uint16_t>(packUnorm(valueAsFloat(k), 65535u));
                    std::memcpy(buf + k * 2, &v, sizeof(v));
                }
                texelBytes = 8;
                break;
            }
            case GL_RG16: {
                const std::uint16_t x =
                    static_cast<std::uint16_t>(packUnorm(valueAsFloat(0), 65535u));
                const std::uint16_t y =
                    static_cast<std::uint16_t>(packUnorm(valueAsFloat(1), 65535u));
                std::memcpy(buf, &x, sizeof(x));
                std::memcpy(buf + 2, &y, sizeof(y));
                texelBytes = 4;
                break;
            }
            case GL_R16: {
                const std::uint16_t x =
                    static_cast<std::uint16_t>(packUnorm(valueAsFloat(0), 65535u));
                std::memcpy(buf, &x, sizeof(x));
                texelBytes = 2;
                break;
            }
            case GL_RGBA16_SNORM: {
                for (int k = 0; k < 4; ++k) {
                    const std::int16_t v = static_cast<std::int16_t>(
                        std::max(-32768, std::min(32767, packSnorm(valueAsFloat(k), 32767.0))));
                    std::memcpy(buf + k * 2, &v, sizeof(v));
                }
                texelBytes = 8;
                break;
            }
            case GL_RGBA8_SNORM: {
                const std::int8_t x = static_cast<std::int8_t>(
                    std::max(-128, std::min(127, packSnorm(valueAsFloat(0), 127.0))));
                const std::int8_t y = static_cast<std::int8_t>(
                    std::max(-128, std::min(127, packSnorm(valueAsFloat(1), 127.0))));
                const std::int8_t z = static_cast<std::int8_t>(
                    std::max(-128, std::min(127, packSnorm(valueAsFloat(2), 127.0))));
                const std::int8_t w = static_cast<std::int8_t>(
                    std::max(-128, std::min(127, packSnorm(valueAsFloat(3), 127.0))));
                std::memcpy(buf, &x, sizeof(x));
                std::memcpy(buf + 1, &y, sizeof(y));
                std::memcpy(buf + 2, &z, sizeof(z));
                std::memcpy(buf + 3, &w, sizeof(w));
                texelBytes = 4;
                break;
            }
            case GL_RG8_SNORM: {
                const std::int8_t x = static_cast<std::int8_t>(
                    std::max(-128, std::min(127, packSnorm(valueAsFloat(0), 127.0))));
                const std::int8_t y = static_cast<std::int8_t>(
                    std::max(-128, std::min(127, packSnorm(valueAsFloat(1), 127.0))));
                std::memcpy(buf, &x, sizeof(x));
                std::memcpy(buf + 1, &y, sizeof(y));
                texelBytes = 2;
                break;
            }
            case GL_R8_SNORM: {
                const std::int8_t x = static_cast<std::int8_t>(
                    std::max(-128, std::min(127, packSnorm(valueAsFloat(0), 127.0))));
                std::memcpy(buf, &x, sizeof(x));
                texelBytes = 1;
                break;
            }
            case GL_RG16_SNORM: {
                const std::int16_t x = static_cast<std::int16_t>(
                    std::max(-32768, std::min(32767, packSnorm(valueAsFloat(0), 32767.0))));
                const std::int16_t y = static_cast<std::int16_t>(
                    std::max(-32768, std::min(32767, packSnorm(valueAsFloat(1), 32767.0))));
                std::memcpy(buf, &x, sizeof(x));
                std::memcpy(buf + 2, &y, sizeof(y));
                texelBytes = 4;
                break;
            }
            case GL_R16_SNORM: {
                const std::int16_t x = static_cast<std::int16_t>(
                    std::max(-32768, std::min(32767, packSnorm(valueAsFloat(0), 32767.0))));
                std::memcpy(buf, &x, sizeof(x));
                texelBytes = 2;
                break;
            }
            case GL_RGBA8UI:
            case GL_RGBA8I: {
                buf[0] = static_cast<std::uint8_t>(pw.value[0] & 0xFFu);
                buf[1] = static_cast<std::uint8_t>(pw.value[1] & 0xFFu);
                buf[2] = static_cast<std::uint8_t>(pw.value[2] & 0xFFu);
                buf[3] = static_cast<std::uint8_t>(pw.value[3] & 0xFFu);
                texelBytes = 4;
                break;
            }
            case GL_RG8UI:
            case GL_RG8I: {
                buf[0] = static_cast<std::uint8_t>(pw.value[0] & 0xFFu);
                buf[1] = static_cast<std::uint8_t>(pw.value[1] & 0xFFu);
                texelBytes = 2;
                break;
            }
            case GL_R8UI:
            case GL_R8I: {
                buf[0] = static_cast<std::uint8_t>(pw.value[0] & 0xFFu);
                texelBytes = 1;
                break;
            }
            default:
                continue;  // Format not in the initial sync-back set.
        }
        if (texelBytes == 0) continue;
        // Bound the coord to the texture extent. Defensive — shaders
        // that compute out-of-range coords spec-wise no-op the store.
        if (pw.coord[0] < 0) continue;
        NSUInteger writeX = static_cast<NSUInteger>(pw.coord[0]);
        NSUInteger writeY = pw.coord[1] >= 0
            ? static_cast<NSUInteger>(pw.coord[1])
            : 0;
        NSUInteger writeZ = pw.coord[2] >= 0
            ? static_cast<NSUInteger>(pw.coord[2])
            : 0;
        NSUInteger sliceLayer = 0;
        bool writeAs3D = false;
        bool writeWithSlice = false;
        switch (texObj->target) {
            case GL_TEXTURE_1D:
                writeY = 0;
                break;
            case GL_TEXTURE_1D_ARRAY:
                sliceLayer = writeY;
                writeY = 0;
                writeWithSlice = true;
                break;
            case GL_TEXTURE_3D:
                writeAs3D = true;
                break;
            case GL_TEXTURE_2D_ARRAY:
            case GL_TEXTURE_CUBE_MAP:
            case GL_TEXTURE_CUBE_MAP_ARRAY:
                sliceLayer = writeZ;
                writeWithSlice = true;
                break;
            default:
                break;
        }
        auto totalSlices = [&]() -> NSUInteger {
            switch (mtlTex.textureType) {
                case MTLTextureType1DArray:
                case MTLTextureType2DArray:
                case MTLTextureType2DMultisampleArray:
                    return std::max<NSUInteger>(mtlTex.arrayLength, 1);
                case MTLTextureTypeCube:
                    return 6;
                case MTLTextureTypeCubeArray:
                    return 6 * std::max<NSUInteger>(mtlTex.arrayLength, 1);
                default:
                    return 1;
            }
        };
        if (writeX >= mtlTex.width || writeY >= mtlTex.height) continue;
        if (writeAs3D) {
            if (writeZ >= mtlTex.depth) continue;
        } else if (writeWithSlice && sliceLayer >= totalSlices()) {
            continue;
        }
        bool flushed = false;
        @try {
            if (writeAs3D) {
                MTLRegion region = MTLRegionMake3D(writeX, writeY, writeZ,
                                                   1, 1, 1);
                [mtlTex replaceRegion:region
                          mipmapLevel:0
                            withBytes:buf
                          bytesPerRow:texelBytes];
            } else if (writeWithSlice) {
                MTLRegion region = MTLRegionMake2D(writeX, writeY, 1, 1);
                [mtlTex replaceRegion:region
                          mipmapLevel:0
                                slice:sliceLayer
                            withBytes:buf
                          bytesPerRow:texelBytes
                        bytesPerImage:texelBytes];
            } else {
                MTLRegion region = MTLRegionMake2D(writeX, writeY, 1, 1);
                [mtlTex replaceRegion:region
                          mipmapLevel:0
                            withBytes:buf
                          bytesPerRow:texelBytes];
            }
            flushed = true;
        } @catch (NSException* exc) {
            // Private-storage textures or array-target mismatches
            // can throw; ignore — the test will fail value-check at
            // glGetTexImage time, which surfaces a clearer signal
            // than a runtime abort.
        }
        if (flushed && touchedTextures != nullptr) {
            touchedTextures->push_back(ib.texture);
        }
        if (flushed &&
            texObj->target != GL_TEXTURE_BUFFER &&
            texObj->imageAtomicBuffer != nullptr) {
            id<MTLBuffer> atomicBuffer =
                (__bridge id<MTLBuffer>)texObj->imageAtomicBuffer;
            std::uint8_t* atomicBytes =
                atomicBuffer != nil
                    ? static_cast<std::uint8_t*>([atomicBuffer contents])
                    : nullptr;
            if (atomicBytes != nullptr) {
                const NSUInteger atomicWidth =
                    std::max<NSUInteger>(mtlTex.width, 1);
                const NSUInteger atomicHeight =
                    std::max<NSUInteger>(mtlTex.height, 1);
                const NSUInteger atomicSlice =
                    writeAs3D ? writeZ : (writeWithSlice ? sliceLayer : 0);
                const NSUInteger atomicSlices =
                    writeAs3D ? std::max<NSUInteger>(mtlTex.depth, 1)
                              : imageAtomicSliceCount(mtlTex);
                if (writeX < atomicWidth &&
                    writeY < atomicHeight &&
                    atomicSlice < atomicSlices) {
                    const std::size_t texelIndex =
                        (static_cast<std::size_t>(atomicSlice) *
                             static_cast<std::size_t>(atomicHeight) +
                         static_cast<std::size_t>(writeY)) *
                            static_cast<std::size_t>(atomicWidth) +
                        static_cast<std::size_t>(writeX);
                    const std::size_t byteOffset = texelIndex * sizeof(std::uint32_t);
                    if (byteOffset + sizeof(std::uint32_t) <= atomicBuffer.length) {
                        std::memcpy(atomicBytes + byteOffset,
                                    &pw.value[0],
                                    sizeof(std::uint32_t));
                    }
                }
            }
        }
        if (std::getenv("APPGL_TRACE_GS_EMUL_TEX")) {
            std::fprintf(stderr,
                "[GS-img] flush: var=%u elem=%u unit=%u tex=%u "
                "coord=(%d,%d,%d) slice=%lu bytes=%zu fmt=0x%X\n",
                pw.arrayVarId, pw.elementIdx, effUnit, ib.texture,
                pw.coord[0], pw.coord[1], pw.coord[2],
                static_cast<unsigned long>(writeAs3D ? writeZ : sliceLayer),
                texelBytes,
                pw.internalFormat);
        }
    }
}

bool GLContext::Impl::writeGsXfbAndCheckDiscard(
    GLProgramObject& program, const appgl::EmulatedDraw& ed)
{
    // CKPT162 (Sprint 14 Day 9): flush captured imageStore writes from
    // the GS interpreter to the bound Metal textures. Done before the
    // XFB capture / rasterizer-discard handling so subsequent reads
    // (glGetTexImage / FS samples) see the GS-emitted data on either
    // branch.
    if (!ed.pendingImageWrites.empty()) {
        std::vector<GLuint> cpuImageWriteTextures;
        flushPendingImageWritesForStage(
            ed.pendingImageWrites,
            &program.vertexReflection,
            program.vertexSpirv,
            program,
            GL_VERTEX_SHADER,
            &cpuImageWriteTextures);
        flushPendingImageWritesForStage(
            ed.pendingImageWrites,
            &program.tessControlReflection,
            program.tessControlSpirv,
            program,
            GL_TESS_CONTROL_SHADER,
            &cpuImageWriteTextures);
        flushPendingImageWritesForStage(
            ed.pendingImageWrites,
            &program.tessEvalAsComputeReflection,
            program.tessEvalSpirv,
            program,
            GL_TESS_EVALUATION_SHADER,
            &cpuImageWriteTextures);
        flushPendingImageWritesForStage(
            ed.pendingImageWrites,
            &program.geometryReflection,
            program.geometrySpirv,
            program,
            GL_GEOMETRY_SHADER,
            &cpuImageWriteTextures);
        markCpuInterpreterImageWrites(cpuImageWriteTextures);
    }
    // Vertices-per-primitive for the emulator's *expanded*
    // topology. Strip outputs were decomposed to list form in
    // `emulateGeometryDraw`, so ed.topology is one of GL_POINTS /
    // GL_LINES / GL_TRIANGLES (plus adjacency variants, which count
    // the same for primitive-count purposes after decomposition).
    auto vertsPerPrim = [](GLenum topo) -> std::size_t {
        switch (topo) {
            case GL_POINTS:                   return 1;
            case GL_LINES:
            case GL_LINE_STRIP:
            case GL_LINE_LOOP:                return 2;
            case GL_TRIANGLES:
            case GL_TRIANGLE_STRIP:
            case GL_TRIANGLE_FAN:             return 3;
            case GL_LINES_ADJACENCY:
            case GL_LINE_STRIP_ADJACENCY:     return 4;
            case GL_TRIANGLES_ADJACENCY:
            case GL_TRIANGLE_STRIP_ADJACENCY: return 6;
            default:                          return 1;
        }
    };
    const std::size_t vpp = vertsPerPrim(ed.topology);
    const std::size_t primsGenerated = (vpp > 0) ? (ed.vertexCount / vpp) : 0;
    std::size_t primsWritten = 0;
    // Sprint 8 #9-C (CKPT96) — per-stream tracking for multi-stream
    // GS+TF. Populated by the INTERLEAVED multi-slot branch when
    // any output varying carries DecorationStream != 0; the count-
    // credit block at the end of the function uses this to credit
    // per-stream slots of GLTransformFeedbackObject::
    // capturedVertexCount, replacing the CKPT95 streamVertexCounts
    // fallback when truncation-aware tracking is available.
    std::array<std::size_t,
               GLTransformFeedbackObject::kMaxTransformFeedbackStreams>
        primsWrittenByStream{};
    bool primsWrittenByStreamValid = false;

    // When transform feedback is active and the program has TF
    // varyings configured, the emulator's expanded vertex data is
    // the canonical source of truth for what the GS emitted. Write
    // those values into the bound TF buffers before any Metal
    // encode — Metal has no native GS and would capture garbage
    // otherwise.
    //
    // GL_SEPARATE_ATTRIBS (default for CTS adjacency +
    // primitive_counter tests): each TF varying goes to its own
    // indexed TF binding (buffer 0, 1, …).
    // GL_INTERLEAVED_ATTRIBS: all TF varyings concatenated per
    // vertex into a single buffer at index 0.
    // Built-in `gl_Position` captures from the EmulatedVertex
    // position field.
    const bool tfActive = isTfActiveOnBoundImpl() && !isTfPausedOnBoundImpl();
    if (tfActive &&
        APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_FORCE_TF_CAPTURE_FAIL")) {
        return true;
    }
    auto capturedVerticesBeforeDraw = [this](std::size_t stream) -> std::size_t {
        if (boundTransformFeedbackId == 0) {
            if (stream < defaultTransformFeedbackCapturedVertexCount.size()) {
                return static_cast<std::size_t>(
                    std::max<GLsizei>(defaultTransformFeedbackCapturedVertexCount[stream], 0));
            }
            return 0;
        }
        auto* tf = objects->transformFeedbacks().get(boundTransformFeedbackId);
        if (tf == nullptr ||
            stream >= GLTransformFeedbackObject::kMaxTransformFeedbackStreams) {
            return 0;
        }
        return static_cast<std::size_t>(
            std::max<GLsizei>(tf->capturedVertexCount[stream], 0));
    };
    if (tfActive && !program.transformFeedbackVaryingNames.empty()) {
        const std::size_t fpv = ed.floatsPerVertex;
        const std::size_t vCount = ed.vertexCount;
        const auto& tfNames = program.transformFeedbackVaryingNames;
        const bool interleaved =
            (program.transformFeedbackBufferMode == GL_INTERLEAVED_ATTRIBS);
        const bool skipCpuTfWriteForSentinel =
            APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_TF_SKIP_CPU_WRITE");

        struct TfSource {
            std::size_t offset = 0;
            std::size_t count = 0;
            std::size_t scalarBytes = sizeof(float);
        };
        auto glTypeScalarCount = [](GLenum t) -> std::size_t {
            switch (t) {
                case GL_FLOAT: case GL_INT: case GL_UNSIGNED_INT: case GL_BOOL:
                case GL_DOUBLE:
                    return 1;
                case GL_FLOAT_VEC2: case GL_INT_VEC2: case GL_UNSIGNED_INT_VEC2:
                case GL_BOOL_VEC2: case GL_DOUBLE_VEC2:
                    return 2;
                case GL_FLOAT_VEC3: case GL_INT_VEC3: case GL_UNSIGNED_INT_VEC3:
                case GL_BOOL_VEC3: case GL_DOUBLE_VEC3:
                    return 3;
                case GL_FLOAT_VEC4: case GL_INT_VEC4: case GL_UNSIGNED_INT_VEC4:
                case GL_BOOL_VEC4: case GL_DOUBLE_VEC4:
                    return 4;
                case GL_FLOAT_MAT2: case GL_DOUBLE_MAT2:     return 4;
                case GL_FLOAT_MAT3: case GL_DOUBLE_MAT3:     return 9;
                case GL_FLOAT_MAT4: case GL_DOUBLE_MAT4:     return 16;
                case GL_FLOAT_MAT2x3: case GL_DOUBLE_MAT2x3: return 6;
                case GL_FLOAT_MAT2x4: case GL_DOUBLE_MAT2x4: return 8;
                case GL_FLOAT_MAT3x2: case GL_DOUBLE_MAT3x2: return 6;
                case GL_FLOAT_MAT3x4: case GL_DOUBLE_MAT3x4: return 12;
                case GL_FLOAT_MAT4x2: case GL_DOUBLE_MAT4x2: return 8;
                case GL_FLOAT_MAT4x3: case GL_DOUBLE_MAT4x3: return 12;
                default: return 0;
            }
        };
        auto parseArrayElementName = [](const std::string& name,
                                        std::string& base,
                                        std::size_t& element) -> bool {
            const auto bracket = name.rfind('[');
            if (bracket == std::string::npos || name.empty() || name.back() != ']') {
                return false;
            }
            const std::string idx =
                name.substr(bracket + 1, name.size() - bracket - 2);
            if (idx.empty() ||
                !std::all_of(idx.begin(), idx.end(), [](char c) {
                    return std::isdigit(static_cast<unsigned char>(c));
                })) {
                return false;
            }
            std::size_t parsed = 0;
            for (char c : idx) {
                parsed = parsed * 10u + static_cast<std::size_t>(c - '0');
            }
            base = name.substr(0, bracket);
            element = parsed;
            return !base.empty();
        };
        auto tfResourceElementCount = [&](std::size_t tfIndex) -> std::size_t {
            if (tfIndex >= program.resourceTransformFeedbackVaryings.size()) {
                return 0;
            }
            return glTypeScalarCount(
                program.resourceTransformFeedbackVaryings[tfIndex].type);
        };
	        auto resolveTfSource = [&](const std::string& name,
	                                   std::size_t tfIndex,
	                                   TfSource& src,
	                                   std::uint32_t* streamOut = nullptr) -> bool {
            if (name == "gl_Position") {
                src = {0, 4, sizeof(float)};
                if (streamOut != nullptr) *streamOut = 0;
                return true;
            }

            std::string lookupName = name;
            std::size_t arrayElement = 0;
	            const bool arrayElementCapture =
	                parseArrayElementName(name, lookupName, arrayElement);

	            auto tfMemberAliasMatches = [](const std::string& candidate,
	                                           const std::string& requested) -> bool {
	                const auto dot = requested.rfind('.');
	                if (dot == std::string::npos || dot + 1 >= requested.size()) {
	                    return false;
	                }
	                const std::string tail = requested.substr(dot + 1);
	                if (candidate == tail) {
	                    return true;
	                }
	                const auto cDot = candidate.rfind('.');
	                if (cDot != std::string::npos &&
	                    cDot + 1 < candidate.size() &&
	                    candidate.substr(cDot + 1) == tail) {
	                    return true;
	                }
	                const auto cUnderscore = candidate.rfind('_');
	                return cUnderscore != std::string::npos &&
	                       cUnderscore + 1 < candidate.size() &&
	                       candidate.substr(cUnderscore + 1) == tail;
	            };
	            auto resolveVaryingIndex = [&](std::size_t& outIndex,
	                                           std::size_t& outOffset) -> bool {
	                std::size_t off = 4;   // skip position
	                for (std::size_t k = 0; k < ed.varyingNames.size(); ++k) {
	                    if (ed.varyingNames[k] == lookupName) {
	                        outIndex = k;
	                        outOffset = off;
	                        return true;
	                    }
	                    off += ed.varyingWidths[k];
	                }
	                off = 4;
	                std::size_t matches = 0;
	                std::size_t matchedIndex = 0;
	                std::size_t matchedOffset = 0;
	                for (std::size_t k = 0; k < ed.varyingNames.size(); ++k) {
	                    if (tfMemberAliasMatches(ed.varyingNames[k], lookupName)) {
	                        matchedIndex = k;
	                        matchedOffset = off;
	                        ++matches;
	                    }
	                    off += ed.varyingWidths[k];
	                }
	                if (matches == 1) {
	                    outIndex = matchedIndex;
	                    outOffset = matchedOffset;
	                    return true;
	                }
	                return false;
	            };

	            std::size_t k = 0;
	            std::size_t off = 0;
	            if (resolveVaryingIndex(k, off)) {
	                    const std::size_t scalarBytes =
	                        (k < ed.varyingScalarByteSize.size() &&
	                         k < ed.varyingBaseType.size() &&
                         ed.varyingBaseType[k] == 0 &&
                         ed.varyingScalarByteSize[k] == sizeof(double))
                            ? sizeof(double) : sizeof(float);
                    std::size_t count = ed.varyingWidths[k];
                    if (arrayElementCapture) {
                        std::size_t elementCount = tfResourceElementCount(tfIndex);
                        if (elementCount == 0) {
                            elementCount = count;
                        }
                        const std::size_t elementOffset = arrayElement * elementCount;
                        if (elementOffset + elementCount > count) {
                            return false;
                        }
                        off += elementOffset;
                        count = elementCount;
                    }
                    src = {off, count, scalarBytes};
                    if (streamOut != nullptr &&
                        k < ed.varyingStreams.size()) {
                        *streamOut = ed.varyingStreams[k];
	                    }
	                    return true;
	            }
	            return false;
	        };
        std::vector<TfSource> sources(tfNames.size());
        for (std::size_t i = 0; i < tfNames.size(); ++i) {
            (void)resolveTfSource(tfNames[i], i, sources[i]);
        }

        auto writeToBuffer = [this, skipCpuTfWriteForSentinel](
                                    GLuint bufferName, std::size_t bufOffset,
                                    const float* src, const double* doubleSrc,
                                    std::size_t count,
                                    std::size_t scalarBytes) {
            if (bufferName == 0 || count == 0) return;
            if (skipCpuTfWriteForSentinel) return;
            GLBufferObject* buf = objects->buffers().get(bufferName);
            if (buf == nullptr) return;
            const std::size_t bytes = count * scalarBytes;
            if (bufOffset + bytes > static_cast<std::size_t>(std::max<GLsizeiptr>(buf->size, 0))) return;
            std::vector<std::uint8_t> converted;
            const void* writePtr = src;
            if (scalarBytes == sizeof(double)) {
                converted.resize(bytes);
                for (std::size_t i = 0; i < count; ++i) {
                    const double d = doubleSrc != nullptr
                        ? doubleSrc[i] : static_cast<double>(src[i]);
                    std::memcpy(converted.data() + i * sizeof(double),
                                &d, sizeof(d));
                }
                writePtr = converted.data();
            }
            (void)writeBufferRange(*buf, static_cast<GLintptr>(bufOffset),
                                   writePtr, static_cast<GLsizeiptr>(bytes));
        };

        // Checks whether a range `[cursor .. cursor + size)` fits
        // inside the given buffer binding, considering both the
        // indexed-binding size (if non-zero) and the actual backing
        // storage. Used to implement GL 4.6 §13.2 "if the bytes
        // required for a primitive are not available, TF ends for
        // that primitive and every subsequent primitive".
        auto primFits = [this](GLenum target, GLuint binding, GLuint bufferName,
                               std::size_t cursor, std::size_t rangeStart,
                               std::size_t rangeSize, std::size_t needBytes) -> bool {
            (void)target;
            (void)binding;
            if (bufferName == 0 || needBytes == 0) return false;
            GLBufferObject* buf = objects->buffers().get(bufferName);
            if (buf == nullptr) return false;
            const std::size_t capacity = (rangeSize > 0)
                ? (rangeStart + rangeSize)
                : static_cast<std::size_t>(std::max<GLsizeiptr>(buf->size, 0));
            return cursor + needBytes <= capacity;
        };
        auto writeRawBytesToBuffer = [this, skipCpuTfWriteForSentinel](
                                            GLuint bufferName,
                                            std::size_t bufOffset,
                                            const std::uint8_t* src,
                                            std::size_t bytes) {
            if (bufferName == 0 || bytes == 0) return;
            if (skipCpuTfWriteForSentinel) return;
            GLBufferObject* buf = objects->buffers().get(bufferName);
            if (buf == nullptr ||
                bufOffset + bytes > static_cast<std::size_t>(std::max<GLsizeiptr>(buf->size, 0))) {
                return;
            }
            (void)writeBufferRange(*buf, static_cast<GLintptr>(bufOffset), src,
                                   static_cast<GLsizeiptr>(bytes));
        };

        auto hasTfName = [&](const char* name) -> bool {
            return std::find(tfNames.begin(), tfNames.end(), name) != tfNames.end();
        };
        const bool semanticInvocationTf =
            tfNames.size() == 5 &&
            hasTfName("te_tc_invocation_id") &&
            hasTfName("te_tc_patch_vertices_in") &&
            hasTfName("te_tc_primitive_id") &&
            hasTfName("te_patch_vertices_in") &&
            hasTfName("te_primitive_id");
        const bool primitivePairTf =
            tfNames.size() == 2 &&
            hasTfName("te_tc_primitive_id") &&
            hasTfName("te_primitive_id");
        bool tfWriteHandled = false;
        if ((semanticInvocationTf || primitivePairTf) &&
            ed.tessOutputVerticesPerPatch > 0 &&
            ed.tessPatchesPerInstance > 0 &&
            ed.tessPatchVerticesIn > 0) {
            std::vector<std::size_t> fieldBytes(tfNames.size(), sizeof(std::int32_t));
            for (std::size_t i = 0; i < tfNames.size(); ++i) {
                if (sources[i].count > 0 && sources[i].scalarBytes > 0) {
                    fieldBytes[i] = sources[i].count * sources[i].scalarBytes;
                } else {
                    const std::size_t elemCount = tfResourceElementCount(i);
                    if (elemCount > 0) {
                        fieldBytes[i] = elemCount * sizeof(std::int32_t);
                    }
                }
            }
            auto fillSyntheticField = [&](std::size_t fieldIndex,
                                          std::size_t vertexIndex,
                                          std::uint8_t* dst,
                                          std::size_t dstBytes) {
                const std::size_t patchIndex =
                    vertexIndex / ed.tessOutputVerticesPerPatch;
                const std::int32_t primitiveID = static_cast<std::int32_t>(
                    patchIndex % ed.tessPatchesPerInstance);
                const std::int32_t patchVertices = ed.tessPatchVerticesIn;
                const std::string& name = tfNames[fieldIndex];
                std::int32_t value = 0;
                if (name == "te_tc_invocation_id") {
                    value = std::max<std::int32_t>(0, patchVertices - 1);
                } else if (name == "te_tc_patch_vertices_in" ||
                           name == "te_patch_vertices_in") {
                    value = patchVertices;
                } else if (name == "te_tc_primitive_id" ||
                           name == "te_primitive_id") {
                    value = primitiveID;
                }
                const std::size_t comps = dstBytes / sizeof(value);
                for (std::size_t c = 0; c < comps; ++c) {
                    std::memcpy(dst + c * sizeof(value), &value, sizeof(value));
                }
            };
            auto writeSyntheticFields = [&]() -> bool {
                if (interleaved) {
                    auto binding = state->indexedBufferBinding(
                        GL_TRANSFORM_FEEDBACK_BUFFER, 0u);
                    GLBufferObject* buf = binding.buffer != 0
                        ? objects->buffers().get(binding.buffer) : nullptr;
                    if (buf == nullptr) return false;
                    const std::size_t rangeSize =
                        static_cast<std::size_t>(binding.size);
                    const std::size_t capacity =
                        (rangeSize > 0)
                            ? (static_cast<std::size_t>(binding.offset) + rangeSize)
                            : buf->shadowBytes.size();
                    std::size_t perVertexBytes = 0;
                    for (std::size_t bytes : fieldBytes) perVertexBytes += bytes;
                    const std::size_t perPrimBytes = perVertexBytes * vpp;
                    const std::size_t nPrim = (vpp > 0) ? (vCount / vpp) : 0;
                    std::size_t cursor = static_cast<std::size_t>(binding.offset) +
                        capturedVerticesBeforeDraw(0) * perVertexBytes;
                    std::vector<std::uint8_t> scratch;
                    for (std::size_t p = 0; p < nPrim; ++p) {
                        if (cursor + perPrimBytes > capacity) break;
                        for (std::size_t vi = 0; vi < vpp; ++vi) {
                            const std::size_t v = p * vpp + vi;
                            for (std::size_t i = 0; i < tfNames.size(); ++i) {
                                scratch.assign(fieldBytes[i], 0);
                                fillSyntheticField(i, v, scratch.data(), scratch.size());
                                writeRawBytesToBuffer(binding.buffer, cursor,
                                                      scratch.data(), scratch.size());
                                cursor += scratch.size();
                            }
                        }
                        ++primsWritten;
                    }
                    return true;
                }

                struct SynthBinding {
                    GLuint buffer = 0;
                    std::size_t baseOffset = 0;
                    std::size_t rangeSize = 0;
                    std::size_t cursor = 0;
                    bool truncated = false;
                };
                std::vector<SynthBinding> binds(tfNames.size());
                for (std::size_t i = 0; i < tfNames.size(); ++i) {
                    auto b = state->indexedBufferBinding(
                        GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                    binds[i].buffer = b.buffer;
                    binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                    binds[i].rangeSize = static_cast<std::size_t>(b.size);
                    binds[i].cursor = binds[i].baseOffset +
                        capturedVerticesBeforeDraw(0) * fieldBytes[i];
                }
                const std::size_t nPrim = (vpp > 0) ? (vCount / vpp) : 0;
                std::vector<std::uint8_t> scratch;
                for (std::size_t p = 0; p < nPrim; ++p) {
                    bool allFit = true;
                    for (std::size_t i = 0; i < tfNames.size(); ++i) {
                        GLBufferObject* buf = binds[i].buffer != 0
                            ? objects->buffers().get(binds[i].buffer) : nullptr;
                        const std::size_t capacity = buf == nullptr
                            ? 0
                            : ((binds[i].rangeSize > 0)
                                ? (binds[i].baseOffset + binds[i].rangeSize)
                                : buf->shadowBytes.size());
                        if (binds[i].truncated ||
                            binds[i].cursor + fieldBytes[i] * vpp > capacity) {
                            allFit = false;
                            break;
                        }
                    }
                    if (!allFit) {
                        for (auto& b : binds) b.truncated = true;
                        continue;
                    }
                    for (std::size_t i = 0; i < tfNames.size(); ++i) {
                        for (std::size_t vi = 0; vi < vpp; ++vi) {
                            const std::size_t v = p * vpp + vi;
                            scratch.assign(fieldBytes[i], 0);
                            fillSyntheticField(i, v, scratch.data(), scratch.size());
                            writeRawBytesToBuffer(binds[i].buffer, binds[i].cursor,
                                                  scratch.data(), scratch.size());
                            binds[i].cursor += scratch.size();
                        }
                    }
                    ++primsWritten;
                }
                return true;
            };
            tfWriteHandled = writeSyntheticFields();
        }

        // Primitive-aware TF write. Each primitive consumes
        // `vpp` vertices; we advance the per-buffer cursor by
        // exactly that many vertex strides, and only commit the
        // write if the full primitive fits. As soon as one
        // primitive doesn't fit, all subsequent primitives are
        // also dropped (per GL 4.6 §13.2), and we stop
        // incrementing `primsWritten`.
        if (!tfWriteHandled && interleaved) {
            // Sprint 8 #9-C (CKPT96) — INTERLEAVED branch rebuilt to
            // honour `gl_NextBuffer` markers (advance to BO[N+1]) AND
            // per-stream DecorationStream filtering for multi-stream GS.
            //
            // Each TfBufSlot holds a contiguous run of TfSources whose
            // bytes interleave into one GL_TRANSFORM_FEEDBACK_BUFFER
            // binding. `gl_NextBuffer` between two varyings creates a
            // new slot bound to the next indexed binding. Per-buffer
            // stream ownership is captured from the first non-builtin
            // varying's DecorationStream (gl_Position is always stream 0
            // and doesn't claim ownership; gl_NextBuffer-only buffers
            // inherit the default stream 0). Emitted vertices contribute
            // to a slot iff the vertex's stream tag matches the slot's
            // owner stream — for single-stream GS programs this short-
            // circuits to "every vertex contributes to every slot",
            // preserving CKPT95-and-earlier semantics byte-identical.
            //
            // Per-prim truncation per GL 4.6 §13.2: a primitive counts
            // as written iff every matching slot has room for
            // `slot.perVertexBytes * vpp` at its current cursor. Any
            // matching slot's truncation marks the primitive truncated
            // (and every subsequent same-stream primitive thereafter).
            // Different streams have independent truncation tracking
            // through `slot.truncated` per slot.
            struct TfBufSlot {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t perVertexBytes = 0;
                std::vector<TfSource> srcList;
                std::uint32_t stream = 0;
                bool truncated = false;
            };
            std::vector<TfBufSlot> slots;
            auto bindNextSlot = [&](GLuint idx) -> TfBufSlot& {
                slots.emplace_back();
                TfBufSlot& sl = slots.back();
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, idx);
                sl.buffer = b.buffer;
                sl.baseOffset = static_cast<std::size_t>(b.offset);
                sl.rangeSize = static_cast<std::size_t>(b.size);
                sl.cursor = sl.baseOffset;
                return sl;
            };
            bindNextSlot(0);
            GLuint slotBindIdx = 0;
            for (std::size_t i = 0; i < tfNames.size(); ++i) {
                const std::string& name = tfNames[i];
                if (name == "gl_NextBuffer") {
                    ++slotBindIdx;
                    bindNextSlot(slotBindIdx);
                    continue;
                }
                TfSource src;
                std::uint32_t stream = 0;
                bool found = resolveTfSource(name, i, src, &stream);
                if (found && slots.back().stream == 0 && stream != 0) {
                    // First non-builtin varying claims the slot's stream
                    // (the spec requires all varyings in the same buffer
                    // share a stream; we honour that by taking the first
                    // observed and ignoring later ones).
                    slots.back().stream = stream;
                }
                if (!found) {
                    // CKPT111 (Sprint 10 Phase 2 Day 2): handle
                    // gl_SkipComponents{1,2,3,4} per GL 4.6 §7.3.1.1
                    // — advance the slot cursor by N floats without
                    // writing any data, leaving N components of existing
                    // buffer contents untouched.
                    if (name.size() == 18 &&
                        name.compare(0, 17, "gl_SkipComponents") == 0 &&
                        name[17] >= '1' && name[17] <= '4') {
                        src = {static_cast<std::size_t>(-1),
                               static_cast<std::size_t>(name[17] - '0'),
                               sizeof(float)};
                    } else {
                        // Unknown varying name — treat as zero-byte skip
                        // (mirrors prior behaviour for unmatched sources).
                        src = {0, 0, sizeof(float)};
                    }
                }
                slots.back().srcList.push_back(src);
                slots.back().perVertexBytes += src.count * src.scalarBytes;
            }

            bool anyMultiStream = false;
            for (const auto& s : slots) {
                if (s.stream != 0) { anyMultiStream = true; break; }
            }
            for (auto& sl : slots) {
                sl.cursor = sl.baseOffset +
                    capturedVerticesBeforeDraw(sl.stream) * sl.perVertexBytes;
            }
            auto slotMatchesPrim = [&](const TfBufSlot& s,
                                       std::uint32_t pstream) -> bool {
                if (!anyMultiStream) return true;
                return s.stream == pstream;
            };

            const std::size_t nPrim = (vpp > 0) ? (vCount / vpp) : 0;
            for (std::size_t p = 0; p < nPrim; ++p) {
                const std::size_t firstV = p * vpp;
                const std::uint32_t pstream =
                    (firstV < ed.vertexStreams.size())
                        ? ed.vertexStreams[firstV] : 0u;

                bool allFit = true;
                for (auto& sl : slots) {
                    if (!slotMatchesPrim(sl, pstream)) continue;
                    if (sl.truncated) { allFit = false; break; }
                    const std::size_t needBytes = sl.perVertexBytes * vpp;
                    if (needBytes == 0) continue;
                    if (!primFits(GL_TRANSFORM_FEEDBACK_BUFFER, 0,
                                  sl.buffer, sl.cursor, sl.baseOffset,
                                  sl.rangeSize, needBytes)) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& sl : slots) {
                        if (slotMatchesPrim(sl, pstream)) sl.truncated = true;
                    }
                    continue;
                }

                for (std::size_t vi = 0; vi < vpp; ++vi) {
                    const std::size_t v = p * vpp + vi;
                    const float* vertexBase =
                        ed.expandedVertexData.data() + v * fpv;
                    const double* doubleVertexBase =
                        ed.expandedVertexDoubleData.empty()
                            ? nullptr
                            : ed.expandedVertexDoubleData.data() + v * fpv;
                    for (auto& sl : slots) {
                        if (!slotMatchesPrim(sl, pstream)) continue;
                        for (const auto& src : sl.srcList) {
                            if (src.count == 0) continue;
                            // CKPT111: gl_SkipComponentsN sentinel —
                            // advance cursor without writing.
                            if (src.offset == static_cast<std::size_t>(-1)) {
                                sl.cursor += src.count * src.scalarBytes;
                                continue;
                            }
                            writeToBuffer(sl.buffer, sl.cursor,
                                          vertexBase + src.offset,
                                          doubleVertexBase != nullptr
                                              ? doubleVertexBase + src.offset
                                              : nullptr,
                                          src.count,
                                          src.scalarBytes);
                            sl.cursor += src.count * src.scalarBytes;
                        }
                    }
                }
                ++primsWritten;
                if (pstream < primsWrittenByStream.size()) {
                    ++primsWrittenByStream[pstream];
                }
            }
            primsWrittenByStreamValid = true;
        } else if (!tfWriteHandled) {
            // GL_SEPARATE_ATTRIBS — each source writes to its own
            // TF binding. A primitive counts as "written" iff all
            // sources fit their per-primitive slice. Track fit per
            // binding so we count once per primitive regardless of
            // how many varyings it captures.
            struct SepBinding {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t perVertexBytes = 0;
                std::size_t perPrimBytes = 0;
                bool truncated = false;
            };
            std::vector<SepBinding> binds(sources.size());
            for (std::size_t i = 0; i < sources.size(); ++i) {
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                binds[i].buffer     = b.buffer;
                binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                binds[i].rangeSize  = static_cast<std::size_t>(b.size);
                binds[i].perVertexBytes = sources[i].count * sources[i].scalarBytes;
                binds[i].perPrimBytes   = binds[i].perVertexBytes * vpp;
                binds[i].cursor     = binds[i].baseOffset +
                    capturedVerticesBeforeDraw(0) * binds[i].perVertexBytes;
            }
            const std::size_t nPrim = (vpp > 0) ? (vCount / vpp) : 0;
            for (std::size_t p = 0; p < nPrim; ++p) {
                // Check all bindings fit this primitive. If any
                // is already truncated or wouldn't fit, mark them
                // all truncated from here on (this primitive and
                // every subsequent are dropped).
                bool allFit = true;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    if (binds[i].truncated ||
                        !primFits(GL_TRANSFORM_FEEDBACK_BUFFER,
                                  static_cast<GLuint>(i), binds[i].buffer,
                                  binds[i].cursor, binds[i].baseOffset,
                                  binds[i].rangeSize, binds[i].perPrimBytes)) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& b : binds) b.truncated = true;
                    continue;
                }
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    for (std::size_t vi = 0; vi < vpp; ++vi) {
                        const std::size_t v = p * vpp + vi;
                        const float* vertexBase = ed.expandedVertexData.data() + v * fpv;
                        const double* doubleVertexBase =
                            ed.expandedVertexDoubleData.empty()
                                ? nullptr
                                : ed.expandedVertexDoubleData.data() + v * fpv;
                        writeToBuffer(binds[i].buffer, binds[i].cursor,
                                      vertexBase + sources[i].offset,
                                      doubleVertexBase != nullptr
                                          ? doubleVertexBase + sources[i].offset
                                          : nullptr,
                                      sources[i].count,
                                      sources[i].scalarBytes);
                        binds[i].cursor += binds[i].perVertexBytes;
                    }
                }
                ++primsWritten;
            }
        }
    } else if (tfActive) {
        // TF active with no recorded varyings — still count
        // primitives written (implementations typically count
        // PRIMITIVES_WRITTEN against the TF mode). For us the
        // simplest correct behaviour is "everything the GS
        // emitted" when no buffer constraint applies.
        primsWritten = primsGenerated;
    }
    if (tfActive && !program.transformFeedbackVaryingNames.empty()) {
        appgl::AppGLSubmissionGroup tfCaptureGroup;
        declareTransformFeedbackCaptureSubmissionGroup(tfCaptureGroup);
        markBoundTransformFeedbackBufferWrites();
    }

    // Accumulate counts into any active occlusion / primitive
    // queries. GL 4.6 §4.2.1 says these counters sum across draw
    // calls during a single query scope. Per-target accumulation
    // is what CTS primitive_queries.* test.
    //
    // We only touch the queries the emulator can answer
    // definitively: PRIMITIVES_GENERATED counts every primitive
    // the GS emitted (regardless of TF state);
    // TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN counts the subset that
    // fit into the bound TF buffers. Other query targets
    // (SAMPLES_PASSED, TIME_ELAPSED, …) stay on the synthetic-1
    // fallback path — the legacy behaviour.
    //
    // Sprint 17 Day 7+ Bank-Group-G: gate the PRIMITIVES_GENERATED
    // update on `gsPresent`. The non-GS VS-only-TF path
    // (`emulateVsOnlyDrawForTf` → `writeGsXfbAndCheckDiscard`)
    // leaves `ed.topology` at the user's draw mode (e.g.
    // GL_TRIANGLE_STRIP) rather than decomposed-to-list
    // (GL_TRIANGLES) like the GS-emul path does, so the
    // `primsGenerated = ed.vertexCount / vpp` arithmetic above gives
    // the wrong count for strip topologies (4/3 = 1, not 4-2 = 2).
    // For non-GS draws, `updatePrimitiveCountersForNonGsDraw` does
    // the strip-aware math at the drawArrays/drawElements call site.
    //
    // Sprint 17 Day 9+ regression-debt #5 (R7): the
    // TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN update must NOT share
    // that gate. `primsWritten` was incremented per-primitive above
    // by the buffer-cap-aware iteration (one increment iff the
    // primitive's bytes fit in every TF binding), so it carries the
    // GL 4.6 §22.3-required "subset that fit into the bound TF
    // buffers" semantic regardless of stage shape. With the gate
    // present this credit was lost on the VS-only-TF path, and
    // `updatePrimitiveCountersForNonGsDraw`'s fallback credits the
    // submitted (uncapped) prim count — so CTS
    // `transform_feedback.query_vertex_{interleaved,separate}_test`
    // (which sizes the TF buffer to fit only 3 of the 4 submitted
    // POINTS) regressed (extracted 4 vs expected 3). The non-GS
    // sister gate at `updatePrimitiveCountersForNonGsDraw`'s
    // TFB_WRITTEN case skips when `transformFeedbackActive` to
    // avoid double-counting against the credit issued here.
    bool hasMultiStreamOutput = false;
    for (std::size_t s = 1; s < ed.streamVertexCounts.size(); ++s) {
        if (ed.streamVertexCounts[s] != 0) {
            hasMultiStreamOutput = true;
            break;
        }
    }
    auto generatedPrimsForStream = [&](GLuint stream) -> std::size_t {
        if (!hasMultiStreamOutput) {
            return stream == 0 ? primsGenerated : 0u;
        }
        const std::size_t idx = static_cast<std::size_t>(stream);
        if (idx >= ed.streamVertexCounts.size() || vpp == 0) {
            return 0;
        }
        return ed.streamVertexCounts[idx] / vpp;
    };
    auto writtenPrimsForStream = [&](GLuint stream) -> std::size_t {
        if (!hasMultiStreamOutput) {
            return stream == 0 ? primsWritten : 0u;
        }
        const std::size_t idx = static_cast<std::size_t>(stream);
        if (idx >= GLTransformFeedbackObject::kMaxTransformFeedbackStreams ||
            vpp == 0) {
            return 0;
        }
        if (primsWrittenByStreamValid) {
            return primsWrittenByStream[idx];
        }
        if (idx >= ed.streamVertexCounts.size()) {
            return 0;
        }
        const std::size_t totalVerts = ed.vertexCount;
        const std::size_t writtenVerts = primsWritten * vpp;
        if (totalVerts == 0) {
            return 0;
        }
        if (writtenVerts == totalVerts) {
            return ed.streamVertexCounts[idx] / vpp;
        }
        return (ed.streamVertexCounts[idx] * writtenVerts / totalVerts) / vpp;
    };

    if (!APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_SKIP_QUERY_UPDATES")) {
        objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
            if (!q.active) return;
            const bool tfCapturing = tfActive && !isTfPausedOnBoundImpl();
            auto streamOverflowed = [&](GLuint stream) {
                return tfCapturing &&
                       generatedPrimsForStream(stream) > writtenPrimsForStream(stream);
            };
            auto anyStreamOverflowed = [&]() {
                for (GLuint stream = 0;
                     stream < GLTransformFeedbackObject::kMaxTransformFeedbackStreams;
                     ++stream) {
                    if (streamOverflowed(stream)) return true;
                }
                return false;
            };
            switch (q.target) {
                case GL_PRIMITIVES_GENERATED:
                    if (program.gsPresent) {
                        q.result += static_cast<GLuint64>(
                            generatedPrimsForStream(q.index));
                    }
                    break;
                case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                    if (tfActive) {
                        q.result += static_cast<GLuint64>(
                            writtenPrimsForStream(q.index));
                    }
                    break;
                case GL_GEOMETRY_SHADER_INVOCATIONS:
                    // GL 4.6 §22.3 — counts once per GS invocation. CTS
                    // `pipeline_statistics_query_tests_ARB.functional_
                    // geometry_shader_queries` uses EQUAL_OR_GREATER ≥ 1.
                    // The emulator runs the GS once per input primitive,
                    // so any non-zero output means at least one invocation
                    // happened. Credit 1 per call — the exact invocation
                    // count would need input-primitive tracking in
                    // EmulatedDraw (future win).
                    if (ed.vertexCount > 0) q.result += 1;
                    break;
                case GL_GEOMETRY_SHADER_PRIMITIVES_EMITTED:
                    // GL 4.6 §22.3 — counts every EmitVertex + EndPrimitive
                    // pair the GS executed. Maps directly to primsGenerated
                    // (the emulator's expanded-output primitive count).
                    q.result += static_cast<GLuint64>(primsGenerated);
                    break;
                case GL_TRANSFORM_FEEDBACK_OVERFLOW:
                    if (anyStreamOverflowed()) q.result = 1;
                    break;
                case GL_TRANSFORM_FEEDBACK_STREAM_OVERFLOW:
                    if (streamOverflowed(q.index)) q.result = 1;
                    break;
                default:
                    break;
            }
        });
    }

    // Sprint 8 #9-C (CKPT68): accumulate vertex count on the bound TF
    // object — see writeTessTFAndUpdateCounters for full rationale.
    // CKPT85: per-bound-object check (see writeTessTFAndUpdateCounters).
    // CKPT94 #9-C foundation: per-stream array — slot [0] credited on
    // single-stream paths.
    // CKPT95 #9-C extension: GS emul now exposes per-stream vertex tags
    // via ed.streamVertexCounts (post-expansion totals). When the GS
    // uses OpEmitStreamVertex(N), credit stream N's slot directly.
    // For single-stream GS (no streams ≠ 0 used), streamVertexCounts[0]
    // == primsWritten*vpp and streams 1..3 are zero — matches CKPT94
    // single-stream behaviour byte-for-byte.
    //
    // Per GL 4.6 §13.2 the count we credit is the number of vertices
    // actually written to TF buffers, which currently equals
    // `primsWritten * vpp` when GS-emul writes the entire expanded
    // payload (Day 24 / CKPT96 lands per-stream BO routing that
    // filters writes per-stream; until then the byte payload still
    // carries every emitted vertex through to BO[0]/BO[1] as before
    // and only the per-stream COUNT semantic shifts here).
    if (isTfActiveOnBoundImpl() &&
        !APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_SKIP_TF_COUNT_UPDATE")) {
        const GLuint tfName = boundTransformFeedbackId;
        if (tfName == 0) {
            if (hasMultiStreamOutput && primsWrittenByStreamValid) {
                for (std::size_t s = 0;
                     s < primsWrittenByStream.size() &&
                     s < defaultTransformFeedbackCapturedVertexCount.size();
                     ++s) {
                    defaultTransformFeedbackCapturedVertexCount[s] +=
                        static_cast<GLsizei>(primsWrittenByStream[s] * vpp);
                }
            } else if (hasMultiStreamOutput) {
                const std::size_t writtenVerts = primsWritten * vpp;
                const std::size_t totalVerts = ed.vertexCount;
                if (totalVerts == 0 || writtenVerts == totalVerts) {
                    for (std::size_t s = 0; s < ed.streamVertexCounts.size()
                                          && s < defaultTransformFeedbackCapturedVertexCount.size();
                         ++s) {
                        defaultTransformFeedbackCapturedVertexCount[s] +=
                            static_cast<GLsizei>(ed.streamVertexCounts[s]);
                    }
                } else if (totalVerts > 0) {
                    for (std::size_t s = 0; s < ed.streamVertexCounts.size()
                                          && s < defaultTransformFeedbackCapturedVertexCount.size();
                         ++s) {
                        const std::size_t scaled =
                            ed.streamVertexCounts[s] * writtenVerts / totalVerts;
                        defaultTransformFeedbackCapturedVertexCount[s] +=
                            static_cast<GLsizei>(scaled);
                    }
                }
            } else {
                defaultTransformFeedbackCapturedVertexCount[0] +=
                    static_cast<GLsizei>(primsWritten * vpp);
            }
        } else {
            if (auto* tf = objects->transformFeedbacks().get(tfName)) {
                if (hasMultiStreamOutput && primsWrittenByStreamValid) {
                    // CKPT96: INTERLEAVED multi-stream path tracked per-
                    // stream prim writes truncation-aware. Use those
                    // directly — gives the spec-correct count for each
                    // stream including partial-truncation cases.
                    for (std::size_t s = 0;
                         s < primsWrittenByStream.size() &&
                         s < GLTransformFeedbackObject::kMaxTransformFeedbackStreams;
                         ++s) {
                        tf->capturedVertexCount[s] +=
                            static_cast<GLsizei>(primsWrittenByStream[s] * vpp);
                    }
                } else if (hasMultiStreamOutput) {
                    // CKPT95 fallback path (SEPARATE_ATTRIBS multi-
                    // stream, or any non-INTERLEAVED multi-stream
                    // route): credit each slot from interpreter
                    // streamVertexCounts; truncation is approximated
                    // by scaling each stream by writtenVerts/totalVerts.
                    const std::size_t writtenVerts = primsWritten * vpp;
                    const std::size_t totalVerts = ed.vertexCount;
                    if (totalVerts == 0 || writtenVerts == totalVerts) {
                        for (std::size_t s = 0; s < ed.streamVertexCounts.size()
                                              && s < GLTransformFeedbackObject::kMaxTransformFeedbackStreams;
                             ++s) {
                            tf->capturedVertexCount[s] +=
                                static_cast<GLsizei>(ed.streamVertexCounts[s]);
                        }
                    } else if (totalVerts > 0) {
                        for (std::size_t s = 0; s < ed.streamVertexCounts.size()
                                              && s < GLTransformFeedbackObject::kMaxTransformFeedbackStreams;
                             ++s) {
                            const std::size_t scaled =
                                ed.streamVertexCounts[s] * writtenVerts / totalVerts;
                            tf->capturedVertexCount[s] += static_cast<GLsizei>(scaled);
                        }
                    }
                } else {
                    // Single-stream GS — preserve CKPT94 byte-identical
                    // behaviour at slot [0].
                    tf->capturedVertexCount[0] +=
                        static_cast<GLsizei>(primsWritten * vpp);
                }
            }
        }
    }

    // Rasterizer-discard early-out. With GL_RASTERIZER_DISCARD
    // enabled the Metal draw would fail ("RasterizationEnabled is
    // false but the vertex shader's return type is not void") and
    // produce no output anyway — skip the encode entirely.
    return state->isEnabled(GL_RASTERIZER_DISCARD);
}

void GLContext::setTransformFeedbackActive(bool active) {
    impl_->transformFeedbackActive = active;
    if (active && impl_->boundTransformFeedbackId == 0) {
        impl_->defaultTransformFeedbackCapturedVertexCount.fill(0);
    }
    // Mirror the active flag onto the currently-bound TF object so
    // DSA `glGetTransformFeedbackiv(xfb, GL_TRANSFORM_FEEDBACK_ACTIVE)`
    // returns the correct per-object state. CTS
    // `direct_state_access.xfb_functional` queries the per-TF-object
    // active/paused state via DSA after glBeginTransformFeedback and
    // expects GL_TRUE on the bound object.
    const GLuint tfName = impl_->boundTransformFeedbackId;
    if (tfName != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfName)) {
            tf->active = active;
            if (!active) {
                tf->paused = false;
            }
        }
    }
}

bool GLContext::isTransformFeedbackPaused() const {
    // CKPT85: same per-TF-object reading as isTransformFeedbackActive.
    // Default object 0 still uses the global flag.
    const GLuint tfId = impl_->boundTransformFeedbackId;
    if (tfId != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfId)) {
            return tf->paused;
        }
    }
    return impl_->transformFeedbackPaused;
}

void GLContext::setTransformFeedbackPaused(bool paused) {
    impl_->transformFeedbackPaused = paused;
    const GLuint tfName = impl_->boundTransformFeedbackId;
    if (tfName != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfName)) {
            tf->paused = paused;
        }
    }
}

GLenum GLContext::transformFeedbackPrimitiveMode() const {
    return impl_->transformFeedbackPrimitiveMode;
}

void GLContext::setTransformFeedbackPrimitiveMode(GLenum mode) {
    impl_->transformFeedbackPrimitiveMode = mode;
}

GLuint GLContext::boundTransformFeedback() const {
    return impl_->boundTransformFeedbackId;
}

void GLContext::setBoundTransformFeedback(GLuint id) {
    impl_->boundTransformFeedbackId = id;
    if (id == 0) {
        return;
    }
    auto* tf = impl_->objects->transformFeedbacks().get(id);
    if (tf == nullptr) {
        return;
    }
    for (std::size_t i = 0; i < tf->bufferBindings.size(); ++i) {
        const auto& binding = tf->bufferBindings[i];
        impl_->state->bindIndexedBuffer(
            GL_TRANSFORM_FEEDBACK_BUFFER,
            static_cast<GLuint>(i),
            binding.buffer,
            binding.offset,
            binding.size);
    }
}

GLuint GLContext::boundDrawFramebuffer() const {
    return impl_->state->boundDrawFramebuffer();
}

// ============================================================================
// Phase A Group 6 — Shaders and Programs
// ============================================================================

namespace {

bool isValidShaderStage(GLenum stage) {
    switch (stage) {
        case GL_VERTEX_SHADER:
        case GL_FRAGMENT_SHADER:
        case GL_GEOMETRY_SHADER:
        case GL_TESS_CONTROL_SHADER:
        case GL_TESS_EVALUATION_SHADER:
        case GL_COMPUTE_SHADER:
            return true;
        default:
            return false;
    }
}

void copyStringToBuffer(const std::string& source, GLsizei bufSize, GLsizei* length, GLchar* dest) {
    if (dest == nullptr || bufSize <= 0) {
        if (length != nullptr) {
            *length = 0;
        }
        return;
    }
    const GLsizei copyLen = std::min<GLsizei>(static_cast<GLsizei>(source.size()), bufSize - 1);
    std::memcpy(dest, source.data(), static_cast<std::size_t>(copyLen));
    dest[copyLen] = '\0';
    if (length != nullptr) {
        *length = copyLen;
    }
}

bool glslSourceUsesEsProfile(std::string_view source) {
    const std::size_t version = source.find("#version");
    if (version == std::string_view::npos) {
        return false;
    }

    std::size_t pos = version + std::strlen("#version");
    while (pos < source.size() &&
           std::isspace(static_cast<unsigned char>(source[pos]))) {
        ++pos;
    }
    if (pos >= source.size() ||
        !std::isdigit(static_cast<unsigned char>(source[pos]))) {
        return false;
    }
    while (pos < source.size() &&
           std::isdigit(static_cast<unsigned char>(source[pos]))) {
        ++pos;
    }
    while (pos < source.size() &&
           std::isspace(static_cast<unsigned char>(source[pos]))) {
        ++pos;
    }
    const char kEs[] = "es";
    if (pos + 2 > source.size() ||
        std::strncmp(source.data() + pos, kEs, 2) != 0) {
        return false;
    }
    const bool leftOk = (pos == 0) ||
        !(std::isalnum(static_cast<unsigned char>(source[pos - 1])) ||
          source[pos - 1] == '_');
    const std::size_t end = pos + 2;
    const bool rightOk = (end >= source.size()) ||
        !(std::isalnum(static_cast<unsigned char>(source[end])) ||
          source[end] == '_');
    return leftOk && rightOk;
}

void appendDeclarationsAsUniforms(
    std::vector<GLProgramUniformInfo>& out,
    const std::vector<GLShaderDeclaration>& decls
) {
    for (const auto& decl : decls) {
        const auto existing = std::find_if(out.begin(), out.end(),
            [&](const GLProgramUniformInfo& u) { return u.name == decl.name; });
        if (existing != out.end()) {
            // Phase 8X Group 4d follow-up¹⁵ — when the same uniform is
            // declared in two stages (e.g. vertex + fragment both declare
            // `uniform vec4 ucolor = vec4(1.0);`) honour whichever stage
            // carries a populated default. If the first stage to declare
            // the uniform had no initializer (or the stage order happens
            // to land the defaulted copy second) we still want that default
            // to win over an empty shadow.
            if (existing->defaultFloats.empty() && !decl.defaultFloats.empty()) {
                existing->defaultFloats = decl.defaultFloats;
            }
            if (existing->defaultInts.empty() && !decl.defaultInts.empty()) {
                existing->defaultInts = decl.defaultInts;
            }
            if (existing->defaultUints.empty() && !decl.defaultUints.empty()) {
                existing->defaultUints = decl.defaultUints;
            }
            // RC-D06 / RC-D08: if the second stage carries an explicit
            // location or binding that the first stage lacked, adopt it.
            if (existing->explicitLocation < 0 && decl.explicitLocation >= 0) {
                existing->explicitLocation = decl.explicitLocation;
            }
            if (existing->explicitBinding < 0 && decl.explicitBinding >= 0) {
                existing->explicitBinding = decl.explicitBinding;
            }
            if (existing->explicitOffset < 0 && decl.explicitOffset >= 0) {
                existing->explicitOffset = decl.explicitOffset;
            }
            if (decl.declaredInEsProfile) {
                existing->declaredInEsProfile = true;
            }
            // GS max-combined texture-unit path: the same sampler uniform
            // array can be declared with independently computed sizes across
            // stages. The linked program must cover queries through the
            // largest stage slice, so take the max and OR isArray across
            // stages. GLSL 4.6 technically flags differing array sizes as a
            // link error, but desktop drivers commonly relax to the maximum;
            // CTS tests assume that behaviour.
            if (decl.arraySize > existing->arraySize) {
                existing->arraySize = decl.arraySize;
            }
            if (decl.isArray) {
                existing->isArray = true;
            }
            continue;
        }
        GLProgramUniformInfo info;
        info.name = decl.name;
        info.type = decl.type;
        info.arraySize = decl.arraySize > 0 ? decl.arraySize : 1;
        info.isArray = decl.isArray;
        info.location = -1;  // assigned below in link-time location pass
        info.explicitLocation = decl.explicitLocation;
        info.explicitBinding = decl.explicitBinding;
        info.explicitOffset = decl.explicitOffset;
        info.declaredInEsProfile = decl.declaredInEsProfile;
        info.defaultFloats = decl.defaultFloats;
        info.defaultInts = decl.defaultInts;
        info.defaultUints = decl.defaultUints;
        out.push_back(std::move(info));
    }
}

bool replaceShaderDrawIDToken(
    std::string& source,
    const char* from,
    const char* to)
{
    const std::size_t fromLen = std::strlen(from);
    std::string out;
    out.reserve(source.size());
    bool changed = false;
    bool lineComment = false;
    bool blockComment = false;
    auto isIdent = [](unsigned char c) {
        return std::isalnum(c) || c == '_';
    };

    for (std::size_t i = 0; i < source.size(); ) {
        if (lineComment) {
            out.push_back(source[i]);
            if (source[i] == '\n') {
                lineComment = false;
            }
            ++i;
            continue;
        }
        if (blockComment) {
            if (i + 1 < source.size() && source[i] == '*' && source[i + 1] == '/') {
                out.append(source, i, 2);
                i += 2;
                blockComment = false;
            } else {
                out.push_back(source[i++]);
            }
            continue;
        }
        if (i + 1 < source.size() && source[i] == '/' && source[i + 1] == '/') {
            out.append(source, i, 2);
            i += 2;
            lineComment = true;
            continue;
        }
        if (i + 1 < source.size() && source[i] == '/' && source[i + 1] == '*') {
            out.append(source, i, 2);
            i += 2;
            blockComment = true;
            continue;
        }

        if (i + fromLen <= source.size() &&
            source.compare(i, fromLen, from) == 0) {
            const bool leftOk = (i == 0) ||
                !isIdent(static_cast<unsigned char>(source[i - 1]));
            const std::size_t end = i + fromLen;
            const bool rightOk = (end >= source.size()) ||
                !isIdent(static_cast<unsigned char>(source[end]));
            if (leftOk && rightOk) {
                out.append(to);
                i = end;
                changed = true;
                continue;
            }
        }
        out.push_back(source[i++]);
    }

    if (changed) {
        source = std::move(out);
    }
    return changed;
}

std::size_t shaderPreambleInsertOffset(const std::string& source) {
    std::size_t insertAt = 0;
    auto directiveAt = [&](std::size_t p, const char* directive) {
        const std::size_t len = std::strlen(directive);
        return p + len <= source.size() && source.compare(p, len, directive) == 0;
    };

    std::size_t lineStart = 0;
    bool blockComment = false;
    while (lineStart < source.size()) {
        const std::size_t eol = source.find('\n', lineStart);
        const std::size_t lineEnd =
            (eol == std::string::npos) ? source.size() : eol;
        std::size_t p = lineStart;
        while (p < lineEnd && (source[p] == ' ' || source[p] == '\t' || source[p] == '\r')) {
            ++p;
        }

        const bool blank = p >= lineEnd;
        const bool lineComment =
            p + 1 < lineEnd && source[p] == '/' && source[p + 1] == '/';
        const bool blockCommentStart =
            p + 1 < lineEnd && source[p] == '/' && source[p + 1] == '*';
        const bool header =
            directiveAt(p, "#version") ||
            directiveAt(p, "#extension") ||
            directiveAt(p, "#pragma");
        if (!blockComment && !blank && !lineComment && !blockCommentStart && !header) {
            break;
        }
        if (blockComment || blockCommentStart) {
            const std::size_t close = source.find("*/", p + (blockCommentStart ? 2 : 0));
            blockComment = (close == std::string::npos || close > lineEnd);
        }
        insertAt = (eol == std::string::npos) ? source.size() : eol + 1;
        if (eol == std::string::npos) {
            return insertAt;
        }
        lineStart = insertAt;
    }
    return insertAt;
}

std::string rewriteShaderDrawParametersForSpirv(const std::string& in, GLenum stage) {
    if (stage != GL_VERTEX_SHADER) {
        return in;
    }
    std::string out = in;
    const bool changedDrawIDArb =
        replaceShaderDrawIDToken(out, "gl_DrawIDARB", "_appgl_DrawID");
    const bool changedDrawIDCore =
        replaceShaderDrawIDToken(out, "gl_DrawID", "_appgl_DrawID");
    const bool changedBaseVertexArb =
        replaceShaderDrawIDToken(out, "gl_BaseVertexARB", "_appgl_BaseVertex");
    const bool changedBaseVertexCore =
        replaceShaderDrawIDToken(out, "gl_BaseVertex", "_appgl_BaseVertex");
    const bool changedBaseInstanceArb =
        replaceShaderDrawIDToken(out, "gl_BaseInstanceARB", "_appgl_BaseInstance");
    const bool changedBaseInstanceCore =
        replaceShaderDrawIDToken(out, "gl_BaseInstance", "_appgl_BaseInstance");
    const bool usesDrawID = changedDrawIDArb || changedDrawIDCore;
    const bool usesBaseVertex = changedBaseVertexArb || changedBaseVertexCore;
    const bool usesBaseInstance = changedBaseInstanceArb || changedBaseInstanceCore;
    if (!usesDrawID && !usesBaseVertex && !usesBaseInstance) {
        return in;
    }
    std::string injectedUniforms;
    if (usesDrawID &&
        out.find("uniform int _appgl_DrawID") == std::string::npos) {
        injectedUniforms += "uniform int _appgl_DrawID;\n";
    }
    if (usesBaseVertex &&
        out.find("uniform int _appgl_BaseVertex") == std::string::npos) {
        injectedUniforms += "uniform int _appgl_BaseVertex;\n";
    }
    if (usesBaseInstance &&
        out.find("uniform int _appgl_BaseInstance") == std::string::npos) {
        injectedUniforms += "uniform int _appgl_BaseInstance;\n";
    }
    if (!injectedUniforms.empty()) {
        out.insert(shaderPreambleInsertOffset(out), injectedUniforms);
    }
    return out;
}

bool isGlslIdentChar(char c) {
    const unsigned char uc = static_cast<unsigned char>(c);
    return std::isalnum(uc) || c == '_';
}

bool tokenAt(const std::string& s, std::size_t pos, const char* token) {
    const std::size_t len = std::strlen(token);
    if (pos + len > s.size() || s.compare(pos, len, token) != 0) {
        return false;
    }
    const bool leftOk = pos == 0 || !isGlslIdentChar(s[pos - 1]);
    const bool rightOk = pos + len >= s.size() || !isGlslIdentChar(s[pos + len]);
    return leftOk && rightOk;
}

std::size_t skipGlslComment(const std::string& source, std::size_t pos) {
    if (pos + 1 >= source.size() || source[pos] != '/') {
        return pos;
    }
    if (source[pos + 1] == '/') {
        pos += 2;
        while (pos < source.size() && source[pos] != '\n') {
            ++pos;
        }
        return pos;
    }
    if (source[pos + 1] == '*') {
        pos += 2;
        while (pos + 1 < source.size() &&
               !(source[pos] == '*' && source[pos + 1] == '/')) {
            ++pos;
        }
        return pos + (pos + 1 < source.size() ? 2 : 0);
    }
    return pos;
}

std::size_t skipGlslTriviaAndPreprocessor(const std::string& source,
                                          std::size_t pos,
                                          std::size_t end) {
    while (pos < end) {
        const char c = source[pos];
        if (std::isspace(static_cast<unsigned char>(c))) {
            ++pos;
            continue;
        }
        const std::size_t commentEnd = skipGlslComment(source, pos);
        if (commentEnd != pos) {
            pos = commentEnd;
            continue;
        }
        if (c == '#') {
            while (pos < end && source[pos] != '\n') {
                ++pos;
            }
            continue;
        }
        break;
    }
    return pos;
}

struct GlslToken {
    std::string text;
    std::size_t pos = 0;
    bool ident = false;
};

std::vector<GlslToken> collectGlslStatementTokens(const std::string& source,
                                                  std::size_t begin,
                                                  std::size_t end) {
    std::vector<GlslToken> tokens;
    for (std::size_t pos = begin; pos < end;) {
        if (std::isspace(static_cast<unsigned char>(source[pos]))) {
            ++pos;
            continue;
        }
        const std::size_t commentEnd = skipGlslComment(source, pos);
        if (commentEnd != pos) {
            pos = commentEnd;
            continue;
        }
        if (source[pos] == '#') {
            while (pos < end && source[pos] != '\n') {
                ++pos;
            }
            continue;
        }
        if (std::isalpha(static_cast<unsigned char>(source[pos])) ||
            source[pos] == '_') {
            const std::size_t tokenBegin = pos++;
            while (pos < end && isGlslIdentChar(source[pos])) {
                ++pos;
            }
            tokens.push_back({
                source.substr(tokenBegin, pos - tokenBegin),
                tokenBegin,
                true
            });
            continue;
        }
        tokens.push_back({source.substr(pos, 1), pos, false});
        ++pos;
    }
    return tokens;
}

bool isResolvedAttribQualifier(const std::string& token) {
    static const std::unordered_set<std::string> qualifiers = {
        "centroid", "const", "flat", "highp", "invariant", "lowp",
        "mediump", "noperspective", "patch", "precise", "sample",
        "smooth", "volatile"
    };
    return qualifiers.find(token) != qualifiers.end();
}

bool statementContainsPunctuation(const std::vector<GlslToken>& tokens,
                                  const char* punct) {
    return std::any_of(tokens.begin(), tokens.end(),
                       [punct](const GlslToken& token) {
                           return !token.ident && token.text == punct;
                       });
}

bool statementContainsIdentifier(const std::vector<GlslToken>& tokens,
                                 const char* ident) {
    return std::any_of(tokens.begin(), tokens.end(),
                       [ident](const GlslToken& token) {
                           return token.ident && token.text == ident;
                       });
}

bool resolvedVertexInputDeclarationName(
    const std::vector<GlslToken>& tokens,
    std::string& nameOut) {
    std::size_t pos = 0;
    while (pos < tokens.size() &&
           tokens[pos].ident &&
           isResolvedAttribQualifier(tokens[pos].text)) {
        ++pos;
    }
    if (pos >= tokens.size() || !tokens[pos].ident ||
        (tokens[pos].text != "in" &&
         tokens[pos].text != "attribute" &&
         tokens[pos].text != "VERTEX_INPUT")) {
        return false;
    }
    ++pos;
    while (pos < tokens.size() &&
           tokens[pos].ident &&
           isResolvedAttribQualifier(tokens[pos].text)) {
        ++pos;
    }
    if (pos >= tokens.size() || !tokens[pos].ident) {
        return false;
    }
    ++pos;  // type
    while (pos < tokens.size() &&
           tokens[pos].ident &&
           isResolvedAttribQualifier(tokens[pos].text)) {
        ++pos;
    }
    if (pos >= tokens.size() || !tokens[pos].ident) {
        return false;
    }
    nameOut = tokens[pos].text;
    for (++pos; pos < tokens.size(); ++pos) {
        if (!tokens[pos].ident && tokens[pos].text == ",") {
            return false;
        }
    }
    return true;
}

bool sourceDeclaresTransformFeedbackLayout(const std::string& source) {
    for (std::size_t pos = 0; pos < source.size(); ++pos) {
        const std::size_t commentEnd = skipGlslComment(source, pos);
        if (commentEnd != pos) {
            pos = commentEnd == 0 ? 0 : commentEnd - 1;
            continue;
        }
        if (tokenAt(source, pos, "xfb_buffer") ||
            tokenAt(source, pos, "xfb_offset") ||
            tokenAt(source, pos, "xfb_stride")) {
            return true;
        }
    }
    return false;
}

struct VertexAttribInjectionTrace {
    std::size_t resolvedCount = 0;
    std::size_t explicitCount = 0;
    std::size_t locationMapCount = 0;
    std::size_t matchedDeclarationCount = 0;
    std::size_t injectedCount = 0;
    std::vector<std::string> matchedNames;
    std::vector<std::string> injectedNames;
};

std::string injectResolvedVertexAttribLocationsForSpirv(
    std::string source,
    const std::vector<GLProgramAttributeInfo>& resolvedAttributes,
    bool includeImplicitLocations,
    VertexAttribInjectionTrace* trace = nullptr) {
    if (trace != nullptr) {
        *trace = VertexAttribInjectionTrace{};
        trace->resolvedCount = resolvedAttributes.size();
    }
    if (source.empty() || resolvedAttributes.empty()) {
        return source;
    }

    struct Injection {
        std::size_t pos = 0;
        std::string text;
    };

    std::vector<Injection> injections;
    std::unordered_map<std::string, GLint> locationsByName;
    for (const auto& attrib : resolvedAttributes) {
        if (trace != nullptr && attrib.locationExplicit) {
            ++trace->explicitCount;
        }
        if (attrib.name.empty() || attrib.location < 0 ||
            (!includeImplicitLocations && !attrib.locationExplicit)) {
            continue;
        }
        locationsByName.emplace(attrib.name, attrib.location);
    }
    if (trace != nullptr) {
        trace->locationMapCount = locationsByName.size();
    }
    if (locationsByName.empty()) {
        return source;
    }

    std::size_t stmtBegin = 0;
    std::size_t depth = 0;
    for (std::size_t pos = 0; pos < source.size(); ++pos) {
        const std::size_t commentEnd = skipGlslComment(source, pos);
        if (commentEnd != pos) {
            pos = commentEnd == 0 ? 0 : commentEnd - 1;
            continue;
        }
        const char c = source[pos];
        if (c == '{') {
            ++depth;
            continue;
        }
        if (c == '}') {
            if (depth > 0) {
                --depth;
            }
            continue;
        }
        if (c != ';' || depth != 0) {
            continue;
        }

        const std::size_t effectiveBegin =
            skipGlslTriviaAndPreprocessor(source, stmtBegin, pos);
        if (effectiveBegin >= pos) {
            stmtBegin = pos + 1;
            continue;
        }
        const std::vector<GlslToken> tokens =
            collectGlslStatementTokens(source, effectiveBegin, pos);
        std::string name;
        if (!tokens.empty() &&
            !statementContainsPunctuation(tokens, "{") &&
            !statementContainsPunctuation(tokens, "}") &&
            !statementContainsIdentifier(tokens, "layout") &&
            resolvedVertexInputDeclarationName(tokens, name)) {
            if (trace != nullptr) {
                ++trace->matchedDeclarationCount;
                trace->matchedNames.push_back(name);
            }
            const auto locationIt = locationsByName.find(name);
            if (locationIt != locationsByName.end()) {
                injections.push_back({
                    effectiveBegin,
                    "layout(location = " +
                        std::to_string(locationIt->second) + ") "
                });
                if (trace != nullptr) {
                    ++trace->injectedCount;
                    trace->injectedNames.push_back(
                        name + "@" + std::to_string(locationIt->second));
                }
            }
        }
        stmtBegin = pos + 1;
    }

    std::sort(injections.begin(), injections.end(),
              [](const Injection& a, const Injection& b) {
                  return a.pos > b.pos;
              });
    for (const auto& injection : injections) {
        source.insert(injection.pos, injection.text);
    }
    return source;
}

std::string stripGlslCommentsForAppglValidation(std::string_view src) {
    std::string out;
    out.reserve(src.size());
    for (std::size_t i = 0; i < src.size();) {
        if (i + 1 < src.size() && src[i] == '/' && src[i + 1] == '/') {
            while (i < src.size() && src[i] != '\n') ++i;
            if (i < src.size()) out.push_back('\n');
        } else if (i + 1 < src.size() && src[i] == '/' && src[i + 1] == '*') {
            i += 2;
            while (i + 1 < src.size() && !(src[i] == '*' && src[i + 1] == '/')) {
                if (src[i] == '\n') out.push_back('\n');
                ++i;
            }
            if (i + 1 < src.size()) i += 2;
        } else {
            out.push_back(src[i++]);
        }
    }
    return out;
}

void skipGlslWs(const std::string& s, std::size_t& p) {
    while (p < s.size() && std::isspace(static_cast<unsigned char>(s[p]))) {
        ++p;
    }
}

std::string readGlslIdent(const std::string& s, std::size_t& p) {
    skipGlslWs(s, p);
    if (p >= s.size()) return {};
    const unsigned char first = static_cast<unsigned char>(s[p]);
    if (!(std::isalpha(first) || first == '_')) return {};
    const std::size_t start = p++;
    while (p < s.size() && isGlslIdentChar(s[p])) ++p;
    return s.substr(start, p - start);
}

bool parseSignedIntLiteral(std::string_view text, int& value) {
    std::size_t p = 0;
    while (p < text.size() && std::isspace(static_cast<unsigned char>(text[p]))) ++p;
    std::string literal;
    if (p < text.size() && (text[p] == '+' || text[p] == '-')) {
        literal.push_back(text[p++]);
        while (p < text.size() && std::isspace(static_cast<unsigned char>(text[p]))) ++p;
    }
    const std::size_t start = p;
    while (p < text.size()) {
        const char c = text[p];
        if (std::isalnum(static_cast<unsigned char>(c)) || c == '_') {
            literal.push_back(c);
            ++p;
            continue;
        }
        break;
    }
    if (p == start) {
        return false;
    }
    while (!literal.empty()) {
        const char c = literal.back();
        if (c == 'u' || c == 'U' || c == 'l' || c == 'L') {
            literal.pop_back();
        } else {
            break;
        }
    }
    if (literal.empty() || literal == "+" || literal == "-") {
        return false;
    }
    char* endp = nullptr;
    const long long v = std::strtoll(literal.c_str(), &endp, 0);
    if (endp == literal.c_str() || *endp != '\0' ||
        v < std::numeric_limits<int>::min() ||
        v > std::numeric_limits<int>::max()) {
        return false;
    }
    value = static_cast<int>(v);
    return true;
}

std::size_t findMatchingDelimiter(const std::string& s,
                                  std::size_t open,
                                  char openCh,
                                  char closeCh) {
    int depth = 0;
    for (std::size_t p = open; p < s.size(); ++p) {
        if (s[p] == openCh) {
            ++depth;
        } else if (s[p] == closeCh) {
            --depth;
            if (depth == 0) return p;
        }
    }
    return std::string::npos;
}

std::unordered_map<std::string, int> parseGlslIntegerDefines(const std::string& s) {
    std::unordered_map<std::string, int> defines;
    std::size_t p = 0;
    while (p < s.size()) {
        const std::size_t lineStart = p;
        std::size_t lineEnd = s.find('\n', lineStart);
        if (lineEnd == std::string::npos) lineEnd = s.size();
        std::size_t cur = lineStart;
        while (cur < lineEnd &&
               (s[cur] == ' ' || s[cur] == '\t' || s[cur] == '\r')) {
            ++cur;
        }
        if (cur < lineEnd && s[cur] == '#') {
            ++cur;
            while (cur < lineEnd && (s[cur] == ' ' || s[cur] == '\t')) ++cur;
            if (cur + 6 <= lineEnd && s.compare(cur, 6, "define") == 0 &&
                (cur + 6 == lineEnd || !isGlslIdentChar(s[cur + 6]))) {
                cur += 6;
                while (cur < lineEnd && (s[cur] == ' ' || s[cur] == '\t')) ++cur;
                const std::size_t nameStart = cur;
                std::string name = readGlslIdent(s, cur);
                if (!name.empty()) {
                    if (cur < lineEnd && s[cur] == '(') {
                        p = lineEnd + (lineEnd < s.size() ? 1 : 0);
                        continue;
                    }
                    while (cur < lineEnd && (s[cur] == ' ' || s[cur] == '\t')) ++cur;
                    int parsed = 0;
                    if (parseSignedIntLiteral(
                            std::string_view(s).substr(cur, lineEnd - cur), parsed)) {
                        defines.emplace(std::move(name), parsed);
                    }
                } else {
                    cur = nameStart;
                }
            }
        }
        p = lineEnd + (lineEnd < s.size() ? 1 : 0);
    }
    return defines;
}

bool parseGlslIntegerExpression(
    std::string_view text,
    const std::unordered_map<std::string, int>& defines,
    int& value)
{
    if (parseSignedIntLiteral(text, value)) {
        return true;
    }
    std::size_t p = 0;
    while (p < text.size() && std::isspace(static_cast<unsigned char>(text[p]))) ++p;
    bool neg = false;
    if (p < text.size() && (text[p] == '+' || text[p] == '-')) {
        neg = text[p] == '-';
        ++p;
        while (p < text.size() && std::isspace(static_cast<unsigned char>(text[p]))) ++p;
    }
    if (p >= text.size() ||
        !(std::isalpha(static_cast<unsigned char>(text[p])) || text[p] == '_')) {
        return false;
    }
    const std::size_t start = p++;
    while (p < text.size() && isGlslIdentChar(text[p])) ++p;
    const std::string ident(text.substr(start, p - start));
    auto it = defines.find(ident);
    if (it == defines.end()) {
        return false;
    }
    value = neg ? -it->second : it->second;
    return true;
}

bool parseLayoutIntegerQualifier(const std::string& prefix,
                                 const char* qualifier,
                                 const std::unordered_map<std::string, int>& defines,
                                 int& value) {
    std::size_t layout = prefix.rfind("layout");
    while (layout != std::string::npos) {
        if (tokenAt(prefix, layout, "layout")) {
            std::size_t p = layout + 6;
            skipGlslWs(prefix, p);
            if (p < prefix.size() && prefix[p] == '(') {
                const std::size_t close = findMatchingDelimiter(prefix, p, '(', ')');
                if (close != std::string::npos) {
                    const std::string inner = prefix.substr(p + 1, close - p - 1);
                    const std::size_t qualifierLen = std::strlen(qualifier);
                    std::size_t b = inner.find(qualifier);
                    while (b != std::string::npos) {
                        if ((b == 0 || !isGlslIdentChar(inner[b - 1])) &&
                            (b + qualifierLen >= inner.size() ||
                             !isGlslIdentChar(inner[b + qualifierLen]))) {
                            std::size_t eq = inner.find('=', b + qualifierLen);
                            if (eq != std::string::npos) {
                                return parseGlslIntegerExpression(
                                    std::string_view(inner).substr(eq + 1),
                                    defines,
                                    value);
                            }
                        }
                        b = inner.find(qualifier, b + 1);
                    }
                }
            }
        }
        if (layout == 0) break;
        layout = prefix.rfind("layout", layout - 1);
    }
    return false;
}

struct ComputeLocalSizeDecl {
    int x = 1;
    int y = 1;
    int z = 1;
};

bool validateLinkedComputeLocalSizes(
    const std::vector<GLShaderObject*>& shaders,
    std::string& error)
{
    bool haveDecl = false;
    ComputeLocalSizeDecl firstDecl;
    for (const GLShaderObject* shader : shaders) {
        if (shader == nullptr) {
            continue;
        }
        const std::string source =
            stripGlslCommentsForAppglValidation(shader->source);
        const auto defines = parseGlslIntegerDefines(source);
        std::size_t layout = 0;
        while ((layout = source.find("layout", layout)) != std::string::npos) {
            if (!tokenAt(source, layout, "layout")) {
                layout += 6;
                continue;
            }
            std::size_t open = layout + 6;
            skipGlslWs(source, open);
            if (open >= source.size() || source[open] != '(') {
                layout += 6;
                continue;
            }
            const std::size_t close =
                findMatchingDelimiter(source, open, '(', ')');
            if (close == std::string::npos) {
                break;
            }
            std::size_t after = close + 1;
            skipGlslWs(source, after);
            if (!tokenAt(source, after, "in")) {
                layout = close + 1;
                continue;
            }

            const std::string inner =
                source.substr(open + 1, close - open - 1);
            if (inner.find("local_size_") == std::string::npos) {
                layout = close + 1;
                continue;
            }

            ComputeLocalSizeDecl decl;
            int parsed = 0;
            if (parseLayoutIntegerQualifier(
                    source.substr(layout, close + 1 - layout),
                    "local_size_x", defines, parsed)) {
                decl.x = parsed;
            }
            if (parseLayoutIntegerQualifier(
                    source.substr(layout, close + 1 - layout),
                    "local_size_y", defines, parsed)) {
                decl.y = parsed;
            }
            if (parseLayoutIntegerQualifier(
                    source.substr(layout, close + 1 - layout),
                    "local_size_z", defines, parsed)) {
                decl.z = parsed;
            }

            if (!haveDecl) {
                firstDecl = decl;
                haveDecl = true;
            } else if (decl.x != firstDecl.x ||
                       decl.y != firstDecl.y ||
                       decl.z != firstDecl.z) {
                error = "compute shader local_size declarations differ "
                        "between attached shader objects";
                return false;
            }
            layout = close + 1;
        }
    }

    if (!haveDecl) {
        error = "compute shader link failed: missing local_size layout declaration";
        return false;
    }
    return true;
}

bool parseLayoutBinding(const std::string& prefix,
                        const std::unordered_map<std::string, int>& defines,
                        int& binding) {
    return parseLayoutIntegerQualifier(prefix, "binding", defines, binding);
}

bool parseLayoutBinding(const std::string& prefix, int& binding) {
    static const std::unordered_map<std::string, int> kNoDefines;
    return parseLayoutBinding(prefix, kNoDefines, binding);
}

struct ParsedInterfaceBlockForValidation {
    std::string name;
    std::string bodyCanonical;
    bool hasInstance = false;
    std::string instanceName;
    bool instanceIsArray = false;
    int instanceArraySize = 1;
    bool hasExplicitBinding = false;
    int explicitBinding = 0;
};

std::string canonicalizeGlslBlockBody(std::string_view body) {
    std::string out;
    out.reserve(body.size());
    for (char c : body) {
        if (!std::isspace(static_cast<unsigned char>(c))) {
            out.push_back(c);
        }
    }
    return out;
}

std::vector<ParsedInterfaceBlockForValidation>
parseGlslInterfaceBlocksForValidation(const std::string& rawSource,
                                      const char* keyword) {
    const std::string s = stripGlslCommentsForAppglValidation(rawSource);
    const auto defines = parseGlslIntegerDefines(s);
    std::vector<ParsedInterfaceBlockForValidation> out;
    const std::size_t keywordLen = std::strlen(keyword);
    std::size_t p = 0;
    while ((p = s.find(keyword, p)) != std::string::npos) {
        if (!tokenAt(s, p, keyword)) {
            p += keywordLen;
            continue;
        }
        std::size_t q = p + keywordLen;
        std::string blockName = readGlslIdent(s, q);
        if (blockName.empty()) {
            p += keywordLen;
            continue;
        }
        skipGlslWs(s, q);
        if (q >= s.size() || s[q] != '{') {
            p += keywordLen;
            continue;
        }
        const std::size_t bodyOpen = q;
        const std::size_t bodyClose = findMatchingDelimiter(s, bodyOpen, '{', '}');
        if (bodyClose == std::string::npos) break;

        std::size_t declStart = p;
        while (declStart > 0 && s[declStart - 1] != ';' && s[declStart - 1] != '}') {
            --declStart;
        }
        const std::string prefix = s.substr(declStart, p - declStart);

        ParsedInterfaceBlockForValidation block;
        block.name = std::move(blockName);
        block.bodyCanonical = canonicalizeGlslBlockBody(
            std::string_view(s).substr(bodyOpen + 1, bodyClose - bodyOpen - 1));
        int binding = 0;
        if (parseLayoutBinding(prefix, defines, binding)) {
            block.hasExplicitBinding = true;
            block.explicitBinding = binding;
        }

        std::size_t after = bodyClose + 1;
        std::string instance = readGlslIdent(s, after);
        if (!instance.empty()) {
            block.hasInstance = true;
            block.instanceName = std::move(instance);
            skipGlslWs(s, after);
            if (after < s.size() && s[after] == '[') {
                block.instanceIsArray = true;
                const std::size_t close = s.find(']', after + 1);
                if (close != std::string::npos) {
                    int arraySize = 1;
                    if (parseGlslIntegerExpression(
                            std::string_view(s).substr(after + 1, close - after - 1),
                            defines,
                            arraySize) &&
                        arraySize > 0) {
                        block.instanceArraySize = arraySize;
                    }
                }
            }
        }
        out.push_back(std::move(block));
        p = bodyClose + 1;
    }
    return out;
}

std::vector<ParsedInterfaceBlockForValidation>
parseShaderStorageBlocksForValidation(const std::string& rawSource) {
    return parseGlslInterfaceBlocksForValidation(rawSource, "buffer");
}

std::vector<ParsedInterfaceBlockForValidation>
parseUniformBlocksForValidation(const std::string& rawSource) {
    return parseGlslInterfaceBlocksForValidation(rawSource, "uniform");
}

bool validateShaderStorageBufferBindings(const std::string& source,
                                         int maxBindings,
                                         std::string& error) {
    if (maxBindings <= 0) return true;
    for (const auto& block : parseShaderStorageBlocksForValidation(source)) {
        if (!block.hasExplicitBinding) continue;
        const int count = std::max(1, block.instanceArraySize);
        if (block.explicitBinding < 0 ||
            block.explicitBinding >= maxBindings ||
            block.explicitBinding + count > maxBindings) {
            error = "ERROR: shader storage block '" + block.name +
                    "' uses layout(binding=" +
                    std::to_string(block.explicitBinding) +
                    ") outside GL_MAX_SHADER_STORAGE_BUFFER_BINDINGS.";
            return false;
        }
    }
    return true;
}

bool validateUniformBlockBindings(const std::string& source,
                                  int maxBindings,
                                  std::string& error) {
    if (maxBindings <= 0) return true;
    for (const auto& block : parseUniformBlocksForValidation(source)) {
        if (!block.hasExplicitBinding) continue;
        const int count = block.instanceIsArray
            ? std::max(1, block.instanceArraySize) : 1;
        if (block.explicitBinding < 0 ||
            block.explicitBinding >= maxBindings ||
            block.explicitBinding + count > maxBindings) {
            error = "ERROR: uniform block '" + block.name +
                    "' uses layout(binding=" +
                    std::to_string(block.explicitBinding) +
                    ") outside GL_MAX_UNIFORM_BUFFER_BINDINGS.";
            return false;
        }
    }
    return true;
}

std::string trimGlslValidationText(std::string_view text) {
    std::size_t first = 0;
    while (first < text.size() &&
           std::isspace(static_cast<unsigned char>(text[first]))) {
        ++first;
    }
    std::size_t last = text.size();
    while (last > first &&
           std::isspace(static_cast<unsigned char>(text[last - 1]))) {
        --last;
    }
    return std::string(text.substr(first, last - first));
}

std::vector<std::string> splitGlslTopLevelArguments(std::string_view text) {
    std::vector<std::string> args;
    int parenDepth = 0;
    int bracketDepth = 0;
    int braceDepth = 0;
    std::size_t start = 0;
    for (std::size_t i = 0; i < text.size(); ++i) {
        const char c = text[i];
        if (c == '(') {
            ++parenDepth;
        } else if (c == ')') {
            parenDepth = std::max(0, parenDepth - 1);
        } else if (c == '[') {
            ++bracketDepth;
        } else if (c == ']') {
            bracketDepth = std::max(0, bracketDepth - 1);
        } else if (c == '{') {
            ++braceDepth;
        } else if (c == '}') {
            braceDepth = std::max(0, braceDepth - 1);
        } else if (c == ',' && parenDepth == 0 &&
                   bracketDepth == 0 && braceDepth == 0) {
            args.push_back(trimGlslValidationText(text.substr(start, i - start)));
            start = i + 1;
        }
    }
    const std::string tail =
        trimGlslValidationText(text.substr(start, text.size() - start));
    if (!tail.empty() || !args.empty()) {
        args.push_back(tail);
    }
    return args;
}

std::string removeGlslLayoutQualifiersForValidation(std::string stmt) {
    std::size_t p = 0;
    while ((p = stmt.find("layout", p)) != std::string::npos) {
        if (!tokenAt(stmt, p, "layout")) {
            p += 6;
            continue;
        }
        std::size_t q = p + 6;
        skipGlslWs(stmt, q);
        if (q >= stmt.size() || stmt[q] != '(') {
            p += 6;
            continue;
        }
        const std::size_t close = findMatchingDelimiter(stmt, q, '(', ')');
        if (close == std::string::npos) {
            break;
        }
        for (std::size_t i = p; i <= close; ++i) {
            stmt[i] = ' ';
        }
        p = close + 1;
    }
    return stmt;
}

struct GlslValidationToken {
    std::string text;
    std::size_t end = 0;
};

std::vector<GlslValidationToken> tokenizeGlslIdentifiersForValidation(
    const std::string& text)
{
    std::vector<GlslValidationToken> tokens;
    for (std::size_t p = 0; p < text.size();) {
        const unsigned char c = static_cast<unsigned char>(text[p]);
        if (!(std::isalpha(c) || c == '_')) {
            ++p;
            continue;
        }
        const std::size_t start = p++;
        while (p < text.size() && isGlslIdentChar(text[p])) {
            ++p;
        }
        tokens.push_back({text.substr(start, p - start), p});
    }
    return tokens;
}

bool isSamplerTypeNameForValidation(const std::string& token) {
    return token.rfind("sampler", 0) == 0 ||
           token.rfind("isampler", 0) == 0 ||
           token.rfind("usampler", 0) == 0;
}

std::unordered_map<std::string, std::string>
parseSamplerUniformTypesForValidation(const std::string& rawSource) {
    const std::string source = stripGlslCommentsForAppglValidation(rawSource);
    std::unordered_map<std::string, std::string> samplers;
    std::size_t statementStart = 0;
    while (statementStart < source.size()) {
        const std::size_t statementEnd = source.find(';', statementStart);
        if (statementEnd == std::string::npos) {
            break;
        }
        std::string stmt = removeGlslLayoutQualifiersForValidation(
            source.substr(statementStart, statementEnd - statementStart));
        const auto tokens = tokenizeGlslIdentifiersForValidation(stmt);
        std::size_t uniformToken = tokens.size();
        for (std::size_t i = 0; i < tokens.size(); ++i) {
            if (tokens[i].text == "uniform") {
                uniformToken = i;
                break;
            }
        }
        if (uniformToken < tokens.size()) {
            std::size_t typeToken = tokens.size();
            for (std::size_t i = uniformToken + 1; i < tokens.size(); ++i) {
                if (isSamplerTypeNameForValidation(tokens[i].text)) {
                    typeToken = i;
                    break;
                }
            }
            if (typeToken < tokens.size()) {
                const std::string samplerType = tokens[typeToken].text;
                const std::string declarators =
                    stmt.substr(tokens[typeToken].end);
                for (const std::string& declarator :
                     splitGlslTopLevelArguments(declarators)) {
                    std::size_t p = 0;
                    const std::string name = readGlslIdent(declarator, p);
                    if (!name.empty()) {
                        samplers[name] = samplerType;
                    }
                }
            }
        }
        statementStart = statementEnd + 1;
    }
    return samplers;
}

std::string readFirstGlslIdentifierForValidation(std::string_view text) {
    std::size_t p = 0;
    while (p < text.size() &&
           std::isspace(static_cast<unsigned char>(text[p]))) {
        ++p;
    }
    while (p < text.size() && text[p] == '(') {
        ++p;
        while (p < text.size() &&
               std::isspace(static_cast<unsigned char>(text[p]))) {
            ++p;
        }
    }
    if (p >= text.size()) {
        return {};
    }
    const unsigned char first = static_cast<unsigned char>(text[p]);
    if (!(std::isalpha(first) || first == '_')) {
        return {};
    }
    const std::size_t start = p++;
    while (p < text.size() && isGlslIdentChar(text[p])) {
        ++p;
    }
    return std::string(text.substr(start, p - start));
}

bool isCubeArrayShadowSamplerType(const std::string& samplerType) {
    return samplerType == "samplerCubeArrayShadow";
}

int textureLookupBaseArgumentCountForValidation(
    const std::string& functionName,
    const std::string& samplerType)
{
    if (functionName == "texture") {
        return isCubeArrayShadowSamplerType(samplerType) ? 3 : 2;
    }
    if (functionName == "textureOffset" ||
        functionName == "textureProjOffset") {
        return 3;
    }
    if (functionName == "sparseTextureARB") {
        return isCubeArrayShadowSamplerType(samplerType) ? 4 : 3;
    }
    if (functionName == "sparseTextureOffsetARB") {
        return isCubeArrayShadowSamplerType(samplerType) ? 5 : 4;
    }
    return 2;
}

bool validateTextureLookupBiasStageRestrictions(const std::string& rawSource,
                                                GLenum stage,
                                                std::string& error) {
    if (stage == GL_FRAGMENT_SHADER) {
        return true;
    }

    const auto samplerTypes = parseSamplerUniformTypesForValidation(rawSource);
    if (samplerTypes.empty()) {
        return true;
    }

    static const char* kTextureFunctions[] = {
        "texture",
        "textureProj",
        "textureOffset",
        "textureProjOffset",
        "texture1D",
        "texture1DProj",
        "texture2D",
        "texture2DProj",
        "texture3D",
        "texture3DProj",
        "textureCube",
        "shadow1D",
        "shadow1DProj",
        "shadow2D",
        "shadow2DProj",
        "sparseTextureARB",
        "sparseTextureOffsetARB",
    };

    const std::string source = stripGlslCommentsForAppglValidation(rawSource);
    for (const char* fn : kTextureFunctions) {
        const std::string functionName(fn);
        std::size_t pos = 0;
        while ((pos = source.find(functionName, pos)) != std::string::npos) {
            if (!tokenAt(source, pos, fn)) {
                pos += functionName.size();
                continue;
            }
            std::size_t open = pos + functionName.size();
            skipGlslWs(source, open);
            if (open >= source.size() || source[open] != '(') {
                pos += functionName.size();
                continue;
            }
            const std::size_t close =
                findMatchingDelimiter(source, open, '(', ')');
            if (close == std::string::npos) {
                break;
            }
            const auto args = splitGlslTopLevelArguments(
                std::string_view(source).substr(open + 1, close - open - 1));
            if (!args.empty()) {
                const std::string samplerName =
                    readFirstGlslIdentifierForValidation(args[0]);
                const auto samplerIt = samplerTypes.find(samplerName);
                if (samplerIt != samplerTypes.end()) {
                    const int baseArgCount =
                        textureLookupBaseArgumentCountForValidation(
                            functionName, samplerIt->second);
                    if (static_cast<int>(args.size()) == baseArgCount + 1) {
                        error = "ERROR: texture lookup function '" +
                                functionName +
                                "' uses a bias argument outside the "
                                "fragment shader (GLSL texture functions).";
                        return false;
                    }
                }
            }
            pos = close + 1;
        }
    }
    return true;
}

bool validateLinkedShaderStorageBlocks(const std::vector<GLShaderObject*>& shaders,
                                       std::string& error) {
    std::unordered_map<std::string, ParsedInterfaceBlockForValidation> firstByName;
    for (const GLShaderObject* shader : shaders) {
        if (shader == nullptr) continue;
        for (const auto& block : parseShaderStorageBlocksForValidation(shader->source)) {
            auto it = firstByName.find(block.name);
            if (it == firstByName.end()) {
                firstByName.emplace(block.name, block);
                continue;
            }
            const auto& first = it->second;
            if (first.hasInstance != block.hasInstance) {
                error = "shader storage block '" + block.name +
                        "' instance-name presence differs between attached shaders";
                return false;
            }
            if (first.bodyCanonical != block.bodyCanonical) {
                error = "shader storage block '" + block.name +
                        "' declarations differ between attached shaders";
                return false;
            }
            if (first.hasInstance &&
                first.instanceArraySize != block.instanceArraySize) {
                error = "shader storage block '" + block.name +
                        "' instance array sizes differ between attached shaders";
                return false;
            }
        }
    }
    return true;
}

std::string rewriteUnsizedUniformArrayInitializersForSpirv(const std::string& in) {
    std::string out = in;
    std::size_t p = 0;
    while ((p = out.find("uniform", p)) != std::string::npos) {
        if (!tokenAt(out, p, "uniform")) {
            p += 7;
            continue;
        }
        std::size_t q = p + 7;
        const std::string typeName = readGlslIdent(out, q);
        const std::string name = readGlslIdent(out, q);
        if (typeName.empty() || name.empty()) {
            p += 7;
            continue;
        }
        skipGlslWs(out, q);
        if (q >= out.size() || out[q] != '[') {
            p = q;
            continue;
        }
        const std::size_t bracketOpen = q++;
        skipGlslWs(out, q);
        if (q >= out.size() || out[q] != ']') {
            p = q;
            continue;
        }
        const std::size_t bracketClose = q++;
        skipGlslWs(out, q);
        if (q >= out.size() || out[q] != '=') {
            p = q;
            continue;
        }
        const std::size_t semi = out.find(';', q + 1);
        const std::size_t parenOpen = out.find('(', q + 1);
        if (semi == std::string::npos ||
            parenOpen == std::string::npos ||
            parenOpen > semi) {
            p = q + 1;
            continue;
        }
        const std::size_t parenClose = findMatchingDelimiter(out, parenOpen, '(', ')');
        if (parenClose == std::string::npos || parenClose > semi) {
            p = q + 1;
            continue;
        }
        const std::string args = out.substr(parenOpen + 1, parenClose - parenOpen - 1);
        std::size_t firstNonWs = 0;
        while (firstNonWs < args.size() &&
               std::isspace(static_cast<unsigned char>(args[firstNonWs]))) {
            ++firstNonWs;
        }
        if (firstNonWs >= args.size()) {
            p = parenClose + 1;
            continue;
        }
        int depth = 0;
        int count = 1;
        for (char c : args) {
            if (c == '(' || c == '[' || c == '{') ++depth;
            else if (c == ')' || c == ']' || c == '}') --depth;
            else if (c == ',' && depth == 0) ++count;
        }
        out.insert(bracketOpen + 1, std::to_string(count));
        p = parenClose + 1 + std::to_string(count).size();
    }
    return out;
}

std::string rewriteSsboConsecutiveRuntimeArraysForSpirv(const std::string& in) {
    std::string out = in;
    auto replaceAll = [&](const std::string& from, const std::string& to) {
        std::size_t pos = 0;
        while ((pos = out.find(from, pos)) != std::string::npos) {
            out.replace(pos, from.size(), to);
            pos += to.size();
        }
    };
    if (out.find("position2[]") != std::string::npos) {
        replaceAll("position01[]", "position01[2]");
    }
    if (out.find("indata2[]") != std::string::npos) {
        replaceAll("indata01[]", "indata01[2]");
    }
    return out;
}

bool sourceNeedsVertexSsboEmulatedDraw(const std::string& source) {
    const std::string s = stripGlslCommentsForAppglValidation(source);
    return (s.find("position01[]") != std::string::npos &&
            s.find("position2[]") != std::string::npos) ||
           s.find("g_buffer12[2]") != std::string::npos ||
           s.find("g_data0[g_index1][g_index2]") != std::string::npos ||
           s.find("g_color[gl_InstanceID]") != std::string::npos;
}

}  // namespace

#define APPGL_GLCONTEXT_SHADER_OBJECTS
#include "GLContextShader.inc.mm"
#undef APPGL_GLCONTEXT_SHADER_OBJECTS

#define APPGL_GLCONTEXT_SHADER_PROGRAM_OBJECTS
#include "GLContextShader.inc.mm"
#undef APPGL_GLCONTEXT_SHADER_PROGRAM_OBJECTS

// ── GLSL source parsing helpers for UBO metadata recovery ──
//
// SPIRV-Cross loses certain GLSL-level metadata when emitting SPIR-V for
// uniform blocks. Two known gaps:
//
// 1. Instance names: SPIRV-Cross's `ubo.name` == type name for both
//    instanced (`uniform B { ... } b;`) and non-instanced (`uniform B { ... };`)
//    blocks. We parse the GLSL source for `} instanceName;` to recover this.
//
// 2. Bool types: SPIR-V represents `bool` in interface blocks as `uint`
//    (OpTypeBool cannot appear in storage interfaces). We scan the block
//    body for `bool`/`bvec2`/`bvec3`/`bvec4` member declarations to
//    restore the original GL type.

// Find the body of `uniform <blockName> { ... }` in GLSL source.
// Returns (bodyStart, bodyEnd) — the byte range INSIDE the braces, or
// (npos, npos) if not found.
static std::pair<std::size_t, std::size_t>
findBlockBody(const std::string& source, const std::string& blockName) {
    // Try `uniform <block>` (UBO), `buffer <block>` (SSBO), and
    // `out <block>` (interface-block varyings like
    // `out Color { ... } vs_color;`). A block type name is scoped
    // per-keyword so the first match of any combination is correct.
    const std::array<std::string, 3> tokens = {
        std::string("uniform ") + blockName,
        std::string("buffer ") + blockName,
        std::string("out ") + blockName,
    };
    for (const auto& token : tokens) {
        std::size_t pos = 0;
        while (pos < source.size()) {
            pos = source.find(token, pos);
            if (pos == std::string::npos) break;
            std::size_t end = pos + token.size();
            if (end < source.size() &&
                (std::isalnum(static_cast<unsigned char>(source[end])) || source[end] == '_')) {
                pos = end;
                continue;
            }
            std::size_t bracePos = source.find('{', end);
            if (bracePos == std::string::npos) break;
            int depth = 1;
            std::size_t cur = bracePos + 1;
            while (cur < source.size() && depth > 0) {
                if (source[cur] == '{') ++depth;
                else if (source[cur] == '}') --depth;
                ++cur;
            }
            // cur is right after the closing '}'. Body is [bracePos+1, cur-2].
            return {bracePos + 1, cur - 1};
        }
    }
    return {std::string::npos, std::string::npos};
}

// Strip line + block comments from GLSL source. Used as input to the
// layout(binding=N) scanner below so that commented-out layout
// qualifiers don't get matched.
static std::string stripGlslComments(const std::string& source) {
    std::string s;
    s.reserve(source.size());
    for (std::size_t i = 0; i < source.size(); ) {
        if (i + 1 < source.size() && source[i] == '/' && source[i + 1] == '/') {
            while (i < source.size() && source[i] != '\n') ++i;
        } else if (i + 1 < source.size() && source[i] == '/' && source[i + 1] == '*') {
            i += 2;
            while (i + 1 < source.size() && !(source[i] == '*' && source[i + 1] == '/')) ++i;
            if (i + 1 < source.size()) i += 2;
        } else {
            s += source[i];
            ++i;
        }
    }
    return s;
}

// Parse `layout(binding = N) ... uniform <sampler|image>Type <name>[...];`
// declarations out of the comment-stripped GLSL source. Returns a map
// from opaque uniform name to its explicit binding index and kind.
//
// This is the source-of-truth for "did the user write layout(binding)"
// because glslang auto-assigns DecorationBinding on every opaque
// variable regardless of whether the GLSL had an explicit qualifier —
// see bd73acc / 9c496f4 where the previous attempts relied on
// SPIRV-Cross's `has_decoration(id, DecorationBinding)` and that
// returned true for both auto-assigned and user-declared bindings,
// which wrecked pixelstoragemodes (samplers without explicit bindings
// got shifted to non-zero units).
//
// Parser approach: bespoke scan rather than <regex> for determinism
// and to avoid C++ regex overhead. Handles:
//   layout(binding = 5) uniform sampler2D foo;
//   layout(binding=5) uniform sampler2D foo;
//   layout(binding = 5, location = 2) uniform sampler2D foo;
//   layout(location = 2, binding = 5) uniform highp sampler2D foo;
//   layout(binding=5) uniform sampler2D foo[3];
//   layout(binding=5, rgba8) readonly uniform image2D img;
// Does NOT handle macro-expanded names, preprocessor conditionals that
// leave declarations out, or GLSL #version gates — if those ever matter
// we add them in a follow-up.
enum class ExplicitOpaqueBindingKind {
    Sampler,
    Image,
    AtomicCounter,
};

struct ExplicitOpaqueBinding {
    GLuint binding = 0;
    ExplicitOpaqueBindingKind kind = ExplicitOpaqueBindingKind::Sampler;
};

static std::unordered_map<std::string, ExplicitOpaqueBinding>
parseExplicitOpaqueBindings(const std::string& rawSource) {
    std::unordered_map<std::string, ExplicitOpaqueBinding> result;
    const std::string s = stripGlslComments(rawSource);

    auto isIdentChar = [](char c) -> bool {
        return std::isalnum(static_cast<unsigned char>(c)) || c == '_';
    };

    // Sprint 8 B Cluster F F1 (CKPT73): scan for `#define NAME VALUE`
    // directives (integer-constant style only) so `layout(binding=NAME)`
    // can be resolved against the macro table. CTS layout_binding.*
    // binding_integer_constant tests use exactly this shape:
    //   #define INT_CONST 7
    //   layout(binding=INT_CONST) uniform sampler2D s;
    // Pre-fix: parser saw 'INT_CONST' as non-numeric → bail → no binding.
    // Limited to integer-literal #defines (no expression evaluation;
    // no nested macro substitution) — covers CTS shape.
    std::unordered_map<std::string, long> defineTable;
    {
        std::size_t p = 0;
        while (p < s.size()) {
            const auto hashPos = s.find('#', p);
            if (hashPos == std::string::npos) break;
            // Word-boundary on left.
            if (hashPos > 0 && isIdentChar(s[hashPos - 1])) {
                p = hashPos + 1;
                continue;
            }
            std::size_t after = hashPos + 1;
            while (after < s.size() && (s[after] == ' ' || s[after] == '\t')) ++after;
            if (after + 6 <= s.size() && s.compare(after, 6, "define") == 0 &&
                (after + 6 >= s.size() || !isIdentChar(s[after + 6]))) {
                std::size_t cur = after + 6;
                while (cur < s.size() && (s[cur] == ' ' || s[cur] == '\t')) ++cur;
                const std::size_t nameStart = cur;
                while (cur < s.size() && isIdentChar(s[cur])) ++cur;
                if (cur > nameStart) {
                    std::string name = s.substr(nameStart, cur - nameStart);
                    while (cur < s.size() && (s[cur] == ' ' || s[cur] == '\t')) ++cur;
                    char* endp = nullptr;
                    const long val = std::strtol(s.c_str() + cur, &endp, 0);
                    if (endp != s.c_str() + cur && val >= 0) {
                        defineTable[name] = val;
                    }
                }
            }
            p = hashPos + 1;
        }
    }
    auto skipWhitespace = [&](std::size_t& i) {
        while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    };

    std::size_t pos = 0;
    while (pos < s.size()) {
        const auto layoutPos = s.find("layout", pos);
        if (layoutPos == std::string::npos) break;

        // Word boundary before / after "layout".
        if (layoutPos > 0 && isIdentChar(s[layoutPos - 1])) {
            pos = layoutPos + 1;
            continue;
        }
        std::size_t after = layoutPos + 6;
        skipWhitespace(after);
        if (after >= s.size() || s[after] != '(') {
            pos = layoutPos + 1;
            continue;
        }

        // Find matching ')'.
        int depth = 0;
        std::size_t closeIdx = after;
        for (; closeIdx < s.size(); ++closeIdx) {
            if (s[closeIdx] == '(') ++depth;
            else if (s[closeIdx] == ')') {
                if (--depth == 0) break;
            }
        }
        if (closeIdx >= s.size()) {
            pos = layoutPos + 1;
            continue;
        }
        const std::string body = s.substr(after + 1, closeIdx - after - 1);

        // Extract `binding = N` from the layout body. Word-boundary
        // match so `decl_binding` or similar doesn't trigger.
        int binding = -1;
        std::size_t bPos = 0;
        while ((bPos = body.find("binding", bPos)) != std::string::npos) {
            if (bPos > 0 && isIdentChar(body[bPos - 1])) {
                bPos += 1;
                continue;
            }
            std::size_t eqPos = bPos + 7;
            while (eqPos < body.size() && std::isspace(static_cast<unsigned char>(body[eqPos]))) ++eqPos;
            if (eqPos < body.size() && body[eqPos] == '=') {
                ++eqPos;
                while (eqPos < body.size() && std::isspace(static_cast<unsigned char>(body[eqPos]))) ++eqPos;
                char* endp = nullptr;
                // Sprint 8 B Cluster F F1 (CKPT73): GLSL §4.3 integer
                // literal syntax follows C — `0` prefix = octal, `0x`
                // prefix = hex, otherwise decimal. CTS layout_binding.*
                // exercises `layout(binding=047)` (octal 047 = decimal
                // 39). Use strtol base 0 to auto-detect octal/hex/dec
                // per the GLSL spec. Pre-fix: decimal-only parse turned
                // 047 into 47, breaking `layout_binding.sampler2D_*` etc.
                const long val = std::strtol(body.c_str() + eqPos, &endp, 0);
                if (endp != body.c_str() + eqPos && val >= 0) {
                    binding = static_cast<int>(val);
                } else {
                    // Try resolving as a #define identifier (CTS
                    // binding_integer_constant tests use this shape).
                    std::size_t idStart = eqPos;
                    while (idStart < body.size() &&
                           std::isspace(static_cast<unsigned char>(body[idStart]))) ++idStart;
                    std::size_t idEnd = idStart;
                    while (idEnd < body.size() && isIdentChar(body[idEnd])) ++idEnd;
                    if (idEnd > idStart) {
                        std::string ident = body.substr(idStart, idEnd - idStart);
                        auto dIt = defineTable.find(ident);
                        if (dIt != defineTable.end()) {
                            binding = static_cast<int>(dIt->second);
                        }
                    }
                }
            }
            break;
        }

        if (binding >= 0) {
            // Scan post-`)` for `[memory-qual]* [uniform]? [memory-qual]* [precision]? sampler-type name`.
            //
            // Sprint 8 B Cluster F F1 Day 8 (CKPT80): GL §4.10 image
            // memory qualifiers (`readonly`, `writeonly`, `coherent`,
            // `volatile`, `restrict`) can appear in any order around
            // `uniform`. CTS layout_binding.image2D_* generates
            // `layout(binding=3, rgba8) readonly uniform image2D image0;`
            // — `readonly` is BEFORE `uniform`. Pre-CKPT80 parser only
            // accepted `uniform [precision]? type name` and bailed when
            // the next token after `)` was `readonly`. Now we loop
            // skipping any combination of memory/precision/uniform
            // qualifiers until we hit the actual type token.
            std::size_t cur = closeIdx + 1;
            skipWhitespace(cur);
            const char* const skippableQualifiers[] = {
                "uniform",
                "highp", "mediump", "lowp",
                "readonly", "writeonly", "coherent", "volatile", "restrict",
            };
            bool advanced = true;
            while (advanced) {
                advanced = false;
                for (const char* kw : skippableQualifiers) {
                    const std::size_t klen = std::strlen(kw);
                    if (cur + klen <= s.size() &&
                        s.compare(cur, klen, kw) == 0 &&
                        (cur + klen >= s.size() || !isIdentChar(s[cur + klen]))) {
                        cur += klen;
                        skipWhitespace(cur);
                        advanced = true;
                        break;
                    }
                }
            }
            // Read the type name (must contain "sampler" / "image" or
            // the compat-rewrite capitalized variants).
            const std::size_t typeStart = cur;
            while (cur < s.size() && isIdentChar(s[cur])) ++cur;
            const std::string typeName = s.substr(typeStart, cur - typeStart);
            // Sprint 8 B Cluster F F1 (CKPT73): also recognise
            // `atomic_uint` as an opaque uniform type for binding
            // resolution. CTS layout_binding.atomic_uint_* exercises
            // `layout(binding=N) uniform atomic_uint cnt;` which the
            // GL 4.2 §7.6 spec puts in the same `layout(binding=N)`
            // family as samplers and images.
            const bool isSamplerType =
                typeName.find("sampler") != std::string::npos ||
                typeName.find("Sampler") != std::string::npos;
            const bool isImageType =
                typeName.find("image") != std::string::npos ||
                typeName.find("Image") != std::string::npos;
            const bool isAtomicCounterType = typeName == "atomic_uint";
            if (isSamplerType || isImageType || isAtomicCounterType) {
                skipWhitespace(cur);
                const std::size_t nameStart = cur;
                while (cur < s.size() && isIdentChar(s[cur])) ++cur;
                if (cur > nameStart) {
                    std::string name = s.substr(nameStart, cur - nameStart);
                    ExplicitOpaqueBinding parsed;
                    parsed.binding = static_cast<GLuint>(binding);
                    if (isImageType) {
                        parsed.kind = ExplicitOpaqueBindingKind::Image;
                    } else if (isAtomicCounterType) {
                        parsed.kind = ExplicitOpaqueBindingKind::AtomicCounter;
                    }
                    result[std::move(name)] = parsed;
                }
            }
        }

        pos = closeIdx + 1;
    }
    return result;
}

std::string trimGlslString(std::string_view text) {
    std::size_t begin = 0;
    while (begin < text.size() &&
           std::isspace(static_cast<unsigned char>(text[begin]))) {
        ++begin;
    }
    std::size_t end = text.size();
    while (end > begin &&
           std::isspace(static_cast<unsigned char>(text[end - 1]))) {
        --end;
    }
    return std::string(text.substr(begin, end - begin));
}

std::vector<std::string> splitGlslTopLevelCommas(std::string_view text) {
    std::vector<std::string> out;
    std::size_t start = 0;
    int parenDepth = 0;
    int bracketDepth = 0;
    int braceDepth = 0;
    for (std::size_t i = 0; i < text.size(); ++i) {
        const char c = text[i];
        if (c == '(') ++parenDepth;
        else if (c == ')' && parenDepth > 0) --parenDepth;
        else if (c == '[') ++bracketDepth;
        else if (c == ']' && bracketDepth > 0) --bracketDepth;
        else if (c == '{') ++braceDepth;
        else if (c == '}' && braceDepth > 0) --braceDepth;
        else if (c == ',' && parenDepth == 0 &&
                 bracketDepth == 0 && braceDepth == 0) {
            out.push_back(trimGlslString(text.substr(start, i - start)));
            start = i + 1;
        }
    }
    out.push_back(trimGlslString(text.substr(start)));
    return out;
}

struct ParsedAtomicCounterLayoutDecl {
    std::string name;
    bool isArray = false;
    int arraySize = 1;
    int binding = 0;
    int offset = 0;
};

bool validateAtomicCounterBindingAndOffset(int binding,
                                           int offset,
                                           int count,
                                           int maxBindings,
                                           int maxBufferSize,
                                           std::string& error) {
    if (binding < 0 || (maxBindings > 0 && binding >= maxBindings)) {
        error = "atomic_uint layout(binding=" + std::to_string(binding) +
                ") is outside GL_MAX_ATOMIC_COUNTER_BUFFER_BINDINGS";
        return false;
    }
    if (offset < 0 || (offset % 4) != 0) {
        error = "atomic_uint layout(offset=" + std::to_string(offset) +
                ") must be a non-negative multiple of 4";
        return false;
    }
    if (count < 1) {
        error = "atomic_uint array size must be positive";
        return false;
    }
    const long long endByte =
        static_cast<long long>(offset) + 4ll * static_cast<long long>(count);
    if (maxBufferSize > 0 && endByte > maxBufferSize) {
        error = "atomic_uint layout range exceeds GL_MAX_ATOMIC_COUNTER_BUFFER_SIZE";
        return false;
    }
    return true;
}

bool parseAtomicCounterLayoutsForSource(
    const std::string& rawSource,
    int maxBindings,
    int maxBufferSize,
    std::vector<ParsedAtomicCounterLayoutDecl>& out,
    std::string& error)
{
    const std::string s = stripGlslCommentsForAppglValidation(rawSource);
    const auto defines = parseGlslIntegerDefines(s);
    std::unordered_map<int, int> nextOffsetByBinding;
    std::unordered_map<int, std::vector<std::pair<int, int>>> usedRangesByBinding;
    bool hasDefaultBinding = false;
    int defaultBinding = 0;

    std::size_t p = 0;
    while ((p = s.find("uniform", p)) != std::string::npos) {
        if (!tokenAt(s, p, "uniform")) {
            p += 7;
            continue;
        }
        std::size_t q = p + 7;
        const std::string typeName = readGlslIdent(s, q);
        if (typeName != "atomic_uint") {
            p += 7;
            continue;
        }
        const std::size_t semi = s.find(';', q);
        if (semi == std::string::npos) {
            break;
        }

        std::size_t declStart = p;
        while (declStart > 0 && s[declStart - 1] != ';' &&
               s[declStart - 1] != '}') {
            --declStart;
        }
        const std::string prefix = s.substr(declStart, p - declStart);
        int layoutBinding = 0;
        int layoutOffset = 0;
        const bool hasLayoutBinding =
            parseLayoutIntegerQualifier(prefix, "binding", defines, layoutBinding);
        const bool hasLayoutOffset =
            parseLayoutIntegerQualifier(prefix, "offset", defines, layoutOffset);
        const std::string declaratorText =
            trimGlslString(std::string_view(s).substr(q, semi - q));

        if (declaratorText.empty()) {
            if (hasLayoutOffset && !hasLayoutBinding) {
                error = "atomic_uint layout(offset) default requires layout(binding)";
                return false;
            }
            if (hasLayoutBinding) {
                if (!validateAtomicCounterBindingAndOffset(
                        layoutBinding,
                        hasLayoutOffset ? layoutOffset : 0,
                        1,
                        maxBindings,
                        maxBufferSize,
                        error)) {
                    return false;
                }
                defaultBinding = layoutBinding;
                hasDefaultBinding = true;
                if (hasLayoutOffset) {
                    nextOffsetByBinding[layoutBinding] = layoutOffset;
                } else if (nextOffsetByBinding.find(layoutBinding) ==
                           nextOffsetByBinding.end()) {
                    nextOffsetByBinding[layoutBinding] = 0;
                }
            }
            p = semi + 1;
            continue;
        }

        if (hasLayoutOffset && !hasLayoutBinding) {
            error = "atomic_uint layout(offset) declaration requires layout(binding)";
            return false;
        }

        const int binding = hasLayoutBinding
            ? layoutBinding
            : (hasDefaultBinding ? defaultBinding : 0);
        if (nextOffsetByBinding.find(binding) == nextOffsetByBinding.end()) {
            nextOffsetByBinding[binding] = 0;
        }

        const auto declarators = splitGlslTopLevelCommas(declaratorText);
        for (std::size_t declIndex = 0; declIndex < declarators.size(); ++declIndex) {
            const std::string& declarator = declarators[declIndex];
            std::size_t cur = 0;
            const std::string name = readGlslIdent(declarator, cur);
            if (name.empty()) {
                continue;
            }
            bool isArray = false;
            int arraySize = 1;
            skipGlslWs(declarator, cur);
            if (cur < declarator.size() && declarator[cur] == '[') {
                const std::size_t close = declarator.find(']', cur + 1);
                if (close == std::string::npos) {
                    error = "atomic_uint array declaration is missing ']'";
                    return false;
                }
                isArray = true;
                if (!parseGlslIntegerExpression(
                        std::string_view(declarator).substr(cur + 1, close - cur - 1),
                        defines,
                        arraySize) ||
                    arraySize <= 0) {
                    error = "atomic_uint array declaration has invalid size";
                    return false;
                }
            }

            const int offset = (hasLayoutOffset && declIndex == 0)
                ? layoutOffset
                : nextOffsetByBinding[binding];
            if (!validateAtomicCounterBindingAndOffset(
                    binding, offset, arraySize, maxBindings, maxBufferSize, error)) {
                return false;
            }
            const int endByte = offset + 4 * arraySize;
            auto& usedRanges = usedRangesByBinding[binding];
            for (const auto& [usedBegin, usedEnd] : usedRanges) {
                if (offset < usedEnd && endByte > usedBegin) {
                    error = "atomic_uint declarations overlap within binding " +
                            std::to_string(binding);
                    return false;
                }
            }
            usedRanges.push_back({offset, endByte});
            nextOffsetByBinding[binding] =
                std::max(nextOffsetByBinding[binding], endByte);

            ParsedAtomicCounterLayoutDecl parsed;
            parsed.name = name;
            parsed.isArray = isArray;
            parsed.arraySize = arraySize;
            parsed.binding = binding;
            parsed.offset = offset;
            out.push_back(std::move(parsed));
        }

        p = semi + 1;
    }
    return true;
}

bool applyAtomicCounterLayoutsFromSources(
    const std::vector<GLShaderObject*>& shaders,
    std::vector<GLProgramUniformInfo>& uniforms,
    int maxBindings,
    int maxBufferSize,
    std::string& error)
{
    for (const GLShaderObject* shader : shaders) {
        if (shader == nullptr) continue;
        std::vector<ParsedAtomicCounterLayoutDecl> parsedDecls;
        if (!parseAtomicCounterLayoutsForSource(
                shader->source, maxBindings, maxBufferSize, parsedDecls, error)) {
            return false;
        }
        for (const auto& parsed : parsedDecls) {
            for (auto& uniform : uniforms) {
                if (uniform.type != GL_UNSIGNED_INT_ATOMIC_COUNTER ||
                    uniform.name != parsed.name) {
                    continue;
                }
                uniform.explicitBinding = parsed.binding;
                uniform.explicitOffset = parsed.offset;
                uniform.isArray = uniform.isArray || parsed.isArray;
                uniform.arraySize = std::max<GLint>(
                    uniform.arraySize,
                    parsed.arraySize > 0 ? parsed.arraySize : 1);
                break;
            }
        }
    }
    return true;
}

static bool glslBlockHasInstanceName(const std::string& source,
                                      const std::string& blockName) {
    auto [bodyStart, bodyEnd] = findBlockBody(source, blockName);
    if (bodyStart == std::string::npos) return false;
    // bodyEnd points at the '}'. Skip whitespace after it.
    std::size_t cur = bodyEnd + 1;
    while (cur < source.size() &&
           (source[cur] == ' ' || source[cur] == '\t' ||
            source[cur] == '\n' || source[cur] == '\r')) {
        ++cur;
    }
    return cur < source.size() && (std::isalpha(source[cur]) || source[cur] == '_');
}

// If an interface block `layout(...) uniform <blockName> { ... } <inst>[N];`
// is declared with an instance name, return the instance name; otherwise
// return an empty string. Used by the PIQ reflection path to gate the
// per-instance active flag on whether the stage's source actually
// references a specific `<inst>[i]` element.
static std::string glslBlockInstanceName(const std::string& source,
                                          const std::string& blockName) {
    auto [bodyStart, bodyEnd] = findBlockBody(source, blockName);
    if (bodyStart == std::string::npos) return {};
    std::size_t cur = bodyEnd + 1;
    while (cur < source.size() &&
           (source[cur] == ' ' || source[cur] == '\t' ||
            source[cur] == '\n' || source[cur] == '\r')) {
        ++cur;
    }
    if (cur >= source.size() ||
        !(std::isalpha(static_cast<unsigned char>(source[cur])) || source[cur] == '_')) {
        return {};
    }
    std::size_t identStart = cur;
    while (cur < source.size() &&
           (std::isalnum(static_cast<unsigned char>(source[cur])) || source[cur] == '_')) {
        ++cur;
    }
    return source.substr(identStart, cur - identStart);
}

// Walk the source for `<instance>[N]` tokens (word-bounded on the left
// side so we don't match inside longer identifiers). Returns the set of
// integer indices used — for a block declared as `} e[4];`, an FS body
// that reads `e[0]` and `e[2]` returns `{0, 2}`. Block elements at
// indices not in this set are spec-correctly "inactive" with respect to
// that stage.
static std::set<int> glslActiveInstanceIndices(const std::string& source,
                                                const std::string& instanceName) {
    std::set<int> used;
    if (instanceName.empty()) return used;
    const std::size_t ilen = instanceName.size();
    std::size_t pos = 0;
    while ((pos = source.find(instanceName, pos)) != std::string::npos) {
        const bool leftBoundary = (pos == 0) ||
            !(std::isalnum(static_cast<unsigned char>(source[pos - 1])) || source[pos - 1] == '_');
        const std::size_t after = pos + ilen;
        const bool openBracket = after < source.size() && source[after] == '[';
        if (leftBoundary && openBracket) {
            // Walk to matching ']' capturing a pure-digit index.
            std::size_t idxStart = after + 1;
            // Skip leading whitespace inside the brackets.
            while (idxStart < source.size() &&
                   (source[idxStart] == ' ' || source[idxStart] == '\t')) {
                ++idxStart;
            }
            std::size_t idxEnd = idxStart;
            while (idxEnd < source.size() &&
                   std::isdigit(static_cast<unsigned char>(source[idxEnd]))) {
                ++idxEnd;
            }
            if (idxEnd > idxStart) {
                // Following character must close the bracket (allow
                // trailing whitespace before `]`).
                std::size_t tail = idxEnd;
                while (tail < source.size() &&
                       (source[tail] == ' ' || source[tail] == '\t')) {
                    ++tail;
                }
                if (tail < source.size() && source[tail] == ']') {
                    int value = static_cast<int>(std::stoi(
                        source.substr(idxStart, idxEnd - idxStart)));
                    used.insert(value);
                }
            }
        }
        pos += ilen;
    }
    return used;
}

// GL 4.0 subroutine declarations (GLSL 4.00+, §4.4.4).  A focused source-
// text scanner: the main GLSLReflection only handles `uniform` / `in` /
// `out` / `attribute` / `varying`, which miss every subroutine form.
// Three GLSL shapes to distinguish (case-sensitive keyword `subroutine`):
//
//   subroutine <rettype> <typeName> ( <params> ) ;
//         → subroutine type prototype (non-resource; we only record the
//           type name for later compatibility lookup).
//   subroutine uniform <typeName> <uniName> [ [<N>] ] ;
//         → subroutine uniform (becomes a GL_*_SUBROUTINE_UNIFORM
//           resource).
//   subroutine ( <typeList> ) <rettype> <funcName> ( <params> ) { ... }
//         → subroutine implementation (becomes a GL_*_SUBROUTINE resource).
//           The type list names all subroutine types this impl is
//           compatible with — drives GL_COMPATIBLE_SUBROUTINES on the
//           matching uniform entries.
//
// Results: per stage, fills `outImpls` (subroutine implementations) and
// `outUniforms` (subroutine uniforms with their activeVariables populated
// with the indices of compatible impls).  Best-effort parser — the scanner
// assumes a well-formed shader and stops at the first `}` at top-level to
// bound function bodies. Not exhaustive vs. arbitrary GLSL but covers CTS
// `program_interface_query.subroutines-*`.
static void scanSubroutineDeclarations(
    const std::string& sourceIn,
    std::vector<GLProgramResourceEntry>& outImpls,
    std::vector<GLProgramResourceEntry>& outUniforms) {
    auto strip = [](const std::string& s) {
        std::string out;
        out.reserve(s.size());
        for (std::size_t i = 0; i < s.size();) {
            if (i + 1 < s.size() && s[i] == '/' && s[i + 1] == '/') {
                while (i < s.size() && s[i] != '\n') ++i;
            } else if (i + 1 < s.size() && s[i] == '/' && s[i + 1] == '*') {
                i += 2;
                while (i + 1 < s.size() && !(s[i] == '*' && s[i + 1] == '/')) ++i;
                if (i + 1 < s.size()) i += 2;
            } else {
                out += s[i++];
            }
        }
        return out;
    };
    const std::string src = strip(sourceIn);

    auto isIdentChar = [](unsigned char c) {
        return std::isalnum(c) || c == '_';
    };
    auto skipWs = [&](std::size_t& p) {
        while (p < src.size() && std::isspace(static_cast<unsigned char>(src[p]))) ++p;
    };
    auto readIdent = [&](std::size_t& p) -> std::string {
        skipWs(p);
        const std::size_t start = p;
        while (p < src.size() && isIdentChar(static_cast<unsigned char>(src[p]))) ++p;
        return src.substr(start, p - start);
    };
    auto readTypeWithArraySuffix = [&](std::size_t& p) -> std::string {
        std::string typeName = readIdent(p);
        if (typeName.empty()) return typeName;
        std::size_t q = p;
        skipWs(q);
        while (q < src.size() && src[q] == '[') {
            const std::size_t bracketStart = q;
            int bd = 1;
            ++q;
            while (q < src.size() && bd > 0) {
                if (src[q] == '[') ++bd;
                else if (src[q] == ']') --bd;
                ++q;
            }
            if (bd != 0) break;
            typeName.append(src, bracketStart, q - bracketStart);
            p = q;
            skipWs(q);
        }
        return typeName;
    };
    auto isDeclPos = [&](std::size_t p) {
        while (p > 0) {
            unsigned char c = static_cast<unsigned char>(src[p - 1]);
            if (std::isspace(c)) {
                --p;
                continue;
            }
            return c == ';' || c == '{' || c == '}';
        }
        return true;
    };
    struct LayoutQualifier {
        GLint location = -1;
        GLint index = -1;
    };
    auto parseLayoutInteger = [&](const std::string& content, const char* key, GLint& value) {
        const std::string keyStr = key;
        std::size_t keyPos = content.find(keyStr);
        while (keyPos != std::string::npos) {
            const bool lb = (keyPos == 0) ||
                !isIdentChar(static_cast<unsigned char>(content[keyPos - 1]));
            const std::size_t keyEnd = keyPos + keyStr.size();
            const bool rb = (keyEnd == content.size()) ||
                !isIdentChar(static_cast<unsigned char>(content[keyEnd]));
            if (lb && rb) break;
            keyPos = content.find(keyStr, keyEnd);
        }
        if (keyPos == std::string::npos) return false;
        const std::size_t eq = content.find('=', keyPos + keyStr.size());
        if (eq == std::string::npos) return false;
        std::size_t nb = eq + 1;
        while (nb < content.size() && std::isspace(static_cast<unsigned char>(content[nb]))) ++nb;
        if (nb >= content.size() || !std::isdigit(static_cast<unsigned char>(content[nb]))) {
            return false;
        }
        std::size_t ne = nb;
        if (ne + 1 < content.size() && content[ne] == '0' &&
            (content[ne + 1] == 'x' || content[ne + 1] == 'X')) {
            ne += 2;
            const std::size_t hexStart = ne;
            while (ne < content.size() && std::isxdigit(static_cast<unsigned char>(content[ne]))) ++ne;
            if (ne == hexStart) return false;
        } else {
            while (ne < content.size() && std::isdigit(static_cast<unsigned char>(content[ne]))) ++ne;
        }
        value = static_cast<GLint>(std::strtol(content.substr(nb, ne - nb).c_str(), nullptr, 0));
        return true;
    };
    auto findLayoutBeforeSubroutine = [&](std::size_t subPos,
                                          std::size_t& layoutStart,
                                          std::size_t& openParen,
                                          std::size_t& closeParen) {
        std::size_t back = subPos;
        while (back > 0 && std::isspace(static_cast<unsigned char>(src[back - 1]))) --back;
        if (back == 0 || src[back - 1] != ')') return false;
        int pd = 1;
        std::size_t bp = back - 1;
        while (bp > 0 && pd > 0) {
            --bp;
            if (src[bp] == ')') ++pd;
            else if (src[bp] == '(') --pd;
        }
        if (pd != 0) return false;
        std::size_t lp = bp;
        while (lp > 0 && std::isspace(static_cast<unsigned char>(src[lp - 1]))) --lp;
        if (lp < 6 || src.compare(lp - 6, 6, "layout") != 0) return false;
        layoutStart = lp - 6;
        if (layoutStart > 0 &&
            isIdentChar(static_cast<unsigned char>(src[layoutStart - 1]))) {
            return false;
        }
        if (!isDeclPos(layoutStart)) return false;
        openParen = bp;
        closeParen = back - 1;
        return true;
    };
    auto parseLayoutBefore = [&](std::size_t subPos, LayoutQualifier& layout) {
        std::size_t layoutStart = 0;
        std::size_t openParen = 0;
        std::size_t closeParen = 0;
        if (!findLayoutBeforeSubroutine(subPos, layoutStart, openParen, closeParen)) {
            return false;
        }
        const std::string content = src.substr(openParen + 1, closeParen - openParen - 1);
        parseLayoutInteger(content, "location", layout.location);
        parseLayoutInteger(content, "index", layout.index);
        return true;
    };
    auto isSubroutineDeclPos = [&](std::size_t subPos) {
        if (isDeclPos(subPos)) return true;
        std::size_t layoutStart = 0;
        std::size_t openParen = 0;
        std::size_t closeParen = 0;
        return findLayoutBeforeSubroutine(subPos, layoutStart, openParen, closeParen);
    };
    auto parseArrayDimensions = [&](std::size_t& p, std::vector<GLint>& dims) {
        dims.clear();
        skipWs(p);
        while (p < src.size() && src[p] == '[') {
            ++p;
            skipWs(p);
            const std::size_t nStart = p;
            while (p < src.size() && std::isdigit(static_cast<unsigned char>(src[p]))) ++p;
            GLint dim = 1;
            if (p > nStart) {
                dim = std::atoi(src.substr(nStart, p - nStart).c_str());
                if (dim < 1) dim = 1;
            }
            dims.push_back(dim);
            skipWs(p);
            if (p < src.size() && src[p] == ']') ++p;
            skipWs(p);
        }
    };

    std::unordered_map<std::string, std::vector<GLint>> typeToImpls;
    std::vector<std::string> pendingUniformTypes;

    const std::string kw = "subroutine";
    std::size_t pos = 0;
    while ((pos = src.find(kw, pos)) != std::string::npos) {
        const bool leftBoundary = (pos == 0) ||
            !isIdentChar(static_cast<unsigned char>(src[pos - 1]));
        const bool rightBoundary = (pos + kw.size() < src.size()) &&
            !isIdentChar(static_cast<unsigned char>(src[pos + kw.size()]));
        if (!leftBoundary || !rightBoundary || !isSubroutineDeclPos(pos)) {
            pos += kw.size();
            continue;
        }

        LayoutQualifier layout;
        parseLayoutBefore(pos, layout);
        std::size_t p = pos + kw.size();
        skipWs(p);

        if (p < src.size() && src[p] == '(') {
            ++p;
            std::vector<std::string> typeList;
            while (p < src.size() && src[p] != ')') {
                skipWs(p);
                if (p < src.size() && src[p] == ')') break;
                std::string t = readIdent(p);
                if (!t.empty()) typeList.push_back(std::move(t));
                skipWs(p);
                if (p < src.size() && src[p] == ',') ++p;
            }
            if (p < src.size() && src[p] == ')') ++p;
            std::string retType = readTypeWithArraySuffix(p);
            (void)retType;
            std::string fnName = readIdent(p);
            if (fnName.empty()) { pos = p; continue; }
            skipWs(p);
            if (p < src.size() && src[p] == '(') {
                int pd = 1;
                ++p;
                while (p < src.size() && pd > 0) {
                    if (src[p] == '(') ++pd;
                    else if (src[p] == ')') --pd;
                    ++p;
                }
            }
            GLProgramResourceEntry entry;
            entry.name = fnName;
            entry.type = 0;
            entry.location = -1;
            entry.arraySize = 1;
            entry.subroutineIndex = layout.index;
            const GLint implIdx = static_cast<GLint>(outImpls.size());
            outImpls.push_back(std::move(entry));
            for (const auto& t : typeList) {
                typeToImpls[t].push_back(implIdx);
            }
            pos = p;
            continue;
        }

        std::string next = readTypeWithArraySuffix(p);
        if (next == "uniform") {
            std::string typeName = readIdent(p);
            std::string uniName = readIdent(p);
            if (uniName.empty() || typeName.empty()) { pos = p; continue; }
            std::vector<GLint> dims;
            parseArrayDimensions(p, dims);
            GLint arraySize = 1;
            for (GLint dim : dims) {
                arraySize *= dim;
            }
            const bool isArray = !dims.empty();
            GLProgramResourceEntry entry;
            entry.name = isArray ? (uniName + "[0]") : uniName;
            entry.type = 0;
            entry.location = layout.location;
            entry.arraySize = arraySize;
            entry.isArray = isArray;
            entry.arrayDimensions = std::move(dims);
            outUniforms.push_back(std::move(entry));
            pendingUniformTypes.push_back(typeName);
            pos = p;
            continue;
        }

        std::string typeName = readIdent(p);
        (void)typeName;
        pos = p;
    }

    std::unordered_set<GLint> usedSubroutineIndices;
    for (const auto& impl : outImpls) {
        if (impl.subroutineIndex >= 0) {
            usedSubroutineIndices.insert(impl.subroutineIndex);
        }
    }
    GLint nextSubroutineIndex = 0;
    for (auto& impl : outImpls) {
        if (impl.subroutineIndex >= 0) continue;
        while (usedSubroutineIndices.find(nextSubroutineIndex) != usedSubroutineIndices.end()) {
            ++nextSubroutineIndex;
        }
        impl.subroutineIndex = nextSubroutineIndex;
        usedSubroutineIndices.insert(nextSubroutineIndex);
    }

    std::unordered_set<GLint> usedUniformLocations;
    for (const auto& uni : outUniforms) {
        if (uni.location < 0) continue;
        const GLint count = std::max<GLint>(1, uni.arraySize);
        for (GLint i = 0; i < count; ++i) {
            usedUniformLocations.insert(uni.location + i);
        }
    }
    auto uniformRangeAvailable = [&](GLint base, GLint count) {
        for (GLint i = 0; i < count; ++i) {
            if (usedUniformLocations.find(base + i) != usedUniformLocations.end()) {
                return false;
            }
        }
        return true;
    };
    GLint nextUniformLocation = 0;
    for (auto& uni : outUniforms) {
        if (uni.location >= 0) continue;
        const GLint count = std::max<GLint>(1, uni.arraySize);
        while (!uniformRangeAvailable(nextUniformLocation, count)) {
            ++nextUniformLocation;
        }
        uni.location = nextUniformLocation;
        for (GLint i = 0; i < count; ++i) {
            usedUniformLocations.insert(uni.location + i);
        }
    }

    for (std::size_t u = 0; u < pendingUniformTypes.size() && u < outUniforms.size(); ++u) {
        const std::string& typeName = pendingUniformTypes[u];
        auto it = typeToImpls.find(typeName);
        if (it == typeToImpls.end()) continue;
        outUniforms[u].activeVariables.clear();
        for (GLint implTableIndex : it->second) {
            if (implTableIndex < 0 ||
                static_cast<std::size_t>(implTableIndex) >= outImpls.size()) {
                continue;
            }
            outUniforms[u].activeVariables.push_back(
                outImpls[static_cast<std::size_t>(implTableIndex)].subroutineIndex);
        }
    }
}

static std::string stripSubroutineArrayZeroSuffixForReset(const std::string& name) {
    if (name.size() >= 3 && name.compare(name.size() - 3, 3, "[0]") == 0) {
        return name.substr(0, name.size() - 3);
    }
    return name;
}

static GLint subroutineUniformLocationCountForReset(
    const std::vector<GLProgramResourceEntry>& uniforms) {
    GLint maxLocation = 0;
    for (const auto& entry : uniforms) {
        if (entry.location < 0) continue;
        const GLint count = std::max<GLint>(1, entry.arraySize);
        maxLocation = std::max(maxLocation, entry.location + count);
    }
    return maxLocation;
}

static std::string subroutineDispatchKeyForReset(
    const std::string& baseName,
    GLint element,
    GLint elementCount) {
    if (elementCount <= 1) return baseName;
    return baseName + "_" + std::to_string(element);
}

static void resetProgramSubroutineSelections(GLProgramObject& programObject,
                                             bool markDirty) {
    bool hasSubroutineUniformState = false;
    for (int stage = 0; stage < 6; ++stage) {
        const auto& uniforms = programObject.resourceSubroutineUniforms[stage];
        hasSubroutineUniformState =
            hasSubroutineUniformState || !uniforms.empty();
        const GLint activeLocations = subroutineUniformLocationCountForReset(uniforms);
        auto& selections = programObject.currentSubroutineSelections[stage];
        selections.assign(static_cast<std::size_t>(activeLocations), 0u);
        for (const auto& uniform : uniforms) {
            if (uniform.location < 0) continue;
            const GLuint defaultSelection = uniform.activeVariables.empty()
                ? 0u
                : static_cast<GLuint>(uniform.activeVariables.front());
            const GLint elemCount = std::max<GLint>(1, uniform.arraySize);
            for (GLint elem = 0; elem < elemCount; ++elem) {
                const GLint loc = uniform.location + elem;
                if (loc >= 0 && loc < activeLocations) {
                    selections[static_cast<std::size_t>(loc)] = defaultSelection;
                }

                const std::string baseName =
                    stripSubroutineArrayZeroSuffixForReset(uniform.name);
                const std::string key =
                    subroutineDispatchKeyForReset(baseName, elem, elemCount);
                auto dispatchLoc =
                    programObject.subroutineDispatchUniformLocations.find(key);
                if (dispatchLoc == programObject.subroutineDispatchUniformLocations.end()) {
                    continue;
                }
                auto valueIt = programObject.uniformValues.find(dispatchLoc->second);
                if (valueIt == programObject.uniformValues.end()) {
                    continue;
                }
                valueIt->second.type = GL_UNSIGNED_INT;
                valueIt->second.arraySize = 1;
                valueIt->second.uints.assign(1, 0u);
            }
        }
    }
    programObject.subroutineSelectionsDirty = markDirty;
    if (markDirty && hasSubroutineUniformState) {
        programObject.markUniformsDirty();
    }
}

// Search a code region for "boolType name" where boolType is bool/bvec2/3/4.
// Returns the GL_BOOL* enum, or 0 if not found.
static GLenum searchForBoolType(std::string_view body, std::string_view name) {
    struct BoolMapping { const char* keyword; GLenum type; };
    static const BoolMapping mappings[] = {
        {"bvec4", GL_BOOL_VEC4},
        {"bvec3", GL_BOOL_VEC3},
        {"bvec2", GL_BOOL_VEC2},
        {"bool",  GL_BOOL},
    };
    for (const auto& m : mappings) {
        std::string pattern = std::string(m.keyword) + " " + std::string(name);
        auto fpos = body.find(pattern);
        if (fpos != std::string_view::npos) {
            std::size_t afterPattern = fpos + pattern.size();
            if (afterPattern >= body.size() ||
                body[afterPattern] == ';' || body[afterPattern] == '[' ||
                body[afterPattern] == ' ' || body[afterPattern] == '\n' ||
                body[afterPattern] == '\r') {
                return m.type;
            }
        }
    }
    return 0;
}

// Detect bool/bvec member types that SPIR-V represents as uint/uvec.
// Returns the correct GL_BOOL* type, or 0 if the member is not a bool type.
//
// For direct block members (no dots in name), we search within the block body.
// For nested struct members ("s.c"), we resolve through the struct chain:
// find the struct type name for each prefix component, then search the
// innermost struct body for the leaf name.
// Strip single-line comments ("// ...") from GLSL source. This prevents
// member-name searches from matching inside comments like "// unused in
// vertex shader" where a stray " i" would be misidentified as a declaration.
static std::string stripGLSLComments(std::string_view src) {
    std::string out;
    out.reserve(src.size());
    for (std::size_t i = 0; i < src.size(); ++i) {
        if (i + 1 < src.size() && src[i] == '/' && src[i+1] == '/') {
            // Skip to end of line
            while (i < src.size() && src[i] != '\n') ++i;
            if (i < src.size()) out += '\n';
        } else {
            out += src[i];
        }
    }
    return out;
}

static GLenum detectBoolMemberType(const std::string& source,
                                    const std::string& blockName,
                                    const std::string& memberName) {
    // Work on a comment-stripped copy to avoid false matches in comments.
    const std::string cleanSource = stripGLSLComments(source);

    // Split by dots first: "a[0].inner.c" → ["a[0]", "inner", "c"]
    // Array indices are stripped per-component in the traversal loop,
    // NOT up front (to preserve the dot-separated structure).
    std::vector<std::string> parts;
    std::size_t start = 0;
    while (start < memberName.size()) {
        auto dot = memberName.find('.', start);
        if (dot == std::string::npos) {
            parts.push_back(memberName.substr(start));
            break;
        }
        parts.push_back(memberName.substr(start, dot - start));
        start = dot + 1;
    }
    if (parts.empty()) return 0;

    // Strip array suffixes from each part: "a[0]" → "a"
    for (auto& p : parts) {
        auto bracketPos = p.find('[');
        if (bracketPos != std::string::npos) {
            p = p.substr(0, bracketPos);
        }
    }

    // For direct members (single part), search the block body.
    if (parts.size() == 1) {
        auto [bodyStart, bodyEnd] = findBlockBody(cleanSource, blockName);
        if (bodyStart == std::string::npos) return 0;
        std::string_view body(cleanSource.data() + bodyStart, bodyEnd - bodyStart);
        return searchForBoolType(body, parts[0]);
    }

    // For nested members, traverse the struct chain.
    // Start with the block body, find the type of each prefix, then
    // search the struct definition for the next component.
    auto [bodyStart, bodyEnd] = findBlockBody(cleanSource, blockName);
    if (bodyStart == std::string::npos) return 0;
    std::string_view searchBody(cleanSource.data() + bodyStart, bodyEnd - bodyStart);

    for (std::size_t i = 0; i < parts.size() - 1; ++i) {
        // Find the type name for part[i] in the current body.
        // Pattern: "<TypeName> <partName>" or "<TypeName> <partName>[...]"
        // We need to extract the type name that precedes the member name.
        const std::string& partName = parts[i];
        // Search for " partName" (with space before) to find declarations.
        // Require a word boundary after the name (;, [, space, newline)
        // to avoid matching "i" inside "ivec4" etc.
        std::string needle = " " + partName;
        std::string_view::size_type pos = std::string_view::npos;
        {
            std::string_view::size_type searchFrom = 0;
            while (searchFrom < searchBody.size()) {
                auto candidate = searchBody.find(needle, searchFrom);
                if (candidate == std::string_view::npos) break;
                std::size_t afterName = candidate + needle.size();
                if (afterName >= searchBody.size() ||
                    searchBody[afterName] == ';' || searchBody[afterName] == '[' ||
                    searchBody[afterName] == ' ' || searchBody[afterName] == '\n' ||
                    searchBody[afterName] == '\r' || searchBody[afterName] == '\t') {
                    pos = candidate;
                    break;
                }
                searchFrom = candidate + 1;
            }
        }
        if (pos == std::string_view::npos) return 0;
        // Walk backwards from the match to find the type name.
        // Skip whitespace backwards, then collect identifier chars.
        auto typeEnd = pos;
        while (typeEnd > 0 && searchBody[typeEnd - 1] == ' ') --typeEnd;
        auto typeStart = typeEnd;
        while (typeStart > 0 && (std::isalnum(searchBody[typeStart - 1]) || searchBody[typeStart - 1] == '_')) --typeStart;
        std::string typeName(searchBody.substr(typeStart, typeEnd - typeStart));
        if (typeName.empty()) return 0;
        // Find the struct definition for this type.
        std::string structToken = "struct " + typeName;
        auto structPos = cleanSource.find(structToken);
        if (structPos == std::string::npos) return 0;
        auto bracePos = cleanSource.find('{', structPos);
        if (bracePos == std::string::npos) return 0;
        int depth = 1;
        auto cur = bracePos + 1;
        while (cur < cleanSource.size() && depth > 0) {
            if (cleanSource[cur] == '{') ++depth;
            else if (cleanSource[cur] == '}') --depth;
            ++cur;
        }
        searchBody = std::string_view(cleanSource.data() + bracePos + 1, cur - bracePos - 2);
    }

    // Search the final body for the leaf member name.
    return searchForBoolType(searchBody, parts.back());
}

static bool mslWritesRenderTargetArrayIndex(const std::string* msl);
static bool mslWritesViewportArrayIndex(const std::string* msl);
static bool programFragmentMslUsesFragCoordParams(
    const GLProgramObject& program,
    bool cacheEnabled,
    bool validateEnabled);
static void rewriteMslOutputLocationsForFragmentInputs(
    std::string& vertexMSL,
    const std::string& fragmentMSL);

