// GL 4.5 — DSA texture operations.
// All delegate to existing bind-target implementations via save/restore.
// ---------------------------------------------------------------------------

struct ScopedTextureBindingRestore {
    GLStateTracker* state = nullptr;
    GLenum target = 0;
    GLuint previous = 0;

    ScopedTextureBindingRestore(GLStateTracker* tracker, GLenum textureTarget, GLuint texture)
        : state(tracker),
          target(textureTarget),
          previous(tracker != nullptr ? tracker->boundTexture(textureTarget) : 0) {
        if (state != nullptr) {
            state->bindTexture(target, texture);
        }
    }

    ~ScopedTextureBindingRestore() {
        if (state != nullptr) {
            state->bindTexture(target, previous);
        }
    }

    ScopedTextureBindingRestore(const ScopedTextureBindingRestore&) = delete;
    ScopedTextureBindingRestore& operator=(const ScopedTextureBindingRestore&) = delete;
};

// Helper: save/restore texture binding around a DSA call.
#define DSA_TEX_WRAP(texName, body) \
    auto* _obj = impl_->objects->textures().get(texName); \
    if (!_obj) { pushError(GL_INVALID_OPERATION); return false; } \
    GLenum _target = _obj->target ? _obj->target : GL_TEXTURE_2D; \
    ScopedTextureBindingRestore _dsaTextureBindingRestore(impl_->state.get(), _target, texName); \
    return [&]() -> bool body();

// Sprint 17 Day 5+ DSA Phase 5-2 [textures_parameter_setup_errors]:
// GL 4.6 §8.11 — the DSA `glTextureParameter*` family demands
// INVALID_OPERATION (not INVALID_ENUM) when the texture's effective
// target is `TEXTURE_2D_MULTISAMPLE` or `TEXTURE_2D_MULTISAMPLE_ARRAY`
// AND `pname` is any sampler state. The non-DSA `glTexParameter*`
// path pushes INVALID_ENUM for the same scenario (per §8.10
// table 23.18; covered by the existing check at line ~12786).
//
// CTS `direct_state_access.textures_parameter_setup_errors` asserts
// the DSA error-code distinction explicitly. The shared helper
// returns true when the (target, pname) combo violates the DSA-spec
// rule and the caller has pushed INVALID_OPERATION.
static bool dsaIsSamplerStateOnMultisampleTarget(GLenum target, GLenum pname) {
    const bool isMSTarget = (target == GL_TEXTURE_2D_MULTISAMPLE ||
                             target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY);
    if (!isMSTarget) return false;
    switch (pname) {
        case GL_TEXTURE_MIN_FILTER:
        case GL_TEXTURE_MAG_FILTER:
        case GL_TEXTURE_WRAP_S:
        case GL_TEXTURE_WRAP_T:
        case GL_TEXTURE_WRAP_R:
        case GL_TEXTURE_MIN_LOD:
        case GL_TEXTURE_MAX_LOD:
        case GL_TEXTURE_LOD_BIAS:
        case GL_TEXTURE_COMPARE_MODE:
        case GL_TEXTURE_COMPARE_FUNC:
        case GL_TEXTURE_BORDER_COLOR:
        case GL_TEXTURE_MAX_ANISOTROPY:
        case GL_TEXTURE_REDUCTION_MODE_ARB:
            return true;
        default:
            return false;
    }
}


// GL 4.6 §8.19 shared effective-target check for DSA TextureStorage*.
// When the DSA function's dim-signature doesn't match the texture's
// effective target, spec demands INVALID_OPERATION (not INVALID_ENUM).
// CTS `direct_state_access.textures_storage_errors` asserts each.
static bool targetIsValidForTexStorage1D(GLenum t) {
    return t == GL_TEXTURE_1D;
}
static bool targetIsValidForTexStorage2D(GLenum t) {
    return t == GL_TEXTURE_2D || t == GL_TEXTURE_1D_ARRAY ||
           t == GL_TEXTURE_RECTANGLE || t == GL_TEXTURE_CUBE_MAP;
}
static bool targetIsValidForTexStorage3D(GLenum t) {
    return t == GL_TEXTURE_3D || t == GL_TEXTURE_2D_ARRAY ||
           t == GL_TEXTURE_CUBE_MAP_ARRAY;
}
static bool targetIsValidForTexStorage2DMultisample(GLenum t) {
    return t == GL_TEXTURE_2D_MULTISAMPLE;
}
static bool targetIsValidForTexStorage3DMultisample(GLenum t) {
    return t == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
}

// Spec's max-level check from §8.19: levels ≤ log2(max(dim)) + 1.
// Computed once per call for the given (width, height, depth) tuple
// appropriate to the target.
static GLsizei log2Floor(GLsizei x) {
    if (x <= 1) return 0;
    GLsizei r = 0;
    while (x > 1) { x >>= 1; ++r; }
    return r;
}

